def _asset_version() -> str:
    """One immutable URL generation for the coupled Calliope browser bundle."""
    digest = hashlib.sha256()
    for name in _CACHE_VERSIONED_ASSETS:
        digest.update(name.encode("utf-8"))
        digest.update((_ASSET_DIR / name).read_bytes())
    return digest.hexdigest()[:16]


_ASSET_VERSION = _asset_version()


def _excalifont_hashes() -> str:
    """The Excalifont subset hashes actually on disk, for the font preload
    in every sketch-rendering surface. Server-derived so a vendored runtime
    upgrade that rotates or adds subsets can never silently re-open the
    measure-before-fonts race (labels render offset until an edit forces a
    re-measure — the stored geometry was right all along)."""
    folder = _ASSET_DIR / "sketch-assets" / "fonts" / "Excalifont"
    try:
        return ",".join(sorted(
            path.stem.rsplit("-", 1)[-1]
            for path in folder.glob("Excalifont-Regular-*.woff2")
        ))
    except OSError:
        return ""


_EXCALIFONT_HASHES = _excalifont_hashes()
