def _blocked_export_path(value: Any) -> bool:
    try:
        lowered_path = tuple(part.lower() for part in Path(str(value)).parts)
    except (TypeError, ValueError):
        return False
    return any(
        lowered_path[index:index + len(blocked)] == blocked
        for blocked in _BLOCKED_EXPORT_PATH_SEGMENTS
        for index in range(len(lowered_path) - len(blocked) + 1)
    )


def _is_html_document_payload(payload: Any) -> bool:
    if not isinstance(payload, dict):
        return False
    for key in ("original_name", "source_path", "storage_path", "path"):
        raw = str(payload.get(key) or "").strip()
        if raw and Path(raw).suffix.lower() in {".htm", ".html"}:
            return True
    return False


