def _ensure_briefs_schema(conn: Any) -> None:
    """Run the briefs DDL without waiting behind a long lock holder."""
    try:
        exists = conn.execute(
            "SELECT to_regclass('rvbbit.calliope_briefs') IS NOT NULL "
            "AND to_regclass('rvbbit.calliope_brief_feedback') IS NOT NULL "
            "AND to_regclass('rvbbit.calliope_identity_aliases') IS NOT NULL AS ok"
        ).fetchone()
        if exists and exists.get("ok"):
            return
    except Exception:  # noqa: BLE001 — fall through to the guarded DDL
        pass
    try:
        conn.execute("SELECT set_config('lock_timeout', '5000', true)")
        conn.execute(_BRIEF_DDL)
    except Exception as exc:  # noqa: BLE001
        print(f"WARNING: briefs schema ensure deferred (lock or DDL error): {exc}", file=os.sys.stderr)
    finally:
        try:
            conn.execute("SELECT set_config('lock_timeout', '0', true)")
        except Exception:  # noqa: BLE001
            pass


_CITATION_EVENTS_DDL = """
CREATE TABLE IF NOT EXISTS rvbbit.calliope_citation_events (
    id bigserial PRIMARY KEY,
    owner_email text NOT NULL,
    session_id uuid,
    turn_id uuid,
    surface_id uuid,
    kind text NOT NULL,
    value text,
    via text,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS calliope_citation_events_created_idx
    ON rvbbit.calliope_citation_events (created_at DESC);
CREATE OR REPLACE VIEW rvbbit.calliope_citation_event_stats AS
SELECT date_trunc('day', created_at)::date AS day,
       count(*) FILTER (WHERE kind = 'chip_click') AS chip_clicks,
       count(*) FILTER (WHERE kind = 'chip_menu_pick') AS chip_menu_picks,
       count(*) FILTER (WHERE kind = 'ledger_open') AS ledger_opens,
       count(*) FILTER (WHERE kind = 'ledger_open' AND via = 'spotlight') AS ledger_opens_of_spotlighted,
       count(*) FILTER (WHERE kind = 'ledger_open' AND via = 'chip') AS ledger_opens_of_chipped,
       count(DISTINCT owner_email) AS people
  FROM rvbbit.calliope_citation_events
 GROUP BY 1 ORDER BY 1 DESC;
COMMENT ON TABLE rvbbit.calliope_citation_events IS 'How people reach Stage results from the chat: value-chip clicks and menu picks versus opening evidence-ledger rows by hand. Answers whether the chips and spotlights actually carry the reader to the result.';
"""


def _ensure_citation_events_schema(conn: Any) -> None:
    """Run the citation-events DDL without waiting behind a long lock holder."""
    try:
        exists = conn.execute(
            "SELECT to_regclass('rvbbit.calliope_citation_events') IS NOT NULL "
            "AND to_regclass('rvbbit.calliope_citation_event_stats') IS NOT NULL AS ok"
        ).fetchone()
        if exists and exists.get("ok"):
            return
    except Exception:  # noqa: BLE001 — fall through to the guarded DDL
        pass
    try:
        conn.execute("SELECT set_config('lock_timeout', '5000', true)")
        conn.execute(_CITATION_EVENTS_DDL)
    except Exception as exc:  # noqa: BLE001
        print(f"WARNING: citation events schema ensure deferred (lock or DDL error): {exc}", file=os.sys.stderr)
    finally:
        try:
            conn.execute("SELECT set_config('lock_timeout', '0', true)")
        except Exception:  # noqa: BLE001
            pass


_BRIEF_DDL = """
CREATE TABLE IF NOT EXISTS rvbbit.calliope_briefs (
    id uuid PRIMARY KEY,
    owner_email text NOT NULL,
    brief_date date NOT NULL,
    timezone text NOT NULL DEFAULT 'UTC',
    session_id uuid NOT NULL REFERENCES rvbbit.calliope_sessions(id) ON DELETE CASCADE,
    window_start timestamptz NOT NULL,
    window_end timestamptz NOT NULL,
    latest_surface_id uuid REFERENCES rvbbit.calliope_surfaces(id) ON DELETE SET NULL,
    item_count integer NOT NULL DEFAULT 0,
    source_count integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    refreshed_at timestamptz,
    CONSTRAINT calliope_briefs_owner_date_key UNIQUE (owner_email,brief_date),
    CONSTRAINT calliope_briefs_window_check CHECK (window_end > window_start),
    CONSTRAINT calliope_briefs_item_count_check CHECK (item_count >= 0),
    CONSTRAINT calliope_briefs_source_count_check CHECK (source_count >= 0)
);
CREATE INDEX IF NOT EXISTS calliope_briefs_owner_refreshed_idx
    ON rvbbit.calliope_briefs (owner_email,refreshed_at DESC NULLS LAST);
CREATE INDEX IF NOT EXISTS calliope_briefs_session_idx
    ON rvbbit.calliope_briefs (session_id);
CREATE TABLE IF NOT EXISTS rvbbit.calliope_brief_feedback (
    owner_email text NOT NULL,
    observation_key text NOT NULL,
    source text NOT NULL DEFAULT '',
    verdict text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_email,observation_key),
    CONSTRAINT calliope_brief_feedback_verdict_check
        CHECK (verdict IN ('relevant','not_mine'))
);
CREATE TABLE IF NOT EXISTS rvbbit.calliope_identity_aliases (
    id uuid PRIMARY KEY,
    owner_email text NOT NULL,
    source text NOT NULL DEFAULT '*',
    alias_kind text NOT NULL DEFAULT 'name',
    alias_value text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT calliope_identity_alias_kind_check
        CHECK (alias_kind IN ('email','name','external_id'))
);
CREATE UNIQUE INDEX IF NOT EXISTS calliope_identity_aliases_owner_source_value_idx
    ON rvbbit.calliope_identity_aliases
       (lower(owner_email),lower(source),lower(alias_value));
CREATE UNIQUE INDEX IF NOT EXISTS calliope_briefs_id_owner_idx
    ON rvbbit.calliope_briefs (id,owner_email);
CREATE TABLE IF NOT EXISTS rvbbit.calliope_daily_notes (
    id uuid PRIMARY KEY,
    brief_id uuid NOT NULL,
    owner_email text NOT NULL,
    note_date date NOT NULL,
    body text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT calliope_daily_notes_body_check
        CHECK (char_length(btrim(body)) BETWEEN 1 AND 12000)
);
CREATE INDEX IF NOT EXISTS calliope_daily_notes_owner_date_idx
    ON rvbbit.calliope_daily_notes (owner_email,note_date DESC,created_at DESC);
CREATE INDEX IF NOT EXISTS calliope_daily_notes_brief_created_idx
    ON rvbbit.calliope_daily_notes (brief_id,created_at,id);
DO $do$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname='calliope_daily_notes_brief_owner_fkey'
           AND conrelid='rvbbit.calliope_daily_notes'::regclass
    ) THEN
        ALTER TABLE rvbbit.calliope_daily_notes
            ADD CONSTRAINT calliope_daily_notes_brief_owner_fkey
            FOREIGN KEY (brief_id,owner_email)
            REFERENCES rvbbit.calliope_briefs(id,owner_email) ON DELETE CASCADE;
    END IF;
END
$do$;
CREATE TABLE IF NOT EXISTS rvbbit.calliope_daily_note_links (
    note_id uuid NOT NULL REFERENCES rvbbit.calliope_daily_notes(id) ON DELETE CASCADE,
    ordinal smallint NOT NULL,
    kg_node_id bigint REFERENCES rvbbit.kg_nodes(node_id) ON DELETE SET NULL,
    graph_id text NOT NULL DEFAULT 'brain',
    node_kind text NOT NULL,
    entity_kind text NOT NULL,
    label text NOT NULL,
    properties jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (note_id,ordinal),
    CONSTRAINT calliope_daily_note_links_ordinal_check
        CHECK (ordinal BETWEEN 0 AND 23),
    CONSTRAINT calliope_daily_note_links_entity_kind_check
        CHECK (entity_kind IN ('person','place','thing','project','ticket'))
);
CREATE UNIQUE INDEX IF NOT EXISTS calliope_daily_note_links_node_idx
    ON rvbbit.calliope_daily_note_links (note_id,kg_node_id)
    WHERE kg_node_id IS NOT NULL;
CREATE OR REPLACE VIEW rvbbit.calliope_private_note_edges AS
SELECT n.owner_email,n.note_date,n.id AS note_id,
       'daily_note'::text AS subject_kind,n.id::text AS subject_key,
       'mentions'::text AS predicate,l.entity_kind AS object_kind,
       coalesce(l.kg_node_id::text,lower(l.label)) AS object_key,
       l.kg_node_id,l.graph_id,l.node_kind,l.label,l.properties,n.created_at
  FROM rvbbit.calliope_daily_notes n
  JOIN rvbbit.calliope_daily_note_links l ON l.note_id=n.id;
"""

_BRAIN_WORK_DDL = """
CREATE TABLE IF NOT EXISTS rvbbit.calliope_brain_work_profiles (
    source_id bigint NOT NULL REFERENCES rvbbit.brain_sources(source_id) ON DELETE CASCADE,
    doc_type text NOT NULL DEFAULT 'document',
    shape_hash text NOT NULL,
    mapping_version integer NOT NULL DEFAULT 1,
    profile_source text NOT NULL DEFAULT 'inferred',
    status text NOT NULL DEFAULT 'possible',
    work_kind text NOT NULL DEFAULT 'work_item',
    confidence double precision NOT NULL DEFAULT 0,
    field_map jsonb NOT NULL DEFAULT '{}'::jsonb,
    lifecycle_map jsonb NOT NULL DEFAULT '{}'::jsonb,
    qualification jsonb NOT NULL DEFAULT '{}'::jsonb,
    sample_count integer NOT NULL DEFAULT 0,
    document_count bigint NOT NULL DEFAULT 0,
    last_source_sync_at timestamptz,
    last_document_ingested_at timestamptz,
    last_indexed_at timestamptz,
    profiled_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    last_error text,
    PRIMARY KEY (source_id,doc_type),
    CONSTRAINT calliope_brain_work_profiles_status_check
        CHECK (status IN ('active','possible','ignored','error')),
    CONSTRAINT calliope_brain_work_profiles_source_check
        CHECK (profile_source IN ('provider','source','provider+source','inferred')),
    CONSTRAINT calliope_brain_work_profiles_confidence_check
        CHECK (confidence BETWEEN 0 AND 1),
    CONSTRAINT calliope_brain_work_profiles_counts_check
        CHECK (sample_count >= 0 AND document_count >= 0),
    CONSTRAINT calliope_brain_work_profiles_map_check
        CHECK (jsonb_typeof(field_map)='object' AND jsonb_typeof(lifecycle_map)='object'
           AND jsonb_typeof(qualification)='object')
);
CREATE TABLE IF NOT EXISTS rvbbit.calliope_brain_work_items (
    doc_id bigint PRIMARY KEY REFERENCES rvbbit.brain_documents(doc_id) ON DELETE CASCADE,
    source_id bigint NOT NULL REFERENCES rvbbit.brain_sources(source_id) ON DELETE CASCADE,
    profile_doc_type text NOT NULL DEFAULT 'document',
    profile_shape_hash text NOT NULL,
    work_kind text NOT NULL DEFAULT 'work_item',
    identifier text,
    title text NOT NULL,
    url text,
    status_label text,
    lifecycle text NOT NULL DEFAULT 'unknown',
    due_at timestamptz,
    priority_label text,
    source_updated_at timestamptz,
    relations jsonb NOT NULL DEFAULT '{}'::jsonb,
    project jsonb NOT NULL DEFAULT '{}'::jsonb,
    facts jsonb NOT NULL DEFAULT '{}'::jsonb,
    index_run_id uuid NOT NULL,
    indexed_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT calliope_brain_work_items_lifecycle_check
        CHECK (lifecycle IN ('open','in_progress','blocked','review','closed','canceled','unknown')),
    CONSTRAINT calliope_brain_work_items_json_check
        CHECK (jsonb_typeof(relations)='object' AND jsonb_typeof(project)='object'
           AND jsonb_typeof(facts)='object')
);
CREATE INDEX IF NOT EXISTS calliope_brain_work_items_source_lifecycle_idx
    ON rvbbit.calliope_brain_work_items (source_id,lifecycle,source_updated_at DESC NULLS LAST);
CREATE INDEX IF NOT EXISTS calliope_brain_work_items_active_due_idx
    ON rvbbit.calliope_brain_work_items (due_at,source_id)
    WHERE lifecycle IN ('open','in_progress','blocked','review');
CREATE INDEX IF NOT EXISTS calliope_brain_work_items_relations_idx
    ON rvbbit.calliope_brain_work_items USING gin (relations jsonb_path_ops);
UPDATE rvbbit.brain_doc_providers
SET observation_map = jsonb_build_object(
    'identity_directory', jsonb_build_object(
        'server', 'linear',
        'tool', 'linear_getUsers',
        'args', '{}'::jsonb,
        'email_paths', jsonb_build_array('$.email'),
        'aliases', jsonb_build_object(
            'external_id', jsonb_build_array('$.id'),
            'name', jsonb_build_array('$.name', '$.displayName')
        ),
        'ttl_seconds', 900
    )
) || observation_map,
    updated_at = now()
WHERE provider = 'linear-issues'
  AND NOT (observation_map ? 'identity_directory');
"""

_GOOGLE_CALENDAR_DDL = """
CREATE TABLE IF NOT EXISTS rvbbit.calliope_google_calendar_connections (
    owner_email text PRIMARY KEY,
    google_email text NOT NULL,
    refresh_token_ciphertext text NOT NULL,
    scopes text[] NOT NULL DEFAULT '{}'::text[],
    sync_token text,
    status text NOT NULL DEFAULT 'connected',
    connected_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    last_synced_at timestamptz,
    last_full_sync_at timestamptz,
    last_error text,
    CONSTRAINT calliope_google_calendar_connections_status_check
        CHECK (status IN ('connected','needs_reconnect','error'))
);
CREATE TABLE IF NOT EXISTS rvbbit.calliope_google_calendar_events (
    owner_email text NOT NULL REFERENCES rvbbit.calliope_google_calendar_connections(owner_email)
        ON DELETE CASCADE,
    calendar_id text NOT NULL DEFAULT 'primary',
    event_id text NOT NULL,
    recurring_event_id text,
    ical_uid text,
    status text NOT NULL DEFAULT 'confirmed',
    visibility text NOT NULL DEFAULT 'default',
    event_type text NOT NULL DEFAULT 'default',
    summary text NOT NULL DEFAULT '',
    description text NOT NULL DEFAULT '',
    location text NOT NULL DEFAULT '',
    html_link text,
    meeting_link text,
    organizer jsonb NOT NULL DEFAULT '{}'::jsonb,
    attendees jsonb NOT NULL DEFAULT '[]'::jsonb,
    starts_at timestamptz,
    ends_at timestamptz,
    all_day boolean NOT NULL DEFAULT false,
    response_status text,
    transparency text,
    etag text,
    google_updated_at timestamptz,
    synced_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_email,calendar_id,event_id),
    CONSTRAINT calliope_google_calendar_events_organizer_check
        CHECK (jsonb_typeof(organizer) = 'object'),
    CONSTRAINT calliope_google_calendar_events_attendees_check
        CHECK (jsonb_typeof(attendees) = 'array')
);
CREATE INDEX IF NOT EXISTS calliope_google_calendar_events_owner_start_idx
    ON rvbbit.calliope_google_calendar_events (owner_email,starts_at)
    WHERE status <> 'cancelled';
CREATE INDEX IF NOT EXISTS calliope_google_calendar_events_owner_updated_idx
    ON rvbbit.calliope_google_calendar_events (owner_email,google_updated_at DESC NULLS LAST);
CREATE OR REPLACE VIEW rvbbit.calliope_private_calendar_edges AS
WITH raw_edges AS (
    SELECT e.owner_email,e.calendar_id,e.event_id,
           'calendar_event'::text AS subject_kind,e.event_id AS subject_key,
           'involves'::text AS predicate,'person'::text AS object_kind,
           lower(a.item->>'email') AS object_key,
           coalesce(nullif(a.item->>'display_name',''),a.item->>'email') AS label,
           jsonb_strip_nulls(jsonb_build_object(
               'email',lower(a.item->>'email'),
               'response_status',a.item->>'response_status',
               'organizer',(a.item->>'organizer')::boolean,
               'self',(a.item->>'self')::boolean
           )) AS properties,e.starts_at,e.ends_at
      FROM rvbbit.calliope_google_calendar_events e
 CROSS JOIN LATERAL jsonb_array_elements(e.attendees) AS a(item)
     WHERE e.status <> 'cancelled' AND nullif(a.item->>'email','') IS NOT NULL
    UNION ALL
    SELECT e.owner_email,e.calendar_id,e.event_id,
           'calendar_event'::text,e.event_id,'organized_by'::text,'person'::text,
           lower(e.organizer->>'email'),
           coalesce(nullif(e.organizer->>'display_name',''),e.organizer->>'email'),
           jsonb_strip_nulls(jsonb_build_object('email',lower(e.organizer->>'email'))),
           e.starts_at,e.ends_at
      FROM rvbbit.calliope_google_calendar_events e
     WHERE e.status <> 'cancelled' AND nullif(e.organizer->>'email','') IS NOT NULL
    UNION ALL
    SELECT e.owner_email,e.calendar_id,e.event_id,
           'calendar_event'::text,e.event_id,'at'::text,'place'::text,
           lower(e.location),e.location,jsonb_build_object('label',e.location),
           e.starts_at,e.ends_at
      FROM rvbbit.calliope_google_calendar_events e
     WHERE e.status <> 'cancelled' AND nullif(e.location,'') IS NOT NULL
)
SELECT r.owner_email,r.calendar_id,r.event_id,r.subject_kind,r.subject_key,
       r.predicate,r.object_kind,r.object_key,r.label,r.properties,
       r.starts_at,r.ends_at,
       resolved.node_id AS kg_node_id,
       resolved.graph_id,
       resolved.kind AS node_kind,
       resolved.label AS canonical_label,
       resolved.match_basis,
       resolved.match_confidence
  FROM raw_edges r
  LEFT JOIN LATERAL (
        WITH direct_lookup(match_value,match_basis,match_priority,match_confidence) AS (
            VALUES
              (rvbbit.kg_normalize_label(r.object_key),'object_key'::text,0,1.0::double precision),
              (rvbbit.kg_normalize_label(r.label),'display_label'::text,2,0.99::double precision)
        ),
        alias_lookup(match_value,match_basis,match_priority,match_confidence) AS (
            VALUES
              (rvbbit.kg_normalize_label(r.object_key),'object_key_alias'::text,1,1.0::double precision),
              (rvbbit.kg_normalize_label(r.label),'display_alias'::text,3,0.98::double precision)
        ),
        candidates AS (
            SELECT n.node_id,n.graph_id,n.kind,n.label,n.confidence,
                   lookup.match_basis,lookup.match_priority,lookup.match_confidence
              FROM direct_lookup lookup
              JOIN rvbbit.kg_nodes n
                ON n.graph_id='brain' AND n.label_norm=lookup.match_value
            UNION ALL
            SELECT n.node_id,n.graph_id,n.kind,n.label,n.confidence,
                   lookup.match_basis,lookup.match_priority,lookup.match_confidence
              FROM alias_lookup lookup
              JOIN rvbbit.kg_aliases a
                ON a.graph_id='brain' AND a.alias_norm=lookup.match_value
              JOIN rvbbit.kg_nodes n ON n.node_id=a.node_id AND n.graph_id='brain'
        )
        SELECT c.node_id,c.graph_id,c.kind,c.label,c.match_basis,c.match_confidence
          FROM candidates c
         WHERE (
             (r.object_kind='person' AND c.kind IN
               ('person','people','employee','user','contact','assignee','owner'))
             OR
             (r.object_kind='place' AND c.kind IN
               ('place','location','city','country','state','region','address',
                'venue','office','site'))
         )
         ORDER BY c.match_priority,c.confidence DESC,c.node_id
         LIMIT 1
  ) resolved ON true;
"""

_GOOGLE_WORKSPACE_DDL = """
CREATE TABLE IF NOT EXISTS rvbbit.calliope_google_workspace_connections (
    owner_email text PRIMARY KEY,
    google_email text NOT NULL,
    refresh_token_ciphertext text NOT NULL,
    scopes text[] NOT NULL DEFAULT '{}'::text[],
    status text NOT NULL DEFAULT 'connected',
    connected_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    last_used_at timestamptz,
    last_error text,
    CONSTRAINT calliope_google_workspace_connections_status_check
        CHECK (status IN ('connected','needs_reconnect','error'))
);
CREATE TABLE IF NOT EXISTS rvbbit.calliope_google_exports (
    id uuid PRIMARY KEY,
    owner_email text NOT NULL
        REFERENCES rvbbit.calliope_google_workspace_connections(owner_email)
        ON DELETE CASCADE,
    session_id uuid REFERENCES rvbbit.calliope_sessions(id) ON DELETE SET NULL,
    surface_id uuid REFERENCES rvbbit.calliope_surfaces(id) ON DELETE SET NULL,
    provider text NOT NULL DEFAULT 'google_sheets',
    provider_file_id text,
    title text NOT NULL,
    url text,
    sheet_name text NOT NULL DEFAULT 'Data',
    row_count integer NOT NULL DEFAULT 0,
    column_count integer NOT NULL DEFAULT 0,
    status text NOT NULL DEFAULT 'pending',
    source jsonb NOT NULL DEFAULT '{}'::jsonb,
    error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT calliope_google_exports_provider_check
        CHECK (provider IN ('google_sheets')),
    CONSTRAINT calliope_google_exports_status_check
        CHECK (status IN ('pending','complete','failed')),
    CONSTRAINT calliope_google_exports_source_check
        CHECK (jsonb_typeof(source) = 'object')
);
CREATE INDEX IF NOT EXISTS calliope_google_exports_owner_created_idx
    ON rvbbit.calliope_google_exports (owner_email,created_at DESC);
CREATE INDEX IF NOT EXISTS calliope_google_exports_surface_idx
    ON rvbbit.calliope_google_exports (surface_id,created_at DESC)
    WHERE surface_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS rvbbit.calliope_google_imports (
    id uuid PRIMARY KEY,
    owner_email text NOT NULL
        REFERENCES rvbbit.calliope_google_workspace_connections(owner_email)
        ON DELETE CASCADE,
    session_id uuid NOT NULL REFERENCES rvbbit.calliope_sessions(id) ON DELETE CASCADE,
    surface_id uuid NOT NULL REFERENCES rvbbit.calliope_surfaces(id) ON DELETE CASCADE,
    provider text NOT NULL DEFAULT 'google_sheets',
    provider_file_id text NOT NULL,
    provider_sheet_id bigint NOT NULL,
    spreadsheet_title text NOT NULL,
    sheet_name text NOT NULL,
    selected_range text,
    first_row_header boolean NOT NULL DEFAULT true,
    row_count integer NOT NULL DEFAULT 0,
    column_count integer NOT NULL DEFAULT 0,
    snapshot_hash text NOT NULL,
    operation text NOT NULL DEFAULT 'import',
    status text NOT NULL DEFAULT 'active',
    last_checked_at timestamptz NOT NULL DEFAULT now(),
    superseded_at timestamptz,
    last_error text,
    source jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT calliope_google_imports_provider_check
        CHECK (provider IN ('google_sheets')),
    CONSTRAINT calliope_google_imports_operation_check
        CHECK (operation IN ('import','refresh')),
    CONSTRAINT calliope_google_imports_status_check
        CHECK (status IN ('active','superseded')),
    CONSTRAINT calliope_google_imports_source_check
        CHECK (jsonb_typeof(source) = 'object')
);
ALTER TABLE rvbbit.calliope_google_imports
    ADD COLUMN IF NOT EXISTS operation text NOT NULL DEFAULT 'import',
    ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'active',
    ADD COLUMN IF NOT EXISTS last_checked_at timestamptz NOT NULL DEFAULT now(),
    ADD COLUMN IF NOT EXISTS superseded_at timestamptz,
    ADD COLUMN IF NOT EXISTS last_error text;
DO $ddl$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'rvbbit.calliope_google_imports'::regclass
           AND conname = 'calliope_google_imports_operation_check'
    ) THEN
        ALTER TABLE rvbbit.calliope_google_imports
            ADD CONSTRAINT calliope_google_imports_operation_check
            CHECK (operation IN ('import','refresh'));
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'rvbbit.calliope_google_imports'::regclass
           AND conname = 'calliope_google_imports_status_check'
    ) THEN
        ALTER TABLE rvbbit.calliope_google_imports
            ADD CONSTRAINT calliope_google_imports_status_check
            CHECK (status IN ('active','superseded'));
    END IF;
END
$ddl$;
WITH ranked AS (
    SELECT id,row_number() OVER (
        PARTITION BY lower(owner_email),provider_file_id,provider_sheet_id,
                     coalesce(selected_range,''),first_row_header
        ORDER BY created_at DESC,id DESC
    ) AS position
    FROM rvbbit.calliope_google_imports
    WHERE status='active'
)
UPDATE rvbbit.calliope_google_imports i
SET status='superseded',superseded_at=coalesce(i.superseded_at,now())
FROM ranked r WHERE i.id=r.id AND r.position>1;
CREATE INDEX IF NOT EXISTS calliope_google_imports_owner_created_idx
    ON rvbbit.calliope_google_imports (owner_email,created_at DESC);
CREATE INDEX IF NOT EXISTS calliope_google_imports_file_idx
    ON rvbbit.calliope_google_imports (owner_email,provider_file_id,provider_sheet_id,created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS calliope_google_imports_active_source_uidx
    ON rvbbit.calliope_google_imports (
        lower(owner_email),provider_file_id,provider_sheet_id,
        coalesce(selected_range,''),first_row_header
    ) WHERE status='active';
CREATE INDEX IF NOT EXISTS calliope_google_imports_status_idx
    ON rvbbit.calliope_google_imports (owner_email,status,created_at DESC);
CREATE TABLE IF NOT EXISTS rvbbit.calliope_google_document_imports (
    id uuid PRIMARY KEY,
    owner_email text NOT NULL
        REFERENCES rvbbit.calliope_google_workspace_connections(owner_email)
        ON DELETE CASCADE,
    session_id uuid NOT NULL REFERENCES rvbbit.calliope_sessions(id) ON DELETE CASCADE,
    surface_id uuid NOT NULL REFERENCES rvbbit.calliope_surfaces(id) ON DELETE CASCADE,
    brain_doc_id bigint NOT NULL REFERENCES rvbbit.brain_documents(doc_id) ON DELETE CASCADE,
    private_role text NOT NULL,
    provider text NOT NULL DEFAULT 'google_docs',
    provider_file_id text NOT NULL,
    document_title text NOT NULL,
    revision_id text,
    character_count integer NOT NULL DEFAULT 0,
    word_count integer NOT NULL DEFAULT 0,
    tab_count integer NOT NULL DEFAULT 1,
    content_hash text NOT NULL,
    operation text NOT NULL DEFAULT 'import',
    status text NOT NULL DEFAULT 'active',
    last_checked_at timestamptz NOT NULL DEFAULT now(),
    superseded_at timestamptz,
    removed_at timestamptz,
    last_error text,
    source jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT calliope_google_document_imports_provider_check
        CHECK (provider IN ('google_docs')),
    CONSTRAINT calliope_google_document_imports_counts_check
        CHECK (character_count >= 0 AND word_count >= 0 AND tab_count >= 1),
    CONSTRAINT calliope_google_document_imports_operation_check
        CHECK (operation IN ('import','refresh')),
    CONSTRAINT calliope_google_document_imports_status_check
        CHECK (status IN ('active','superseded','removed')),
    CONSTRAINT calliope_google_document_imports_source_check
        CHECK (jsonb_typeof(source) = 'object')
);
ALTER TABLE rvbbit.calliope_google_document_imports
    ADD COLUMN IF NOT EXISTS operation text NOT NULL DEFAULT 'import',
    ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'active',
    ADD COLUMN IF NOT EXISTS last_checked_at timestamptz NOT NULL DEFAULT now(),
    ADD COLUMN IF NOT EXISTS superseded_at timestamptz,
    ADD COLUMN IF NOT EXISTS removed_at timestamptz,
    ADD COLUMN IF NOT EXISTS last_error text;
DO $ddl$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'rvbbit.calliope_google_document_imports'::regclass
           AND conname = 'calliope_google_document_imports_operation_check'
    ) THEN
        ALTER TABLE rvbbit.calliope_google_document_imports
            ADD CONSTRAINT calliope_google_document_imports_operation_check
            CHECK (operation IN ('import','refresh'));
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'rvbbit.calliope_google_document_imports'::regclass
           AND conname = 'calliope_google_document_imports_status_check'
    ) THEN
        ALTER TABLE rvbbit.calliope_google_document_imports
            ADD CONSTRAINT calliope_google_document_imports_status_check
            CHECK (status IN ('active','superseded','removed'));
    END IF;
END
$ddl$;
WITH ranked AS (
    SELECT id,row_number() OVER (
        PARTITION BY lower(owner_email),provider_file_id
        ORDER BY created_at DESC,id DESC
    ) AS position
    FROM rvbbit.calliope_google_document_imports
    WHERE status='active'
)
UPDATE rvbbit.calliope_google_document_imports i
SET status='superseded',superseded_at=coalesce(i.superseded_at,now())
FROM ranked r WHERE i.id=r.id AND r.position>1;
CREATE INDEX IF NOT EXISTS calliope_google_document_imports_owner_created_idx
    ON rvbbit.calliope_google_document_imports (owner_email,created_at DESC);
CREATE INDEX IF NOT EXISTS calliope_google_document_imports_file_idx
    ON rvbbit.calliope_google_document_imports (owner_email,provider_file_id,created_at DESC);
CREATE INDEX IF NOT EXISTS calliope_google_document_imports_brain_doc_idx
    ON rvbbit.calliope_google_document_imports (brain_doc_id,created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS calliope_google_document_imports_active_file_uidx
    ON rvbbit.calliope_google_document_imports (lower(owner_email),provider_file_id)
    WHERE status = 'active';
CREATE INDEX IF NOT EXISTS calliope_google_document_imports_status_idx
    ON rvbbit.calliope_google_document_imports (owner_email,status,created_at DESC);
"""

