def _profile_speech_persona(conn_factory, agent_key: str) -> str:
    """Canonical profile default, refreshed through the profile-hash metadata cache."""
    try:
        profile_key = "default"
        if agent_key != "calliope":
            with conn_factory() as conn:
                row = conn.execute("SELECT profile_name FROM rvbbit.calliope_specialists WHERE specialist_key=%s", (agent_key,)).fetchone()
            if not row or not row.get("profile_name"):
                return ""
            profile_key = row["profile_name"]
        for profile in hermes_profiles.profiles().get("profiles", []):
            if profile.get("key") == profile_key:
                return _clean_voice_personality(profile.get("speech_persona"))
    except Exception:
        logging.getLogger(__name__).warning("Could not resolve speech persona default for %s", agent_key)
    return ""


def _stored_speech_persona(conn_factory, owner: str, agent_key: str) -> str:
    with conn_factory() as conn:
        if agent_key == "calliope":
            row = conn.execute("SELECT response_personality AS personality FROM rvbbit.calliope_response_preferences WHERE owner_email=%s", (owner,)).fetchone()
        else:
            row = conn.execute("SELECT personality FROM rvbbit.calliope_agent_speech_personas WHERE owner_email=%s AND agent_key=%s", (owner, agent_key)).fetchone()
    return _clean_voice_personality(row.get("personality") if row else "")


def _agent_speech_persona(conn_factory, owner: str, agent_key: str, fallback: str = "") -> str:
    return _stored_speech_persona(conn_factory, owner, agent_key) or _profile_speech_persona(conn_factory, agent_key) or _clean_voice_personality(fallback)


def _speech_persona_settings(conn_factory, owner: str, agent_key: str) -> dict:
    stored = _stored_speech_persona(conn_factory, owner, agent_key)
    default = _profile_speech_persona(conn_factory, agent_key)
    return {"agent_key": agent_key, "personality": stored or default,
            "default_personality": default, "source": "custom" if stored else "profile"}


def _save_agent_speech_persona(conn_factory, owner: str, agent_key: str, personality: str):
    personality = _clean_voice_personality(personality)
    with conn_factory() as conn:
        if agent_key == "calliope":
            conn.execute("INSERT INTO rvbbit.calliope_response_preferences(owner_email,response_personality) VALUES(%s,%s) "
                         "ON CONFLICT(owner_email) DO UPDATE SET response_personality=EXCLUDED.response_personality,updated_at=now()", (owner, personality))
        else:
            conn.execute("INSERT INTO rvbbit.calliope_agent_speech_personas(owner_email,agent_key,personality) VALUES(%s,%s,%s) "
                         "ON CONFLICT(owner_email,agent_key) DO UPDATE SET personality=EXCLUDED.personality,updated_at=now()", (owner, agent_key, personality))
    return personality


def _stored_voice_direction(conn_factory, owner: str, agent_key: str) -> str:
    """The delivery direction this person set for an agent, so a take the server makes
    on its own is directed the way their own requests are."""
    try:
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT delivery_direction AS direction FROM rvbbit.calliope_response_preferences WHERE owner_email=%s"
                if agent_key == "calliope" else
                "SELECT delivery_direction AS direction FROM rvbbit.calliope_agent_speech_personas "
                "WHERE owner_email=%s AND agent_key=%s",
                (owner,) if agent_key == "calliope" else (owner, agent_key),
            ).fetchone()
    except Exception:  # noqa: BLE001 - an undirected take is still a take
        return ""
    return _clean_voice_direction((row or {}).get("direction"))


def _save_voice_direction(conn_factory, owner: str, agent_key: str, direction: str) -> str:
    direction = _clean_voice_direction(direction)
    with conn_factory() as conn:
        if agent_key == "calliope":
            conn.execute("INSERT INTO rvbbit.calliope_response_preferences(owner_email,delivery_direction) VALUES(%s,%s) "
                         "ON CONFLICT(owner_email) DO UPDATE SET delivery_direction=EXCLUDED.delivery_direction,updated_at=now()",
                         (owner, direction))
        else:
            conn.execute("INSERT INTO rvbbit.calliope_agent_speech_personas(owner_email,agent_key,delivery_direction) "
                         "VALUES(%s,%s,%s) ON CONFLICT(owner_email,agent_key) DO UPDATE SET "
                         "delivery_direction=EXCLUDED.delivery_direction,updated_at=now()", (owner, agent_key, direction))
    return direction


def _agent_voice_instruction(instruction: str, agent_key: str, name: str) -> str:
    if agent_key == "calliope":
        return instruction
    return instruction.replace("Calliope", name) + " The speaking agent's identity is " + json.dumps(name) + ". Keep this identity; never introduce yourself as Calliope."


def _prepare_agent_voice_preview(conn_factory, config, owner: str, agent: dict, personality: str) -> str:
    source = hermes_profiles.clean_voice_preview_text(agent.get("voice_preview_text")) or f"Hello, I'm {agent['name']}. I'm ready to get to work."
    memory = _presentation_memory_recall(conn_factory, config, owner, "expressive", "Introduce yourself and briefly explain your role.", source, agent["key"])
    instruction = _agent_voice_instruction(_voice_rewrite_instruction("expressive", personality), agent["key"], agent["name"])
    instruction += " This is a short voice audition: revoice the supplied first-person introduction, keep its name and role, and do not add business claims, recollections, or a conversation recap."
    script, _, _ = _generate_voice_script(config, source, "expressive", personality, owner, [], instruction, memory.get("items"))
    # Rehearsals can recall rapport, but are never retained as real exchanges.
    return script


