_RESPONSE_PREFERENCE_MODES = frozenset({"off", "fast", "expressive"})
_RESPONSE_PREFERENCE_VERSION = 1


def _default_response_preferences() -> dict[str, Any]:
    return {
        "version": _RESPONSE_PREFERENCE_VERSION,
        "conversational_answers": True,
        "read_aloud_mode": "off",
        "response_personality": "",
        "speak_working_updates": False,
    }


def _normalize_response_preferences(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("response preferences must be an object")
    if value.get("version") != _RESPONSE_PREFERENCE_VERSION:
        raise ValueError("response preferences must use version 1")
    mode = str(value.get("read_aloud_mode") or "").strip().lower()
    if mode not in _RESPONSE_PREFERENCE_MODES:
        raise ValueError("read aloud mode must be off, fast, or expressive")
    mode = "expressive" if mode == "fast" else mode  # one kind of take; fast meant voice on
    personality_value = value.get("response_personality")
    if personality_value is None:
        personality_value = ""
    if not isinstance(personality_value, str):
        raise ValueError("response personality must be text")
    personality = re.sub(r"[\x00-\x1f\x7f]", " ", personality_value)[:600]
    return {
        "version": _RESPONSE_PREFERENCE_VERSION,
        "conversational_answers": value.get("conversational_answers") is True,
        "read_aloud_mode": mode,
        "response_personality": personality,
        "speak_working_updates": value.get("speak_working_updates") is True,
    }


def _response_preferences_payload(owner: str, row: Any = None) -> dict[str, Any]:
    value = dict(row or {})
    preferences = _default_response_preferences()
    if value:
        preferences.update({
            "conversational_answers": value.get("conversational_answers") is True,
            "read_aloud_mode": (
                "off" if str(value.get("read_aloud_mode") or "off") not in {"fast", "expressive"}
                else "expressive"
            ),
            "response_personality": str(value.get("response_personality") or "")[:600],
            "speak_working_updates": value.get("speak_working_updates") is True,
        })
    return {
        "owner": owner,
        "exists": bool(value),
        "preferences": preferences,
        "updated_at": _now_iso(value.get("updated_at")),
    }

_APPEARANCE_LIBRARY_URL_RE = re.compile(
    r"^(?:/theme/images/full/[A-Za-z0-9][A-Za-z0-9_-]{0,160}\.webp|"
    r"/api/desktop/wallpapers/[A-Za-z0-9._%+-]{1,220}\?"
    r"variant=(?:1080|1440|original))$"
)
_APPEARANCE_TOKEN_KEY_RE = re.compile(r"^--[a-z][a-z0-9-]{0,80}$")
_APPEARANCE_UPLOAD_MIMES = frozenset({
    "image/png", "image/jpeg", "image/webp", "image/gif", "image/avif",
})


def _normalize_appearance_preference(value: Any) -> dict[str, Any] | None:
    """Validate the compact browser theme before it becomes shared state."""
    if value is None:
        return None
    if not isinstance(value, dict) or value.get("version") != 1:
        raise ValueError("appearance must use version 1")
    source = value.get("source")
    if not isinstance(source, dict):
        raise ValueError("appearance source is required")
    source_kind = str(source.get("kind") or "")
    if source_kind == "library":
        source_id = str(source.get("id") or "")
        source_url = str(source.get("url") or "")
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,160}", source_id):
            raise ValueError("appearance library id is invalid")
        if not _APPEARANCE_LIBRARY_URL_RE.fullmatch(source_url):
            raise ValueError("appearance library URL is invalid")
        normalized_source: dict[str, Any] = {
            "kind": "library",
            "id": source_id,
            "url": source_url,
        }
        label = str(source.get("label") or "").strip()
        original_url = str(source.get("originalUrl") or "")
        if label:
            normalized_source["label"] = label[:240]
        if original_url and _APPEARANCE_LIBRARY_URL_RE.fullmatch(original_url):
            normalized_source["originalUrl"] = original_url
    elif source_kind == "upload":
        name = re.sub(r"[\x00-\x1f\x7f]", "", str(source.get("name") or "wallpaper"))
        normalized_source = {"kind": "upload", "name": name[:240] or "wallpaper"}
    elif source_kind == "default":
        normalized_source = {"kind": "default"}
        label = str(source.get("label") or "").strip()
        if label:
            normalized_source["label"] = label[:240]
    else:
        raise ValueError("appearance source kind is invalid")

    palette = value.get("palette")
    if not isinstance(palette, dict):
        raise ValueError("appearance palette is required")
    try:
        base_hue = float(palette.get("baseHue"))
        chroma = float(palette.get("chroma"))
    except (TypeError, ValueError) as exc:
        raise ValueError("appearance palette is invalid") from exc
    if not math.isfinite(base_hue) or not math.isfinite(chroma):
        raise ValueError("appearance palette is invalid")
    normalized_palette: dict[str, Any] = {
        "baseHue": base_hue,
        "chroma": chroma,
    }
    for key in (
        "vibrant", "darkVibrant", "lightVibrant", "muted", "darkMuted", "lightMuted",
    ):
        swatch = str(palette.get(key) or "")
        if not swatch or len(swatch) > 180 or re.search(r"[<>{};]", swatch):
            raise ValueError(f"appearance palette {key} is invalid")
        normalized_palette[key] = swatch
    palette_source = str(palette.get("source") or "").strip()
    if palette_source:
        normalized_palette["source"] = palette_source[:240]

    raw_tokens = value.get("tokens")
    if not isinstance(raw_tokens, dict) or len(raw_tokens) > 100:
        raise ValueError("appearance tokens are invalid")
    tokens: dict[str, str] = {}
    for raw_key, raw_value in raw_tokens.items():
        key = str(raw_key)
        token = str(raw_value).strip()
        if not _APPEARANCE_TOKEN_KEY_RE.fullmatch(key):
            continue
        if not token or len(token) > 260 or re.search(r"[<>{};]", token):
            continue
        tokens[key] = token
    if not tokens:
        raise ValueError("appearance tokens are empty")

    background = value.get("background")
    if not isinstance(background, dict):
        background = {}
    background_mode = "solid" if background.get("mode") == "solid" else "image"
    solid_color = str(background.get("solidColor") or "").lower()
    if not re.fullmatch(r"#[0-9a-f]{6}", solid_color):
        solid_color = "#100d0b"

    normalized: dict[str, Any] = {
        "version": 1,
        "source": normalized_source,
        "palette": normalized_palette,
        "tokens": tokens,
        "background": {"mode": background_mode, "solidColor": solid_color},
        "updatedAt": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
    }
    overrides = value.get("paletteOverrides")
    if isinstance(overrides, dict):
        bounded = {
            str(key): raw
            for key, raw in overrides.items()
            if str(key) in normalized_palette and isinstance(raw, (str, int, float))
        }
        if bounded:
            normalized["paletteOverrides"] = bounded
    return normalized


def _appearance_response_payload(row: Any = None) -> dict[str, Any]:
    """Serialize an appearance row without leaking driver-specific values."""
    value = dict(row or {})
    return {
        "appearance": value.get("appearance"),
        "mode": value.get("color_mode"),
        "has_upload": bool(value.get("has_upload")),
        "updated_at": _now_iso(value.get("updated_at")),
    }



def _resolved_appearance_payload(row: Any, workspace: Any, owner: str) -> dict[str, Any]:
    personal = dict(row or {})
    defaults = dict(workspace or {})
    own = personal.get("appearance") is not None
    result = _appearance_response_payload(personal if own else defaults)
    result.update(
        mode=personal.get("color_mode") or defaults.get("color_mode") or "dark",
        personal_mode=personal.get("color_mode"),
        source="personal" if own else "workspace" if defaults.get("appearance") else "builtin",
        owner=owner,
        has_upload=bool(own and personal.get("has_upload")),
    )
    return result


def _seed_action_catalog(conn: Any) -> None:
    for item in _ACTION_LIBRARY_SEED:
        conn.execute(
            "INSERT INTO rvbbit.calliope_action_catalog "
            "(id,version,category,title,summary,description,executor,risk,tags,"
            "input_schema,config,sort_order,active,updated_at) "
            "VALUES (%s,1,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s,true,now()) "
            "ON CONFLICT (id) DO UPDATE SET version=excluded.version,category=excluded.category,"
            "title=excluded.title,summary=excluded.summary,description=excluded.description,"
            "executor=excluded.executor,risk=excluded.risk,tags=excluded.tags,"
            "input_schema=excluded.input_schema,config=excluded.config,sort_order=excluded.sort_order,"
            "active=true,updated_at=now()",
            (
                item["id"], item["category"], item["title"], item["summary"],
                item["description"], item["executor"], item["risk"], item["tags"],
                json.dumps({"fields": item.get("fields") or []}),
                json.dumps({
                    **dict(item.get("config") or {}),
                    "requirements": item.get("requirements") or [],
                    "prompt_template": item.get("prompt_template") or "",
                }),
                int(item.get("sort_order") or 100),
            ),
        )


def _builtin_design_profile_spec() -> dict[str, Any]:
    """Load the checked-in system profile used by both fresh and upgraded UI installs."""
    try:
        spec = json.loads(_ADAPTIVE_DESIGN_PROFILE_SPEC.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeError("Adaptive Calliope Design Profile is missing or invalid") from exc
    if not isinstance(spec, dict):
        raise RuntimeError("Adaptive Calliope Design Profile must be a JSON object")
    if str(spec.get("id")) != _ADAPTIVE_DESIGN_PROFILE_ID:
        raise RuntimeError("Adaptive Calliope Design Profile id changed unexpectedly")
    if str(spec.get("version_id")) != _ADAPTIVE_DESIGN_PROFILE_VERSION_ID:
        raise RuntimeError("Adaptive Calliope Design Profile version id changed unexpectedly")
    return spec


def _builtin_design_profile_specs() -> list[dict[str, Any]]:
    """Keep the two adaptive compositions on the same palette and design rules."""
    adaptive = _builtin_design_profile_spec()
    colors = json.loads(json.dumps(adaptive))
    colors.update({
        "id": _ADAPTIVE_COLORS_PROFILE_ID,
        "version_id": _ADAPTIVE_COLORS_VERSION_ID,
        "version": 1,
        "name": "Adaptive Calliope — No Wallpaper",
        "description": "The same viewer-adaptive palette and editorial system on a quiet, image-free canvas.",
        "source_summary": "Built into Calliope. Shares Adaptive Calliope's typography, composition, and live viewer colors. Wallpaper is disabled by the artifact runtime, including in Stage and captures.",
    })
    colors["tokens"]["behavior"]["wallpaper"] = "none"
    colors["tokens"]["effects"].update({
        "surface_mode": "flat",
        "glass": "Use opaque theme panels. No wallpaper, backdrop blur, or decorative background imagery.",
    })
    colors["markdown"] = colors["markdown"].replace(
        "# Adaptive Calliope\n", "# Adaptive Calliope — No Wallpaper\n", 1,
    ).replace(
        "## Material policy\n" + adaptive["markdown"].split("## Material policy\n", 1)[1].split("\n\n## ", 1)[0],
        "## Material policy\nThe runtime disables wallpaper and its overlay, while keeping all viewer palette and chart tokens live. "
        "Use var(--artifact-bg) for the quiet canvas and var(--artifact-panel) for opaque grouped regions. "
        "Keep the authored body transparent so the runtime can supply the canvas. "
        "Do not add replacement photos, textures, ornamental gradients, or backdrop blur. "
        "Images that are actual report content remain welcome. Separate sections through spacing, alignment, "
        "and selective tonal grouping; avoid giving every module an outline.",
    )
    return [adaptive, colors]


_SYSTEM_DASHBOARD_OWNER = "calliope@system"
_SYSTEM_DASHBOARDS_DIR = _HERE / "system-dashboards"
# slug -> (file, name, description, seed key). System dashboards are owned by
# calliope@system, viewable by the Everyone team, and re-versioned only when
# the bundled content changes. They are seeded only when the extension views
# they read exist, so an older extension never serves a broken page.
_SYSTEM_DASHBOARDS: tuple[tuple[str, str, str, str, str], ...] = (
    (
        "rvbbit-acceleration-health",
        "acceleration-health.html",
        "Acceleration health",
        "RVBBIT acceleration observatory: eligible-table readiness, policy freshness, "
        "variant-layout coverage, worker concurrency, and rebuild cost. System-maintained; "
        "reads rvbbit.accel_observatory_* views.",
        "rvbbit.accel_observatory_coverage",
    ),
)


def _row_value(row: Any, key: str, index: int = 0) -> Any:
    """Read a column from a row regardless of the connection's row factory."""
    if row is None:
        return None
    if isinstance(row, dict):
        return row.get(key)
    return row[index]


def _seed_system_dashboards(conn: Any) -> list[dict[str, Any]]:
    """Publish/refresh the bundled system dashboards without a human caller.

    Idempotent: one rvbbit.dashboards row per slug (owner calliope@system), a new
    dashboard_versions row only when the bundled HTML's sha256 changes, and an
    Everyone view grant so verified people can open it. Skips (and reports) a
    dashboard whose required relation is not installed yet.
    """
    outcomes: list[dict[str, Any]] = []
    if not _row_value(
        conn.execute("SELECT to_regclass('rvbbit.dashboards') IS NOT NULL AS present").fetchone(), "present"
    ):
        return outcomes
    for slug, filename, name, description, required in _SYSTEM_DASHBOARDS:
        path = _SYSTEM_DASHBOARDS_DIR / filename
        try:
            html = path.read_text(encoding="utf-8")
        except OSError as exc:
            outcomes.append({"slug": slug, "status": "missing_file", "error": str(exc)})
            continue
        if required and not _row_value(
            conn.execute("SELECT to_regclass(%s) IS NOT NULL AS present", (required,)).fetchone(), "present"
        ):
            outcomes.append({"slug": slug, "status": "skipped", "reason": f"{required} not installed"})
            continue
        digest = hashlib.sha256(html.encode("utf-8")).hexdigest()
        design_profile = _system_dashboard_design_profile(conn)
        design_version = str((design_profile or {}).get("version_id") or "")
        manifest = {
            "system_dashboard": {
                "key": slug,
                "content_sha256": digest,
                "design_profile_version_id": design_version or None,
                "seeded_by": _SYSTEM_DASHBOARD_OWNER,
            },
            "runtime_kind": "html",
            "app_kind": "dashboard",
        }
        if design_profile:
            manifest["design_profile"] = design_profile
        row = conn.execute(
            "SELECT id, latest_version, manifest FROM rvbbit.dashboards WHERE slug = %s",
            (slug,),
        ).fetchone()
        if row is None:
            dashboard_id = int(_row_value(conn.execute(
                "INSERT INTO rvbbit.dashboards (slug, name, description, owner_email, status, "
                "latest_version, runtime_kind, app_kind, manifest) "
                "VALUES (%s, %s, %s, %s, 'live', 1, 'html', 'dashboard', %s::jsonb) RETURNING id",
                (slug, name, description, _SYSTEM_DASHBOARD_OWNER, json.dumps(manifest)),
            ).fetchone(), "id"))
            version = 1
            status = "created"
        else:
            dashboard_id = int(_row_value(row, "id", 0))
            latest = _row_value(row, "latest_version", 1)
            current = _row_value(row, "manifest", 2)
            if isinstance(current, str):
                try:
                    current = json.loads(current)
                except json.JSONDecodeError:
                    current = {}
            current = current if isinstance(current, dict) else {}
            seed = current.get("system_dashboard") or {}
            previous = seed.get("content_sha256")
            previous_design = str(seed.get("design_profile_version_id") or "")
            if previous == digest and previous_design == design_version:
                outcomes.append({"slug": slug, "status": "unchanged", "version": int(latest or 1)})
                _grant_system_dashboard_to_everyone(conn, dashboard_id)
                continue
            version = int(latest or 0) + 1
            conn.execute(
                "UPDATE rvbbit.dashboards SET name = %s, description = %s, latest_version = %s, "
                "manifest = %s::jsonb, updated_at = now(), status = 'live', archived = false "
                "WHERE id = %s",
                (name, description, version, json.dumps(manifest), dashboard_id),
            )
            status = "updated"
        conn.execute(
            "INSERT INTO rvbbit.dashboard_versions (dashboard_id, version, html, kind, created_by, notes, manifest) "
            "VALUES (%s, %s, %s, 'live', %s, %s, %s::jsonb) ON CONFLICT (dashboard_id, version) DO NOTHING",
            (dashboard_id, version, html, _SYSTEM_DASHBOARD_OWNER,
             f"system dashboard seed {digest[:12]}", json.dumps(manifest)),
        )
        _grant_system_dashboard_to_everyone(conn, dashboard_id)
        outcomes.append({"slug": slug, "status": status, "version": version})
    return outcomes


def _system_dashboard_design_profile(conn: Any) -> dict[str, Any] | None:
    """Freeze the system Adaptive Calliope profile the way a normal publish does,
    so seeded pages theme like every other artifact (live viewer theme, tokens)."""
    import contextlib

    try:
        row = _design_profile_version(
            lambda: contextlib.nullcontext(conn), _ADAPTIVE_DESIGN_PROFILE_VERSION_ID, active_only=True
        )
        return _artifact_design_profile_manifest(row) if row else None
    except Exception as exc:  # noqa: BLE001 — a missing profile must not block the seed
        print(f"WARNING: system dashboard design profile unavailable: {exc}", file=os.sys.stderr)
        return None


def _grant_system_dashboard_to_everyone(conn: Any, dashboard_id: int) -> None:
    if not _row_value(
        conn.execute("SELECT to_regclass('rvbbit.artifact_view_grants') IS NOT NULL AS present").fetchone(), "present"
    ):
        return
    conn.execute(
        "INSERT INTO rvbbit.artifact_view_grants (artifact_id, team_id, granted_by) "
        "SELECT %s, t.id, %s FROM rvbbit.teams t WHERE t.system_key = 'everyone' "
        "AND NOT EXISTS (SELECT 1 FROM rvbbit.artifact_view_grants g "
        "WHERE g.artifact_id = %s AND g.team_id = t.id)",
        (dashboard_id, _SYSTEM_DASHBOARD_OWNER, dashboard_id),
    )


def _seed_builtin_design_profiles(conn: Any) -> None:
    """Make immutable system profiles available even before an extension upgrade."""
    for spec in _builtin_design_profile_specs():
        _seed_builtin_design_profile(conn, spec)
    # Upgrade the default for future turns without rewriting the design contract
    # recorded on historical turns, surfaces, or published artifact versions.
    conn.execute(
        "UPDATE rvbbit.calliope_sessions SET design_profile_version_id=%s::uuid "
        "WHERE design_profile_version_id=%s::uuid",
        (_ADAPTIVE_DESIGN_PROFILE_VERSION_ID, _PREVIOUS_ADAPTIVE_DESIGN_PROFILE_VERSION_ID),
    )


def _seed_builtin_design_profile(conn: Any, spec: dict[str, Any]) -> None:
    profile_id, version_id = str(spec["id"]), str(spec["version_id"])
    version = int(spec["version"])
    markdown = str(spec.get("markdown") or "").strip()
    if not 1 <= len(markdown) <= _MAX_STYLE_MARKDOWN_CHARS:
        raise RuntimeError("Adaptive Calliope Design Profile Markdown is out of bounds")
    tokens = _normalize_design_tokens(spec.get("tokens"))
    compiled = _compile_design_profile(
        str(spec["name"]),
        markdown,
        tokens,
        profile_id,
        version,
    )
    conn.execute(
        "INSERT INTO rvbbit.calliope_design_profiles "
        "(id,owner_email,name,description,current_version,archived) "
        "VALUES (%s::uuid,%s,%s,%s,%s,false) "
        "ON CONFLICT (id) DO UPDATE SET "
        "owner_email=excluded.owner_email,name=excluded.name,"
        "description=excluded.description,current_version=excluded.current_version,archived=false "
        "WHERE (rvbbit.calliope_design_profiles.owner_email,"
        "rvbbit.calliope_design_profiles.name,"
        "rvbbit.calliope_design_profiles.description,"
        "rvbbit.calliope_design_profiles.current_version,"
        "rvbbit.calliope_design_profiles.archived) IS DISTINCT FROM "
        "(excluded.owner_email,excluded.name,excluded.description,excluded.current_version,false)",
        (
            profile_id,
            str(spec.get("owner_email") or "calliope@system"),
            str(spec["name"]),
            str(spec.get("description") or "")[:500],
            version,
        ),
    )
    conn.execute(
        "INSERT INTO rvbbit.calliope_design_profile_versions "
        "(id,profile_id,version,markdown,tokens,compiled_prompt,"
        "source_summary,created_by) "
        "SELECT %s::uuid,%s::uuid,%s,%s,%s::jsonb,%s,%s,%s "
        "WHERE EXISTS (SELECT 1 FROM rvbbit.calliope_design_profiles "
        "WHERE id=%s::uuid) ON CONFLICT DO NOTHING",
        (
            version_id,
            profile_id,
            version,
            markdown,
            json.dumps(tokens, ensure_ascii=False),
            compiled,
            str(spec.get("source_summary") or "")[:4_000],
            str(spec.get("owner_email") or "calliope@system"),
            profile_id,
        ),
    )


def ensure_tables(conn_factory: Callable[..., Any]) -> None:
    orphaned_manual_runs: list[dict[str, Any]] = []
    with conn_factory() as conn:
        # Keep Warehouse startup scoped to the service-owned, idempotent DDL
        # below. Extension-wide migrations are a deployment concern: invoking
        # rvbbit.migrate() here can make an unrelated pending extension
        # migration prevent the HTTP service from starting at all.
        conn.execute(_DDL)
        conn.execute(_SETUP_DDL)
        conn.execute(_SKETCH_DDL)
        # Teams are initialized before Calliope during Warehouse startup. Keep
        # the sharing projection additive here as well so service and extension
        # images can be rolled forward in either order.
        conn.execute(calliope_access.DDL)
        import system_console
        conn.execute(system_console.DDL)
        conn.execute(_STYLE_DDL)
        conn.execute(dashboard_mode.DDL)
        conn.execute(visual_intent.DDL)
        _seed_builtin_design_profiles(conn)
        try:
            _seed_system_dashboards(conn)
        except Exception as exc:  # noqa: BLE001 — a seed must never block Warehouse startup
            print(f"WARNING: system dashboard seed skipped: {exc}", file=os.sys.stderr)
        conn.execute(_HOME_DDL)
        conn.execute(_METRIC_FOLLOW_DDL)
        conn.execute(_WATCH_DDL)
        conn.execute(_INBOX_DDL)
        conn.execute(floor_presentations.NOTIFICATION_LABEL_POLICY_SQL)
        # Work Inbox is an attention surface, not an append-only activity log.
        # Routine receipts age out; explicit user stops are not work at all.
        conn.execute(
            "DELETE FROM rvbbit.calliope_work_items wi USING rvbbit.calliope_turns t "
            "WHERE wi.source='calliope_turn' AND wi.source_ref=t.id::text "
            "AND t.status='interrupted' AND t.error=%s",
            (_USER_STOPPED_TURN_ERROR,),
        )
        conn.execute(
            "UPDATE rvbbit.calliope_work_items SET expires_at=created_at+CASE "
            "WHEN kind='result' THEN interval '7 days' ELSE interval '14 days' END "
            "WHERE expires_at IS NULL AND kind IN ('result','suggestion')"
        )
        conn.execute(
            "UPDATE rvbbit.calliope_work_items SET expires_at=created_at+interval '3 days' "
            "WHERE expires_at IS NULL AND source='calliope_turn'"
        )
        conn.execute(
            "UPDATE rvbbit.calliope_work_items SET state='dismissed',updated_at=now(),"
            "resolved_at=coalesce(resolved_at,now()) WHERE state IN ('unread','seen') "
            "AND expires_at IS NOT NULL AND expires_at<=now()"
        )
        # Named model loadouts for the Models & agents UI (save/apply a whole
        # team's provider+model choices through the batched apply path).
        conn.execute(
            "CREATE TABLE IF NOT EXISTS rvbbit.calliope_model_loadouts ("
            " id uuid PRIMARY KEY DEFAULT gen_random_uuid(),"
            " name text NOT NULL UNIQUE,"
            " owner_email text,"
            " config jsonb NOT NULL,"
            " created_at timestamptz NOT NULL DEFAULT clock_timestamp(),"
            " updated_at timestamptz NOT NULL DEFAULT clock_timestamp())"
        )
        # The agent-to-agent mailbox (0336) references the specialist tables
        # that only the extension chain creates; apply it once they exist so
        # an async delegation can queue its reply from the first turn.
        specialist_relations = conn.execute(
            "SELECT to_regclass('rvbbit.calliope_specialist_runs') AS relation"
        ).fetchall()
        if specialist_relations and specialist_relations[0].get("relation"):
            try:
                import hermes_mirror
                hermes_mirror.ensure_agent_mailbox(conn)
            except Exception as exc:  # noqa: BLE001 — a read-only role gets it from the extension instead
                print(f"WARNING: agent mailbox schema skipped: {exc}", file=os.sys.stderr)
        playbook_relations = conn.execute(
            "SELECT to_regclass('rvbbit.calliope_playbooks') AS relation"
        ).fetchall()
        if playbook_relations and playbook_relations[0].get("relation"):
            # Add the personal handoff once for Playbooks created before the
            # Inbox projection shipped. Never reopen an item on restart; live
            # draft/revision/approval writes maintain it from then on.
            conn.execute(
                "INSERT INTO rvbbit.calliope_work_items "
                "(id,owner_email,session_id,kind,source,source_ref,dedupe_key,title,"
                "summary,urgency,state,context,action_prompt,expires_at) "
                "SELECT gen_random_uuid(),p.owner_email,v.source_session_id,"
                "CASE WHEN p.approved_version=p.latest_version THEN 'result' ELSE 'suggestion' END,"
                "'calliope_playbook',p.id::text,'playbook:'||p.id::text,"
                "CASE WHEN p.approved_version=p.latest_version THEN 'Playbook ready · ' "
                "ELSE 'Review Playbook · ' END||v.title,v.synopsis,'normal','unread',"
                "jsonb_strip_nulls(jsonb_build_object('playbook_id',p.id,'capability_name',"
                "p.capability_name,'version',v.version,'status',CASE WHEN "
                "p.approved_version=p.latest_version THEN 'approved' ELSE 'draft' END,"
                "'source_session_id',v.source_session_id,'open_url',CASE WHEN "
                "v.source_session_id IS NOT NULL THEN '/calliope?session='||v.source_session_id::text END)),"
                "CASE WHEN p.approved_version=p.latest_version THEN 'Use, revise, or share this approved Playbook.' "
                "ELSE 'Review this private Playbook draft and approve it only if the method is reusable.' END,"
                "now()+CASE WHEN p.approved_version=p.latest_version "
                "THEN interval '7 days' ELSE interval '14 days' END "
                "FROM rvbbit.calliope_playbooks p JOIN rvbbit.calliope_playbook_versions v "
                "ON v.playbook_id=p.id AND v.version=p.latest_version WHERE NOT p.archived "
                "AND p.approved_version IS DISTINCT FROM p.latest_version "
                "ON CONFLICT (owner_email,source,dedupe_key) DO NOTHING"
            )
        # The briefs ensure is CREATE TABLE IF NOT EXISTS behind a relation lock; the hourly
        # storage-maintain job held that lock for 20 minutes on the pilot and the server sat
        # unhealthy (no listener) the whole time. Bound the wait; the tables already exist on
        # every install past first boot, and a missed ensure is retried on the next start.
        _ensure_briefs_schema(conn)
        _ensure_citation_events_schema(conn)
        conn.execute(_BRAIN_WORK_DDL)
        calliope_pages.ensure(conn)
        conn.execute(_GOOGLE_CALENDAR_DDL)
        conn.execute(_GOOGLE_WORKSPACE_DDL)
        conn.execute(_INSTRUMENT_DDL)
        if not _cost_caller_schema_ready(conn):
            conn.execute(_COST_CALLER_DDL)
        conn.execute(_WORKFLOW_DDL)
        conn.execute(_WORK_ORDER_DDL)
        conn.execute(_DREAM_DDL)
        conn.execute(dream_handoffs.DDL)
        conn.execute(calliope_observations.DDL)
        conn.execute(calliope_decisions.DDL)
        calliope_inputs.ensure(conn)
        calliope_rooms.ensure(conn)
        conn.execute(_PERSONAL_DREAM_DDL)
        calliope_observations.backfill_dream_observations(conn)
        conn.execute(_DREAM_SCHEDULER_DDL)
        conn.execute(_ACTION_DDL)
        conn.execute(_APPEARANCE_DDL)
        conn.execute(_RESPONSE_PREFERENCES_DDL)
        conn.execute(_AGENT_SPEECH_PERSONAS_DDL)
        conn.execute(_PERSONA_DEFAULT_DDL)
        conn.execute(_PRESENTATION_MEMORY_DDL)
        conn.execute(_TAKES_DDL)
        if conn.execute(
            "SELECT to_regclass('rvbbit.calliope_playbooks') IS NOT NULL AS ready"
        ).fetchone()["ready"]:
            conn.execute(playbook_access.HOMES_DDL)
        _seed_action_catalog(conn)
        # Hermes /v1/runs owns modern turn execution across a server restart.
        # Release only the observer lease so this process can reattach to the
        # same run id. Legacy stream-only turns have no safe resume identity and
        # retain the old interrupted behavior.
        conn.execute(
            "UPDATE rvbbit.calliope_turns "
            "SET runner_id=NULL,lease_expires_at=NULL "
            "WHERE status='running' AND hermes_run_id IS NOT NULL"
        )
        conn.execute(
            "UPDATE rvbbit.calliope_turns "
            "SET status='interrupted',error='warehouse service restarted before a "
            "durable Hermes run was assigned',completed_at=coalesce(completed_at,now()) "
            "WHERE status='running' AND hermes_run_id IS NULL"
        )
        conn.execute(
            "INSERT INTO rvbbit.calliope_work_items "
            "(id,owner_email,session_id,kind,source,source_ref,dedupe_key,title,summary,urgency,context,action_prompt,expires_at) "
            "SELECT gen_random_uuid(),s.owner_email,s.id,'blocked','calliope_turn',t.id::text,t.id::text,"
            "'Calliope work was interrupted',coalesce(nullif(t.error,''),'This turn stopped before Calliope could finish.'),"
            "'high',jsonb_build_object('turn_id',t.id,'session_id',s.id,'user_message',left(t.user_message,1200)),"
            "'Resume this interrupted work. Start from the saved notebook context and determine what remains.',"
            "now()+interval '3 days' "
            "FROM rvbbit.calliope_turns t JOIN rvbbit.calliope_sessions s ON s.id=t.session_id "
            "WHERE t.status IN ('failed','interrupted') "
            "AND t.error IS DISTINCT FROM 'Stopped by you.' AND NOT EXISTS ("
            " SELECT 1 FROM rvbbit.calliope_turns later WHERE later.session_id=t.session_id "
            " AND later.ordinal>t.ordinal AND later.status='complete'"
            ") AND NOT EXISTS ("
            " SELECT 1 FROM rvbbit.calliope_workflow_runs wr WHERE wr.session_id=t.session_id "
            " AND wr.trigger_kind='manual' AND wr.status='running'"
            ") "
            "ON CONFLICT (owner_email,source,dedupe_key) DO NOTHING"
        )
        # Scheduled runs are owned by Hermes and may reconnect after this
        # service returns. Manual runs are owned by the browser/SSE process we
        # just replaced, so none of them can still have a live finish call.
        orphaned_manual_runs = [dict(row) for row in conn.execute(
            "SELECT id FROM rvbbit.calliope_workflow_runs "
            "WHERE trigger_kind='manual' AND status='running'"
        ).fetchall()]
        _backfill_artifact_attribution(conn)
    for run in orphaned_manual_runs:
        try:
            finish_workflow_run(
                conn_factory,
                str(run["id"]),
                "failed",
                "Warehouse restarted before the Workflow committed its required finish result.",
                {"reason": "warehouse_service_restarted"},
                action_prompt=(
                    "Open the pinned run notebook and rerun the Workflow. Its prior browser "
                    "agent process cannot be resumed after the service restart."
                ),
            )
        except Exception as exc:
            print(
                f"WARNING: could not reconcile manual Workflow run {run.get('id')}: "
                f"{type(exc).__name__}: {str(exc)[:300]}",
                file=os.sys.stderr,
            )


def _calliope_service_identities() -> list[str]:
    """Return the non-human principals Hermes may publish artifacts as.

    The shared bearer always has ``client_id=static-key``, but installations
    may give its caller a readable label through WAREHOUSE_MCP_STATIC_CALLER.
    That configured label is still the same service principal and is safe to
    replace only at the trusted Calliope session/surface boundary below.
    """
    values = {"static-key"}
    configured = str(os.environ.get("WAREHOUSE_MCP_STATIC_CALLER") or "").strip().lower()
    if configured:
        values.add(configured)
    return sorted(values)


def _is_calliope_service_identity(value: Any) -> bool:
    normalized = str(value or "").strip().lower() or "static-key"
    return normalized in _calliope_service_identities()


def _backfill_artifact_attribution(conn: Any) -> None:
    """Replace shared-key creator labels when Calliope has signed provenance.

    Hermes reaches Warehouse through one service credential, so its MCP token
    cannot identify the human who initiated a Calliope turn. The append-only
    surface ledger can: artifact surfaces are emitted only by publication
    tools and retain the exact slug and version alongside the owning session.
    """
    candidates = """
        SELECT DISTINCT ON (v.dashboard_id,v.version)
               v.dashboard_id,v.version,s.owner_email
        FROM rvbbit.calliope_surfaces f
        JOIN rvbbit.calliope_turns t ON t.id=f.turn_id
        JOIN rvbbit.calliope_sessions s ON s.id=f.session_id
        JOIN rvbbit.dashboards d ON d.slug=f.artifact_slug
        JOIN rvbbit.dashboard_versions v
          ON v.dashboard_id=d.id AND v.version=f.artifact_version
        WHERE f.kind='artifact'
          AND nullif(btrim(s.owner_email),'') IS NOT NULL
        ORDER BY v.dashboard_id,v.version,
                 abs(extract(epoch FROM (v.created_at-t.created_at))),
                 f.created_at
    """
    service_identities = _calliope_service_identities()
    conn.execute(
        "WITH attributed AS (" + candidates + ") "
        "UPDATE rvbbit.dashboard_versions v SET created_by=a.owner_email "
        "FROM attributed a "
        "WHERE v.dashboard_id=a.dashboard_id AND v.version=a.version "
        "AND coalesce(nullif(lower(btrim(v.created_by)),''),'static-key')=ANY(%s::text[])",
        (service_identities,),
    )
    conn.execute(
        "WITH attributed AS (" + candidates + "), "
        "owners AS ("
        " SELECT DISTINCT ON (dashboard_id) dashboard_id,owner_email"
        " FROM attributed ORDER BY dashboard_id,version"
        ") "
        "UPDATE rvbbit.dashboards d SET owner_email=o.owner_email "
        "FROM owners o WHERE d.id=o.dashboard_id "
        "AND coalesce(nullif(lower(btrim(d.owner_email)),''),'static-key')=ANY(%s::text[])",
        (service_identities,),
    )


def _uuid(value: Any) -> str | None:
    value = str(value or "").strip().lower()
    return value if _UUID_RE.fullmatch(value) else None


def _now_iso(value: Any) -> Any:
    return value.isoformat() if hasattr(value, "isoformat") else value


def _row_json(row: Any) -> dict[str, Any]:
    return {k: _now_iso(v) for k, v in dict(row or {}).items()}


def _json_object(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return dict(parsed) if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}


def _json_array(value: Any) -> list[Any]:
    if isinstance(value, list):
        return list(value)
    if isinstance(value, tuple):
        return list(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return list(parsed) if isinstance(parsed, list) else []
        except Exception:
            return []
    return []


def _capability_action_key(catalog_id: Any) -> str:
    return str(catalog_id or "").strip().lower().replace("~", "-").replace("/", "~")


def _library_inventory_fact(label: str, value: Any) -> dict[str, Any] | None:
    if value is None or value == "":
        return None
    return {"label": str(label)[:80], "value": value}


def _library_inventory_item(
    *,
    ref: str,
    kind: str,
    section: str,
    label: str,
    summary: str,
    state: str = "ready",
    health: str = "Configured and available to Calliope.",
    facts: list[dict[str, Any] | None] | None = None,
    owner: str | None = None,
    visibility: str | None = None,
    updated_at: Any = None,
    last_activity_at: Any = None,
    detail: dict[str, Any] | None = None,
    open_url: str | None = None,
    intents: list[str] | None = None,
) -> dict[str, Any]:
    normalized_state = state if state in _LIBRARY_INVENTORY_STATES else "ready"
    item = {
        "ref": str(ref)[:320],
        "kind": str(kind)[:80],
        "section": section if section in _LIBRARY_INVENTORY_SECTIONS else "tools",
        "section_label": _LIBRARY_INVENTORY_SECTIONS.get(section, "Tools"),
        "label": str(label or ref)[:240],
        "summary": str(summary or "Configured for this Calliope installation.")[:1200],
        "state": normalized_state,
        "state_label": _LIBRARY_INVENTORY_STATES[normalized_state],
        "health": str(health or "Configured and available to Calliope.")[:1200],
        "facts": [fact for fact in (facts or []) if fact],
        "owner": str(owner)[:320] if owner else None,
        "visibility": str(visibility)[:80] if visibility else None,
        "updated_at": _now_iso(updated_at),
        "last_activity_at": _now_iso(last_activity_at),
        "detail": detail or {},
        "open_url": str(open_url)[:2000] if open_url else None,
        "intents": list(dict.fromkeys(str(intent)[:80] for intent in (intents or ["inspect"]))),
    }
    # Normalize Decimal, UUID, datetime, and driver-specific values once at the
    # boundary. The inventory is also pinned into Stage payloads, so it must be
    # stable JSON rather than a live psycopg row shape.
    return json.loads(json.dumps(item, default=str))


def _library_metric_value(value: Any) -> str:
    if value is None:
        return "Not observed"
    if isinstance(value, dict):
        candidate = value.get("value")
        if isinstance(candidate, dict):
            candidate = candidate.get("value")
        if candidate is not None and not isinstance(candidate, (dict, list)):
            return str(candidate)[:120]
    if not isinstance(value, (dict, list)):
        return str(value)[:120]
    return json.dumps(value, default=str, ensure_ascii=False)[:120]


def _library_safe_endpoint(value: Any) -> str | None:
    """Expose endpoint identity without leaking URL credentials or query tokens."""
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parts = urlsplit(raw)
    except ValueError:
        return raw.split("?", 1)[0].split("#", 1)[0][:1200]
    if not parts.scheme or not parts.netloc:
        return raw.split("?", 1)[0].split("#", 1)[0][:1200]
    netloc = parts.netloc.rsplit("@", 1)[-1]
    return urlunsplit((parts.scheme, netloc, parts.path, "", ""))[:1200]


def _library_brain_inventory(conn: Any, _owner: str) -> list[dict[str, Any]]:
    rows = conn.execute(
        "SELECT to_jsonb(s) AS source,"
        "(SELECT count(*)::int FROM rvbbit.brain_documents d "
        " WHERE d.source_id=s.source_id AND d.deleted_at IS NULL) AS docs,"
        "(SELECT count(*)::int FROM rvbbit.brain_documents d "
        " WHERE d.source_id=s.source_id AND d.deleted_at IS NULL "
        " AND d.props->>'docType'='meeting_summary') AS meeting_briefs,"
        "(SELECT count(*)::int FROM rvbbit.brain_chunks c "
        " JOIN rvbbit.brain_documents d ON d.doc_id=c.doc_id "
        " WHERE d.source_id=s.source_id AND d.deleted_at IS NULL) AS chunks,"
        "(SELECT to_jsonb(r) FROM rvbbit.brain_sync_runs r "
        " WHERE r.source_id=s.source_id ORDER BY r.started_at DESC LIMIT 1) AS last_sync,"
        "(SELECT count(*)::int FROM rvbbit.brain_pending_grants g "
        " WHERE g.source_id=s.source_id AND NOT g.approved) AS pending_grants "
        "FROM rvbbit.brain_sources s ORDER BY s.label,s.source_id"
    ).fetchall()
    items: list[dict[str, Any]] = []
    for row in rows:
        source = _json_object(row.get("source"))
        sync = _json_object(row.get("last_sync"))
        sync_detail = _json_object(sync.get("detail"))
        connector_stats = _json_object(sync_detail.get("connector_stats"))
        meeting_summaries = _json_object(sync_detail.get("meeting_summaries"))
        auto_transcription = _json_object(connector_stats.get("auto_transcription"))
        docs = int(row.get("docs") or 0)
        meeting_briefs = int(row.get("meeting_briefs") or 0)
        chunks = int(row.get("chunks") or 0)
        pending = int(row.get("pending_grants") or 0)
        enabled = source.get("enabled", True) is not False
        errors = int(sync.get("errors") or 0)
        running = bool(sync and not sync.get("finished_at"))
        meetings_missing = int(connector_stats.get("meetings_without_transcript") or 0)
        connector_warnings = int(connector_stats.get("warnings") or 0)
        auto_transcription_errors = int(auto_transcription.get("errors") or 0)
        if not enabled:
            state, health = "inactive", "This knowledge source is currently disabled."
        elif running:
            state, health = "syncing", "A document synchronization is currently running."
        elif errors:
            state, health = "attention", f"The latest synchronization reported {errors} error{'s' if errors != 1 else ''}."
        elif pending:
            state, health = "attention", f"{pending} discovered access grant{'s' if pending != 1 else ''} still need review."
        elif auto_transcription_errors:
            state, health = (
                "attention",
                f"Automatic transcription could not be configured for "
                f"{auto_transcription_errors} upcoming meeting space"
                f"{'s' if auto_transcription_errors != 1 else ''}.",
            )
        elif meetings_missing:
            state, health = (
                "attention",
                f"{meetings_missing} recent meeting{'s' if meetings_missing != 1 else ''} "
                "did not have a generated transcript artifact.",
            )
        elif connector_warnings and not docs:
            state, health = "attention", "The connector completed with warnings and produced no readable documents."
        elif docs:
            state, health = "healthy", "Indexed documents are available to search, Briefs, and Workflows."
        else:
            state, health = "ready", "The source is configured but has not produced indexed documents yet."
        provider = str(_json_object(source.get("config")).get("provider") or source.get("kind") or "document")
        label = str(source.get("label") or f"Knowledge source {source.get('source_id')}")
        items.append(_library_inventory_item(
            ref=f"brain_source:{source.get('source_id')}",
            kind="brain_source",
            section="knowledge",
            label=label,
            summary=f"{provider.replace('_', ' ')} documents indexed into Company Brain.",
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Documents", docs),
                _library_inventory_fact("Chunks", chunks),
                _library_inventory_fact("Source type", provider.replace("_", " ")),
                _library_inventory_fact("Last sync", source.get("last_synced_at") or sync.get("finished_at")),
                _library_inventory_fact("Access reviews", pending if pending else None),
                _library_inventory_fact("Transcripts found", connector_stats.get("transcript_files")),
                _library_inventory_fact("Meeting briefs", meeting_briefs),
                _library_inventory_fact(
                    "Summary status",
                    "Available" if meeting_summaries.get("available") is True
                    else ("Not configured" if meeting_summaries.get("reason") == "no_summarizer" else None),
                ),
                _library_inventory_fact("Missing transcripts", meetings_missing if meetings_missing else None),
                _library_inventory_fact("Workspace users polled", connector_stats.get("subjects_polled")),
                _library_inventory_fact("Auto-transcripts enabled", auto_transcription.get("enabled")),
            ],
            visibility="governed",
            updated_at=source.get("last_synced_at") or source.get("created_at"),
            last_activity_at=sync.get("finished_at") or sync.get("started_at") or source.get("last_synced_at"),
            detail={
                "source_id": source.get("source_id"),
                "provider": provider,
                "kind": source.get("kind"),
                "folder_prefix": source.get("folder_prefix"),
                "default_roles": source.get("default_roles") or [],
                "latest_sync": {
                    key: sync.get(key) for key in (
                        "trigger", "started_at", "finished_at", "added", "changed",
                        "removed", "skipped", "errors", "elapsed_sec",
                    ) if sync.get(key) is not None
                },
                "connector_stats": connector_stats,
                "meeting_summaries": meeting_summaries,
            },
            intents=["inspect", "sync", "change"],
        ))
    return items


def _library_mcp_inventory(conn: Any, _owner: str) -> list[dict[str, Any]]:
    rows = conn.execute(
        "SELECT s.name,s.transport,s.url,s.command,s.timeout_ms,s.description,s.created_at,"
        "(SELECT count(*)::int FROM rvbbit.mcp_tools t WHERE t.server=s.name) AS tools,"
        "(SELECT count(*)::int FROM rvbbit.mcp_resources r WHERE r.server=s.name) AS resources,"
        "(SELECT array_agg(t.name ORDER BY t.name) FROM rvbbit.mcp_tools t WHERE t.server=s.name) AS tool_names,"
        "(SELECT jsonb_build_object('at',i.invocation_at,'failed',i.error IS NOT NULL,"
        " 'latency_ms',i.latency_ms,'tool',i.tool) FROM rvbbit.mcp_invocations i "
        " WHERE i.server=s.name ORDER BY i.invocation_at DESC LIMIT 1) AS last_call "
        "FROM rvbbit.mcp_servers s ORDER BY s.name"
    ).fetchall()
    items: list[dict[str, Any]] = []
    for row in rows:
        tools = int(row.get("tools") or 0)
        resources = int(row.get("resources") or 0)
        tool_names = [str(value) for value in (row.get("tool_names") or [])]
        read_names = [
            name for name in tool_names
            if re.search(r"(?:^|_)(?:get|list|search|read|fetch|find|query|lookup|browse|retrieve)(?:_|$)", name, re.I)
        ]
        last_call = _json_object(row.get("last_call"))
        if not tools and not resources:
            state, health = "attention", "The server is registered but no tools or resources have been discovered."
        elif last_call.get("failed"):
            state, health = "attention", "The latest observed MCP invocation reported an error."
        else:
            state, health = "healthy", "Discovered MCP surfaces are available as governed tools and SQL functions."
        intents = ["inspect", "test", "change"]
        if read_names or resources:
            intents.append("knowledge_source")
        name = str(row.get("name") or "MCP server")
        endpoint = (
            _library_safe_endpoint(row.get("url"))
            if row.get("transport") == "http"
            else str(row.get("command") or "")[:1200] or None
        )
        items.append(_library_inventory_item(
            ref=f"mcp:{name.lower()}",
            kind="mcp_server",
            section="tools",
            label=name,
            summary=str(row.get("description") or f"{row.get('transport') or 'MCP'} connection exposing company tools."),
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Tools", tools),
                _library_inventory_fact("Resources", resources),
                _library_inventory_fact("Read surfaces", len(read_names) + resources),
                _library_inventory_fact("Transport", row.get("transport")),
                _library_inventory_fact("Last call", last_call.get("at")),
            ],
            visibility="organization",
            updated_at=row.get("created_at"),
            last_activity_at=last_call.get("at"),
            detail={
                "transport": row.get("transport"),
                "endpoint": endpoint,
                "timeout_ms": row.get("timeout_ms"),
                "tool_names": tool_names[:120],
                "read_candidate_tools": read_names[:40],
                "resource_count": resources,
                "last_call": last_call,
                "knowledge_source_candidate": bool(read_names or resources),
            },
            intents=intents,
        ))
    return items


def _library_cube_inventory(conn: Any, _owner: str) -> list[dict[str, Any]]:
    status_row = conn.execute(
        "SELECT to_regclass('rvbbit.cube_refresh_status') IS NOT NULL AS present"
    ).fetchone() or {}
    if status_row.get("present"):
        rows = conn.execute(
            "SELECT to_jsonb(c) AS catalog,to_jsonb(s) AS refresh "
            "FROM rvbbit.cube_catalog c LEFT JOIN rvbbit.cube_refresh_status s ON s.name=c.name "
            "ORDER BY c.name"
        ).fetchall()
    else:
        rows = conn.execute(
            "SELECT to_jsonb(c) AS catalog,NULL::jsonb AS refresh "
            "FROM rvbbit.cube_catalog c ORDER BY c.name"
        ).fetchall()
    items: list[dict[str, Any]] = []
    for row in rows:
        cube = _json_object(row.get("catalog"))
        refresh = _json_object(row.get("refresh"))
        enabled = refresh.get("enabled", True) is not False
        recommended = str(refresh.get("recommended_action") or "")
        if not enabled:
            state, health = "inactive", "Automatic refresh is disabled for this cube."
        elif refresh.get("last_error"):
            state, health = "attention", "The latest cube refresh reported an error."
        elif recommended in {"fix_error", "refresh_cube", "maintain_storage"}:
            state, health = "attention", {
                "fix_error": "The cube needs a refresh error reviewed.",
                "refresh_cube": "The cube is stale or its source has changed since the latest refresh.",
                "maintain_storage": "The cube is current but its optimized storage needs maintenance.",
            }[recommended]
        elif refresh.get("refreshed_at"):
            state, health = "healthy", "The governed cube is refreshed and available for analysis."
        else:
            state, health = "ready", "The cube is defined but has no observed refresh state yet."
        name = str(cube.get("name") or "cube")
        items.append(_library_inventory_item(
            ref=f"cube:{name}",
            kind="cube",
            section="meaning",
            label=name.replace("_", " ").title(),
            summary=str(cube.get("description") or f"Governed analytical cube at the {cube.get('grain') or 'declared'} grain."),
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Version", cube.get("version")),
                _library_inventory_fact("Grain", cube.get("grain")),
                _library_inventory_fact("Rows", refresh.get("last_rows")),
                _library_inventory_fact("Last refresh", refresh.get("refreshed_at")),
                _library_inventory_fact("Sources", refresh.get("source_count")),
            ],
            owner=cube.get("owner"),
            visibility="organization",
            updated_at=cube.get("created_at"),
            last_activity_at=refresh.get("refreshed_at"),
            detail={
                "name": name,
                "version": cube.get("version"),
                "grain": cube.get("grain"),
                "category": cube.get("category"),
                "subcategory": cube.get("subcategory"),
                "refresh_cron": cube.get("refresh_cron"),
                "refresh": {key: refresh.get(key) for key in (
                    "enabled", "refresh_mode", "refreshed_at", "last_rows", "last_refresh_seconds",
                    "recommended_action", "source_count", "dirty_source_count", "source_tables",
                ) if refresh.get(key) is not None},
            },
            intents=["inspect", "refresh", "change"],
        ))
    return items


def _library_metric_inventory(conn: Any, _owner: str) -> list[dict[str, Any]]:
    rows = conn.execute(
        "SELECT to_jsonb(m) AS metric,"
        "(SELECT to_jsonb(o) FROM rvbbit.metric_observations o WHERE o.metric_name=m.name "
        " ORDER BY coalesce(o.data_as_of,o.observed_at) DESC,o.observation_id DESC LIMIT 1) AS observation,"
        "(SELECT to_jsonb(mm) FROM rvbbit.metric_materialize mm WHERE mm.metric_name=m.name) AS materialize,"
        "(SELECT count(*)::int FROM rvbbit.metric_dependencies d WHERE d.metric_name=m.name) AS dependencies,"
        "(SELECT count(*)::int FROM rvbbit.calliope_metric_follows f WHERE f.metric_name=m.name) AS follows "
        "FROM rvbbit.metric_catalog m ORDER BY m.name"
    ).fetchall()
    items: list[dict[str, Any]] = []
    failing = {"fail", "failed", "failing", "breach", "breaching", "error"}
    for row in rows:
        metric = _json_object(row.get("metric"))
        observation = _json_object(row.get("observation"))
        materialize = _json_object(row.get("materialize"))
        labels = _json_object(metric.get("labels"))
        display = _json_object(labels.get("display"))
        status = str(observation.get("status") or "").lower()
        if materialize and materialize.get("enabled") is False:
            state, health = "inactive", "Automatic metric observation is disabled."
        elif status in failing:
            state, health = "attention", f"The latest governed observation is {status}."
        elif observation:
            state, health = "healthy", "A durable governed observation is available."
        else:
            state, health = "ready", "The metric is defined but has not produced a durable observation yet."
        name = str(metric.get("name") or "metric")
        title = str(display.get("title") or labels.get("title") or name.replace("_", " ").title())
        observed_at = observation.get("data_as_of") or observation.get("observed_at")
        items.append(_library_inventory_item(
            ref=f"metric:{name}",
            kind="metric",
            section="meaning",
            label=title,
            summary=str(metric.get("description") or "A governed metric definition with versioned observations."),
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Current", _library_metric_value(observation.get("value"))),
                _library_inventory_fact("Version", metric.get("version")),
                _library_inventory_fact("Grain", metric.get("grain")),
                _library_inventory_fact("Observed", observed_at),
                _library_inventory_fact("Brief subscribers", int(row.get("follows") or 0)),
            ],
            owner=metric.get("owner"),
            visibility="organization",
            updated_at=metric.get("created_at"),
            last_activity_at=observed_at,
            detail={
                "name": name,
                "version": metric.get("version"),
                "grain": metric.get("grain"),
                "params": metric.get("params") or {},
                "category": metric.get("category"),
                "subcategory": metric.get("subcategory"),
                "dependencies": int(row.get("dependencies") or 0),
                "brief_subscribers": int(row.get("follows") or 0),
                "observation": {key: observation.get(key) for key in (
                    "observation_id", "metric_version", "value", "verdict", "status",
                    "data_as_of", "observed_at", "trigger",
                ) if observation.get(key) is not None},
                "materialize": materialize,
            },
            open_url="/gallery?" + urlencode({"view": "metrics", "metric": name}),
            intents=["inspect", "watch", "change"],
        ))
    return items


def _library_mirror_inventory(conn: Any, _owner: str) -> list[dict[str, Any]]:
    """Project the dlt control plane as credential-free Library diagnostics."""
    present = conn.execute(
        "SELECT to_regclass('rvbbit.mirror_jobs') IS NOT NULL AS jobs,"
        "to_regclass('rvbbit.mirror_runs') IS NOT NULL AS runs"
    ).fetchone() or {}
    if not bool(present.get("jobs")) or not bool(present.get("runs")):
        return []
    rows = conn.execute(
        "SELECT j.job_name,j.connection_name,j.source_schema,j.destination_schema,j.enabled,"
        "j.schedule_seconds,j.next_run_at,j.last_run_at,j.updated_at,"
        "(SELECT count(*)::int FROM rvbbit.mirror_tables t "
        " WHERE t.job_name=j.job_name AND t.enabled) AS table_count,"
        "latest.run_id,latest.trigger AS latest_run_trigger,"
        "latest.status AS latest_run_status,latest.requested_at AS latest_run_requested_at,"
        "latest.started_at AS latest_run_started_at,latest.finished_at AS latest_run_finished_at,"
        "latest.tables_succeeded,latest.tables_failed,latest.rows_loaded,"
        "latest.error_code AS latest_run_error_code,latest.error_message AS latest_run_error_message "
        "FROM rvbbit.mirror_jobs j LEFT JOIN LATERAL ("
        " SELECT r.* FROM rvbbit.mirror_runs r WHERE r.job_name=j.job_name "
        " ORDER BY r.requested_at DESC LIMIT 1"
        ") latest ON true ORDER BY j.job_name"
    ).fetchall()
    items: list[dict[str, Any]] = []
    for raw in rows:
        row = _row_json(raw)
        status = str(row.get("latest_run_status") or "")
        if not row.get("enabled"):
            state, health = "inactive", "Future scheduled and manual mirror runs are paused."
        elif status in {"queued", "running"}:
            state, health = "syncing", f"The latest mirror run is {status}."
        elif status in _MIRROR_RETRYABLE_STATUSES:
            state, health = "attention", f"The latest mirror run is {status} and can be retried."
        elif status == "succeeded":
            state, health = "healthy", "The latest mirror run completed successfully."
        else:
            state, health = "ready", "The mirror is configured and waiting for its first run."
        cadence = (
            next(
                (label for value, label in _MIRROR_SCHEDULE_OPTIONS
                 if value == str(row.get("schedule_seconds"))),
                f"Every {row.get('schedule_seconds')} seconds",
            )
            if row.get("schedule_seconds") is not None
            else "Manual only"
        )
        error = _action_error_text(row.get("latest_run_error_message")) or None
        job_name = str(row.get("job_name") or "mirror")
        intents = ["inspect", "run", "change"]
        if status in _MIRROR_RETRYABLE_STATUSES:
            intents.append("retry")
        items.append(_library_inventory_item(
            ref=f"mirror:{job_name}",
            kind="mirror_job",
            section="routines",
            label=job_name,
            summary=(
                f"Mirrors {row.get('connection_name')}.{row.get('source_schema')} into "
                f"the local {row.get('destination_schema')} schema."
            ),
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Tables", int(row.get("table_count") or 0)),
                _library_inventory_fact("Cadence", cadence),
                _library_inventory_fact("Next run", row.get("next_run_at")),
                _library_inventory_fact("Latest run", status or "Not run"),
                _library_inventory_fact("Rows loaded", row.get("rows_loaded")),
            ],
            visibility="organization",
            updated_at=row.get("updated_at"),
            last_activity_at=(
                row.get("latest_run_finished_at")
                or row.get("latest_run_started_at")
                or row.get("latest_run_requested_at")
                or row.get("updated_at")
            ),
            detail={
                "job_name": job_name,
                "connection_name": row.get("connection_name"),
                "source_schema": row.get("source_schema"),
                "destination_schema": row.get("destination_schema"),
                "enabled": bool(row.get("enabled")),
                "schedule_seconds": row.get("schedule_seconds"),
                "next_run_at": row.get("next_run_at"),
                "table_count": int(row.get("table_count") or 0),
                "latest_run": {
                    "run_id": str(row.get("run_id")) if row.get("run_id") else None,
                    "trigger": row.get("latest_run_trigger"),
                    "status": status or None,
                    "requested_at": row.get("latest_run_requested_at"),
                    "started_at": row.get("latest_run_started_at"),
                    "finished_at": row.get("latest_run_finished_at"),
                    "tables_succeeded": int(row.get("tables_succeeded") or 0),
                    "tables_failed": int(row.get("tables_failed") or 0),
                    "rows_loaded": int(row.get("rows_loaded") or 0),
                    "error_code": row.get("latest_run_error_code"),
                    "error": error,
                },
                "action_id": "mirror.manage:" + _capability_action_key(job_name),
            },
            intents=intents,
        ))
    return items


def _library_routine_inventory(conn: Any, owner: str) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    workflow_rows = conn.execute(
        "SELECT to_jsonb(w) AS routine,to_jsonb(v) AS version,"
        "(SELECT to_jsonb(r) FROM rvbbit.calliope_workflow_runs r "
        " WHERE r.workflow_id=w.id ORDER BY r.started_at DESC LIMIT 1) AS last_run "
        "FROM rvbbit.calliope_workflows w JOIN LATERAL ("
        " SELECT vv.* FROM rvbbit.calliope_workflow_versions vv WHERE vv.workflow_id=w.id "
        " AND vv.version=CASE WHEN lower(w.owner_email)=lower(%s) THEN w.latest_version ELSE w.published_version END"
        ") v ON true WHERE NOT w.archived AND (lower(w.owner_email)=lower(%s) OR "
        "(w.visibility='company' AND w.published_version IS NOT NULL)) ORDER BY v.name,w.updated_at DESC",
        (owner, owner),
    ).fetchall()
    for row in workflow_rows:
        routine = _json_object(row.get("routine"))
        version = _json_object(row.get("version"))
        last_run = _json_object(row.get("last_run"))
        if routine.get("schedule_state") == "error" or routine.get("schedule_error"):
            state, health = "attention", "The scheduled Workflow needs attention before its next run."
        elif str(last_run.get("status") or "") in {"failed", "blocked"}:
            state, health = "attention", f"The latest Workflow run is {last_run.get('status')}."
        elif routine.get("schedule_enabled"):
            state, health = "healthy", "The Workflow is published to its configured schedule."
        else:
            state, health = "ready", "The Workflow is available on demand and is not currently scheduled."
        name = str(version.get("name") or routine.get("slug") or "Workflow")
        items.append(_library_inventory_item(
            ref=f"workflow:{routine.get('id')}",
            kind="workflow",
            section="routines",
            label=name,
            summary=str(version.get("description") or version.get("goal") or "A reusable Calliope Workflow."),
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Version", version.get("version")),
                _library_inventory_fact("Visibility", routine.get("visibility")),
                _library_inventory_fact("Schedule", "enabled" if routine.get("schedule_enabled") else "on demand"),
                _library_inventory_fact("Next run", routine.get("schedule_next_run_at")),
                _library_inventory_fact("Last result", last_run.get("status")),
            ],
            owner=routine.get("owner_email"),
            visibility=routine.get("visibility"),
            updated_at=routine.get("updated_at"),
            last_activity_at=last_run.get("completed_at") or last_run.get("started_at") or routine.get("updated_at"),
            detail={
                "id": routine.get("id"), "slug": routine.get("slug"),
                "version": version.get("version"), "goal": version.get("goal"),
                "schedule_enabled": routine.get("schedule_enabled"),
                "schedule_state": routine.get("schedule_state"),
                "schedule_next_run_at": routine.get("schedule_next_run_at"),
                "last_run": {key: last_run.get(key) for key in (
                    "id", "workflow_version", "trigger_kind", "status", "result_summary",
                    "started_at", "completed_at",
                ) if last_run.get(key) is not None},
            },
            intents=["inspect", "run", "change"],
        ))

    instrument_rows = conn.execute(
        "SELECT to_jsonb(i) AS routine,to_jsonb(v) AS version "
        "FROM rvbbit.calliope_instruments i JOIN LATERAL ("
        " SELECT vv.* FROM rvbbit.calliope_instrument_versions vv WHERE vv.instrument_id=i.id "
        " AND vv.version=CASE WHEN lower(i.owner_email)=lower(%s) THEN i.latest_version ELSE i.published_version END"
        ") v ON true WHERE NOT i.archived AND (lower(i.owner_email)=lower(%s) OR "
        "(i.visibility='company' AND i.published_version IS NOT NULL)) ORDER BY v.name,i.updated_at DESC",
        (owner, owner),
    ).fetchall()
    for row in instrument_rows:
        routine = _json_object(row.get("routine"))
        version = _json_object(row.get("version"))
        name = str(version.get("name") or routine.get("slug") or "Instrument")
        fields = version.get("fields") if isinstance(version.get("fields"), list) else []
        items.append(_library_inventory_item(
            ref=f"instrument:{routine.get('id')}",
            kind="instrument",
            section="routines",
            label=name,
            summary=str(version.get("description") or "A reusable guided Calliope Instrument."),
            state="healthy" if routine.get("published_version") else "ready",
            health="A human-approved revision is published." if routine.get("published_version") else "A private draft is available to its owner.",
            facts=[
                _library_inventory_fact("Version", version.get("version")),
                _library_inventory_fact("Visibility", routine.get("visibility")),
                _library_inventory_fact("Inputs", len(fields)),
                _library_inventory_fact("Published", routine.get("published_at")),
            ],
            owner=routine.get("owner_email"),
            visibility=routine.get("visibility"),
            updated_at=routine.get("updated_at"),
            last_activity_at=routine.get("updated_at"),
            detail={
                "id": routine.get("id"), "slug": routine.get("slug"),
                "version": version.get("version"), "field_count": len(fields),
                "published_version": routine.get("published_version"),
            },
            intents=["inspect", "run", "change"],
        ))

    watch_rows = conn.execute(
        "SELECT id,name,comparator,threshold,cadence,consecutive_n,active,last_value,last_status,"
        "last_evaluated_at,last_triggered_at,last_error,created_at,updated_at,source "
        "FROM rvbbit.calliope_watches WHERE lower(owner_email)=lower(%s) ORDER BY updated_at DESC",
        (owner,),
    ).fetchall()
    for row in watch_rows:
        if not row.get("active"):
            state, health = "inactive", "This private data watch is paused."
        elif row.get("last_error"):
            state, health = "attention", "The latest watch evaluation reported an error."
        elif row.get("last_evaluated_at"):
            state, health = "healthy", "The watch is active and has a recent evaluation."
        else:
            state, health = "ready", "The watch is active and waiting for its first evaluation."
        items.append(_library_inventory_item(
            ref=f"watch:{row.get('id')}",
            kind="watch",
            section="routines",
            label=str(row.get("name") or "Data watch"),
            summary=f"Notify when the selected value is {row.get('comparator') or 'outside'} {row.get('threshold')}.",
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Rule", f"{row.get('comparator')} {row.get('threshold')}"),
                _library_inventory_fact("Cadence", row.get("cadence")),
                _library_inventory_fact("Last value", row.get("last_value")),
                _library_inventory_fact("Evaluated", row.get("last_evaluated_at")),
            ],
            owner=owner,
            visibility="private",
            updated_at=row.get("updated_at"),
            last_activity_at=row.get("last_evaluated_at") or row.get("updated_at"),
            detail={
                "id": str(row.get("id")), "source": row.get("source") or {},
                "comparator": row.get("comparator"), "threshold": row.get("threshold"),
                "cadence": row.get("cadence"), "consecutive_n": row.get("consecutive_n"),
                "last_status": row.get("last_status"), "last_triggered_at": row.get("last_triggered_at"),
            },
            intents=["inspect", "test", "change"],
        ))

    # Playbooks are identity-scoped capabilities rather than executable graphs.
    # Owners see their latest draft; authorized readers see only the approved
    # immutable version.  Keep this additive and rolling-upgrade-safe so a
    # Warehouse image can coexist briefly with an older pg_rvbbit image.
    try:
        playbook_rows = conn.execute(
            "SELECT to_jsonb(p) AS routine,to_jsonb(v) AS version,"
            "lower(p.owner_email)=lower(%s) AS is_owner,"
            "(SELECT count(*)::int FROM rvbbit.capability_access_grants g "
            " WHERE g.capability_kind=p.capability_kind AND g.capability_name=p.capability_name) AS grants,"
            "EXISTS(SELECT 1 FROM rvbbit.capability_access_grants g JOIN rvbbit.teams t ON t.id=g.team_id "
            " WHERE g.capability_kind=p.capability_kind AND g.capability_name=p.capability_name "
            " AND t.system_key='everyone' AND NOT t.archived) AS everyone "
            "FROM rvbbit.calliope_playbooks p JOIN LATERAL ("
            " SELECT vv.* FROM rvbbit.calliope_playbook_versions vv WHERE vv.playbook_id=p.id "
            " AND vv.version=CASE WHEN lower(p.owner_email)=lower(%s) THEN p.latest_version "
            " ELSE p.approved_version END"
            ") v ON true WHERE NOT p.archived AND (lower(p.owner_email)=lower(%s) OR "
            "(p.approved_version IS NOT NULL AND rvbbit.capability_can_use("
            "p.capability_kind,p.capability_name,%s))) ORDER BY v.title,p.updated_at DESC",
            (owner, owner, owner, owner),
        ).fetchall()
    except Exception:  # noqa: BLE001 — feature may lead pg_rvbbit during rollout
        playbook_rows = []
    for row in playbook_rows:
        routine = _json_object(row.get("routine"))
        version = _json_object(row.get("version"))
        contract = _json_object(version.get("semantic_contract"))
        is_owner = bool(row.get("is_owner"))
        approved = int(version.get("version") or 0) == int(
            routine.get("approved_version") or 0
        )
        readiness = str(version.get("readiness") or "ready")
        if readiness in {"blocked", "degraded"}:
            state = "attention"
            health = "This Playbook declares itself " + readiness + ". Review its capability needs before use."
        elif approved:
            state = "healthy"
            health = "This reviewed version is available through identity-aware capability search."
        else:
            state = "ready"
            health = "This private draft is waiting for its owner to review and approve it."
        grant_count = int(row.get("grants") or 0)
        visibility = (
            "everyone" if row.get("everyone") else
            "shared" if grant_count else "private"
        )
        version_number = int(version.get("version") or 1)
        source_session_id = version.get("source_session_id")
        facts = [
            _library_inventory_fact("Version", version_number),
            _library_inventory_fact("Approved", routine.get("approved_version") or "Not yet"),
            _library_inventory_fact("Readiness", readiness),
            _library_inventory_fact(
                "Access",
                ("Everyone signed in" if row.get("everyone") else
                 f"{grant_count} grant{'s' if grant_count != 1 else ''}" if grant_count else
                 "Only you") if is_owner else "Shared with you",
            ),
        ]
        items.append(_library_inventory_item(
            ref=f"playbook:{routine.get('id')}",
            kind="playbook",
            section="routines",
            label=str(version.get("title") or routine.get("capability_name") or "Playbook"),
            summary=str(version.get("synopsis") or "A reusable method learned from Calliope work."),
            state=state,
            health=health,
            facts=facts,
            owner=routine.get("owner_email"),
            visibility=visibility,
            updated_at=routine.get("updated_at"),
            last_activity_at=routine.get("approved_at") or routine.get("updated_at"),
            detail={
                "id": str(routine.get("id")),
                "capability_name": routine.get("capability_name"),
                "version": version_number,
                "latest_version": routine.get("latest_version"),
                "approved_version": routine.get("approved_version"),
                "approved": approved,
                "has_newer_draft": bool(
                    routine.get("approved_version")
                    and int(routine.get("latest_version") or 0)
                    > int(routine.get("approved_version") or 0)
                ),
                "readiness": readiness,
                "outcome": contract.get("outcome"),
                "when_to_use": contract.get("when_to_use") or [],
                "method": contract.get("method") or [],
                "guardrails": contract.get("guardrails") or [],
                "deliverable": contract.get("deliverable"),
                "completion_criteria": contract.get("completion_criteria") or [],
                "required_capabilities": contract.get("required_capabilities") or [],
                "preferred_capabilities": contract.get("preferred_capabilities") or [],
                "change_summary": version.get("change_summary"),
                "is_owner": is_owner,
                "access_revision": routine.get("access_revision") if is_owner else None,
            },
            open_url=(
                f"/calliope?session={quote(str(source_session_id), safe='')}"
                if is_owner and source_session_id else None
            ),
            intents=(
                ["inspect", "approve", "share", "change"]
                if is_owner else ["inspect", "use"]
            ),
        ))
    return items


def _library_team_inventory(conn: Any, owner: str) -> list[dict[str, Any]]:
    """Company-visible flat Teams in their own focused Library section."""
    teams = conn.execute(
        "SELECT t.id::text,t.slug,t.name,t.description,t.system_key,t.archived,t.revision,"
        "t.created_by,t.created_at,t.updated_by,t.updated_at,"
        "coalesce(array_agg(m.principal_email ORDER BY m.principal_email) "
        "FILTER (WHERE m.principal_email IS NOT NULL),ARRAY[]::text[]) AS members,"
        "(SELECT max(e.created_at) FROM rvbbit.team_events e WHERE e.team_id=t.id) AS last_changed_at "
        "FROM rvbbit.teams t LEFT JOIN rvbbit.team_members m ON m.team_id=t.id "
        "GROUP BY t.id ORDER BY CASE t.system_key WHEN 'admins' THEN 0 "
        "WHEN 'everyone' THEN 1 ELSE 2 END,t.archived,t.name"
    ).fetchall()
    admin = conn.execute(
        "SELECT EXISTS(SELECT 1 FROM rvbbit.team_members m JOIN rvbbit.teams t ON t.id=m.team_id "
        "WHERE t.system_key='admins' AND NOT t.archived AND m.principal_email=lower(%s)) AS allowed",
        (owner,),
    ).fetchone() or {}
    can_manage = bool(admin.get("allowed"))
    items = []
    for row in teams:
        members = list(row.get("members") or [])
        system_key = row.get("system_key")
        everyone = system_key == "everyone"
        protected = system_key in {"admins", "everyone"}
        if row.get("archived"):
            state, health = "inactive", "This Team is archived and confers no application access."
        elif everyone:
            state, health = (
                "healthy",
                "Automatically matches every verified application user; no explicit member list is stored.",
            )
        elif system_key == "admins" and not members:
            state, health = "attention", "Bootstrap the first Admin before Team management is available."
        elif system_key == "admins":
            state, health = "healthy", "Members of this protected Team may create and change Teams."
        elif members:
            state, health = "healthy", "This Team has explicit observed-person membership."
        else:
            state, health = "ready", "This Team is active but does not have any members yet."
        items.append(_library_inventory_item(
            ref=f"team:{row.get('id')}",
            kind="team",
            section="teams",
            label=str(row.get("name") or row.get("slug") or "Team"),
            summary=str(row.get("description") or "A flat application access Team."),
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Members", "Any authenticated user" if everyone else len(members)),
                _library_inventory_fact("Membership", "Automatic" if everyone else "Explicit"),
                _library_inventory_fact("Revision", row.get("revision")),
                _library_inventory_fact("Last changed", row.get("last_changed_at") or row.get("updated_at")),
                _library_inventory_fact("Protected", "Yes" if protected else None),
            ],
            owner=row.get("created_by"),
            visibility="organization",
            updated_at=row.get("updated_at"),
            last_activity_at=row.get("last_changed_at") or row.get("updated_at"),
            detail={
                "id": str(row.get("id")),
                "slug": row.get("slug"),
                "system_key": system_key,
                "revision": row.get("revision"),
                "members": members,
                "member_count": None if everyone else len(members),
                "membership_rule": "authenticated_users" if everyone else "explicit_members",
                "dynamic_membership": everyone,
                "archived": bool(row.get("archived")),
                "protected": protected,
                "can_manage": can_manage,
                "updated_by": row.get("updated_by"),
            },
            intents=["inspect", "change"],
        ))
    return items


def _library_personal_inventory(conn: Any, owner: str) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    connection = conn.execute(
        "SELECT owner_email,google_email,status,connected_at,updated_at,last_synced_at,"
        "last_full_sync_at,last_error,(SELECT count(*)::int FROM rvbbit.calliope_google_calendar_events e "
        " WHERE lower(e.owner_email)=lower(c.owner_email)) AS events "
        "FROM rvbbit.calliope_google_calendar_connections c WHERE lower(owner_email)=lower(%s)",
        (owner,),
    ).fetchone()
    if connection:
        status = str(connection.get("status") or "connected")
        if status in {"error", "needs_reconnect"} or connection.get("last_error"):
            state, health = "attention", "Google Calendar needs attention before Calliope can refresh it."
        elif connection.get("last_synced_at"):
            state, health = "healthy", "Calendar events are available to private Briefs and personal context."
        else:
            state, health = "ready", "Google Calendar is connected and waiting for its first sync."
        items.append(_library_inventory_item(
            ref="calendar:google:primary",
            kind="personal_source",
            section="knowledge",
            label="Google Calendar",
            summary="Private meeting context for Daily Briefs, personal knowledge, and follow-up.",
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Account", connection.get("google_email")),
                _library_inventory_fact("Events", int(connection.get("events") or 0)),
                _library_inventory_fact("Last sync", connection.get("last_synced_at")),
                _library_inventory_fact("Status", status.replace("_", " ")),
            ],
            owner=owner,
            visibility="private",
            updated_at=connection.get("updated_at"),
            last_activity_at=connection.get("last_synced_at") or connection.get("connected_at"),
            detail={
                "provider": "google_calendar", "google_email": connection.get("google_email"),
                "status": status, "event_count": int(connection.get("events") or 0),
                "last_synced_at": connection.get("last_synced_at"),
                "last_full_sync_at": connection.get("last_full_sync_at"),
            },
            intents=["inspect", "sync", "change"],
        ))

    workspace = conn.execute(
        "SELECT owner_email,google_email,status,connected_at,updated_at,last_used_at,last_error,"
        "(SELECT count(*)::int FROM rvbbit.calliope_google_exports e "
        " WHERE lower(e.owner_email)=lower(w.owner_email) AND e.status='complete') AS exports,"
        "(SELECT count(*)::int FROM rvbbit.calliope_google_imports i "
        " WHERE lower(i.owner_email)=lower(w.owner_email)) AS imports "
        "FROM rvbbit.calliope_google_workspace_connections w "
        "WHERE lower(owner_email)=lower(%s)",
        (owner,),
    ).fetchone()
    if workspace:
        status = str(workspace.get("status") or "connected")
        if status in {"error", "needs_reconnect"} or workspace.get("last_error"):
            state, health = "attention", "Google Workspace needs attention before Calliope can use Sheets."
        elif workspace.get("last_used_at"):
            state, health = "healthy", "Google Sheets imports and exports use explicit file-scoped access."
        else:
            state, health = "ready", "Google Workspace is ready for an explicit Sheet import or export."
        items.append(_library_inventory_item(
            ref="workspace:google:sheets",
            kind="personal_source",
            section="tools",
            label="Google Sheets",
            summary="Bring selected spreadsheets into a private Stage or export governed results without broad Drive access.",
            state=state,
            health=health,
            facts=[
                _library_inventory_fact("Account", workspace.get("google_email")),
                _library_inventory_fact("Imports", int(workspace.get("imports") or 0)),
                _library_inventory_fact("Exports", int(workspace.get("exports") or 0)),
                _library_inventory_fact("Last used", workspace.get("last_used_at")),
                _library_inventory_fact("Access", "Files you explicitly choose"),
            ],
            owner=owner,
            visibility="private",
            updated_at=workspace.get("updated_at"),
            last_activity_at=workspace.get("last_used_at") or workspace.get("connected_at"),
            detail={
                "provider": "google_workspace",
                "google_email": workspace.get("google_email"),
                "status": status,
                "import_count": int(workspace.get("imports") or 0),
                "export_count": int(workspace.get("exports") or 0),
                "scope": "drive.file",
            },
            intents=["inspect", "import", "export", "change"],
        ))

    alias_row = conn.execute(
        "SELECT count(*)::int AS aliases,count(DISTINCT source)::int AS sources "
        "FROM rvbbit.calliope_identity_aliases WHERE lower(owner_email)=lower(%s)",
        (owner,),
    ).fetchone() or {}
    role_rows = conn.execute(
        "SELECT r.role,r.label,r.description,"
        "(SELECT count(*)::int FROM rvbbit.brain_doc_roles dr "
        " JOIN rvbbit.brain_documents d ON d.doc_id=dr.doc_id "
        " WHERE dr.role=r.role AND d.deleted_at IS NULL) AS documents "
        "FROM rvbbit.brain_role_members rm JOIN rvbbit.brain_roles r ON r.role=rm.role "
        "WHERE lower(rm.principal)=lower(%s) ORDER BY coalesce(r.label,r.role),r.role",
        (owner,),
    ).fetchall()
    aliases = int(alias_row.get("aliases") or 0)
    items.append(_library_inventory_item(
        ref=f"identity:{owner.lower()}",
        kind="identity",
        section="people",
        label=owner,
        summary="The signed-in identity Calliope uses for ownership, private context, and governed access.",
        state="healthy",
        health="Requests, personal context, and ownership are scoped to this verified identity.",
        facts=[
            _library_inventory_fact("Identity aliases", aliases),
            _library_inventory_fact("Access roles", len(role_rows)),
            _library_inventory_fact("Alias sources", int(alias_row.get("sources") or 0)),
        ],
        owner=owner,
        visibility="private",
        detail={
            "email": owner, "identity_aliases": aliases,
            "roles": [str(row.get("role")) for row in role_rows],
        },
        intents=["inspect", "change"],
    ))
    for row in role_rows:
        role = str(row.get("role") or "role")
        items.append(_library_inventory_item(
            ref=f"access_role:{role}",
            kind="access_role",
            section="people",
            label=str(row.get("label") or role),
            summary=str(row.get("description") or "A governed Company Brain access role assigned to you."),
            state="healthy",
            health="This role contributes to the signed-in user's governed document visibility.",
            facts=[
                _library_inventory_fact("Role", role),
                _library_inventory_fact("Documents", int(row.get("documents") or 0)),
            ],
            owner=owner,
            visibility="governed",
            detail={"role": role, "document_count": int(row.get("documents") or 0)},
            intents=["inspect", "change"],
        ))
    return items


def _library_inventory_matches(item: dict[str, Any], query: str) -> bool:
    normalized = re.sub(r"\s+", " ", str(query or "").strip().lower())
    if not normalized:
        return True
    body = " ".join((
        str(item.get("ref") or ""), str(item.get("kind") or ""),
        str(item.get("section_label") or ""), str(item.get("label") or ""),
        str(item.get("summary") or ""), str(item.get("health") or ""),
        " ".join(str(value) for value in (item.get("intents") or [])),
        json.dumps(item.get("facts") or [], default=str, ensure_ascii=False),
        json.dumps(item.get("detail") or {}, default=str, ensure_ascii=False),
    )).lower()
    return all(token in body for token in re.findall(r"[a-z0-9_.:@/-]+", normalized))


def _library_inventory_snapshot(
    conn_factory: Callable[..., Any],
    owner: str,
    *,
    query: str = "",
    section: str | None = None,
    state: str | None = None,
    refs: list[str] | None = None,
    limit: int = _MAX_LIBRARY_INVENTORY_RESULTS,
) -> dict[str, Any]:
    normalized_section = str(section or "").strip().lower()
    normalized_state = str(state or "").strip().lower()
    if normalized_section and normalized_section not in _LIBRARY_INVENTORY_SECTIONS:
        raise ValueError("Unknown Library section")
    if normalized_state and normalized_state not in _LIBRARY_INVENTORY_STATES:
        raise ValueError("Unknown Library state")
    requested_refs = {str(value)[:320] for value in (refs or []) if str(value).strip()}
    collectors = (
        ("Knowledge sources", _library_brain_inventory),
        ("MCP servers", _library_mcp_inventory),
        ("Cubes", _library_cube_inventory),
        ("Metrics", _library_metric_inventory),
        ("Database mirrors", _library_mirror_inventory),
        ("Routines", _library_routine_inventory),
        ("Teams", _library_team_inventory),
        ("Personal context", _library_personal_inventory),
    )
    all_items: list[dict[str, Any]] = []
    warnings: list[str] = []
    for label, collector in collectors:
        try:
            with conn_factory() as conn:
                all_items.extend(collector(conn, owner))
        except Exception as exc:
            warnings.append(f"{label} are temporarily unavailable ({type(exc).__name__}).")
    all_items.sort(key=lambda item: (
        _LIBRARY_INVENTORY_STATE_ORDER.get(str(item.get("state")), 9),
        list(_LIBRARY_INVENTORY_SECTIONS).index(str(item.get("section")))
        if item.get("section") in _LIBRARY_INVENTORY_SECTIONS else 99,
        str(item.get("label") or "").casefold(),
        str(item.get("ref") or ""),
    ))
    section_counts = {
        key: sum(item.get("section") == key for item in all_items)
        for key in _LIBRARY_INVENTORY_SECTIONS
    }
    state_counts = {
        key: sum(item.get("state") == key for item in all_items)
        for key in _LIBRARY_INVENTORY_STATES
    }
    filtered = [
        item for item in all_items
        if (not requested_refs or item.get("ref") in requested_refs)
        and (not normalized_section or item.get("section") == normalized_section)
        and (not normalized_state or item.get("state") == normalized_state)
        and _library_inventory_matches(item, query)
    ]
    bounded_limit = max(1, min(int(limit or _MAX_LIBRARY_INVENTORY_RESULTS), _MAX_LIBRARY_INVENTORY_RESULTS))
    bounded = filtered[:bounded_limit]
    return {
        "query": str(query or ""),
        "section": normalized_section or None,
        "state": normalized_state or None,
        "items": bounded,
        "total": len(filtered),
        "available_total": len(all_items),
        "truncated": len(filtered) > len(bounded),
        "sections": [
            {"id": key, "label": label, "count": section_counts[key]}
            for key, label in _LIBRARY_INVENTORY_SECTIONS.items()
        ],
        "states": [
            {"id": key, "label": label, "count": state_counts[key]}
            for key, label in _LIBRARY_INVENTORY_STATES.items()
        ],
        "summary": {
            "total": len(all_items),
            "needs_attention": state_counts["attention"],
            "healthy": state_counts["healthy"],
            "ready": state_counts["ready"],
            "working": state_counts["syncing"],
            "inactive": state_counts["inactive"],
        },
        "warnings": warnings,
    }


def _capability_runtime_facts(conn, names):
    """Runtime packs need registration evidence, not generated SQL operators.

    Used at read time: a capability graph snapshot can outlive an installation
    or removal, and infrastructure packs need not publish any operator at all.
    """
    if not names:
        return {}
    rows = conn.execute(
        "SELECT c.name,c.runtime_name,coalesce(p.status,m.status,g.status) AS runtime_status,"
        "(p.name IS NOT NULL OR m.name IS NOT NULL OR g.name IS NOT NULL) AS installed "
        "FROM rvbbit.capability_catalog c "
        "LEFT JOIN rvbbit.python_runtimes p ON p.name=c.runtime_name "
        "LEFT JOIN rvbbit.memory_services m ON m.name=c.runtime_name "
        "LEFT JOIN rvbbit.mcp_gateways g ON g.name=c.runtime_name "
        "WHERE c.active AND c.kind='runtime_sidecar' AND c.name=ANY(%s)",
        (list(names),),
    ).fetchall()
    return {row["name"]: dict(row) for row in rows}


def _refresh_capability_runtime_readiness(conn, rows):
    facts = _capability_runtime_facts(conn, [row["name"] for row in rows if row.get("kind") == "runtime_sidecar"])
    for row in rows:
        if row.get("name") in facts:
            fact = facts[row["name"]]
            row["runtime_ready"] = bool(fact["installed"] and fact["runtime_status"] == "ready")
            row["has_operator"] = row["runtime_ready"]  # legacy workflow projection key
    return rows


def _action_runtime_inventory(conn: Any, owner: str | None = None) -> dict[str, Any]:
    mcp_rows = conn.execute(
        "SELECT name,description FROM rvbbit.mcp_servers ORDER BY name LIMIT 500"
    ).fetchall()
    brain_rows = conn.execute(
        "SELECT s.source_id,s.label,s.enabled,"
        "coalesce(nullif(s.config->>'provider',''),s.kind) AS provider,"
        "(SELECT count(*)::int FROM rvbbit.brain_documents d "
        " WHERE d.source_id=s.source_id AND d.deleted_at IS NULL) AS docs "
        "FROM rvbbit.brain_sources s ORDER BY s.source_id LIMIT 500"
    ).fetchall()
    capability_rows = conn.execute(
        "SELECT c.id,c.name,c.title,c.description,c.kind,c.tags,c.operators,c.manifest,"
        "c.catalog_entry,c.resource_profile,c.active,"
        "EXISTS (SELECT 1 FROM unnest(coalesce(c.operators,ARRAY[]::text[])) op(name) "
        " JOIN rvbbit.operators o ON o.name=op.name) AS runtime_ready "
        "FROM rvbbit.capability_catalog c WHERE c.active ORDER BY c.kind,c.title,c.id LIMIT 1000"
    ).fetchall()
    capability_rows = _refresh_capability_runtime_readiness(conn, [dict(row) for row in capability_rows])
    personal = {"briefs": 0, "notes": 0, "inbox_open": 0}
    if owner:
        row = conn.execute(
            "SELECT "
            "(SELECT count(*)::int FROM rvbbit.calliope_briefs WHERE lower(owner_email)=lower(%s)) AS briefs,"
            "(SELECT count(*)::int FROM rvbbit.calliope_daily_notes WHERE lower(owner_email)=lower(%s)) AS notes,"
            "(SELECT count(*)::int FROM rvbbit.calliope_work_items "
            " WHERE lower(owner_email)=lower(%s) AND state IN ('unread','seen')) AS inbox_open",
            (owner, owner, owner),
        ).fetchone() or {}
        personal = {key: int(row.get(key) or 0) for key in personal}
    company_admin = False
    mirror_jobs: list[dict[str, Any]] = []
    mcp_credentials: list[dict[str, Any]] = []
    if owner:
        try:
            company_admin = calliope_dreams._is_company_admin_conn(conn, owner)
        except Exception:
            company_admin = False
    if company_admin:
        relations = conn.execute(
            "SELECT to_regclass('rvbbit.mirror_jobs') IS NOT NULL AS mirror_jobs,"
            "to_regclass('rvbbit.mirror_runs') IS NOT NULL AS mirror_runs,"
            "to_regclass('rvbbit.credentials') IS NOT NULL AS credentials"
        ).fetchone() or {}
        if bool(relations.get("mirror_jobs")) and bool(relations.get("mirror_runs")):
            mirror_jobs = [
                _row_json(row) for row in conn.execute(
                    "SELECT j.job_name,j.connection_name,j.source_schema,j.destination_schema,"
                    "j.enabled,j.schedule_seconds,j.next_run_at,j.last_run_at,j.updated_at,"
                    "(SELECT count(*)::int FROM rvbbit.mirror_tables t "
                    " WHERE t.job_name=j.job_name AND t.enabled) AS table_count,"
                    "latest.run_id AS latest_run_id,latest.status AS latest_run_status,"
                    "latest.trigger AS latest_run_trigger,latest.requested_at AS latest_run_requested_at,"
                    "latest.finished_at AS latest_run_finished_at,"
                    "latest.tables_succeeded AS latest_tables_succeeded,"
                    "latest.tables_failed AS latest_tables_failed,"
                    "latest.rows_loaded AS latest_rows_loaded,"
                    "latest.error_code AS latest_error_code,"
                    "latest.error_message AS latest_error_message "
                    "FROM rvbbit.mirror_jobs j LEFT JOIN LATERAL ("
                    " SELECT r.* FROM rvbbit.mirror_runs r WHERE r.job_name=j.job_name "
                    " ORDER BY r.requested_at DESC LIMIT 1"
                    ") latest ON true ORDER BY j.job_name LIMIT 500"
                ).fetchall()
            ]
        if bool(relations.get("credentials")):
            mcp_credentials = [
                _row_json(row) for row in conn.execute(
                    "SELECT namespace AS server_name,name AS secret_name,version,status,"
                    "updated_at,rotated_at FROM rvbbit.credentials "
                    "WHERE kind='mcp' ORDER BY namespace,name LIMIT 2000"
                ).fetchall()
            ]
    return {
        "mcp_servers": [dict(row) for row in mcp_rows],
        "brain_sources": [dict(row) for row in brain_rows],
        "capabilities": [dict(row) for row in capability_rows],
        "personal": personal,
        "company_admin": company_admin,
        "mirror_jobs": mirror_jobs,
        "mcp_credentials": mcp_credentials,
        "warehouse_ready": True,
    }


def _action_requirement_state(ref: str, inventory: dict[str, Any]) -> dict[str, Any]:
    value = str(ref or "").strip().lower()
    mcp_names = {
        str(item.get("name") or "").lower()
        for item in inventory.get("mcp_servers") or []
        if item.get("name")
    }
    brain_providers = {
        str(item.get("provider") or "").lower()
        for item in inventory.get("brain_sources") or []
        if item.get("enabled", True) and item.get("provider")
    }
    capability_map = {
        str(item.get("id") or "").lower(): item
        for item in inventory.get("capabilities") or []
    }
    available = False
    remediation_action_id = None
    if value == "warehouse":
        available = bool(inventory.get("warehouse_ready"))
    elif value == "personal_context":
        available = sum(int(v or 0) for v in (inventory.get("personal") or {}).values()) > 0
    elif value == "project_ticket":
        available = bool(
            mcp_names.intersection({"linear", "github"})
            or any(
                re.search(
                    r"\b(linear|github|ticket|issue|project)\b",
                    f"{item.get('provider','')} {item.get('label','')}",
                    re.I,
                )
                for item in inventory.get("brain_sources") or []
                if item.get("enabled", True)
            )
        )
        project_capability = next(
            (
                item
                for preferred in ("linear", "github")
                for item in inventory.get("capabilities") or []
                if str(item.get("kind") or "").lower() == "mcp"
                and str(item.get("name") or "").lower() == preferred
            ),
            None,
        )
        if project_capability:
            remediation_action_id = (
                "mcp.connect:" + _capability_action_key(project_capability.get("id"))
            )
    elif value.startswith("mcp:"):
        target = value.split(":", 1)[1]
        available = target in mcp_names
        capability = next(
            (
                item for item in inventory.get("capabilities") or []
                if str(item.get("kind") or "").lower() == "mcp"
                and str(item.get("name") or "").lower() == target
            ),
            None,
        )
        if capability:
            remediation_action_id = (
                "mcp.connect:" + _capability_action_key(capability.get("id"))
            )
    elif value.startswith("brain:"):
        target = value.split(":", 1)[1]
        available = target in brain_providers
        remediation_action_id = "admin.brain_query_source"
    elif value.startswith("capability:"):
        target = value.split(":", 1)[1]
        capability = capability_map.get(target)
        available = bool(capability and capability.get("runtime_ready"))
        if capability:
            remediation_action_id = (
                ("mcp.connect:" if str(capability.get("kind")) == "mcp" else "capability.install:")
                + _capability_action_key(capability.get("id"))
            )
    return {
        "ref": value,
        "available": available,
        "remediation_action_id": remediation_action_id,
    }


def _catalog_action(row: Any) -> dict[str, Any]:
    raw = dict(row)
    schema = _json_object(raw.get("input_schema"))
    config = _json_object(raw.get("config"))
    return {
        "id": str(raw.get("id") or ""),
        "version": int(raw.get("version") or 1),
        "category": str(raw.get("category") or "admin"),
        "title": str(raw.get("title") or raw.get("id") or "Action"),
        "summary": str(raw.get("summary") or ""),
        "description": str(raw.get("description") or ""),
        "executor": str(raw.get("executor") or "conversation"),
        "risk": str(raw.get("risk") or "reversible"),
        "tags": [str(value) for value in (raw.get("tags") or [])],
        "fields": [
            dict(field) for field in (schema.get("fields") or []) if isinstance(field, dict)
        ],
        "requirements": [str(value) for value in (config.get("requirements") or [])],
        "prompt_template": str(config.get("prompt_template") or ""),
        "sort_order": int(raw.get("sort_order") or 100),
        "config": {
            key: value for key, value in config.items()
            if key not in {"requirements", "prompt_template"}
        },
    }


def _dynamic_capability_actions(inventory: dict[str, Any]) -> list[dict[str, Any]]:
    actions: list[dict[str, Any]] = []
    mcp_names = {
        str(item.get("name") or "").lower()
        for item in inventory.get("mcp_servers") or []
    }
    saved_by_server: dict[str, list[str]] = {}
    for credential in inventory.get("mcp_credentials") or []:
        if str(credential.get("status") or "") != "active":
            continue
        server_name = str(credential.get("server_name") or "").strip()
        secret_name = str(credential.get("secret_name") or "").strip()
        if server_name and secret_name:
            saved_by_server.setdefault(server_name, []).append(secret_name)
    for row in inventory.get("capabilities") or []:
        catalog_id = str(row.get("id") or "")
        name = str(row.get("name") or catalog_id.rsplit("/", 1)[-1])
        title = str(row.get("title") or name.replace("-", " ").title())
        description = str(row.get("description") or "")
        manifest = _json_object(row.get("manifest"))
        tags = [str(tag) for tag in (row.get("tags") or [])]
        operators = [str(op) for op in (row.get("operators") or [])]
        if str(row.get("kind") or "").lower() == "mcp":
            fields: list[dict[str, Any]] = [{
                "key": "server_name",
                "label": "Connection name",
                "type": "text",
                "required": True,
                "default": name,
                "pattern": r"^[A-Za-z_][A-Za-z0-9_]{0,63}$",
                "help": "The stable SQL and Workflow name for this connection.",
            }]
            for secret in manifest.get("secrets") or []:
                if not isinstance(secret, dict):
                    continue
                secret_name = str(
                    secret.get("env_var") or secret.get("name") or ""
                ).strip()
                if not secret_name:
                    continue
                fields.append({
                    "key": f"secret:{secret_name}",
                    "secret_name": secret_name,
                    "label": str(secret.get("label") or secret_name),
                    "type": "secret",
                    "required": bool(secret.get("required", True)),
                    "help": str(secret.get("help") or "Stored as canonical encrypted ciphertext through the MCP gateway; never placed in chat, model context, or registration metadata."),
                    "link": str(secret.get("link") or ""),
                })
            installed = name.lower() in mcp_names
            resolves = [f"mcp:{name.lower()}", f"capability:{catalog_id.lower()}"]
            if name.lower() in {"linear", "github"}:
                resolves.append("project_ticket")
            actions.append({
                "id": "mcp.connect:" + _capability_action_key(catalog_id),
                "version": 1,
                "category": "connect",
                "title": f"{'Review' if installed else 'Connect'} {title}",
                "summary": (
                    description
                    or f"Install {title} and expose its tools as typed SQL functions and operators."
                ),
                "description": (
                    f"Register the published {title} MCP connection, keep credentials in the "
                    "canonical encrypted store through the gateway, discover its live tools, generate typed SQL "
                    "functions and RVBBIT operators, and verify reachability."
                ),
                "executor": "mcp_connect",
                "risk": "organization_change",
                "tags": list(dict.fromkeys([*tags, name, "mcp", "connect", "integration", "admin"])),
                "fields": fields,
                "requirements": [],
                "prompt_template": "",
                "sort_order": 200 if installed else 50,
                "config": {
                    "catalog_id": catalog_id,
                    "capability_name": name,
                    "requires_admin": True,
                },
                "resolves": resolves,
                "state": "ready" if installed else "connect",
                "state_label": "Connected" if installed else "Connect",
                "operator_count": len(operators),
                "secure_state": {
                    "server": name,
                    "known": True,
                    "saved_names": sorted(set(saved_by_server.get(name, []))),
                },
            })
            continue
        ready = bool(row.get("runtime_ready"))
        prebuilt = _json_object(manifest.get("prebuilt_runtime"))
        options = [{"value": "build", "label": "Build from packaged source"}]
        if prebuilt.get("image") or _json_object(manifest.get("runtime")).get("image"):
            options.insert(0, {"value": "image", "label": "Use prebuilt image"})
        actions.append({
            "id": "capability.install:" + _capability_action_key(catalog_id),
            "version": 1,
            "category": "admin",
            "title": f"{'Inspect' if ready else 'Install'} {title}",
            "summary": description or f"Deploy the {title} capability through Warren.",
            "description": (
                "Validate the packaged manifest, queue a Warren deployment, and return the "
                "durable job and runtime observation needed to follow its progress."
            ),
            "executor": "capability_install",
            "risk": "organization_change",
            "tags": list(dict.fromkeys([*tags, name, "capability", "install", str(row.get("kind") or "")])),
            "fields": [{
                "key": "install_mode", "label": "Install mode", "type": "select",
                "required": True, "default": options[0]["value"], "options": options,
            }],
            "requirements": [],
            "prompt_template": "",
            "sort_order": 300 if ready else 120,
            "config": {
                "catalog_id": catalog_id,
                "capability_name": name,
                "requires_admin": True,
            },
            "resolves": [f"capability:{catalog_id.lower()}"],
            "state": "ready" if ready else "install",
            "state_label": "Ready" if ready else "Install",
            "operator_count": len(operators),
        })
    return actions


def _dynamic_administration_actions(inventory: dict[str, Any]) -> list[dict[str, Any]]:
    """Build admin-only actions from the exact control-plane revisions observed now."""
    if not inventory.get("company_admin"):
        return []
    actions: list[dict[str, Any]] = mirror_actions.catalog()
    for raw in inventory.get("mirror_jobs") or []:
        row = _row_json(raw)
        job_name = str(row.get("job_name") or "").strip()
        if not job_name:
            continue
        enabled = bool(row.get("enabled"))
        latest_status = str(row.get("latest_run_status") or "")
        operations: list[dict[str, str]] = []
        if enabled:
            operations.extend([
                {"value": "run_now", "label": "Run now"},
                {"value": "pause", "label": "Pause future runs"},
            ])
        else:
            operations.append({"value": "resume", "label": "Resume mirror"})
        if enabled and latest_status in _MIRROR_RETRYABLE_STATUSES:
            operations.insert(0, {"value": "retry_last_failed", "label": "Retry latest failed run"})
        operations.append({"value": "set_schedule", "label": "Change cadence"})
        default_operation = (
            "retry_last_failed"
            if enabled and latest_status in _MIRROR_RETRYABLE_STATUSES
            else "run_now" if enabled else "resume"
        )
        if not enabled:
            state, state_label = "connect", "Paused"
        elif latest_status in _MIRROR_RETRYABLE_STATUSES:
            state, state_label = "blocked", "Retry available"
        elif latest_status in {"queued", "running"}:
            state, state_label = "ready", "Running"
        elif row.get("schedule_seconds"):
            state, state_label = "ready", "Scheduled"
        else:
            state, state_label = "ready", "Manual"
        latest_error = _action_error_text(row.get("latest_error_message")) or None
        actions.append({
            "id": "mirror.manage:" + _capability_action_key(job_name),
            "version": 1,
            "category": "admin",
            "title": f"Manage {job_name} mirror",
            "summary": (
                f"Run, retry, or change the cadence for the {job_name} database mirror "
                "without giving Calliope access to its production source."
            ),
            "description": (
                f"Manage the local dlt control-plane job that mirrors "
                f"{row.get('connection_name')}.{row.get('source_schema')} into the "
                f"{row.get('destination_schema')} schema. Each receipt is pinned to the "
                "current job revision and never exposes the source credential."
            ),
            "executor": "mirror_control",
            "risk": "reversible",
            "tags": [
                job_name, "mirror", "database mirror", "dlt", "sync", "run",
                "retry", "failure", "pause", "resume", "schedule", "cadence", "admin",
            ],
            "fields": [
                {
                    "key": "operation", "label": "Change", "type": "select",
                    "required": True, "default": default_operation, "options": operations,
                },
                {
                    "key": "schedule_seconds", "label": "Cadence", "type": "select",
                    "required": True,
                    "default": (
                        str(row.get("schedule_seconds"))
                        if row.get("schedule_seconds") is not None else "manual"
                    ),
                    "options": [
                        {"value": value, "label": label}
                        for value, label in _MIRROR_SCHEDULE_OPTIONS
                    ],
                    "visible_when": {"field": "operation", "value": "set_schedule"},
                    "help": "Manual keeps the job available on demand but removes its recurring schedule.",
                },
            ],
            "requirements": [],
            "prompt_template": "",
            "sort_order": 35 if latest_status in _MIRROR_RETRYABLE_STATUSES else 180,
            "config": {
                "requires_admin": True,
                "job_name": job_name,
                "expected_updated_at": row.get("updated_at"),
                "current": {
                    "connection_name": row.get("connection_name"),
                    "source_schema": row.get("source_schema"),
                    "destination_schema": row.get("destination_schema"),
                    "enabled": enabled,
                    "schedule_seconds": row.get("schedule_seconds"),
                    "next_run_at": row.get("next_run_at"),
                    "table_count": int(row.get("table_count") or 0),
                },
                "latest_run": {
                    "run_id": str(row.get("latest_run_id")) if row.get("latest_run_id") else None,
                    "status": latest_status or None,
                    "trigger": row.get("latest_run_trigger"),
                    "requested_at": row.get("latest_run_requested_at"),
                    "finished_at": row.get("latest_run_finished_at"),
                    "tables_succeeded": int(row.get("latest_tables_succeeded") or 0),
                    "tables_failed": int(row.get("latest_tables_failed") or 0),
                    "rows_loaded": int(row.get("latest_rows_loaded") or 0),
                    "error_code": row.get("latest_error_code"),
                    "error": latest_error,
                },
            },
            "resolves": [f"mirror:{job_name.lower()}"],
            "state": state,
            "state_label": state_label,
        })

    credentials_by_server: dict[str, list[dict[str, Any]]] = {}
    for raw in inventory.get("mcp_credentials") or []:
        row = _row_json(raw)
        credentials_by_server.setdefault(str(row.get("server_name") or ""), []).append(row)
    for raw in inventory.get("mcp_servers") or []:
        server = str(raw.get("name") or "").strip()
        if not server:
            continue
        credential_rows = credentials_by_server.get(server, [])
        revisions = {
            str(row.get("secret_name")): {
                "version": int(row.get("version") or 0),
                "status": str(row.get("status") or ""),
                "updated_at": row.get("updated_at"),
                "rotated_at": row.get("rotated_at"),
            }
            for row in credential_rows
            if row.get("secret_name")
        }
        active_names = sorted(
            name for name, revision in revisions.items()
            if revision.get("status") == "active"
        )
        actions.append({
            "id": "mcp.credentials:" + _capability_action_key(server),
            "version": 1,
            "category": "admin",
            "title": f"Manage {server} credentials",
            "summary": (
                f"Add, rotate, or revoke named credentials for the {server} MCP server "
                "through the canonical encrypted store."
            ),
            "description": (
                "Calliope can inspect names, versions, and status, but never receives a value. "
                "The native Library sends a one-way value envelope directly to the MCP gateway, "
                "applies the requested change, and verifies the resulting metadata in one step."
            ),
            "executor": "mcp_credentials",
            "risk": "organization_change",
            "tags": [
                server, "mcp", "credential", "credentials", "secret", "api key",
                "rotate", "revoke", "token", "admin",
            ],
            "fields": [
                {
                    "key": "operation", "label": "Change", "type": "select",
                    "required": True, "default": "rotate",
                    "options": [
                        {"value": "rotate", "label": "Add or rotate a credential"},
                        *([{"value": "revoke", "label": "Revoke a credential"}]
                          if active_names else []),
                    ],
                },
                {
                    "key": "credential_name", "label": "Credential name", "type": "text",
                    "required": True, "default": active_names[0] if active_names else "",
                    "pattern": r"^[A-Za-z_][A-Za-z0-9_]{0,127}$",
                    "placeholder": "SERVICE_API_KEY",
                    "help": "The exact ${NAME} referenced by this MCP registration.",
                },
                {
                    "key": "secret:CREDENTIAL_VALUE", "secret_name": "CREDENTIAL_VALUE",
                    "secret_group": True, "allow_reuse": False,
                    "label": "New credential value", "type": "secret",
                    "required": True,
                    "visible_when": {"field": "operation", "value": "rotate"},
                    "help": (
                        "Submitted only when applying in the native Library. It is encrypted by "
                        "the canonical store and never enters chat, model context, plans, or receipts."
                    ),
                },
            ],
            "requirements": [],
            "prompt_template": "",
            "sort_order": 190,
            "config": {
                "requires_admin": True,
                "server_name": server,
                "credential_revisions": revisions,
                "active_names": active_names,
            },
            "resolves": [f"mcp:{server.lower()}:credentials"],
            "state": "ready",
            "state_label": f"{len(active_names)} saved" if active_names else "No saved credentials",
        })
    return actions


def _action_search_score(action: dict[str, Any], query: str) -> int:
    query = re.sub(r"\s+", " ", str(query or "").strip().lower())
    if not query:
        return 1
    action_id = str(action.get("id") or "").lower()
    title = str(action.get("title") or "").lower()
    tags = " ".join(str(value).lower() for value in action.get("tags") or [])
    body = " ".join((
        action_id,
        title,
        str(action.get("summary") or "").lower(),
        str(action.get("description") or "").lower(),
        tags,
        " ".join(action.get("requirements") or []),
    ))
    tokens = [token for token in re.findall(r"[a-z0-9_./-]+", query) if len(token) > 1]
    score = 0
    if query == action_id:
        score += 260
    elif query == title:
        score += 200
    elif query in title:
        score += 90
    elif query in body:
        score += 40
    for token in tokens:
        if token in title:
            score += 30
        if token in tags:
            score += 18
        if token in body:
            score += 8
    return score


def _action_catalog_snapshot(
    conn_factory: Callable[..., Any],
    owner: str,
    query: str = "",
    category: str | None = None,
    requirement: str | None = None,
    limit: int = 100,
) -> dict[str, Any]:
    normalized_category = str(category or "").strip().lower()
    if normalized_category and normalized_category not in _ACTION_CATEGORIES:
        raise ValueError("Unknown action category")
    with conn_factory() as conn:
        inventory = _action_runtime_inventory(conn, owner)
        rows = conn.execute(
            "SELECT id,version,category,title,summary,description,executor,risk,tags,"
            "input_schema,config,sort_order FROM rvbbit.calliope_action_catalog "
            "WHERE active ORDER BY sort_order,title,id"
        ).fetchall()
    actions = [_catalog_action(row) for row in rows]
    import correspondence
    actions.append(correspondence.connection_action())
    import sms
    actions.extend(sms.actions())
    actions.extend(_dynamic_capability_actions(inventory))
    actions.extend(_dynamic_administration_actions(inventory))
    for action in actions:
        requirement_states = [
            _action_requirement_state(ref, inventory)
            for ref in action.get("requirements") or []
        ]
        action["requirement_states"] = requirement_states
        missing = [item for item in requirement_states if not item["available"]]
        action["missing_requirements"] = missing
        if (action.get("config") or {}).get("generic_mcp"):
            action["state"] = "connect"
            action["state_label"] = "Connect"
        elif "state" not in action:
            action["state"] = "blocked" if missing else "ready"
            action["state_label"] = "Needs setup" if missing else (
                "Guided" if action.get("executor") == "conversation" else "Ready"
            )
        action["resolves"] = [str(value) for value in action.get("resolves") or []]
        action["category_label"] = _ACTION_CATEGORIES.get(action["category"], action["category"])
        action["score"] = _action_search_score(action, query)
    filtered = [
        action for action in actions
        if action["score"] > 0
        and (not normalized_category or action["category"] == normalized_category)
        and (not requirement or str(requirement).lower() in action.get("resolves", []))
    ]
    filtered.sort(key=lambda action: (
        -int(action.get("score") or 0),
        0 if action.get("state") not in {"ready"} else 1,
        int(action.get("sort_order") or 100),
        str(action.get("title") or "").lower(),
    ))
    bounded = filtered[:max(1, min(int(limit or 100), _MAX_ACTION_SEARCH_RESULTS))]
    counts = {
        key: sum(1 for action in actions if action.get("category") == key)
        for key in _ACTION_CATEGORIES
    }
    return {
        "query": str(query or ""),
        "category": normalized_category or None,
        "actions": bounded,
        "total": len(filtered),
        "categories": [
            {"id": key, "label": label, "count": counts[key]}
            for key, label in _ACTION_CATEGORIES.items()
        ],
        "trusted_organization_mode": True,
    }


def _action_by_id(
    conn_factory: Callable[..., Any], owner: str, action_id: Any
) -> dict[str, Any] | None:
    value = str(action_id or "").strip().lower()
    if not _ACTION_ID_RE.fullmatch(value):
        return None
    # Searching by the exact id keeps dynamic actions addressable even when a
    # large capability catalog would otherwise push them past the list limit.
    snapshot = _action_catalog_snapshot(
        conn_factory, owner, query=value, limit=_MAX_ACTION_SEARCH_RESULTS
    )
    return next(
        (action for action in snapshot["actions"] if action.get("id") == value),
        None,
    )


def _action_field_is_visible(
    field: dict[str, Any], resolved_inputs: dict[str, Any]
) -> bool:
    condition = field.get("visible_when")
    if not isinstance(condition, dict):
        return True
    controller = str(condition.get("field") or "").strip()
    if not controller:
        return True
    expected = condition.get("values")
    if not isinstance(expected, list):
        expected = [condition.get("value")]
    actual = resolved_inputs.get(controller)
    return str(actual) in {str(value) for value in expected}


def _normalize_action_inputs(
    action: dict[str, Any],
    raw_inputs: Any,
    *,
    require_secrets: bool = False,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, str]]:
    supplied = dict(raw_inputs) if isinstance(raw_inputs, dict) else {}
    resolved_inputs = {
        str(field.get("key") or "").strip(): supplied.get(
            str(field.get("key") or "").strip(), field.get("default")
        )
        for field in action.get("fields") or []
        if isinstance(field, dict) and str(field.get("key") or "").strip()
    }
    values: dict[str, Any] = {}
    redacted: dict[str, Any] = {}
    secrets: dict[str, str] = {}
    for field in action.get("fields") or []:
        if not isinstance(field, dict):
            continue
        key = str(field.get("key") or "").strip()
        kind = str(field.get("type") or "text").strip().lower()
        if not key or kind not in _ACTION_FIELD_TYPES:
            continue
        if not _action_field_is_visible(field, resolved_inputs):
            continue
        value = supplied.get(key, field.get("default"))
        if kind == "secret":
            secret_value = str(value or "")
            if len(secret_value) > _MAX_ACTION_INPUT_CHARS:
                raise ValueError(f"{field.get('label') or key} is too long")
            if secret_value:
                secret_name = str(field.get("secret_name") or key.removeprefix("secret:"))
                secrets[secret_name] = secret_value
                redacted[key] = "••••••"
            elif require_secrets and field.get("required"):
                raise ValueError(f"{field.get('label') or key} is required")
            else:
                redacted[key] = None
            continue
        if kind == "boolean":
            if isinstance(value, str):
                value = value.strip().lower() in {"1", "true", "yes", "on"}
            value = bool(value)
        else:
            value = str(value or "").strip()
            if len(value) > _MAX_ACTION_INPUT_CHARS:
                raise ValueError(f"{field.get('label') or key} is too long")
            if field.get("required") and not value:
                raise ValueError(f"{field.get('label') or key} is required")
            pattern = str(field.get("pattern") or "")
            if value and pattern and not re.fullmatch(pattern, value):
                raise ValueError(f"{field.get('label') or key} has an invalid format")
            if kind == "select" and value:
                allowed = {
                    str(option.get("value"))
                    for option in field.get("options") or []
                    if isinstance(option, dict)
                }
                if value not in allowed:
                    raise ValueError(f"{field.get('label') or key} has an invalid choice")
        values[key] = value
        redacted[key] = value
    return values, redacted, secrets


def _parse_custom_mcp_args(raw: Any) -> list[str]:
    text = str(raw or "").strip()
    if not text:
        return []
    try:
        parsed = json.loads(text)
        parsed_json = True
    except json.JSONDecodeError:
        parsed = None
        parsed_json = False
    if not parsed_json:
        args = [line.strip() for line in text.splitlines() if line.strip()]
        if any(re.search(r"\s", arg) for arg in args):
            raise ValueError(
                "Arguments must be a JSON string array or one whitespace-free argument per line"
            )
    elif isinstance(parsed, list):
        args = parsed
    else:
        raise ValueError("Arguments must be a JSON string array")
    if len(args) > _MAX_MCP_ARGS:
        raise ValueError(f"Arguments can contain at most {_MAX_MCP_ARGS} entries")
    if any(not isinstance(arg, str) or not arg or len(arg) > 4_000 for arg in args):
        raise ValueError("Every MCP argument must be a non-empty string of at most 4000 characters")
    if any("\x00" in arg or "\r" in arg or "\n" in arg for arg in args):
        raise ValueError("MCP arguments cannot contain control characters")
    return args


def _parse_custom_mcp_environment(raw: Any) -> dict[str, str]:
    text = str(raw or "").strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("Non-secret environment must be a valid JSON object") from exc
    if not isinstance(parsed, dict):
        raise ValueError("Non-secret environment must be a JSON object")
    if len(parsed) > _MAX_MCP_ENV_KEYS:
        raise ValueError(
            f"Non-secret environment can contain at most {_MAX_MCP_ENV_KEYS} entries"
        )
    environment: dict[str, str] = {}
    for raw_name, raw_value in parsed.items():
        name = str(raw_name or "").strip()
        if not _MCP_ENV_NAME_RE.fullmatch(name):
            raise ValueError(f"Environment name {name or '(empty)'} has an invalid format")
        if not isinstance(raw_value, str) or len(raw_value) > 8_000:
            raise ValueError(
                f"Environment value {name} must be a string of at most 8000 characters"
            )
        if "\x00" in raw_value or "\r" in raw_value or "\n" in raw_value:
            raise ValueError(f"Environment value {name} cannot contain control characters")
        if _MCP_SECRETISH_ENV_RE.search(name) and not _MCP_SECRET_REF_RE.search(raw_value):
            raise ValueError(
                f"Environment value {name} looks secret; use a ${{{name}}} reference and "
                "provide its value in Secure values"
            )
        environment[name] = raw_value
    return environment


def _parse_custom_mcp_secret_names(raw: Any) -> set[str]:
    names = {
        value for value in re.split(r"[\s,]+", str(raw or "").strip()) if value
    }
    invalid = sorted(name for name in names if not _MCP_ENV_NAME_RE.fullmatch(name))
    if invalid:
        raise ValueError("Secret name has an invalid format: " + ", ".join(invalid))
    if len(names) > _MAX_MCP_SECRET_NAMES:
        raise ValueError(f"At most {_MAX_MCP_SECRET_NAMES} secret names can be declared")
    return names


def _parse_custom_mcp_secure_values(raw: Any) -> dict[str, str]:
    text = str(raw or "").strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("Secure values must be a valid JSON object") from exc
    if not isinstance(parsed, dict):
        raise ValueError("Secure values must be a JSON object")
    if len(parsed) > _MAX_MCP_SECRET_NAMES:
        raise ValueError(f"At most {_MAX_MCP_SECRET_NAMES} secure values can be supplied")
    values: dict[str, str] = {}
    for raw_name, raw_value in parsed.items():
        name = str(raw_name or "").strip()
        if not _MCP_ENV_NAME_RE.fullmatch(name):
            raise ValueError(f"Secure value name {name or '(empty)'} has an invalid format")
        if not isinstance(raw_value, str) or not raw_value or len(raw_value) > 16_000:
            raise ValueError(
                f"Secure value {name} must be a non-empty string of at most 16000 characters"
            )
        values[name] = raw_value
    return values


def _custom_mcp_spec(
    values: dict[str, Any], secret_envelope: dict[str, str]
) -> tuple[dict[str, Any], dict[str, str]]:
    server = str(values.get("server_name") or "").strip()
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,62}", server):
        raise ValueError("Connection name must be an identifier of at most 63 characters")
    if server.lower() in _RESERVED_MCP_SCHEMA_NAMES or server.lower().startswith("pg_"):
        raise ValueError(
            "Connection name is reserved by Postgres or RVBBIT; choose a distinct MCP name"
        )
    transport = str(values.get("transport") or "http").strip().lower()
    if transport not in {"http", "stdio"}:
        raise ValueError("Transport must be hosted HTTP or local stdio")
    try:
        timeout_ms = int(str(values.get("timeout_ms") or "30000"))
    except (TypeError, ValueError) as exc:
        raise ValueError("Timeout must be a whole number of milliseconds") from exc
    if not 1 <= timeout_ms <= 600_000:
        raise ValueError("Timeout must be between 1 and 600000 milliseconds")
    description = str(values.get("description") or "").strip()
    if len(description) > 2_000:
        raise ValueError("Description must be at most 2000 characters")

    url: str | None = None
    command: str | None = None
    args: list[str] = []
    environment: dict[str, str] = {}
    auth_token_name: str | None = None
    auth_mode = "bearer"
    oauth_client_id: str | None = None
    oauth_scope: str | None = None
    declared_secret_names: set[str] = set()
    if transport == "http":
        url = str(values.get("url") or "").strip()
        try:
            parsed_url = urlsplit(url)
            parsed_port = parsed_url.port
        except ValueError as exc:
            raise ValueError("MCP endpoint URL has an invalid host or port") from exc
        if (
            parsed_url.scheme.lower() not in {"http", "https"}
            or not parsed_url.hostname
            or parsed_url.username
            or parsed_url.password
            or parsed_url.fragment
        ):
            raise ValueError(
                "MCP endpoint must be an HTTP(S) URL without credentials or a fragment"
            )
        if parsed_port is not None and not 1 <= parsed_port <= 65_535:
            raise ValueError("MCP endpoint URL has an invalid port")
        for key, query_value in parse_qsl(parsed_url.query, keep_blank_values=True):
            normalized_key = re.sub(r"[^A-Za-z0-9]+", "_", key).strip("_")
            if query_value and _MCP_SECRETISH_ENV_RE.search(normalized_key):
                raise ValueError(
                    "MCP endpoint URL appears to contain a credential; use Bearer token name "
                    "and Secure values instead"
                )
        auth_mode = str(values.get("auth_mode") or "bearer").strip().lower()
        if auth_mode not in {"bearer", "oauth"}:
            raise ValueError("Authentication must be Bearer token or OAuth")
        if auth_mode == "oauth":
            # OAuth replaces the static bearer: no auth_header_env is
            # registered; the gateway injects refreshed access tokens itself.
            oauth_client_id = str(values.get("oauth_client_id") or "").strip() or None
            if oauth_client_id and (
                len(oauth_client_id) > 512 or re.search(r"[\s\x00-\x1f]", oauth_client_id)
            ):
                raise ValueError("OAuth client id has an invalid format")
            oauth_scope = str(values.get("oauth_scope") or "").strip() or None
            if oauth_scope and (
                len(oauth_scope) > 512 or re.search(r"[\x00-\x1f]", oauth_scope)
            ):
                raise ValueError("OAuth scope has an invalid format")
        else:
            auth_token_name = str(values.get("auth_token_name") or "").strip() or None
            if auth_token_name and not _MCP_ENV_NAME_RE.fullmatch(auth_token_name):
                raise ValueError("Bearer token name has an invalid format")
            if auth_token_name:
                declared_secret_names.add(auth_token_name)
    else:
        command = str(values.get("command") or "").strip()
        if not command:
            raise ValueError("Executable is required for a stdio MCP server")
        if len(command) > 1_000 or "\x00" in command or re.search(r"[\r\n]", command):
            raise ValueError("Executable has an invalid format")
        if re.search(r"\s", command):
            raise ValueError("Executable must not include arguments; put them in Arguments")
        args = _parse_custom_mcp_args(values.get("args"))
        environment = _parse_custom_mcp_environment(values.get("environment"))
        declared_secret_names.update(
            _parse_custom_mcp_secret_names(values.get("secret_names"))
        )
        for candidate in [*args, *environment.values()]:
            declared_secret_names.update(_MCP_SECRET_REF_RE.findall(candidate))
        if len(declared_secret_names) > _MAX_MCP_SECRET_NAMES:
            raise ValueError(f"At most {_MAX_MCP_SECRET_NAMES} secret names can be declared")
        for name in declared_secret_names:
            environment.setdefault(name, f"${{{name}}}")

    secure_values = _parse_custom_mcp_secure_values(
        secret_envelope.get("MCP_SECRET_VALUES")
    )
    undeclared = sorted(set(secure_values).difference(declared_secret_names))
    if undeclared:
        raise ValueError(
            "Secure value name was not declared in the reviewed connection: "
            + ", ".join(undeclared)
        )
    oauth_client_secret = str(
        secret_envelope.get("MCP_OAUTH_CLIENT_SECRET") or ""
    ).strip()
    if oauth_client_secret:
        if auth_mode != "oauth":
            raise ValueError(
                "An OAuth client secret was supplied without OAuth authentication"
            )
        if not oauth_client_id:
            raise ValueError(
                "An OAuth client secret needs its client id in the reviewed connection"
            )
        # Rides the secure channel to /oauth/start (sealed into the OAuth
        # client record there) — deliberately NOT a per-server gateway secret.
        secure_values[_MCP_OAUTH_CLIENT_SECRET_KEY] = oauth_client_secret
    spec = {
        "server": server,
        "transport": transport,
        "command": command,
        "args": args,
        "environment": environment,
        "url": url,
        "auth_mode": auth_mode if transport == "http" else "bearer",
        "auth_token_name": auth_token_name,
        "oauth_client_id": oauth_client_id,
        "oauth_scope": oauth_scope,
        "timeout_ms": timeout_ms,
        "description": description or None,
        "create_sql_functions": bool(values.get("create_sql_functions", True)),
        "create_operators": bool(values.get("create_operators", True)),
        "declared_secret_names": declared_secret_names,
    }
    return spec, secure_values


def _require_action_access(
    conn_factory: Callable[..., Any], owner: str, action: dict[str, Any]
) -> None:
    if not (action.get("config") or {}).get("requires_admin"):
        return
    if not calliope_dreams.is_company_admin(conn_factory, owner):
        raise PermissionError(
            "Only a member of the Admins Team can apply this company change."
        )


def _validate_administration_action_inputs(
    action: dict[str, Any], values: dict[str, Any]
) -> None:
    executor = str(action.get("executor") or "")
    config = action.get("config") or {}
    if executor == 'mail_connect':
        if values.get('address'):
            import correspondence
            correspondence.connection_settings(values)
    elif executor == "mirror_connect":
        mirror_actions.validate_source(values)
    elif executor == "mirror_create":
        mirror_actions.plan(values)
    elif executor == "mirror_control":
        operation = str(values.get("operation") or "")
        if operation == "set_schedule":
            allowed = {value for value, _label in _MIRROR_SCHEDULE_OPTIONS}
            if str(values.get("schedule_seconds") or "") not in allowed:
                raise ValueError("Cadence has an invalid choice")
        if operation == "retry_last_failed":
            latest = config.get("latest_run") or {}
            if (
                not latest.get("run_id")
                or str(latest.get("status") or "") not in _MIRROR_RETRYABLE_STATUSES
            ):
                raise ValueError("The frozen plan has no failed mirror run to retry")
    elif executor == "brain_query_source":
        provider = str(values.get("provider") or config.get("provider") or "").strip()
        label = str(values.get("label") or config.get("label") or "").strip()
        if not re.fullmatch(r"[a-z][a-z0-9_-]{1,63}", provider):
            raise ValueError("Document provider key has an invalid format")
        if not label:
            raise ValueError("Document source label is required")
        if not values.get("list_sql") and not config.get("reuse_provider"):
            raise ValueError("List query is required for a new document provider")
        if not isinstance(config.get("source_config", {}), dict):
            raise ValueError("Document source configuration must be an object")
    elif executor == "mcp_credentials":
        operation = str(values.get("operation") or "")
        name = str(values.get("credential_name") or "")
        if not _MCP_ENV_NAME_RE.fullmatch(name):
            raise ValueError("Credential name has an invalid format")
        if operation == "revoke":
            revision = (config.get("credential_revisions") or {}).get(name) or {}
            if revision.get("status") != "active":
                raise ValueError(
                    f"No active {name} credential exists in the reviewed {config.get('server_name')} state"
                )


def _action_plan_document(action: dict[str, Any], values: dict[str, Any]) -> dict[str, Any]:
    executor = action.get("executor")
    if executor in {'sms_connect', 'sms_user'}:
        steps = [('connect', 'Configure text messaging', 'Verify Twilio or an existing login mapping and save the reviewed settings.')]
        change = 'Connect Twilio for SMS.' if executor == 'sms_connect' else 'Link or revoke a phone number for an existing Calliope login.'
        rollback = 'Reconnect to rotate credentials; use sms.user to revoke a phone mapping. No test text is sent.'
    elif executor == 'mail_connect':
        steps = [('connect', 'Test and connect mailbox', 'Verify incoming and outgoing access, then save the encrypted credential.')]
        change = 'Connect this operator’s mailbox for incoming mail and reviewed outgoing drafts.'
        rollback = 'Reconnect the same address with corrected connection details. No email is sent by this test.'
    elif executor == "mcp_connect":
        if (action.get("config") or {}).get("generic_mcp"):
            steps = [
                (
                    "inspect", "Inspect custom connection",
                    "Validate the reviewed transport, endpoint or executable, secret references, and current registration.",
                ),
                (
                    "register", "Register MCP server",
                    "Store only the requested connection shape and ${NAME} references in Postgres.",
                ),
                (
                    "secrets", "Store credentials securely",
                    "Send declared secret values only through the gateway to the canonical encrypted store.",
                ),
                *(
                    [(
                        "authorize", "Sign in with the browser",
                        "Discover the service's authorization server, open its sign-in page, and store only refreshable tokens in the encrypted gateway store.",
                    )]
                    if str(values.get("auth_mode") or "") == "oauth"
                    and str(values.get("transport") or "http") == "http"
                    else []
                ),
                (
                    "discover", "Discover tools and build SQL surface",
                    "Introspect live tools and resources, then generate typed SQL functions and optional RVBBIT operators.",
                ),
                (
                    "verify", "Verify reachability and functions",
                    "Actively probe tools/list and count the live SQL, resource, and operator surfaces.",
                ),
            ]
            change = (
                f"Connect custom {values.get('transport') or 'http'} MCP server "
                f"{values.get('server_name')}"
            )
        else:
            steps = [
                (
                    "inspect", "Inspect published connection",
                    "Validate the exact catalog manifest and current registration.",
                ),
                (
                    "register", "Register MCP server",
                    "Apply the catalog-owned command, transport, and environment references.",
                ),
                (
                    "secrets", "Store credentials securely",
                    "Send only typed secret values through the gateway to the canonical encrypted store.",
                ),
                (
                    "discover", "Discover tools and build SQL surface",
                    "Refresh the live server, reconcile drift, and create typed SQL functions and RVBBIT operators.",
                ),
                (
                    "verify", "Verify reachability",
                    "Actively probe tools/list and confirm the installed SQL and operator surfaces.",
                ),
            ]
            change = (
                f"Connect {action.get('config', {}).get('capability_name') or action.get('title')} "
                f"as {values.get('server_name')}"
            )
        rollback = (
            "Drop a new MCP registration, or restore the prior reviewed connection when "
            "reusing a name, then remove its gateway secret entries."
        )
    elif executor == "capability_install":
        steps = [
            ("inspect", "Inspect packaged capability", "Validate the active SQL catalog row and chosen install mode."),
            ("queue", "Queue Warren deployment", "Create a durable capability job for the selected runtime."),
            ("verify", "Verify deployment handoff", "Confirm the Warren job exists and report its current lifecycle state."),
        ]
        change = f"Deploy {action.get('config', {}).get('catalog_id')} in {values.get('install_mode')} mode"
        rollback = "Use the resulting Warren deployment controls to stop or remove the runtime."
    elif executor == "brain_query_source":
        config = action.get("config") or {}
        provider = values.get("provider") or config.get("provider")
        label = values.get("label") or config.get("label")
        reuse_provider = bool(config.get("reuse_provider"))
        steps = [
            (
                "inspect", "Validate packaged provider" if reuse_provider else "Validate provider contract",
                (
                    "Verify the packaged provider and its required live read connection."
                    if reuse_provider
                    else "Check the stable key, SQL, document type, and current source state."
                ),
            ),
            (
                "define", "Reuse packaged document provider" if reuse_provider else "Define document provider",
                (
                    "Keep the shipped provider definition intact and bind it by stable key."
                    if reuse_provider
                    else "Create or update the reusable query-backed provider."
                ),
            ),
            ("source", "Enable Company Brain source", "Create or reuse the source and leave it enabled for scheduled refresh."),
            ("sync", "Run first synchronization", "Resolve query rows into searchable documents when requested."),
            ("verify", "Verify source and documents", "Report enabled state, sync status, and current document count."),
        ]
        change = f"Enable Company Brain source {label} using provider {provider}"
        rollback = (
            "Delete the source with document purge; the packaged provider remains available."
            if reuse_provider
            else "Delete the source with document purge, then remove the unused provider."
        )
    elif executor in {"mirror_connect", "mirror_create"}:
        steps = [
            ("apply", "Connect source" if executor == "mirror_connect" else "Create mirror job",
             "Reuse existing configuration; apply ordinary database work with a durable receipt."),
            ("verify", "Verify source" if executor == "mirror_connect" else "Verify job registration",
             "Report what was saved and distinguish source reachability or queued work from completed loading."),
        ]
        change = str(action.get("summary"))
        rollback = "Pause the mirror through its manage action. Existing source data remains untouched."
    elif executor == "mirror_control":
        operation = str(values.get("operation") or "")
        job_name = str((action.get("config") or {}).get("job_name") or "mirror")
        current = (action.get("config") or {}).get("current") or {}
        labels = {
            "run_now": "Run now",
            "retry_last_failed": "Retry latest failed run",
            "pause": "Pause future runs",
            "resume": "Resume mirror",
            "set_schedule": "Change cadence",
        }
        steps = [
            (
                "inspect", "Recheck mirror revision",
                "Read the exact local job and latest run again; stop if either changed after this plan was created.",
            ),
            (
                "apply", labels.get(operation, "Apply mirror change"),
                (
                    "Queue a local dlt run using the already-registered read-only credential reference."
                    if operation in {"run_now", "retry_last_failed"}
                    else "Change only the local job schedule controls; a currently queued or running load is not cancelled."
                ),
            ),
            (
                "verify", "Verify local control-plane state",
                "Read the job and latest durable dlt run receipt back from the RVBBIT database.",
            ),
        ]
        if operation == "set_schedule":
            cadence = next(
                (label for value, label in _MIRROR_SCHEDULE_OPTIONS
                 if value == str(values.get("schedule_seconds"))),
                str(values.get("schedule_seconds")),
            )
            change = f"Set {job_name} mirror cadence to {cadence}"
        else:
            change = f"{labels.get(operation, 'Manage')} for {job_name} mirror"
        rollback = (
            f"Restore enabled={bool(current.get('enabled'))} and the prior cadence "
            f"({current.get('schedule_seconds') or 'manual'}). Queued or completed loads remain as durable receipts."
        )
    elif executor == "mcp_credentials":
        operation = str(values.get("operation") or "")
        server = str((action.get("config") or {}).get("server_name") or "MCP server")
        name = str(values.get("credential_name") or "credential")
        steps = [
            (
                "inspect", "Recheck canonical credential metadata",
                "Require the canonical encrypted store and compare the exact name, version, and status with this plan.",
            ),
            (
                "apply", "Rotate credential" if operation == "rotate" else "Revoke credential",
                (
                    "Accept the replacement value only through the native Library's one-way secure envelope."
                    if operation == "rotate"
                    else "Remove the encrypted credential through the MCP gateway; no value is read or returned."
                ),
            ),
            (
                "verify", "Verify metadata and runtime cache",
                (
                    "Confirm the new canonical version and actively probe the MCP server after its cache is evicted."
                    if operation == "rotate"
                    else "Confirm the canonical row is a ciphertext-free revoked tombstone and the gateway cache name is absent."
                ),
            ),
        ]
        change = (
            f"Add or rotate {name} for {server}"
            if operation == "rotate"
            else f"Revoke {name} from {server}"
        )
        rollback = (
            "Enter a known-good replacement value through a new secure Library submission; "
            "previous plaintext values cannot be recovered from receipts."
        )
    else:
        steps = [("handoff", "Open guided Calliope session", "Pin this action and its structured choices into a new notebook.")]
        change = str(action.get("summary") or action.get("title") or "Open guided action")
        rollback = "No system change is made until the guided action produces a typed submission."
    return {
        "title": str(action.get("title") or "Calliope action"),
        "summary": change,
        "risk": str(action.get("risk") or "reversible"),
        "trusted_organization_mode": True,
        "steps": [
            {"id": step_id, "label": label, "detail": detail, "status": "pending"}
            for step_id, label, detail in steps
        ],
        "rollback": rollback,
    }


def _render_action_prompt(action: dict[str, Any], values: dict[str, Any]) -> str:
    prompt = str(action.get("prompt_template") or action.get("summary") or action.get("title") or "")
    field_map = {
        str(field.get("key") or ""): field
        for field in action.get("fields") or []
        if isinstance(field, dict)
    }
    for key, field in field_map.items():
        value = values.get(key, field.get("default"))
        if field.get("type") == "select":
            label = next(
                (
                    option.get("label") for option in field.get("options") or []
                    if isinstance(option, dict) and str(option.get("value")) == str(value)
                ),
                value,
            )
            value = label
        elif isinstance(value, bool):
            value = "yes" if value else "no"
        prompt = prompt.replace("{{" + key + "}}", str(value or "not specified"))
    return prompt.strip()[:12_000]


def _action_run_json(row: Any) -> dict[str, Any]:
    value = _row_json(row)
    for key in (
        "action_snapshot", "input_values", "input_redacted", "plan", "result", "verification"
    ):
        value[key] = _json_object(value.get(key))
    value["steps"] = _json_array(value.get("steps"))
    return value


def _action_error_text(value: Any, secret_values: Any = ()) -> str:
    """Bound receipt errors and remove credential-shaped or exact transient values."""
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]+", " ", str(value or ""))
    for secret in sorted(
        {str(item) for item in (secret_values or []) if str(item)},
        key=len,
        reverse=True,
    ):
        text = text.replace(secret, "[redacted]")
    text = re.sub(
        r"(?i)\b(bearer)\s+[a-z0-9._~+/=-]{8,}",
        r"\1 [redacted]",
        text,
    )
    text = re.sub(
        r"(?i)\b(api[-_ ]?key|password|passwd|secret|access[-_ ]?token|auth[-_ ]?token)"
        r"\s*[:=]\s*[^\s,;]+",
        r"\1=[redacted]",
        text,
    )
    text = re.sub(
        r"[A-Za-z][A-Za-z0-9+._-]*://[^\s'\"]+",
        lambda match: _library_safe_endpoint(match.group(0)) or "[redacted endpoint]",
        text,
    )
    text = re.sub(r"\bsk-[a-zA-Z0-9_-]{12,}\b", "[redacted]", text)
    return re.sub(r"\s+", " ", text).strip()[:1200]


def plan_action(
    conn_factory: Callable[..., Any],
    owner: str,
    action_id: str,
    inputs: Any = None,
    session_id: str | None = None,
) -> dict[str, Any]:
    action = _action_by_id(conn_factory, owner, action_id)
    if not action:
        raise LookupError("Action not found")
    _require_action_access(conn_factory, owner, action)
    if action.get("executor") == "conversation":
        raise ValueError("Guided actions open with Calliope instead of creating an apply plan")
    normalized_session = _uuid(session_id)
    if normalized_session and not _session_for_participant(conn_factory, normalized_session, owner):
        raise LookupError("Calliope session not found")
    values, redacted, _ = _normalize_action_inputs(action, inputs)
    _validate_administration_action_inputs(action, values)
    plan = _action_plan_document(action, values)
    run_id = str(uuid.uuid4())
    with conn_factory() as conn:
        row = conn.execute(
            "INSERT INTO rvbbit.calliope_action_runs "
            "(id,owner_email,session_id,action_id,action_version,action_snapshot,status,"
            "input_values,input_redacted,plan,steps) "
            "VALUES (%s::uuid,%s,%s::uuid,%s,%s,%s::jsonb,'planned',%s::jsonb,%s::jsonb,%s::jsonb,%s::jsonb) "
            "RETURNING *",
            (
                run_id, owner, normalized_session, action["id"], int(action.get("version") or 1),
                json.dumps(action, default=str), json.dumps(values, default=str),
                json.dumps(redacted, default=str), json.dumps(plan, default=str),
                json.dumps(plan["steps"], default=str),
            ),
        ).fetchone()
    return _action_run_json(row)


def _action_run_for_owner(
    conn_factory: Callable[..., Any], owner: str, run_id: Any
) -> dict[str, Any] | None:
    normalized = _uuid(run_id)
    if not normalized:
        return None
    with conn_factory() as conn:
        row = conn.execute(
            "SELECT * FROM rvbbit.calliope_action_runs "
            "WHERE id=%s::uuid AND lower(owner_email)=lower(%s)",
            (normalized, owner),
        ).fetchone()
        if row:
            row = local_sql_review.refresh(conn, dict(row))
    return _action_run_json(row) if row else None


def _sql_result_snapshot(value):
    """Bound SQL previews without destroying columns, NULLs, or nested batch rows."""
    value = value if isinstance(value, dict) else {}
    if not value:
        return {}
    result = _bounded_evidence_json({k: v for k, v in value.items() if k not in {'rows', 'columns', 'statements'}})
    if isinstance(value.get('statements'), list):
        result['statements'] = [_sql_result_snapshot(item) for item in value['statements'][:50]]
        return result
    columns = value.get('columns') or []
    names = [str(c.get('name') if isinstance(c, dict) else c) for c in columns]
    result['columns'] = names
    rows = value.get('rows') or []
    result['rows'] = []
    for row in rows[:200]:
        cells = [row.get(name) for name in names] if isinstance(row, dict) else row
        if not isinstance(cells, (list, tuple)):
            continue
        shown = []
        for cell in cells:
            encoded = json.dumps(cell, default=str, ensure_ascii=False)
            if len(encoded) > 2400:
                shown.append(encoded[:2400] + '…')
                result['cells_truncated'] = True
            else:
                shown.append(json.loads(encoded, parse_constant=lambda _: None))
        result['rows'].append(dict(zip(names, shown)) if isinstance(row, dict) else shown)
    result['row_count'] = len(result['rows'])
    recorded_count = value.get('row_count')
    result['truncated'] = bool(value.get('truncated') or len(rows) > 200
                               or isinstance(recorded_count, int) and recorded_count > len(rows))
    return result


def _sql_receipt_payload(payload):
    """Keep the normal action envelope, but do not depth-limit SQL result sets."""
    bounded = _bounded_evidence_json(payload)
    run = payload.get('run') or {}
    if (run.get('action_snapshot') or {}).get('executor') in {'local_sql', 'workspace_sql'}:
        bounded['run']['input_redacted'] = dict(run.get('input_redacted') or {})
        bounded['run']['result'] = _sql_result_snapshot(run.get('result'))
    return bounded


def _refresh_local_sql_surfaces(conn_factory, session_id, owner, surfaces):
    """Hydrate frozen Stage copies from the canonical receipts in one batch."""
    ids = list({
        _uuid((surface.get('payload') or {}).get('run', {}).get('id'))
        for surface in surfaces
        if surface.get('kind') == 'action'
        and isinstance((surface.get('payload') or {}).get('run'), dict)
        and ((surface['payload']['run'].get('action_snapshot') or {}).get('executor') in {'local_sql', 'workspace_sql'})
    } - {None})
    if not ids:
        return surfaces
    with conn_factory() as conn:
        rows = conn.execute(
            "SELECT * FROM rvbbit.calliope_action_runs WHERE id=ANY(%s::uuid[]) "
            "AND session_id=%s::uuid AND lower(owner_email)=lower(%s) "
            "AND action_snapshot->>'executor' IN ('local_sql','workspace_sql')",
            (ids, session_id, owner),
        ).fetchall()
        cache = {}
        runs = {str(row['id']): _action_run_json(local_sql_review.refresh(conn, dict(row), cache)) for row in rows}
    result = []
    for surface in surfaces:
        payload = surface.get('payload') or {}
        frozen = payload.get('run') or {}
        run = runs.get(str(frozen.get('id'))) if isinstance(frozen, dict) else None
        if run:
            run = {**run, 'result': _sql_result_snapshot(run.get('result'))}
            review = (run.get('verification') or {}).get('local_sql_review') or {}
            payload = {**payload, 'run': run, 'action': run['action_snapshot'],
                       'approval_required': bool(run.get('plan', {}).get('approval_required')) and run['status'] == 'planned' and not review,
                       'message': review.get('message') or ''}
            surface = {**surface, 'payload': payload}
        result.append(surface)
    return result


def _set_action_step(
    conn_factory: Callable[..., Any],
    run_id: str,
    step_id: str,
    status: str,
    detail: Any = None,
) -> None:
    with conn_factory() as conn:
        with conn.transaction():
            row = conn.execute(
                "SELECT steps FROM rvbbit.calliope_action_runs WHERE id=%s::uuid FOR UPDATE",
                (run_id,),
            ).fetchone()
            steps = _json_array((row or {}).get("steps"))
            now = datetime.now(timezone.utc).isoformat()
            for step in steps:
                if not isinstance(step, dict) or step.get("id") != step_id:
                    continue
                step["status"] = status
                if status == "running":
                    step["started_at"] = now
                if status in {"complete", "failed", "skipped"}:
                    step["completed_at"] = now
                if detail not in (None, "", {}, []):
                    step["result"] = _bounded_evidence_json(detail)
                break
            conn.execute(
                "UPDATE rvbbit.calliope_action_runs SET steps=%s::jsonb WHERE id=%s::uuid",
                (json.dumps(steps, default=str), run_id),
            )


def _mark_action_running(
    conn_factory: Callable[..., Any],
    owner: str,
    run_id: str,
    *,
    mark_approved: bool = True,
) -> None:
    with conn_factory() as conn:
        row = conn.execute(
            "UPDATE rvbbit.calliope_action_runs SET status='running',"
            "approved_at=CASE WHEN %s THEN now() ELSE approved_at END,"
            "started_at=now(),error=NULL WHERE id=%s::uuid AND lower(owner_email)=lower(%s) "
            "AND status='planned' AND coalesce(verification->'local_sql_review'->>'state','') <> 'retired' RETURNING id",
            (bool(mark_approved), run_id, owner),
        ).fetchone()
    if not row:
        raise ValueError("This action is no longer ready to run")


def _finish_action_run(
    conn_factory: Callable[..., Any],
    run_id: str,
    status: str,
    *,
    result: Any = None,
    verification: Any = None,
    error: str | None = None,
) -> None:
    if status not in {"complete", "failed"}:
        raise ValueError("Invalid terminal action status")
    with conn_factory() as conn:
        row = conn.execute(
            "UPDATE rvbbit.calliope_action_runs SET status=%s,result=%s::jsonb,"
            "verification=%s::jsonb,error=%s,completed_at=now() WHERE id=%s::uuid "
            "RETURNING session_id",
            (
                status, json.dumps(_json_object(result), default=str),
                json.dumps(_json_object(verification), default=str), error, run_id,
            ),
        ).fetchone()
    # The thread's brief (and its Floor card) still describes the approval as
    # pending until it is rewritten with the outcome.
    if row and row.get("session_id"):
        _enqueue_session_synopsis(conn_factory, str(row["session_id"]))


def _fail_active_action_step(
    conn_factory: Callable[..., Any], run_id: str, message: str
) -> None:
    run = None
    with conn_factory() as conn:
        row = conn.execute(
            "SELECT steps FROM rvbbit.calliope_action_runs WHERE id=%s::uuid", (run_id,)
        ).fetchone()
        run = _json_array((row or {}).get("steps"))
    active = next(
        (step for step in run if isinstance(step, dict) and step.get("status") == "running"),
        None,
    )
    if active:
        _set_action_step(conn_factory, run_id, str(active.get("id")), "failed", {"error": message})


def _execute_capability_install(
    conn_factory: Callable[..., Any], run: dict[str, Any]
) -> tuple[dict[str, Any], dict[str, Any]]:
    run_id = run["id"]
    action = run["action_snapshot"]
    values = run["input_values"]
    catalog_id = str((action.get("config") or {}).get("catalog_id") or "")
    _set_action_step(conn_factory, run_id, "inspect", "running")
    with conn_factory() as conn:
        catalog = conn.execute(
            "SELECT id,name,title,kind,active,operators FROM rvbbit.capability_catalog "
            "WHERE id=%s AND active",
            (catalog_id,),
        ).fetchone()
    if not catalog:
        raise LookupError(f"Active capability {catalog_id} was not found")
    _set_action_step(conn_factory, run_id, "inspect", "complete", {
        "catalog_id": catalog_id,
        "kind": catalog.get("kind"),
        "operators": len(catalog.get("operators") or []),
    })
    _set_action_step(conn_factory, run_id, "queue", "running")
    with conn_factory() as conn:
        queued = conn.execute(
            "SELECT rvbbit.deploy_catalog_capability(%s,'{}'::jsonb,NULL,%s) AS job_id",
            (catalog_id, values.get("install_mode") or "build"),
        ).fetchone()
    job_id = str((queued or {}).get("job_id") or "")
    if not _uuid(job_id):
        raise RuntimeError("Warren did not return a capability job id")
    _set_action_step(conn_factory, run_id, "queue", "complete", {"job_id": job_id})
    _set_action_step(conn_factory, run_id, "verify", "running")
    with conn_factory() as conn:
        job = conn.execute(
            "SELECT job_id,name,status,backend_name,runtime_name,operator_name,created_at,updated_at "
            "FROM rvbbit.warren_jobs WHERE job_id=%s::uuid",
            (job_id,),
        ).fetchone()
    if not job:
        raise RuntimeError("The queued Warren job could not be read back")
    verification = _row_json(job)
    _set_action_step(conn_factory, run_id, "verify", "complete", verification)
    return {"catalog_id": catalog_id, "job_id": job_id, "queued": True}, verification


def _execute_brain_query_source(
    conn_factory: Callable[..., Any], run: dict[str, Any]
) -> tuple[dict[str, Any], dict[str, Any]]:
    run_id = run["id"]
    values = run["input_values"]
    action = run.get("action_snapshot") or {}
    config = action.get("config") or {}
    provider = str(values.get("provider") or config.get("provider") or "")
    label = str(values.get("label") or config.get("label") or "")
    reuse_provider = bool(config.get("reuse_provider"))
    source_config = dict(config.get("source_config") or {})
    _set_action_step(conn_factory, run_id, "inspect", "running")
    with conn_factory() as conn:
        existing = conn.execute(
            "SELECT provider,label,doc_type FROM rvbbit.brain_doc_providers WHERE provider=%s",
            (provider,),
        ).fetchone()
    if reuse_provider and not existing:
        raise LookupError(f"Packaged Company Brain provider {provider} is unavailable")
    _set_action_step(conn_factory, run_id, "inspect", "complete", {
        "provider": provider,
        "existing": bool(existing),
        "doc_type": (existing or {}).get("doc_type"),
    })
    _set_action_step(conn_factory, run_id, "define", "running")
    if reuse_provider:
        defined_provider = str((existing or {}).get("provider") or provider)
    else:
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT rvbbit.brain_define_provider(%s,%s,%s,%s,NULL,%s,'[]'::jsonb,%s,'{}'::jsonb) AS provider",
                (
                    provider, label, values.get("list_sql"), values.get("item_sql") or None,
                    f"Created through Calliope Action Library for {label}",
                    values.get("doc_type") or "document",
                ),
            ).fetchone()
        defined_provider = str((row or {}).get("provider") or "")
    _set_action_step(conn_factory, run_id, "define", "complete", {
        "provider": defined_provider,
        "reused": reuse_provider,
    })
    _set_action_step(conn_factory, run_id, "source", "running")
    with conn_factory() as conn:
        existing_source = conn.execute(
            "SELECT source_id FROM rvbbit.brain_sources "
            "WHERE config->>'provider'=%s ORDER BY source_id LIMIT 1",
            (provider,),
        ).fetchone()
        if existing_source:
            source_id = int(existing_source["source_id"])
            conn.execute(
                "UPDATE rvbbit.brain_sources SET enabled=true,"
                "config=coalesce(config,'{}'::jsonb)||%s::jsonb||jsonb_build_object('provider',%s::text) "
                "WHERE source_id=%s",
                (json.dumps(source_config), provider, source_id),
            )
        else:
            created = conn.execute(
                "SELECT rvbbit.brain_add_query_source(%s,%s,%s::jsonb,true) AS source_id",
                (label, provider, json.dumps(source_config)),
            ).fetchone()
            source_id = int((created or {}).get("source_id") or 0)
    if source_id < 1:
        raise RuntimeError("Company Brain did not return a source id")
    _set_action_step(conn_factory, run_id, "source", "complete", {
        "source_id": source_id,
        "reused": bool(existing_source),
    })
    sync_result: dict[str, Any] = {}
    if values.get("sync_now", True):
        _set_action_step(conn_factory, run_id, "sync", "running")
        with conn_factory() as conn:
            synced = conn.execute(
                "SELECT rvbbit.brain_sync_dispatch(%s,'manual') AS result",
                (source_id,),
            ).fetchone()
        sync_result = _json_object((synced or {}).get("result"))
        _set_action_step(conn_factory, run_id, "sync", "complete", sync_result)
    else:
        _set_action_step(conn_factory, run_id, "sync", "skipped", {"reason": "Not requested"})
    _set_action_step(conn_factory, run_id, "verify", "running")
    with conn_factory() as conn:
        verified = conn.execute(
            "SELECT s.source_id,s.label,s.kind,s.enabled,s.last_synced_at,"
            "s.config->>'provider' AS provider,"
            "(SELECT count(*)::int FROM rvbbit.brain_documents d "
            " WHERE d.source_id=s.source_id AND d.deleted_at IS NULL) AS documents "
            "FROM rvbbit.brain_sources s WHERE s.source_id=%s",
            (source_id,),
        ).fetchone()
    if not verified:
        raise RuntimeError("The Company Brain source could not be read back")
    verification = _row_json(verified)
    _set_action_step(conn_factory, run_id, "verify", "complete", verification)
    return {
        "provider": provider,
        "source_id": source_id,
        "sync": sync_result,
    }, verification


def _mirror_control_snapshot(
    conn: Any, job_name: str, *, lock: bool = False
) -> dict[str, Any] | None:
    job = conn.execute(
        "SELECT job_name,connection_name,source_schema,destination_schema,enabled,"
        "schedule_seconds,next_run_at,last_run_at,updated_at,updated_by,"
        "(SELECT count(*)::int FROM rvbbit.mirror_tables t "
        " WHERE t.job_name=j.job_name AND t.enabled) AS table_count "
        "FROM rvbbit.mirror_jobs j WHERE j.job_name=%s" + (" FOR UPDATE OF j" if lock else ""),
        (job_name,),
    ).fetchone()
    if not job:
        return None
    latest = conn.execute(
        "SELECT run_id,trigger,status,attempt,requested_at,requested_by,started_at,"
        "finished_at,tables_succeeded,tables_failed,rows_loaded,error_code,error_message "
        "FROM rvbbit.mirror_runs WHERE job_name=%s ORDER BY requested_at DESC LIMIT 1",
        (job_name,),
    ).fetchone()
    snapshot = _row_json(job)
    latest_json = _row_json(latest)
    if latest_json.get("run_id"):
        latest_json["run_id"] = str(latest_json["run_id"])
    if latest_json.get("error_message"):
        latest_json["error_message"] = _action_error_text(latest_json["error_message"])
    snapshot["latest_run"] = latest_json
    return snapshot


def _assert_mirror_plan_current(
    action: dict[str, Any], current: dict[str, Any]
) -> None:
    config = action.get("config") or {}
    if str(current.get("updated_at") or "") != str(config.get("expected_updated_at") or ""):
        raise ValueError(
            "The mirror job changed after this plan was created; review a fresh plan."
        )
    expected_latest = config.get("latest_run") or {}
    latest = current.get("latest_run") or {}
    if (
        str(latest.get("run_id") or "") != str(expected_latest.get("run_id") or "")
        or (
            expected_latest.get("run_id")
            and str(latest.get("status") or "") != str(expected_latest.get("status") or "")
        )
    ):
        raise ValueError(
            "The latest mirror run changed after this plan was created; review a fresh plan."
        )


def _execute_mirror_control(
    conn_factory: Callable[..., Any], run: dict[str, Any]
) -> tuple[dict[str, Any], dict[str, Any]]:
    run_id = str(run["id"])
    action = run.get("action_snapshot") or {}
    values = run.get("input_values") or {}
    owner = str(run.get("owner_email") or "calliope")
    config = action.get("config") or {}
    job_name = str(config.get("job_name") or "")
    operation = str(values.get("operation") or "")

    _set_action_step(conn_factory, run_id, "inspect", "running")
    with conn_factory() as conn:
        observed = _mirror_control_snapshot(conn, job_name)
    if not observed:
        raise LookupError(f"Mirror job {job_name} was not found")
    _assert_mirror_plan_current(action, observed)
    _set_action_step(conn_factory, run_id, "inspect", "complete", {
        "job_name": job_name,
        "enabled": bool(observed.get("enabled")),
        "schedule_seconds": observed.get("schedule_seconds"),
        "updated_at": observed.get("updated_at"),
        "latest_run": observed.get("latest_run") or {},
    })

    _set_action_step(conn_factory, run_id, "apply", "running")
    queued_run_id: str | None = None
    with conn_factory() as conn:
        with conn.transaction():
            locked = _mirror_control_snapshot(conn, job_name, lock=True)
            if not locked:
                raise LookupError(f"Mirror job {job_name} was not found")
            _assert_mirror_plan_current(action, locked)
            if operation == "pause":
                if not locked.get("enabled"):
                    raise ValueError("This mirror is already paused; review a fresh plan")
                conn.execute(
                    "UPDATE rvbbit.mirror_jobs SET enabled=false,next_run_at=NULL,"
                    "updated_at=clock_timestamp(),updated_by=%s WHERE job_name=%s",
                    (owner, job_name),
                )
            elif operation == "resume":
                if locked.get("enabled"):
                    raise ValueError("This mirror is already enabled; review a fresh plan")
                conn.execute(
                    "UPDATE rvbbit.mirror_jobs SET enabled=true,"
                    "next_run_at=CASE WHEN schedule_seconds IS NULL THEN NULL ELSE clock_timestamp() END,"
                    "updated_at=clock_timestamp(),updated_by=%s WHERE job_name=%s",
                    (owner, job_name),
                )
            elif operation == "set_schedule":
                raw_schedule = str(values.get("schedule_seconds") or "")
                allowed = {value for value, _label in _MIRROR_SCHEDULE_OPTIONS}
                if raw_schedule not in allowed:
                    raise ValueError("Cadence has an invalid choice")
                schedule_seconds = None if raw_schedule == "manual" else int(raw_schedule)
                conn.execute(
                    "UPDATE rvbbit.mirror_jobs SET schedule_seconds=%s,"
                    "next_run_at=CASE WHEN enabled AND %s IS NOT NULL THEN clock_timestamp() ELSE NULL END,"
                    "updated_at=clock_timestamp(),updated_by=%s WHERE job_name=%s",
                    (schedule_seconds, schedule_seconds, owner, job_name),
                )
            elif operation in {"run_now", "retry_last_failed"}:
                if not locked.get("enabled"):
                    raise ValueError("Resume this mirror before requesting a run")
                if operation == "retry_last_failed":
                    latest = locked.get("latest_run") or {}
                    if str(latest.get("status") or "") not in _MIRROR_RETRYABLE_STATUSES:
                        raise ValueError("The latest mirror run is no longer retryable")
                # A manual request is itself a new control-plane revision. This
                # serializes other Library plans while request_mirror_run keeps
                # its existing one-active-run behavior.
                conn.execute(
                    "UPDATE rvbbit.mirror_jobs SET updated_at=clock_timestamp(),updated_by=%s "
                    "WHERE job_name=%s",
                    (owner, job_name),
                )
                queued = conn.execute(
                    "SELECT rvbbit.request_mirror_run(%s,%s) AS run_id",
                    (job_name, "retry" if operation == "retry_last_failed" else "manual"),
                ).fetchone() or {}
                queued_run_id = str(queued.get("run_id") or "") or None
            else:
                raise ValueError("Unknown mirror operation")
    _set_action_step(conn_factory, run_id, "apply", "complete", {
        "job_name": job_name,
        "operation": operation,
        "queued_run_id": queued_run_id,
        "active_run_not_cancelled": operation == "pause",
    })

    _set_action_step(conn_factory, run_id, "verify", "running")
    with conn_factory() as conn:
        verified = _mirror_control_snapshot(conn, job_name)
    if not verified:
        raise RuntimeError("The mirror job could not be read back")
    latest = verified.get("latest_run") or {}
    if queued_run_id and str(latest.get("run_id") or "") != queued_run_id:
        raise RuntimeError("The requested mirror run is not the latest durable receipt")
    verification = {
        "job_name": job_name,
        "enabled": bool(verified.get("enabled")),
        "schedule_seconds": verified.get("schedule_seconds"),
        "next_run_at": verified.get("next_run_at"),
        "updated_at": verified.get("updated_at"),
        "updated_by": verified.get("updated_by"),
        "table_count": int(verified.get("table_count") or 0),
        "latest_run": latest,
    }
    _set_action_step(conn_factory, run_id, "verify", "complete", verification)
    return {
        "job_name": job_name,
        "operation": operation,
        "queued_run_id": queued_run_id,
    }, verification


def execute_action(
    conn_factory: Callable[..., Any],
    owner: str,
    run_id: str,
) -> dict[str, Any]:
    run = _action_run_for_owner(conn_factory, owner, run_id)
    if not run:
        raise LookupError("Action plan not found")
    action = run.get("action_snapshot") or {}
    _require_action_access(conn_factory, owner, action)
    executor = str(action.get("executor") or "")
    if executor in {"mcp_connect", "mcp_credentials", "mirror_connect", "mail_connect", "sms_connect", "sms_user"}:
        return {
            "run": run,
            "secure_input_required": True,
            "message": "Complete this change in the Calliope Library so credentials stay outside model context.",
        }
    _mark_action_running(conn_factory, owner, run["id"], mark_approved=executor != "mirror_create")
    try:
        if executor == "capability_install":
            result, verification = _execute_capability_install(conn_factory, run)
        elif executor == "brain_query_source":
            result, verification = _execute_brain_query_source(conn_factory, run)
        elif executor == "mirror_create":
            result, verification = mirror_actions.create_job(conn_factory, run)
        elif executor == "mirror_control":
            result, verification = _execute_mirror_control(conn_factory, run)
        else:
            raise ValueError(f"Unsupported typed action executor: {executor}")
        _finish_action_run(
            conn_factory, run["id"], "complete", result=result, verification=verification
        )
    except Exception as exc:
        message = _action_error_text(f"{type(exc).__name__}: {exc}")
        _fail_active_action_step(conn_factory, run["id"], message)
        _finish_action_run(conn_factory, run["id"], "failed", error=message)
        raise
    return {"run": _action_run_for_owner(conn_factory, owner, run["id"])}


def _mcp_gateway_headers() -> dict[str, str]:
    headers = {"content-type": "application/json"}
    token = str(
        os.environ.get("RVBBIT_GATEWAY_TOKEN")
        or os.environ.get("MCP_GATEWAY_TOKEN")
        or ""
    ).strip()
    if token:
        headers["authorization"] = f"Bearer {token}"
    return headers


def _mcp_gateway_url(conn_factory: Callable[..., Any]) -> str:
    explicit = str(os.environ.get("MCP_GATEWAY_URL") or "").strip().rstrip("/")
    if explicit:
        return explicit
    try:
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT rvbbit.mcp_gateway_endpoint() AS url"
            ).fetchone()
        configured = str((row or {}).get("url") or "").strip().rstrip("/")
        if re.match(r"^https?://", configured, re.I):
            return configured
    except Exception:
        pass
    return "http://mcp-gateway:9180"


async def _mcp_gateway_secret_names(
    conn_factory: Callable[..., Any], server: str
) -> tuple[set[str], bool]:
    url = _mcp_gateway_url(conn_factory)
    timeout = httpx.Timeout(8.0, connect=3.0)
    try:
        async with httpx.AsyncClient(timeout=timeout, trust_env=False) as client:
            response = await client.get(
                f"{url}/secrets/{quote(server, safe='')}",
                headers=_mcp_gateway_headers(),
            )
        if response.status_code == 404:
            return set(), False
        response.raise_for_status()
        payload = response.json()
        return {
            str(value) for value in (payload.get("set") or []) if str(value).strip()
        }, True
    except Exception:
        return set(), False


async def _mcp_gateway_health(
    conn_factory: Callable[..., Any]
) -> dict[str, Any]:
    url = _mcp_gateway_url(conn_factory)
    timeout = httpx.Timeout(8.0, connect=3.0)
    try:
        async with httpx.AsyncClient(timeout=timeout, trust_env=False) as client:
            response = await client.get(
                f"{url}/health", headers=_mcp_gateway_headers()
            )
        response.raise_for_status()
        payload = response.json()
    except Exception as exc:
        raise ValueError("The secure MCP gateway could not be reached") from exc
    if not isinstance(payload, dict) or payload.get("credential_store") != "canonical":
        raise ValueError(
            "Canonical MCP credentials are not active on the running gateway"
        )
    return {
        "status": str(payload.get("status") or ""),
        "credential_store": "canonical",
    }


async def _push_mcp_gateway_secret(
    conn_factory: Callable[..., Any],
    server: str,
    name: str,
    value: str,
    *,
    expected_version: int | None = None,
    expected_status: str | None = None,
    expect_absent: bool = False,
) -> None:
    url = _mcp_gateway_url(conn_factory)
    timeout = httpx.Timeout(15.0, connect=4.0)
    payload: dict[str, Any] = {"server": server, "name": name, "value": value}
    if expected_version is not None:
        payload["expected_version"] = int(expected_version)
    if expected_status:
        payload["expected_status"] = str(expected_status)
    if expect_absent:
        payload["expect_absent"] = True
    async with httpx.AsyncClient(timeout=timeout, trust_env=False) as client:
        response = await client.post(
            f"{url}/secrets",
            headers=_mcp_gateway_headers(),
            json=payload,
        )
    if response.status_code >= 400:
        if response.status_code == 409:
            raise ValueError(
                "The credential changed after this plan was created; review a fresh plan"
            )
        hint = (
            " The running gateway predates secure install-time secrets; rebuild or redeploy it."
            if response.status_code == 404 else ""
        )
        raise RuntimeError(
            f"MCP gateway rejected secure value {name} ({response.status_code}).{hint}"
        )


async def _mcp_gateway_oauth_start(
    conn_factory: Callable[..., Any],
    server: str,
    redirect_uri: str,
    *,
    scope: str | None = None,
    client_id: str | None = None,
    client_secret: str | None = None,
) -> dict[str, Any]:
    url = _mcp_gateway_url(conn_factory)
    payload: dict[str, Any] = {"server": server, "redirect_uri": redirect_uri}
    if scope:
        payload["scope"] = scope
    if client_id:
        payload["client_id"] = client_id
    if client_secret:
        payload["client_secret"] = client_secret
    # Discovery + dynamic registration happen inside this call.
    async with httpx.AsyncClient(
        timeout=httpx.Timeout(45.0, connect=4.0), trust_env=False
    ) as client:
        response = await client.post(
            f"{url}/oauth/start", headers=_mcp_gateway_headers(), json=payload
        )
    if response.status_code >= 400:
        detail = ""
        try:
            detail = str((response.json() or {}).get("detail") or "")
        except Exception:
            detail = response.text[:300]
        hint = (
            " The running gateway predates OAuth connections; rebuild or redeploy it."
            if response.status_code == 404 else ""
        )
        raise ValueError(
            f"OAuth sign-in could not be prepared: {detail or response.status_code}.{hint}"
        )
    return response.json()


async def _mcp_gateway_oauth_finish(
    conn_factory: Callable[..., Any], state: str, code: str
) -> dict[str, Any]:
    url = _mcp_gateway_url(conn_factory)
    async with httpx.AsyncClient(
        timeout=httpx.Timeout(45.0, connect=4.0), trust_env=False
    ) as client:
        response = await client.post(
            f"{url}/oauth/finish",
            headers=_mcp_gateway_headers(),
            json={"state": state, "code": code},
        )
    if response.status_code >= 400:
        try:
            detail = str((response.json() or {}).get("detail") or "")
        except Exception:
            detail = response.text[:300]
        raise ValueError(detail or f"token exchange failed ({response.status_code})")
    return response.json()


async def _mcp_gateway_oauth_status(
    conn_factory: Callable[..., Any], server: str
) -> dict[str, Any]:
    url = _mcp_gateway_url(conn_factory)
    async with httpx.AsyncClient(
        timeout=httpx.Timeout(8.0, connect=3.0), trust_env=False
    ) as client:
        response = await client.get(
            f"{url}/oauth/status/{quote(server, safe='')}",
            headers=_mcp_gateway_headers(),
        )
    response.raise_for_status()
    return response.json()


def _mcp_oauth_redirect_uri() -> str:
    public = str(os.environ.get("WAREHOUSE_PUBLIC_URL") or "").strip().rstrip("/")
    if not public:
        raise ValueError(
            "OAuth sign-in needs WAREHOUSE_PUBLIC_URL configured so the service "
            "can redirect the browser back to this appliance"
        )
    return f"{public}{_MCP_OAUTH_CALLBACK_PATH}"


async def _delete_mcp_gateway_secret(
    conn_factory: Callable[..., Any],
    server: str,
    name: str,
    *,
    expected_version: int | None = None,
    expected_status: str | None = None,
) -> None:
    url = _mcp_gateway_url(conn_factory)
    timeout = httpx.Timeout(15.0, connect=4.0)
    payload: dict[str, Any] = {"server": server, "name": name}
    if expected_version is not None:
        payload["expected_version"] = int(expected_version)
    if expected_status:
        payload["expected_status"] = str(expected_status)
    async with httpx.AsyncClient(timeout=timeout, trust_env=False) as client:
        response = await client.request(
            "DELETE",
            f"{url}/secrets",
            headers=_mcp_gateway_headers(),
            json=payload,
        )
    if response.status_code == 409:
        raise ValueError(
            "The credential changed after this plan was created; review a fresh plan"
        )
    if response.status_code >= 400:
        raise RuntimeError(
            f"MCP gateway rejected credential revocation for {name} ({response.status_code})."
        )


def _sql_string_literal(value: Any) -> str:
    return "'" + str(value or "").replace("'", "''") + "'"


def _sql_identifier(value: Any) -> str:
    return '"' + str(value or "").replace('"', '""') + '"'


async def _execute_custom_mcp_steps(
    conn_factory: Callable[..., Any],
    run_id: str,
    spec: dict[str, Any],
    secrets: dict[str, str],
    saved_names: set[str],
) -> tuple[dict[str, Any], dict[str, Any]]:
    server = str(spec["server"])
    declared_names = set(spec.get("declared_secret_names") or set())
    oauth_mode = str(spec.get("auth_mode") or "") == "oauth"
    # The OAuth client secret is sealed into the OAuth client record by
    # /oauth/start — never stored as an ordinary per-server secret.
    oauth_client_secret = secrets.pop(_MCP_OAUTH_CLIENT_SECRET_KEY, None)
    if oauth_mode:
        # Fail before any mutation when the appliance cannot receive the
        # redirect; the operator fixes configuration, not a half-registration.
        oauth_redirect_uri = _mcp_oauth_redirect_uri()
    _set_action_step(conn_factory, run_id, "inspect", "running")
    with conn_factory() as conn:
        existing = conn.execute(
            "SELECT name,transport,command,args,env,url,auth_header_env,timeout_ms,"
            "description FROM rvbbit.mcp_servers WHERE name=%s",
            (server,),
        ).fetchone()
        schema_state = conn.execute(
            "SELECT "
            "EXISTS(SELECT 1 FROM pg_namespace WHERE nspname=%s) AS schema_exists,"
            "(SELECT count(*)::int FROM pg_class c JOIN pg_namespace n "
            " ON n.oid=c.relnamespace WHERE n.nspname=%s) AS schema_relations,"
            "(SELECT count(*)::int FROM pg_proc p JOIN pg_namespace n "
            " ON n.oid=p.pronamespace WHERE n.nspname=%s "
            " AND (p.prokind<>'f' OR position('rvbbit.mcp_rows' in p.prosrc)=0)) "
            "AS foreign_functions",
            (server, server, server),
        ).fetchone() or {}
    schema_exists = bool(schema_state.get("schema_exists"))
    if (
        spec.get("create_sql_functions")
        and schema_exists
        and (
            not existing
            or int(schema_state.get("schema_relations") or 0) > 0
            or int(schema_state.get("foreign_functions") or 0) > 0
        )
    ):
        raise ValueError(
            f"SQL schema {server} already exists and is not an RVBBIT-generated MCP wrapper "
            "schema; choose another connection name"
        )
    endpoint = ""
    if spec.get("url"):
        parsed_url = urlsplit(str(spec["url"]))
        endpoint = f"{parsed_url.scheme}://{parsed_url.netloc}{parsed_url.path}"
    _set_action_step(conn_factory, run_id, "inspect", "complete", {
        "server": server,
        "transport": spec["transport"],
        "endpoint": endpoint or None,
        "executable": spec.get("command"),
        "declared_secret_names": sorted(declared_names),
        "replaces_existing": bool(existing),
        "existing_transport": (existing or {}).get("transport") if existing else None,
        "wrapper_schema_reused": bool(schema_exists and existing),
    })

    _set_action_step(conn_factory, run_id, "register", "running")
    environment_json = (
        json.dumps(spec.get("environment") or {})
        if spec["transport"] == "stdio"
        else None
    )
    with conn_factory() as conn:
        conn.execute(
            "SELECT rvbbit.register_mcp_server("
            "server_name => %s,server_transport => %s,server_command => %s,"
            "server_args => %s,server_env => %s::jsonb,server_url => %s,"
            "server_auth_env => %s,server_timeout_ms => %s,server_description => %s)",
            (
                server,
                spec["transport"],
                spec.get("command"),
                spec.get("args") if spec["transport"] == "stdio" else None,
                environment_json,
                spec.get("url"),
                spec.get("auth_token_name"),
                spec["timeout_ms"],
                spec.get("description"),
            ),
        )
    _set_action_step(conn_factory, run_id, "register", "complete", {
        "server": server,
        "transport": spec["transport"],
        "registration_contains_secret_values": False,
    })

    _set_action_step(conn_factory, run_id, "secrets", "running")
    for name, value in secrets.items():
        await _push_mcp_gateway_secret(conn_factory, server, name, value)
    _set_action_step(conn_factory, run_id, "secrets", "complete", {
        "stored": sorted(secrets),
        "reused": sorted(declared_names.intersection(saved_names).difference(secrets)),
        "credential_store": "canonical encrypted gateway",
        "values_in_chat_or_receipts": False,
    })

    if oauth_mode:
        # The run PARKS here: execute returns the sign-in URL immediately (so
        # the agent can hand the link out in chat and the Library can render
        # it), the OAuth callback resumes discovery server-side once the
        # browser leg lands, and the expiry watchdog fails the run cleanly if
        # the link is never used.
        pending = await _begin_mcp_oauth_authorization(
            conn_factory,
            run_id,
            server,
            oauth_redirect_uri,
            scope=spec.get("oauth_scope"),
            client_id=spec.get("oauth_client_id"),
            client_secret=oauth_client_secret,
        )
        return pending, {"pending_authorization": True}

    return _custom_mcp_discover_verify(conn_factory, run_id, spec)


async def _begin_mcp_oauth_authorization(
    conn_factory: Callable[..., Any],
    run_id: str,
    server: str,
    redirect_uri: str,
    *,
    scope: str | None,
    client_id: str | None,
    client_secret: str | None,
) -> dict[str, Any]:
    """Start the browser leg and park the run on its authorize step."""
    _set_action_step(conn_factory, run_id, "authorize", "running")
    started = await _mcp_gateway_oauth_start(
        conn_factory,
        server,
        redirect_uri,
        scope=scope,
        client_id=client_id,
        client_secret=client_secret,
    )
    authorization_url = str(started.get("authorization_url") or "")
    _set_action_step(conn_factory, run_id, "authorize", "running", {
        "authorization_url": authorization_url,
        "authorization_server": started.get("authorization_server"),
        "client_registration": (
            "dynamic" if started.get("dynamic_registration") else "pre-registered"
        ),
        "waiting": "Waiting for the browser sign-in; the connection finishes itself afterwards.",
    })
    _schedule_mcp_oauth_expiry(conn_factory, run_id, server)
    return {
        "pending_authorization": True,
        "server": server,
        "authorization_url": authorization_url,
        "authorization_server": started.get("authorization_server"),
        "sign_in_expires_in_seconds": _MCP_OAUTH_SIGNIN_TIMEOUT_S,
        "message": (
            "Give the user this sign-in link. After they authorize in the "
            "browser, discovery, SQL generation, and verification finish "
            "automatically and the receipt completes — nothing else to do."
        ),
    }


def _schedule_mcp_oauth_expiry(
    conn_factory: Callable[..., Any], run_id: str, server: str
) -> None:
    """Fail a parked run whose sign-in link was never used. Best-effort and
    in-process: a service restart drops the watchdog, in which case the run
    stays visibly parked on its authorize step instead of failing crisply."""

    async def _expire() -> None:
        await asyncio.sleep(_MCP_OAUTH_SIGNIN_TIMEOUT_S)
        try:
            with conn_factory() as conn:
                row = conn.execute(
                    "SELECT status,steps FROM rvbbit.calliope_action_runs "
                    "WHERE id=%s::uuid",
                    (run_id,),
                ).fetchone()
            if not row or str(row.get("status") or "") != "running":
                return
            authorize = next(
                (
                    step for step in _json_array(row.get("steps"))
                    if isinstance(step, dict) and step.get("id") == "authorize"
                ),
                None,
            )
            if not authorize or authorize.get("status") != "running":
                return
            message = (
                "The sign-in link expired before it was used "
                f"({_MCP_OAUTH_SIGNIN_TIMEOUT_S // 60} minutes); run Connect "
                "again for a fresh link"
            )
            _fail_active_action_step(conn_factory, run_id, message)
            _finish_action_run(conn_factory, run_id, "failed", error=message)
        except Exception as exc:
            print(
                f"WARNING: MCP OAuth expiry watchdog failed for run {run_id} "
                f"({server}): {type(exc).__name__}: {exc}",
                file=os.sys.stderr,
            )

    try:
        asyncio.get_running_loop().create_task(_expire())
    except RuntimeError:
        # No running loop (sync test context): the gateway's own flow TTL
        # still expires the state; the run just isn't auto-failed.
        pass


def _find_awaiting_oauth_run(
    conn_factory: Callable[..., Any], server: str
) -> dict[str, Any] | None:
    """The newest running mcp_connect run parked on its authorize step for
    this server — the run the OAuth callback should resume."""
    with conn_factory() as conn:
        rows = conn.execute(
            "SELECT * FROM rvbbit.calliope_action_runs "
            "WHERE status='running' AND action_snapshot->>'executor'='mcp_connect' "
            "AND input_values->>'server_name'=%s "
            "AND created_at > now() - interval '1 hour' "
            "ORDER BY created_at DESC LIMIT 5",
            (server,),
        ).fetchall()
    for row in rows:
        run = _action_run_json(row)
        authorize = next(
            (
                step for step in (run.get("steps") or [])
                if isinstance(step, dict) and step.get("id") == "authorize"
            ),
            None,
        )
        if authorize and authorize.get("status") == "running":
            return run
    return None


async def _resume_awaiting_mcp_oauth_run(
    conn_factory: Callable[..., Any], server: str
) -> None:
    """Continue a parked connect run after the OAuth callback landed:
    authorize completes, then discovery, SQL surface, and verification run
    exactly as in the blocking path, finishing the durable receipt."""
    run = _find_awaiting_oauth_run(conn_factory, server)
    if not run:
        return
    run_id = str(run["id"])
    try:
        status = await _mcp_gateway_oauth_status(conn_factory, server)
        if not status.get("connected"):
            return
        action = run.get("action_snapshot") or {}
        values, _redacted, _secrets = _normalize_action_inputs(
            action, run.get("input_values") or {}
        )
        spec, _secure = _custom_mcp_spec(values, {})
        _set_action_step(conn_factory, run_id, "authorize", "complete", {
            "authorization_server": status.get("authorization_server"),
            "scope": status.get("scope"),
            "refresh_token_stored": bool(status.get("has_refresh_token")),
            "token_store": "canonical encrypted gateway",
        })
        result, verification = _custom_mcp_discover_verify(conn_factory, run_id, spec)
        _finish_action_run(
            conn_factory, run_id, "complete",
            result=result, verification=verification,
        )
    except Exception as exc:
        message = _action_error_text(f"{type(exc).__name__}: {exc}")
        _fail_active_action_step(conn_factory, run_id, message)
        _finish_action_run(conn_factory, run_id, "failed", error=message)


def _custom_mcp_discover_verify(
    conn_factory: Callable[..., Any],
    run_id: str,
    spec: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    server = str(spec["server"])
    _set_action_step(conn_factory, run_id, "discover", "running")
    with conn_factory() as conn:
        refreshed = conn.execute(
            "SELECT rvbbit.refresh_mcp_server(%s) AS tools", (server,)
        ).fetchone() or {}
        tool_rows = conn.execute(
            "SELECT name,description FROM rvbbit.mcp_tools "
            "WHERE server=%s ORDER BY name LIMIT 200",
            (server,),
        ).fetchall()
        conflicts = conn.execute(
            "SELECT coalesce(array_agg(o.name ORDER BY o.name),ARRAY[]::text[]) AS names "
            "FROM rvbbit.operators o JOIN rvbbit.mcp_tools t ON t.server=%s "
            "AND o.name=%s || '_' || CASE "
            " WHEN left(t.name,length(%s)+1)=%s || '_' THEN substr(t.name,length(%s)+2) "
            " ELSE t.name END "
            "WHERE position('[MCP ' || %s || '.' in coalesce(o.description,''))=0",
            (server, server, server, server, server, server),
        ).fetchone() or {}
    operator_conflicts = [str(value) for value in (conflicts.get("names") or [])]
    if spec.get("create_operators") and operator_conflicts:
        raise ValueError(
            "Generated RVBBIT operator names would replace unrelated operators: "
            + ", ".join(operator_conflicts[:12])
        )
    tools = [str(row.get("name") or "") for row in tool_rows if row.get("name")]
    sql_functions_created = 0
    if spec.get("create_sql_functions"):
        with conn_factory() as conn:
            wrappers = conn.execute(
                "SELECT rvbbit.generate_mcp_wrappers(%s) AS sql_functions", (server,)
            ).fetchone() or {}
        sql_functions_created = int(wrappers.get("sql_functions") or 0)
    operators_created = 0
    if spec.get("create_operators"):
        with conn_factory() as conn:
            operators = conn.execute(
                "SELECT rvbbit.generate_mcp_operators(%s) AS operators", (server,)
            ).fetchone() or {}
        operators_created = int(operators.get("operators") or 0)
    _set_action_step(conn_factory, run_id, "discover", "complete", {
        "tools_discovered": int(refreshed.get("tools") or len(tools)),
        "sql_functions_created": sql_functions_created,
        "operators_created": operators_created,
        "tools": tools[:24],
    })

    _set_action_step(conn_factory, run_id, "verify", "running")
    with conn_factory() as conn:
        probe_row = conn.execute(
            "SELECT rvbbit.mcp_probe(%s) AS probe", (server,)
        ).fetchone() or {}
        counts = conn.execute(
            "SELECT "
            "(SELECT count(*)::int FROM rvbbit.mcp_tools WHERE server=%s) AS tools,"
            "(SELECT count(*)::int FROM rvbbit.mcp_resources WHERE server=%s) AS resources,"
            "(SELECT count(*)::int FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace "
            " WHERE n.nspname=%s) AS sql_functions,"
            "(SELECT count(*)::int FROM rvbbit.operators o "
            " WHERE position('[MCP ' || %s || '.' in coalesce(o.description,'')) > 0) AS operators",
            (server, server, server, server),
        ).fetchone() or {}
        function_rows = conn.execute(
            "SELECT p.proname AS name,pg_get_function_identity_arguments(p.oid) AS arguments "
            "FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace "
            "WHERE n.nspname=%s ORDER BY p.proname LIMIT 24",
            (server,),
        ).fetchall()
    probe = _json_object(probe_row.get("probe"))
    verification = {
        "server": server,
        "transport": spec["transport"],
        "reachable": bool(probe.get("reachable")),
        "latency_ms": probe.get("latency_ms"),
        "tools": int(counts.get("tools") or probe.get("n_tools") or 0),
        "resources": int(counts.get("resources") or 0),
        "sql_functions": int(counts.get("sql_functions") or 0),
        "operators": int(counts.get("operators") or 0),
    }
    if not verification["reachable"]:
        raise RuntimeError(
            str(probe.get("error") or "The custom MCP server did not pass its active probe")
        )
    functions = [
        {
            "name": str(row.get("name") or ""),
            "arguments": str(row.get("arguments") or ""),
        }
        for row in function_rows
        if row.get("name")
    ]
    _set_action_step(conn_factory, run_id, "verify", "complete", verification)
    direct_sql = None
    typed_sql = None
    if tools:
        direct_sql = (
            "SELECT rvbbit.mcp_call("
            f"{_sql_string_literal(server)}, {_sql_string_literal(tools[0])}, "
            "'{}'::jsonb);"
        )
    if functions:
        typed_sql = (
            f"SELECT * FROM {_sql_identifier(server)}."
            f"{_sql_identifier(functions[0]['name'])}(/* named arguments */);"
        )
    result = {
        "server": server,
        "transport": spec["transport"],
        "tools": tools,
        "functions": functions,
        "sql_functions_created": sql_functions_created,
        "operators_created": operators_created,
        "base_sql_function": "rvbbit.mcp_call(server, tool, args jsonb)",
        "direct_sql_example": direct_sql,
        "typed_sql_example": typed_sql,
    }
    return result, verification


def _mcp_credential_metadata(
    conn_factory: Callable[..., Any], server: str, name: str
) -> dict[str, Any] | None:
    with conn_factory() as conn:
        row = conn.execute(
            "SELECT credential_ref,namespace AS server_name,name AS secret_name,"
            "version,status,updated_at,updated_by,rotated_at "
            "FROM rvbbit.credentials WHERE kind='mcp' AND namespace=%s AND name=%s",
            (server, name),
        ).fetchone()
    return _row_json(row) if row else None


def _assert_mcp_credential_plan_current(
    action: dict[str, Any], name: str, current: dict[str, Any] | None
) -> dict[str, Any] | None:
    expected = ((action.get("config") or {}).get("credential_revisions") or {}).get(name)
    if not expected:
        if current:
            raise ValueError(
                "The credential was added after this plan was created; review a fresh plan."
            )
        return None
    if not current or any(
        str(current.get(key) or "") != str(expected.get(key) or "")
        for key in ("version", "status", "updated_at")
    ):
        raise ValueError(
            "The credential changed after this plan was created; review a fresh plan."
        )
    return expected


async def _execute_mcp_credentials(
    conn_factory: Callable[..., Any],
    run: dict[str, Any],
    values: dict[str, Any],
    secrets: dict[str, str],
) -> tuple[dict[str, Any], dict[str, Any]]:
    run_id = str(run["id"])
    action = run.get("action_snapshot") or {}
    config = action.get("config") or {}
    server = str(config.get("server_name") or "")
    name = str(values.get("credential_name") or "")
    operation = str(values.get("operation") or "")

    _set_action_step(conn_factory, run_id, "inspect", "running")
    gateway = await _mcp_gateway_health(conn_factory)
    current = _mcp_credential_metadata(conn_factory, server, name)
    expected = _assert_mcp_credential_plan_current(action, name, current)
    _set_action_step(conn_factory, run_id, "inspect", "complete", {
        "server": server,
        "credential_name": name,
        "credential_store": gateway.get("credential_store"),
        "current": ({
            "version": current.get("version"),
            "status": current.get("status"),
            "updated_at": current.get("updated_at"),
        } if current else None),
    })

    _set_action_step(conn_factory, run_id, "apply", "running")
    if operation == "rotate":
        value = str(secrets.get("CREDENTIAL_VALUE") or "")
        if not value:
            raise ValueError("New credential value is required in the secure Library form")
        await _push_mcp_gateway_secret(
            conn_factory,
            server,
            name,
            value,
            expected_version=(int(expected["version"]) if expected else None),
            expected_status=(str(expected.get("status")) if expected else None),
            expect_absent=expected is None,
        )
    elif operation == "revoke":
        if not expected or expected.get("status") != "active":
            raise ValueError("The reviewed credential is no longer active")
        await _delete_mcp_gateway_secret(
            conn_factory,
            server,
            name,
            expected_version=int(expected["version"]),
            expected_status=str(expected.get("status") or "active"),
        )
    else:
        raise ValueError("Unknown credential operation")
    _set_action_step(conn_factory, run_id, "apply", "complete", {
        "server": server,
        "credential_name": name,
        "operation": operation,
        "credential_value_returned": False,
        "gateway_cache_evicted": True,
    })

    _set_action_step(conn_factory, run_id, "verify", "running")
    verified = _mcp_credential_metadata(conn_factory, server, name)
    saved_names, names_known = await _mcp_gateway_secret_names(conn_factory, server)
    if not names_known:
        raise RuntimeError("The gateway credential cache could not be verified")
    probe: dict[str, Any] = {}
    if operation == "rotate":
        expected_version = int(expected.get("version") or 0) + 1 if expected else 1
        if (
            not verified
            or verified.get("status") != "active"
            or int(verified.get("version") or 0) != expected_version
            or name not in saved_names
        ):
            raise RuntimeError("The rotated canonical credential could not be verified")
        with conn_factory() as conn:
            probe_row = conn.execute(
                "SELECT rvbbit.mcp_probe(%s) AS probe", (server,)
            ).fetchone() or {}
        probe = _json_object(probe_row.get("probe"))
        if not probe.get("reachable"):
            raise RuntimeError(
                _action_error_text(
                    probe.get("error")
                    or "The MCP server did not pass its active probe after credential rotation"
                )
            )
    else:
        expected_version = int(expected.get("version") or 0) + 1
        if (
            not verified
            or verified.get("status") != "revoked"
            or int(verified.get("version") or 0) != expected_version
            or name in saved_names
        ):
            raise RuntimeError("The canonical credential revocation could not be verified")
    verification = {
        "server": server,
        "credential_name": name,
        "operation": operation,
        "credential_store": "canonical",
        "status": verified.get("status"),
        "version": verified.get("version"),
        "updated_at": verified.get("updated_at"),
        "saved_names": sorted(saved_names),
        "reachable": bool(probe.get("reachable")) if operation == "rotate" else None,
        "latency_ms": probe.get("latency_ms") if operation == "rotate" else None,
    }
    _set_action_step(conn_factory, run_id, "verify", "complete", verification)
    return {
        "server": server,
        "credential_name": name,
        "operation": operation,
        "credential_ref": verified.get("credential_ref"),
    }, verification


async def execute_action_with_secure_inputs(
    conn_factory: Callable[..., Any],
    owner: str,
    run_id: str,
    raw_inputs: Any,
) -> dict[str, Any]:
    run = _action_run_for_owner(conn_factory, owner, run_id)
    if not run:
        raise LookupError("Action plan not found")
    action = run.get("action_snapshot") or {}
    _require_action_access(conn_factory, owner, action)
    executor = str(action.get("executor") or "")
    if executor not in {"mcp_connect", "mcp_credentials", "mirror_connect", "mail_connect", "sms_connect", "sms_user"}:
        return execute_action(conn_factory, owner, run_id)
    merged_inputs = {**(run.get("input_values") or {})}
    secret_field_keys = {
        str(field.get("key") or "")
        for field in action.get("fields") or []
        if isinstance(field, dict) and field.get("type") == "secret"
    }
    if isinstance(raw_inputs, dict):
        # The durable receipt freezes every ordinary field.  The apply request is
        # only a one-way credential envelope; it cannot silently change the
        # server name or any other planned input.
        merged_inputs.update({
            key: value for key, value in raw_inputs.items()
            if key in secret_field_keys
        })
    values, _redacted, secrets = _normalize_action_inputs(action, merged_inputs)
    _validate_administration_action_inputs(action, values)
    if executor in {'sms_connect', 'sms_user'}:
        import sms
        _mark_action_running(conn_factory, owner, run['id'], mark_approved=False)
        _set_action_step(conn_factory, run['id'], 'connect', 'running')
        try:
            if executor == 'sms_connect':
                result = await asyncio.to_thread(sms.connect, conn_factory, owner, values, secrets.get('TWILIO_AUTH_TOKEN'))
            else:
                result = await asyncio.to_thread(sms.bind, conn_factory, owner, values)
            _set_action_step(conn_factory, run['id'], 'connect', 'complete', result)
            _finish_action_run(conn_factory, run['id'], 'complete', result=result, verification=result)
        except Exception as exc:
            message = _action_error_text(exc, secrets.values())
            _fail_active_action_step(conn_factory, run['id'], message)
            _finish_action_run(conn_factory, run['id'], 'failed', error=message)
            raise ValueError(message) from None
        return {'run': _action_run_for_owner(conn_factory, owner, run['id'])}
    if executor == 'mail_connect':
        import correspondence
        _mark_action_running(conn_factory, owner, run['id'], mark_approved=False)
        _set_action_step(conn_factory, run['id'], 'connect', 'running')
        try:
            result = await asyncio.to_thread(correspondence.connect_mailbox, conn_factory, owner, values, secrets.get('MAIL_PASSWORD'))
            verification = {**result, 'imap_authenticated': True, 'smtp_authenticated': True}
            _set_action_step(conn_factory, run['id'], 'connect', 'complete', verification)
            _finish_action_run(conn_factory, run['id'], 'complete', result=result, verification=verification)
        except Exception as exc:
            message = _action_error_text(exc, secrets.values())
            _fail_active_action_step(conn_factory, run['id'], message)
            verification = exc.verification if isinstance(exc, correspondence.MailboxConnectionError) else {}
            _finish_action_run(conn_factory, run['id'], 'failed', error=message, verification=verification)
            raise ValueError(message) from None
        return {'run': _action_run_for_owner(conn_factory, owner, run['id'])}
    if executor == "mirror_connect":
        _mark_action_running(conn_factory, owner, run["id"], mark_approved=False)
        try:
            result, verification = await mirror_actions.execute_connect(conn_factory, run, values, secrets)
            _finish_action_run(conn_factory, run["id"], "complete", result=result, verification=verification)
        except Exception as exc:
            import connection_forms
            nested_secrets = []
            if secrets.get("CONNECTION_INPUTS"):
                try:
                    nested_secrets = connection_forms.private_values(json.loads(secrets["CONNECTION_INPUTS"]))
                except ValueError:
                    pass
            message = _action_error_text(f"{type(exc).__name__}: {exc}", [*secrets.values(), *nested_secrets])
            _fail_active_action_step(conn_factory, run["id"], message)
            _finish_action_run(conn_factory, run["id"], "failed", error=message)
            raise RuntimeError(message) from None
        return {"run": _action_run_for_owner(conn_factory, owner, run["id"])}
    if executor == "mcp_credentials":
        if values.get("operation") == "rotate" and not secrets.get("CREDENTIAL_VALUE"):
            raise ValueError("New credential value is required in the secure Library form")
        _mark_action_running(conn_factory, owner, run["id"])
        try:
            result, verification = await _execute_mcp_credentials(
                conn_factory, run, values, secrets
            )
            _finish_action_run(
                conn_factory,
                run["id"],
                "complete",
                result=result,
                verification=verification,
            )
        except Exception as exc:
            message = _action_error_text(
                f"{type(exc).__name__}: {exc}", secrets.values()
            )
            _fail_active_action_step(conn_factory, run["id"], message)
            _finish_action_run(conn_factory, run["id"], "failed", error=message)
            raise RuntimeError(message) from None
        return {"run": _action_run_for_owner(conn_factory, owner, run["id"])}
    server = str(values.get("server_name") or "")
    generic_mcp = bool((action.get("config") or {}).get("generic_mcp"))
    custom_spec: dict[str, Any] | None = None
    if generic_mcp:
        custom_spec, secrets = _custom_mcp_spec(values, secrets)
        required_secrets = set(custom_spec["declared_secret_names"])
    else:
        required_secrets = {
            str(
                field.get("secret_name")
                or str(field.get("key") or "").removeprefix("secret:")
            )
            for field in action.get("fields") or []
            if isinstance(field, dict)
            and field.get("type") == "secret"
            and field.get("required")
        }
    saved_names, saved_known = await _mcp_gateway_secret_names(conn_factory, server)
    if not saved_known:
        raise ValueError(
            "The secure MCP gateway could not be reached or does not support install-time secrets"
        )
    missing = sorted(required_secrets.difference(saved_names).difference(secrets))
    if missing:
        raise ValueError(
            f"Required secure value{'s are' if len(missing) != 1 else ' is'} missing: "
            + ", ".join(missing)
        )
    _mark_action_running(conn_factory, owner, run["id"])
    try:
        if custom_spec is not None:
            result, verification = await _execute_custom_mcp_steps(
                conn_factory,
                run["id"],
                custom_spec,
                secrets,
                saved_names,
            )
            if result.get("pending_authorization"):
                # The run is parked on its authorize step: the caller (chat
                # agent or Library) hands out the sign-in link; the OAuth
                # callback resumes and finishes the run server-side.
                return {
                    "run": _action_run_for_owner(conn_factory, owner, run["id"]),
                    "status": "awaiting_authorization",
                    "authorization": result,
                }
            _finish_action_run(
                conn_factory,
                run["id"],
                "complete",
                result=result,
                verification=verification,
            )
            return {"run": _action_run_for_owner(conn_factory, owner, run["id"])}

        catalog_id = str((action.get("config") or {}).get("catalog_id") or "")
        _set_action_step(conn_factory, run["id"], "inspect", "running")
        with conn_factory() as conn:
            catalog = conn.execute(
                "SELECT id,name,title,manifest,operators FROM rvbbit.capability_catalog "
                "WHERE id=%s AND kind='mcp' AND active",
                (catalog_id,),
            ).fetchone()
        if not catalog:
            raise LookupError(f"Published MCP capability {catalog_id} was not found")
        _set_action_step(conn_factory, run["id"], "inspect", "complete", {
            "catalog_id": catalog_id,
            "published_tools": len(catalog.get("operators") or []),
            "saved_secret_names": sorted(saved_names),
        })

        _set_action_step(conn_factory, run["id"], "register", "running")
        with conn_factory() as conn:
            registered = conn.execute(
                "SELECT rvbbit.install_mcp_register(%s,%s) AS server",
                (catalog_id, server),
            ).fetchone()
        server = str((registered or {}).get("server") or server)
        _set_action_step(conn_factory, run["id"], "register", "complete", {"server": server})

        _set_action_step(conn_factory, run["id"], "secrets", "running")
        for name, value in secrets.items():
            await _push_mcp_gateway_secret(conn_factory, server, name, value)
        _set_action_step(conn_factory, run["id"], "secrets", "complete", {
            "stored": sorted(secrets),
            "reused": sorted(saved_names.difference(secrets)),
            "credential_store": "canonical encrypted gateway",
            "values_in_chat_or_receipts": False,
        })

        _set_action_step(conn_factory, run["id"], "discover", "running")
        with conn_factory() as conn:
            finalized = conn.execute(
                "SELECT rvbbit.install_mcp_finalize(%s,%s) AS result",
                (catalog_id, server),
            ).fetchone()
        finalize_result = _json_object((finalized or {}).get("result"))
        with conn_factory() as conn:
            wrapper_row = conn.execute(
                "SELECT rvbbit.generate_mcp_wrappers(%s) AS sql_functions",
                (server,),
            ).fetchone() or {}
        finalize_result["sql_functions_created"] = int(
            wrapper_row.get("sql_functions") or 0
        )
        _set_action_step(conn_factory, run["id"], "discover", "complete", finalize_result)

        _set_action_step(conn_factory, run["id"], "verify", "running")
        with conn_factory() as conn:
            probe_row = conn.execute(
                "SELECT rvbbit.mcp_probe(%s) AS probe", (server,)
            ).fetchone()
            counts = conn.execute(
                "SELECT "
                "(SELECT count(*)::int FROM rvbbit.mcp_tools WHERE server=%s) AS tools,"
                "(SELECT count(*)::int FROM rvbbit.operators o "
                " WHERE o.name=ANY(coalesce((SELECT c.operators "
                " FROM rvbbit.capability_catalog c WHERE c.id=%s),ARRAY[]::text[]))) AS operators,"
                "(SELECT count(*)::int FROM pg_proc p JOIN pg_namespace n "
                " ON n.oid=p.pronamespace WHERE n.nspname=%s) AS sql_functions",
                (server, catalog_id, server),
            ).fetchone() or {}
        probe = _json_object((probe_row or {}).get("probe"))
        verification = {
            "server": server,
            "reachable": bool(probe.get("reachable")),
            "latency_ms": probe.get("latency_ms"),
            "tools": int(counts.get("tools") or probe.get("n_tools") or 0),
            "operators": int(counts.get("operators") or finalize_result.get("operators_created") or 0),
            "sql_functions": int(
                counts.get("sql_functions")
                or finalize_result.get("sql_functions_created")
                or 0
            ),
            "drift": finalize_result.get("drift") or {},
        }
        if not verification["reachable"]:
            raise RuntimeError(
                str(probe.get("error") or "The installed MCP server did not pass its active probe")
            )
        _set_action_step(conn_factory, run["id"], "verify", "complete", verification)
        result = {
            "catalog_id": catalog_id,
            "server": server,
            "operators_created": finalize_result.get("operators_created"),
            "sql_functions_created": finalize_result.get("sql_functions_created"),
            "tools": finalize_result.get("tools") or [],
            "base_sql_function": "rvbbit.mcp_call(server, tool, args jsonb)",
            "typed_sql_schema": server,
        }
        _finish_action_run(
            conn_factory, run["id"], "complete", result=result, verification=verification
        )
    except Exception as exc:
        message = _action_error_text(
            f"{type(exc).__name__}: {exc}", secrets.values()
        )
        _fail_active_action_step(conn_factory, run["id"], message)
        _finish_action_run(conn_factory, run["id"], "failed", error=message)
        raise RuntimeError(message) from None
    return {"run": _action_run_for_owner(conn_factory, owner, run["id"])}


def _owner_for_calliope_session(
    conn_factory: Callable[..., Any], session_id: Any
) -> str:
    normalized = _uuid(session_id)
    if not normalized:
        raise ValueError("session_id must be a Calliope session UUID")
    with conn_factory() as conn:
        row = conn.execute(
            "SELECT owner_email FROM rvbbit.calliope_sessions WHERE id=%s::uuid",
            (normalized,),
        ).fetchone()
    if not row or not row.get("owner_email"):
        raise LookupError("Calliope session not found")
    return str(row["owner_email"])


def _execution_subject_for_session(conn_factory, session_id, subject=None):
    owner = _owner_for_calliope_session(conn_factory, session_id)
    if not subject or owner.lower() == str(subject).strip().lower():
        return owner
    try:
        with conn_factory() as conn:
            calliope_access.require_participant(conn, session_id, subject)
    except calliope_access.CalliopeAccessError as exc:
        raise PermissionError(str(exc)) from exc
    return str(subject).strip().lower()


_ACTION_SEARCH_DESCRIPTION_CAP = 320


def _compact_action_for_search(action: dict[str, Any]) -> dict[str, Any]:
    """The MCP search result is read by an agent choosing what to call next, and
    it is re-read on every later step of the turn (measured on the pilot: 12
    full actions averaged 22k chars). Keep what informs the choice — identity,
    state, question fields for runnable actions, what is missing for blocked
    ones — and leave prompt templates, executor config, and scoring to the
    plan/execute path, which reloads the action by id."""
    state = str(action.get("state") or "")
    missing = [
        {k: item.get(k) for k in ("ref", "remediation_action_id") if item.get(k) is not None}
        if isinstance(item, dict) else item
        for item in (action.get("missing_requirements") or [])
    ]
    description = str(action.get("description") or "")
    summary = str(action.get("summary") or "")
    if description and (not summary or description.strip() != summary.strip()):
        if len(description) > _ACTION_SEARCH_DESCRIPTION_CAP:
            description = description[:_ACTION_SEARCH_DESCRIPTION_CAP].rstrip() + "…"
    else:
        description = ""
    compact: dict[str, Any] = {
        "id": action.get("id"),
        "title": action.get("title"),
        "summary": summary,
        "category": action.get("category"),
        "category_label": action.get("category_label"),
        "executor": action.get("executor"),
        "risk": action.get("risk"),
        "state": state,
        "state_label": action.get("state_label"),
    }
    if description:
        compact["description"] = description
    if action.get("tags"):
        compact["tags"] = list(action.get("tags") or [])[:6]
    if missing:
        compact["missing_requirements"] = missing
    if state != "blocked" and action.get("fields"):
        compact["fields"] = action.get("fields")
    return compact


def search_actions_for_session(
    conn_factory: Callable[..., Any],
    session_id: str,
    query: str,
    category: str | None = None,
    limit: int = 12,
    *, authorized_owner: str | None = None,
) -> dict[str, Any]:
    owner = _execution_subject_for_session(conn_factory, session_id, authorized_owner)
    snapshot = _action_catalog_snapshot(conn_factory, owner, query, category, limit=limit)
    snapshot["actions"] = [_compact_action_for_search(action) for action in snapshot.get("actions") or []]
    snapshot["hint"] = (
        "Compact results: question fields are included for runnable actions; "
        "administer_calliope_action / plan by id reloads the full definition."
    )
    return snapshot


def plan_action_for_session(
    conn_factory: Callable[..., Any],
    session_id: str,
    action_id: str,
    inputs: Any = None,
    *, authorized_owner: str | None = None,
) -> dict[str, Any]:
    owner = _execution_subject_for_session(conn_factory, session_id, authorized_owner)
    return {"run": plan_action(conn_factory, owner, action_id, inputs, session_id)}


def execute_action_for_session(
    conn_factory: Callable[..., Any], session_id: str, run_id: str,
    *, authorized_owner: str | None = None,
) -> dict[str, Any]:
    owner = _execution_subject_for_session(conn_factory, session_id, authorized_owner)
    return execute_action(conn_factory, owner, run_id)


_DIRECT_ADMIN_EXECUTORS = {
    "mail_connect",
    "sms_connect",
    "sms_user",
    "mirror_connect",
    "mirror_create",
    "mcp_connect",
    "mcp_credentials",
    "capability_install",
    "mirror_control",
    "brain_query_source",
}

_LOCAL_ADMIN_SQL_ACTION_ID = "admin.local_sql"
_LOCAL_ADMIN_SQL_MAX_CHARS = 100_000
_LOCAL_ADMIN_SQL_ROW_CAP = 200


def _local_admin_sql_timeout_ms() -> int:
    try:
        value = int(os.environ.get("WAREHOUSE_ADMIN_SQL_TIMEOUT_MS", "120000"))
    except (TypeError, ValueError):
        value = 120_000
    return max(1_000, min(value, 600_000))


_LOCAL_ADMIN_SQL_TIMEOUT_MS = _local_admin_sql_timeout_ms()
_LOCAL_ADMIN_SQL_BLOCKS: tuple[tuple[re.Pattern[str], str], ...] = (
    (
        re.compile(r"\bcopy\b", re.I),
        "COPY is outside the local database administration lane",
    ),
    (
        re.compile(
            r"\b(?:pg_read_file|pg_read_binary_file|pg_ls_dir|pg_stat_file|"
            r"lo_import|lo_export)\s*\(",
            re.I,
        ),
        "Host filesystem access is outside the local database administration lane",
    ),
    (
        re.compile(
            r"\b(?:create|alter|drop)\s+(?:database|role|user|tablespace)\b|"
            r"\balter\s+system\b|\bset\s+(?:role|session\s+authorization)\b",
            re.I,
        ),
        "Instance identity and host-wide administration are outside this RVBBIT database lane",
    ),
    (
        re.compile(
            r"\b(?:create|alter|drop)\s+(?:server|foreign\s+data\s+wrapper|"
            r"user\s+mapping)\b|\bimport\s+foreign\s+schema\b|\bdblink\w*\s*\(",
            re.I,
        ),
        "Remote database access belongs to the dlt mirror controller",
    ),
    (
        re.compile(r"\bload\s+'|\blanguage\s+(?:c|internal)\b", re.I),
        "Native library loading is outside the local SQL administration lane",
    ),
)
_LOCAL_ADMIN_SQL_SECRET_RE = re.compile(
    r"(?is)(?:\b(?:password|passwd|api[_ -]?key|access[_ -]?token|auth[_ -]?token|secret)"
    r"\b\s*(?:=>|:=|=|to)?\s*'[^']+'|"
    r"'(?:password|passwd|api[_ -]?key|access[_ -]?token|auth[_ -]?token|secret)\s*[:=][^']+'|"
    r"[a-z][a-z0-9+.-]*://[^\s'\"/:@]+:[^\s'\"@]+@|"
    r"\b(?:sk-|lin_api_|ghp_|github_pat_|xox[baprs]-)[a-z0-9_-]{8,})"
)
_LOCAL_ADMIN_SQL_EXPLICIT_MUTATION_KEYS = {
    "alter", "create", "delete", "drop", "grant", "insert", "merge",
    "revoke", "truncatetable", "update",
}


def _local_admin_sql_contract(raw_sql: Any) -> dict[str, Any]:
    statement = str(raw_sql or "").strip()
    if not statement:
        raise ValueError("sql is required")
    if len(statement) > _LOCAL_ADMIN_SQL_MAX_CHARS:
        raise ValueError(
            f"sql must be at most {_LOCAL_ADMIN_SQL_MAX_CHARS} characters"
        )
    if "\x00" in statement:
        raise ValueError("sql cannot contain a null byte")
    for pattern, message in _LOCAL_ADMIN_SQL_BLOCKS:
        if pattern.search(statement):
            raise ValueError(message)
    if _LOCAL_ADMIN_SQL_SECRET_RE.search(statement):
        raise ValueError(
            "Credentials cannot be placed in admin SQL; use the native secure control"
        )
    try:
        parsed = [
            expression
            for expression in sqlglot.parse(statement, read="postgres")
            if expression is not None
        ]
    except Exception as exc:
        raise ValueError(f"sql could not be parsed as PostgreSQL: {exc}") from None
    if len(parsed) != 1:
        raise ValueError("exactly one SQL statement is allowed per administration receipt")
    expression = parsed[0]
    key = str(expression.key or "statement").lower()
    if key == "command":
        key = str(expression.args.get("this") or key).strip().lower()
    nested_mutation = any(
        str(node.key or "").lower() in _LOCAL_ADMIN_SQL_EXPLICIT_MUTATION_KEYS
        for node in expression.walk()
    )
    direct_select = bool(
        (isinstance(expression, sqlglot_exp.Query) or key == "values")
        and not expression.args.get("into")
        and not nested_mutation
    )
    return {
        "sql": statement,
        "sql_sha256": hashlib.sha256(statement.encode("utf-8")).hexdigest(),
        "statement_type": key,
        "direct_select": direct_select,
        "approval_required": not direct_select,
    }


def _require_direct_administration_action(
    conn_factory: Callable[..., Any], owner: str, action_id: str
) -> dict[str, Any]:
    # Personal correspondence already belongs to the authenticated operator.
    # Organization-level connectors still require the protected Admins Team.
    if action_id != 'email.connect' and not calliope_dreams.is_company_admin(conn_factory, owner):
        raise PermissionError(
            "Direct administration requires a member of the protected Admins Team."
        )
    action = _action_by_id(conn_factory, owner, action_id)
    if not action:
        raise LookupError("Action not found")
    _require_action_access(conn_factory, owner, action)
    executor = str(action.get("executor") or "")
    if executor not in _DIRECT_ADMIN_EXECUTORS:
        raise ValueError(
            "This Library item is a conversational design recipe, not a typed appliance "
            "administration action."
        )
    return action


def _required_mcp_connection_secrets(
    action: dict[str, Any], values: dict[str, Any]
) -> tuple[str, set[str]]:
    server = str(values.get("server_name") or "").strip()
    if (action.get("config") or {}).get("generic_mcp"):
        spec, _ = _custom_mcp_spec(values, {})
        return server, set(spec.get("declared_secret_names") or set())
    required = {
        str(
            field.get("secret_name")
            or str(field.get("key") or "").removeprefix("secret:")
        )
        for field in action.get("fields") or []
        if isinstance(field, dict)
        and field.get("type") == "secret"
        and field.get("required")
        and _action_field_is_visible(field, values)
    }
    return server, {name for name in required if name}


def _secure_action_handoff(
    action: dict[str, Any], server: str, missing_names: list[str], values: dict | None = None
) -> dict[str, Any]:
    import connection_forms
    return {
        "secure_input_required": True,
        "approval_required": False,
        "action_id": action["id"],
        "server": server,
        "missing_secret_names": missing_names,
        "inputs": values or {"server_name": server},
        "form_contract": connection_forms.contract(action, values or {"server_name": server}, missing_names),
        "message": (
            "Use the secure connection card and submit once. "
            "The native control applies and tests the change immediately; no separate approval "
            "is required."
        ),
    }


async def administer_action_with_secure_inputs(
    conn_factory: Callable[..., Any],
    owner: str,
    action_id: str,
    inputs: Any = None,
    session_id: str | None = None,
) -> dict[str, Any]:
    """Apply one typed appliance action from the trusted native UI in one step."""
    action = _require_direct_administration_action(
        conn_factory, owner, action_id
    )
    supplied = dict(inputs) if isinstance(inputs, dict) else {}
    # plan_action persists only normalized ordinary values plus redaction markers;
    # the plaintext envelope remains in this request and is handed directly to the
    # credential gateway executor below.
    run = await asyncio.to_thread(
        plan_action,
        conn_factory,
        owner,
        action["id"],
        supplied,
        session_id,
    )
    try:
        if str(action.get("executor") or "") in {"mcp_connect", "mcp_credentials", "mirror_connect", "mail_connect", "sms_connect", "sms_user"}:
            result = await execute_action_with_secure_inputs(
                conn_factory, owner, str(run["id"]), supplied
            )
        else:
            result = await asyncio.to_thread(
                execute_action, conn_factory, owner, str(run["id"])
            )
    except Exception as exc:
        current = _action_run_for_owner(conn_factory, owner, str(run["id"]))
        if current and current.get("status") == "planned":
            secret_keys = {
                str(field.get("key") or "")
                for field in action.get("fields") or []
                if isinstance(field, dict) and field.get("type") == "secret"
            }
            message = _action_error_text(
                f"{type(exc).__name__}: {exc}",
                [supplied.get(key) for key in secret_keys if supplied.get(key)],
            )
            first_step = next(
                (
                    str(step.get("id"))
                    for step in current.get("steps") or []
                    if isinstance(step, dict) and step.get("id")
                ),
                "",
            )
            if first_step:
                _set_action_step(
                    conn_factory, str(run["id"]), first_step, "failed", {"error": message}
                )
            _finish_action_run(
                conn_factory, str(run["id"]), "failed", error=message
            )
            replacement: Exception = (
                ValueError(message) if isinstance(exc, ValueError) else RuntimeError(message)
            )
            setattr(replacement, "action_run_id", str(run["id"]))
            raise replacement from None
        # Let the HTTP route return the exact redacted failed-step receipt without
        # ever attaching the submitted secret envelope to the exception.
        try:
            setattr(exc, "action_run_id", str(run["id"]))
        except Exception:
            pass
        raise
    result["execution_mode"] = "direct_native"
    result["approval_required"] = False
    return result


async def administer_action_for_session(
    conn_factory: Callable[..., Any],
    session_id: str,
    action_id: str,
    inputs: Any = None,
    *, authorized_owner: str | None = None,
) -> dict[str, Any]:
    """Run one typed appliance admin action directly, retaining its durable receipt."""
    owner = _execution_subject_for_session(conn_factory, session_id, authorized_owner)
    action = _require_direct_administration_action(
        conn_factory, owner, action_id
    )
    executor = str(action.get("executor") or "")

    supplied = dict(inputs) if isinstance(inputs, dict) else {}
    secret_fields = {
        str(field.get("key") or "")
        for field in action.get("fields") or []
        if isinstance(field, dict) and field.get("type") == "secret"
    }
    if any(str(supplied.get(key) or "") for key in secret_fields):
        raise ValueError(
            "Secrets cannot be passed to Calliope; enter them only in the secure native control."
        )
    values, _redacted, _secrets = _normalize_action_inputs(action, supplied)
    _validate_administration_action_inputs(action, values)

    if executor in {'sms_connect', 'sms_user'}:
        return _secure_action_handoff(action, values.get('phone_number') or 'text messaging', ['TWILIO_AUTH_TOKEN'] if executor == 'sms_connect' else [], values)
    if executor == 'mail_connect':
        return _secure_action_handoff(action, values.get('address') or 'your mailbox', ['MAIL_PASSWORD'], values)
    if executor == "mirror_connect":
        handoff = await mirror_actions.connect_handoff(conn_factory, action, values)
        if handoff:
            return handoff
    elif executor == "mcp_connect":
        server, required_names = _required_mcp_connection_secrets(action, values)
        saved_names, known = await _mcp_gateway_secret_names(conn_factory, server)
        if not known:
            raise RuntimeError(
                "The canonical MCP credential store is unavailable; no connection change was attempted."
            )
        missing = sorted(required_names.difference(saved_names))
        if missing:
            return _secure_action_handoff(action, server, missing, values)
    elif executor == "mcp_credentials" and values.get("operation") == "rotate":
        return _secure_action_handoff(
            action,
            str((action.get("config") or {}).get("server_name") or ""),
            [str(values.get("credential_name") or "CREDENTIAL_VALUE")],
            values,
        )

    run = await asyncio.to_thread(
        plan_action,
        conn_factory,
        owner,
        action["id"],
        supplied,
        session_id,
    )
    if executor in {"mcp_connect", "mcp_credentials", "mirror_connect"}:
        result = await execute_action_with_secure_inputs(
            conn_factory, owner, str(run["id"]), {}
        )
    else:
        result = await asyncio.to_thread(
            execute_action, conn_factory, owner, str(run["id"])
        )
    result["execution_mode"] = "direct_admin"
    result["approval_required"] = False
    return result


def _create_local_admin_sql_run(
    conn_factory: Callable[..., Any],
    owner: str,
    session_id: str,
    contract: dict[str, Any],
) -> dict[str, Any]:
    workspace = bool(contract.get("workspace"))
    direct = bool(contract.get("direct_select")) or workspace
    statement_type = str(contract.get("statement_type") or "statement")
    action = {
        "id": "data.workspace_sql" if workspace else _LOCAL_ADMIN_SQL_ACTION_ID,
        "version": 1,
        "category": "admin",
        "category_label": "Local database administration",
        "title": f"Run local RVBBIT {statement_type.upper()} SQL",
        "summary": (
            "Execute one SELECT-shaped RVBBIT administration statement directly."
            if direct
            else "Execute one explicitly approved local RVBBIT database change."
        ),
        "description": (
            "Calliope is the administrator of this appliance-local PostgreSQL database. "
            "The exact SQL and its hash remain in the durable receipt."
        ),
        "executor": "local_sql",
        "risk": "select_function" if direct else "database_change",
        "receipt_only": True,
        "fields": [],
        "config": {
            "requires_admin": True,
            "local_database_only": True,
            "remote_mirror_access": False,
        },
    }
    steps = [
        {
            "id": "inspect",
            "label": "Validate frozen local SQL",
            "detail": (
                f"Require one local PostgreSQL statement and verify SHA-256 "
                f"{contract['sql_sha256']}."
            ),
            "status": "pending",
        },
        {
            "id": "execute",
            "label": f"Execute {statement_type.upper()}",
            "detail": (
                "Run through the appliance's writable local RVBBIT connection with a bounded timeout."
            ),
            "status": "pending",
        },
        {
            "id": "verify",
            "label": "Verify commit and database health",
            "detail": "Open a fresh local connection and retain the command status and bounded result rows.",
            "status": "pending",
        },
    ]
    if workspace:
        action.update({
            "title": "Build Calliope workspace data",
            "summary": "Execute an atomic SQL batch in the agent-owned calliope and calliope_apps schemas.",
            "description": "Ordinary derived-data work runs without approval. SQL and results remain in this execution receipt.",
            "executor": "workspace_sql", "risk": "workspace_write",
        })
        steps[0].update(label="Validate workspace batch", detail="Check supported SQL and workspace targets.")
        steps[1].update(label="Execute atomic batch", detail="Run as the dedicated workspace database login.")
        steps[2].update(label="Record commit", detail="Record the transaction outcome and bounded statement results.")
    plan = {
        "title": action["title"],
        "summary": action["summary"],
        "risk": action["risk"],
        "statement_type": statement_type,
        "sql_sha256": contract["sql_sha256"],
        "approval_required": not direct,
        "steps": steps,
        "rollback": (
            "Use a new local SQL administration receipt for any compensating statement. "
            "The database's own transaction guarantees apply to this single statement."
        ),
    }
    run_id = str(uuid.uuid4())
    values = {
        "sql": contract["sql"],
        "sql_sha256": contract["sql_sha256"],
        "statement_type": statement_type,
        "direct_select": bool(contract.get("direct_select")),
    }
    if workspace:
        plan["rollback"] = "The whole batch rolls back on failure. Correct the SQL and retry without approval."
        values["workspace"] = "calliope"  # Compatibility marker for workspace receipts.
        values["workspace_schemas"] = sorted({s for s, _ in contract["writes"]})
        values["workspace_objects"] = [f"{s}.{t}" for s, t in sorted(set(contract["reads"] + contract["writes"]))]
    with conn_factory() as conn:
        guard = local_sql_review.freeze(conn, contract['sql']) if not direct else None
        if guard:
            plan['local_sql_guard'] = guard
        row = conn.execute(
            "INSERT INTO rvbbit.calliope_action_runs "
            "(id,owner_email,session_id,action_id,action_version,action_snapshot,status,"
            "input_values,input_redacted,plan,steps) "
            "VALUES (%s::uuid,%s,%s::uuid,%s,1,%s::jsonb,'planned',"
            "%s::jsonb,%s::jsonb,%s::jsonb,%s::jsonb) RETURNING *",
            (
                run_id,
                owner,
                session_id,
                action["id"],
                json.dumps(action, default=str),
                json.dumps(values, default=str),
                json.dumps(values, default=str),
                json.dumps(plan, default=str),
                json.dumps(steps, default=str),
            ),
        ).fetchone()
    return _action_run_json(row)


def _execute_local_admin_sql_run(
    conn_factory: Callable[..., Any],
    owner: str,
    run: dict[str, Any],
    *,
    explicitly_approved: bool,
) -> dict[str, Any]:
    values = _json_object(run.get("input_values"))
    contract = _local_admin_sql_contract(values.get("sql"))
    if contract["sql_sha256"] != values.get("sql_sha256"):
        raise ValueError("The frozen SQL receipt hash no longer matches")
    if contract["approval_required"] and not explicitly_approved:
        raise PermissionError("This SQL statement requires explicit approval")
    with conn_factory() as conn:
        checked = local_sql_review.refresh(conn, run)
    review = (checked.get('verification') or {}).get('local_sql_review') or {}
    if review.get('state') in ('retired', 'unavailable'):
        raise ValueError(review['message'])
    run_id = str(run["id"])
    _mark_action_running(
        conn_factory,
        owner,
        run_id,
        mark_approved=explicitly_approved,
    )
    try:
        _set_action_step(
            conn_factory,
            run_id,
            "inspect",
            "complete",
            {
                "statement_type": contract["statement_type"],
                "sql_sha256": contract["sql_sha256"],
                "local_database_only": True,
                "approval_mode": (
                    "explicit_user_approval"
                    if explicitly_approved
                    else "select_shaped_direct"
                ),
            },
        )
        _set_action_step(conn_factory, run_id, "execute", "running")
        started = time.monotonic()
        with conn_factory() as conn:
            conn.execute(
                "SELECT set_config('statement_timeout', %s, false)",
                (str(_LOCAL_ADMIN_SQL_TIMEOUT_MS),),
            )
            cursor = conn.execute(contract["sql"])
            columns = [
                {
                    "name": str(getattr(column, "name", "column")),
                    "type_oid": getattr(column, "type_code", None),
                }
                for column in (cursor.description or [])
            ]
            rows = cursor.fetchmany(_LOCAL_ADMIN_SQL_ROW_CAP) if cursor.description else []
            truncated = bool(cursor.fetchone() is not None) if cursor.description else False
            status_message = str(getattr(cursor, "statusmessage", "") or "")
            affected = getattr(cursor, "rowcount", None)
        elapsed_ms = int((time.monotonic() - started) * 1000)
        execution = _sql_result_snapshot({
            "statement_type": contract["statement_type"],
            "status": status_message,
            "rows_affected": affected if isinstance(affected, int) and affected >= 0 else None,
            "columns": columns,
            "rows": rows,
            "row_count": len(rows),
            "truncated": truncated,
            "elapsed_ms": elapsed_ms,
        })
        _set_action_step(conn_factory, run_id, "execute", "complete", execution)
        _set_action_step(conn_factory, run_id, "verify", "running")
        with conn_factory() as conn:
            health = conn.execute(
                "SELECT current_database() AS database,current_user AS database_user,"
                "pg_is_in_recovery() AS in_recovery"
            ).fetchone() or {}
        verification = _bounded_evidence_json({
            "sql_sha256": contract["sql_sha256"],
            "statement_type": contract["statement_type"],
            "database": health.get("database"),
            "database_user": health.get("database_user"),
            "in_recovery": bool(health.get("in_recovery")),
            "committed": True,
            "remote_source_contacted": False,
        })
        _set_action_step(conn_factory, run_id, "verify", "complete", verification)
        _finish_action_run(
            conn_factory,
            run_id,
            "complete",
            result=execution,
            verification=verification,
        )
    except Exception as exc:
        message = _action_error_text(f"{type(exc).__name__}: {exc}")
        _fail_active_action_step(conn_factory, run_id, message)
        _finish_action_run(conn_factory, run_id, "failed", error=message)
    completed = _action_run_for_owner(conn_factory, owner, run_id)
    return {
        "run": completed,
        "execution_mode": (
            "approved_local_sql" if explicitly_approved else "direct_local_select_sql"
        ),
        "approval_required": False,
    }


def administer_local_sql_for_session(
    conn_factory: Callable[..., Any],
    session_id: str,
    sql: Any = None,
    approved_run_id: Any = None,
    *,
    authorized_owner: str | None = None,
    expected_sql_sha256: str | None = None,
) -> dict[str, Any]:
    """Give one authenticated Calliope administrator a local RVBBIT DBA lane."""
    owner = _execution_subject_for_session(conn_factory, session_id, authorized_owner)
    if not calliope_dreams.is_company_admin(conn_factory, owner):
        raise PermissionError(
            "Local SQL administration requires a member of the protected Admins Team."
        )
    if approved_run_id:
        run = _action_run_for_owner(conn_factory, owner, approved_run_id)
        if not run or run.get("action_id") != _LOCAL_ADMIN_SQL_ACTION_ID:
            raise LookupError("Local SQL change receipt not found")
        if str(run.get("session_id") or "") != str(session_id):
            raise PermissionError("The SQL change receipt belongs to another Calliope session")
        if run.get("status") != "planned":
            raise ValueError("This SQL change receipt is no longer awaiting execution")
        frozen_sql = str((run.get("input_values") or {}).get("sql") or "")
        frozen_hash = str((run.get("input_values") or {}).get("sql_sha256") or "").lower()
        if expected_sql_sha256 and not hmac.compare_digest(
            str(expected_sql_sha256).lower(), frozen_hash
        ):
            raise ValueError("The reviewed SQL hash no longer matches the frozen receipt")
        if sql not in (None, "") and str(sql).strip() != frozen_sql:
            raise ValueError("Approved execution accepts only the exact frozen SQL")
        return _execute_local_admin_sql_run(
            conn_factory, owner, run, explicitly_approved=True
        )

    if workspace_sql.is_workspace_write(sql):
        return run_workspace_sql_for_session(
            conn_factory, session_id, sql, authorized_owner=authorized_owner
        )
    contract = _local_admin_sql_contract(sql)
    run = _create_local_admin_sql_run(conn_factory, owner, session_id, contract)
    if contract["direct_select"]:
        return _execute_local_admin_sql_run(
            conn_factory, owner, run, explicitly_approved=False
        )
    return {
        "run": run,
        "execution_mode": "awaiting_explicit_approval",
        "approval_required": True,
        "message": (
            f"This {contract['statement_type'].upper()} statement is frozen under receipt "
            f"{run['id']}. Show the exact SQL to the user and wait for explicit approval. "
            "Then call this tool again with approved_run_id only."
        ),
    }


def run_workspace_sql_for_session(
    conn_factory: Callable[..., Any], session_id: str, sql: Any,
    *, authorized_owner: str | None = None,
    on_run_created: Callable[[str], None] | None = None,
) -> dict[str, Any]:
    """Run ordinary data work under existing appliance administrator authority."""
    import auth
    import server

    owner = _execution_subject_for_session(conn_factory, session_id, authorized_owner)
    if not calliope_dreams.is_company_admin(conn_factory, owner):
        raise PermissionError("The shared data workspace currently requires an Admins Team session")
    statement = str(sql or "")
    if _LOCAL_ADMIN_SQL_SECRET_RE.search(statement):
        raise ValueError("Credentials cannot be placed in workspace SQL; use the native secure control")
    batch = workspace_sql.plan(statement)
    run = _create_local_admin_sql_run(conn_factory, owner, session_id, {
        **batch, "workspace": True, "statement_type": "batch", "direct_select": False,
    })
    run_id = str(run["id"])
    _mark_action_running(conn_factory, owner, run_id, mark_approved=False)
    try:
        if on_run_created:
            on_run_created(run_id)
        _set_action_step(conn_factory, run_id, "inspect", "complete", {
            "sql_sha256": batch["sql_sha256"], "statements": len(batch["statements"]),
            "approval_mode": "workspace_authority", "objects": batch["writes"],
        })
        _set_action_step(conn_factory, run_id, "execute", "running")
        execution = workspace_sql.execute(
            conn_factory, batch, seed=str(auth.JWT_SECRET or ""),
            schema_allowed=server._schema_allowed, timeout_ms=_LOCAL_ADMIN_SQL_TIMEOUT_MS,
        )
    except Exception as exc:
        message = _action_error_text(f"{type(exc).__name__}: {exc}")
        _fail_active_action_step(conn_factory, run_id, message)
        _finish_action_run(conn_factory, run_id, "failed", error=message)
    else:
        # No extra database health probe after commit: its failure must not turn
        # successful data work into a misleading failed/retryable receipt.
        # Bound each statement independently so a 50-statement batch retains
        # its final verification result and nested rows remain structured.
        execution = _sql_result_snapshot(execution)
        verification = {"committed": True, "sql_sha256": batch["sql_sha256"],
                        "schema": execution.get("schema"), "schemas": execution.get("schemas", []),
                        "database_user": execution["database_user"]}
        _set_action_step(conn_factory, run_id, "execute", "complete", execution)
        _set_action_step(conn_factory, run_id, "verify", "complete", verification)
        _finish_action_run(conn_factory, run_id, "complete", result=execution, verification=verification)
    return {"run": _action_run_for_owner(conn_factory, owner, run_id),
            "execution_mode": "workspace_sql", "approval_required": False}


# Items wait only in the person's own, live, web-channel conversations: the
# same rule that lets them answer (SMS threads answer by text).
_AWAITING_SQL = """
SELECT * FROM (
  SELECT r.id, 'question' AS kind, r.session_id, coalesce(r.request->>'title', 'A question') AS title,
         s.title AS session_title, r.created_at
  FROM rvbbit.calliope_input_requests r JOIN rvbbit.calliope_sessions s ON s.id=r.session_id
  WHERE r.status='open' AND r.owner_email=lower(%(owner)s) AND NOT s.archived AND s.channel='web'
  UNION ALL
  SELECT f.id, 'approval', a.session_id, coalesce(nullif(f.title, ''), 'A SQL change'), s.title, a.created_at
  FROM rvbbit.calliope_action_runs a
  JOIN rvbbit.calliope_sessions s ON s.id=a.session_id
  JOIN rvbbit.calliope_surfaces f ON f.session_id=a.session_id AND f.kind='action'
       AND f.payload->'run'->>'id'=a.id::text
  WHERE a.status='planned' AND a.action_snapshot->>'executor'='local_sql'
    AND a.action_snapshot->>'receipt_only'='true' AND lower(a.owner_email)=lower(%(owner)s)
    AND coalesce(a.verification->'local_sql_review'->>'state', '') NOT IN ('retired', 'unavailable')
    AND NOT s.archived AND s.channel='web'
  UNION ALL
  SELECT d.id, 'decision', d.session_id, d.question, s.title, d.created_at
  FROM rvbbit.calliope_decision_requests d JOIN rvbbit.calliope_sessions s ON s.id=d.session_id
  WHERE d.status='open' AND d.owner_email=lower(%(owner)s) AND NOT s.archived AND s.channel='web'
) awaiting ORDER BY created_at DESC LIMIT 20
"""


def _team_opt_in(body: Any) -> bool:
    """Team mode is opt-in: slower and costlier, so a chat starts solo unless
    the person switched Team on for it."""
    return isinstance(body, dict) and body.get("team_mode") is True


def approve_local_sql_run(
    conn_factory: Callable[..., Any],
    owner: str,
    run_id: Any,
    expected_sql_sha256: Any,
) -> dict[str, Any]:
    """Execute one reviewed, frozen local-SQL receipt from the native UI."""
    run = _action_run_for_owner(conn_factory, owner, run_id)
    if not run or run.get("action_id") != _LOCAL_ADMIN_SQL_ACTION_ID:
        raise LookupError("Local SQL change receipt not found")
    action = run.get("action_snapshot") or {}
    if action.get("executor") != "local_sql" or not action.get("receipt_only"):
        raise ValueError("This receipt is not an approval-gated local SQL change")
    if run.get("status") != "planned":
        raise ValueError("This SQL change receipt is no longer awaiting execution")
    reviewed_hash = str(expected_sql_sha256 or "").strip().lower()
    frozen_hash = str((run.get("input_values") or {}).get("sql_sha256") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", reviewed_hash):
        raise ValueError("The reviewed SQL SHA-256 is required for approval")
    if not frozen_hash or not hmac.compare_digest(reviewed_hash, frozen_hash):
        raise ValueError("The reviewed SQL hash no longer matches the frozen receipt")
    session_id = str(run.get("session_id") or "")
    if not _uuid(session_id):
        raise ValueError("The local SQL receipt has no originating Calliope session")
    return administer_local_sql_for_session(
        conn_factory,
        session_id,
        approved_run_id=run["id"],
        authorized_owner=owner,
        expected_sql_sha256=reviewed_hash,
    )


def _mirror_run_history(conn_factory, job_name, run_id, limit):
    """Read bounded local receipts even when the worker is offline."""
    with conn_factory() as conn:
        rows = conn.execute(
            "SELECT run_id,job_name,trigger,status,attempt,requested_at,started_at,"
            "heartbeat_at,finished_at,tables_succeeded,tables_failed,rows_loaded,"
            "error_code,error_message FROM rvbbit.mirror_runs "
            "WHERE (%s::text IS NULL OR job_name=%s) "
            "AND (%s::uuid IS NULL OR run_id=%s::uuid) "
            "ORDER BY requested_at DESC,run_id DESC LIMIT %s",
            (job_name, job_name, run_id, run_id, limit + 1),
        ).fetchall()
        if run_id and not rows:
            raise LookupError("Mirror run not found for the requested job")
        tables = []
        if run_id:
            tables = conn.execute(
                "SELECT source_table,destination_table,load_mode,status,rows_loaded,"
                "started_at,finished_at,error_code,error_message "
                "FROM rvbbit.mirror_table_runs WHERE run_id=%s::uuid "
                "ORDER BY source_table LIMIT 201", (run_id,),
            ).fetchall()
    def clean(row):
        result = _row_json(row)
        if result.get("run_id"):
            result["run_id"] = str(result["run_id"])
        result["error_message"] = _action_error_text(result.get("error_message")) or None
        return result
    return {
        "runs": [clean(row) for row in rows[:limit]],
        "runs_truncated": len(rows) > limit,
        "run_tables": [clean(row) for row in tables[:200]],
        "run_tables_truncated": len(tables) > 200,
    }


async def mirror_status_for_session(
    conn_factory: Callable[..., Any], session_id: str,
    job_name: str = "", run_id: str = "", limit: int = 10,
) -> dict[str, Any]:
    """Return credential-free local schedule, controller, and run status."""
    _owner_for_calliope_session(conn_factory, session_id)
    job_name = str(job_name or "").strip()
    run_id = str(run_id or "").strip()
    if run_id and not _uuid(run_id):
        raise ValueError("run_id must be a mirror run UUID")
    if not 1 <= int(limit) <= 100:
        raise ValueError("limit must be between 1 and 100")
    limit = int(limit)
    snapshot = await asyncio.to_thread(_setup_mirror_snapshot, conn_factory)
    active_health: dict[str, Any]
    try:
        health = await _setup_mirror_worker_request(
            conn_factory, "GET", "/health", timeout_seconds=10
        )
        active_health = {
            key: health.get(key)
            for key in (
                "status",
                "ok",
                "database_name",
                "dlt_version",
                "controller_auth_configured",
                "credential_store",
            )
            if health.get(key) not in (None, "", [], {})
        }
        active_health["reachable"] = True
        active_health["checked_at"] = datetime.now(timezone.utc).isoformat()
    except Exception as exc:
        active_health = {
            "reachable": False,
            "error": _action_error_text(exc),
        }
    jobs: list[dict[str, Any]] = []
    connections = []
    for connection in snapshot.get("connections") or []:
        connections.append({key: connection.get(key) for key in (
            "connection_name", "label", "dialect", "enabled", "credential_configured",
            "last_tested_at", "last_test_ok",
        )})
        for job in connection.get("jobs") or []:
            if job_name and job.get("job_name") != job_name:
                continue
            jobs.append({
                key: job.get(key)
                for key in (
                    "job_name",
                    "connection_name",
                    "source_schema",
                    "destination_schema",
                    "enabled",
                    "schedule_seconds",
                    "next_run_at",
                    "last_run_at",
                    "table_count",
                    "run_id",
                    "latest_run_status",
                    "latest_run_rows_loaded",
                    "latest_run_requested_at",
                    "latest_run_finished_at",
                    "latest_run_error_code",
                    "latest_run_error_message",
                )
            })
            jobs[-1]["latest_run_error_message"] = _action_error_text(job.get("latest_run_error_message")) or None
            if job_name:
                tables = job.get("tables") or []
                jobs[-1]["tables"] = [{key: table.get(key) for key in (
                    "source_table", "destination_table", "load_mode", "primary_key",
                    "cursor_column", "change_detection", "enabled",
                )} for table in tables[:200]]
                jobs[-1]["tables_truncated"] = len(tables) > 200
    if job_name and not jobs:
        raise LookupError("Mirror job not found")
    controller = {
        **_json_object(snapshot.get("worker")),
        "available": bool(snapshot.get("available")),
        "active_health": active_health,
    }
    active_worker_auth = active_health.get("controller_auth_configured")
    if isinstance(active_worker_auth, bool):
        controller["worker_authenticated"] = active_worker_auth
        controller["authenticated"] = bool(
            controller.get("warehouse_authenticated") and active_worker_auth
        )
        controller["available"] = bool(
            snapshot.get("credential_store_ready")
            and controller.get("registered")
            and controller["authenticated"]
            and active_health.get("ok") is True
        )
    controller["available"] = bool(controller.get("available") and active_health.get("reachable") and active_health.get("ok") is True)
    history = {"runs": [], "runs_truncated": False, "run_tables": [], "run_tables_truncated": False}
    if snapshot.get("installed"):
        history = await asyncio.to_thread(_mirror_run_history, conn_factory, job_name or None, run_id or None, limit)
    return {
        "installed": bool(snapshot.get("installed") and controller.get("registered")),
        "control_plane_installed": bool(snapshot.get("installed")),
        "scope": "managed_dlt_sql_mirrors",
        "controller": controller,
        "connections": connections,
        "jobs": jobs,
        **history,
        "summary": {
            "jobs": len(jobs),
            "enabled": sum(bool(job.get("enabled")) for job in jobs),
            "active_runs": sum(
                str(job.get("latest_run_status") or "") in {"queued", "running"}
                for job in jobs
            ),
            "failed": sum(
                str(job.get("latest_run_status") or "") in _MIRROR_RETRYABLE_STATUSES
                for job in jobs
            ),
        },
        "source_access": "Remote source access is confined to the dlt mirror worker.",
        "capabilities": {
            "job_inventory": True, "run_history": True, "table_run_status": True,
            "connect_source": True, "discover_source": True, "create_job": True,
            "arbitrary_dlt_jobs": False,
        },
        "guidance": (
            "No jobs does not mean dlt is missing. For a job's configuration and tables, "
            "call mirror_status with job_name; for a run's table outcomes use run_id. "
            "Existing mirrors have typed mirror.manage actions via search_calliope_actions. "
            "Use connect_mirror_source, discover_mirror_source and create_mirror_job from any chat. "
            "New jobs default to manual; arbitrary Python/dlt collectors "
            "are not exposed yet. For local SQL ETL, including MCP/API SQL materializers, use "
            "run_workspace_sql on demand or save_workspace_job for direct scheduled execution; "
            "manage_workspace_job pauses/resumes/runs it and workspace_job_status returns history."
        ),
    }


def _canonical_owner(request: Any) -> tuple[str | None, dict[str, Any] | None]:
    import auth

    session = auth.read_session_full(request)
    if not session:
        return None, None
    identity = str(session.get("identity") or "").strip().lower()
    return (identity or None), session


def _hermes_headers(config: CalliopeConfig) -> dict[str, str]:
    headers = {
        "Authorization": f"Bearer {config.hermes_api_key}",
        "Content-Type": "application/json",
    }
    # One optional COMPANY scope. Never derive this from owner email: the
    # intended pilot behavior is shared memory across Calliope + GChat.
    if config.memory_key:
        headers["X-Hermes-Session-Key"] = config.memory_key
    return headers


def _hermes_session_url(
    config: CalliopeConfig,
    hermes_id: str,
    suffix: str = "",
    *,
    base_url: str | None = None,
) -> str:
    root = str(base_url or config.hermes_url).rstrip("/")
    return f"{root}/api/sessions/{quote(hermes_id, safe='')}{suffix}"


def _specialist_profile(
    conn_factory: Callable[..., Any], specialist_key: Any
) -> dict[str, Any] | None:
    key = str(specialist_key or "").strip().lower()
    if not key or key == "calliope":
        return None
    with conn_factory() as conn:
        row = conn.execute(
            "SELECT specialist_key,profile_name,display_name,description,capabilities "
            "FROM rvbbit.calliope_specialists "
            "WHERE status='active' AND ("
            "specialist_key=%(key)s OR lower(display_name)=%(key)s OR lower(profile_name)=%(key)s"
            ") ORDER BY (specialist_key=%(key)s) DESC, created_at LIMIT 1",
            {"key": key},
        ).fetchone()
    return dict(row) if row else None


def _hermes_profile_base_url(
    config: CalliopeConfig, profile_name: Any = None
) -> str:
    root = str(config.hermes_url).rstrip("/")
    profile = str(profile_name or "").strip()
    return f"{root}/p/{quote(profile, safe='')}" if profile else root


def _session_hermes_base_url(
    config: CalliopeConfig,
    conn_factory: Callable[..., Any],
    session: dict[str, Any] | Any,
) -> str:
    specialist = _specialist_profile(
        conn_factory, (session or {}).get("specialist_key")
    )
    return _hermes_profile_base_url(
        config, specialist.get("profile_name") if specialist else None
    )


async def _hermes_json(
    config: CalliopeConfig,
    method: str,
    path: str,
    body: dict[str, Any] | None = None,
    timeout_seconds: float = 45.0,
    *,
    base_url: str | None = None,
) -> dict[str, Any]:
    timeout = httpx.Timeout(timeout_seconds, connect=8.0)
    async with httpx.AsyncClient(timeout=timeout) as client:
        response = await client.request(
            method,
            f"{str(base_url or config.hermes_url).rstrip('/')}{path}",
            headers=_hermes_headers(config),
            json=body,
        )
    if response.status_code >= 400:
        detail = response.text[:800]
        raise RuntimeError(f"Hermes {method} {path} failed ({response.status_code}): {detail}")
    try:
        value = response.json()
    except ValueError:
        value = {"text": response.text}
    return value if isinstance(value, dict) else {"result": value}


def _hermes_inference_timeout_seconds() -> float:
    """Generous bound for model work; health/control probes stay short."""

    try:
        value = float(
            os.environ.get("WAREHOUSE_HERMES_INFERENCE_TIMEOUT_SECONDS", "900")
        )
    except (TypeError, ValueError):
        value = 900.0
    return max(240.0, min(value, 3600.0))


def _hermes_json_sync(
    config: CalliopeConfig,
    method: str,
    path: str,
    body: dict[str, Any] | None = None,
    timeout_seconds: float = 45.0,
) -> dict[str, Any]:
    """Synchronous Hermes bridge for MCP tools executed in FastMCP workers."""
    timeout = httpx.Timeout(timeout_seconds, connect=8.0)
    with httpx.Client(timeout=timeout) as client:
        response = client.request(
            method,
            f"{config.hermes_url}{path}",
            headers=_hermes_headers(config),
            json=body,
        )
    if response.status_code >= 400:
        raise RuntimeError(
            f"Hermes {method} {path} failed ({response.status_code}): {response.text[:800]}"
        )
    try:
        value = response.json()
    except ValueError:
        value = {"text": response.text}
    return value if isinstance(value, dict) else {"result": value}


