    def workbench_error_response(exc: Exception) -> Response:
        if isinstance(exc, workbench_access.WorkbenchError):
            return json_response(
                {"error": {"code": exc.code, "message": str(exc)}}, exc.status
            )
        return json_response(
            {
                "error": {
                    "code": "DESKTOP_WORKBENCH_FAILED",
                    "message": str(exc)[:1000],
                }
            },
            500,
        )


    async def render_calliope_page(request: Any, *, setup_mode: bool, page: str = "") -> Response:
        owner, session = _canonical_owner(request)
        if not owner:
            return RedirectResponse(f"/login?next={quote(request.url.path)}", status_code=302)
        if not session.get("mapped", True):
            return RedirectResponse("/gallery", status_code=302)
        observe_browser_principal(request)
        can_administer = False if setup_mode else await asyncio.to_thread(
            calliope_dreams.is_company_admin, conn_factory, owner
        )
        template = (_ASSET_DIR / "index.html").read_text(encoding="utf-8")
        background = auth.background_layer(
            0.74,
            "radial-gradient(1000px 700px at 58% -15%, rgba(32,67,64,.10), transparent 67%),"
            "linear-gradient(to bottom,rgba(16,13,11,.10),rgba(16,13,11,.40) 86%)",
            scene_key=owner,
        )
        html = (
            template.replace("__CALLIOPE_BACKGROUND__", background)
            .replace("__CALLIOPE_WORKSPACE_NAV__", "" if setup_mode else warehouse_theme.workspace_navigation(can_administer=can_administer))
            .replace("__CALLIOPE_RABBIT__", rabbit_svg)
            .replace(
                "__CALLIOPE_ACCOUNT__",
                "" if setup_mode else warehouse_theme.account_control(
                    session,
                    workspace_menu=True,
                    can_administer=can_administer,
                ),
            )
            .replace("__CALLIOPE_ASSET_VERSION__", _ASSET_VERSION)
            .replace("__CALLIOPE_EXCALIFONT__", _EXCALIFONT_HASHES)
            .replace(
                "__CALLIOPE_PAGE_TITLE__",
                "Set up Calliope" if setup_mode else "Calliope",
            )
            .replace("__CALLIOPE_MODE__", "setup" if setup_mode else "arrangement" if page else "chat")
            .replace("__CALLIOPE_PAGE__", page)
            .replace(
                "__CALLIOPE_BRAND_LINK__",
                'aria-disabled="true"' if setup_mode else 'href="/floor"',
            )
        )
        return HTMLResponse(
            html,
            headers={
                "cache-control": "private, no-store, max-age=0, must-revalidate",
                "pragma": "no-cache",
                "expires": "0",
                "content-security-policy": (
                    "default-src 'self'; script-src 'self' https://apis.google.com; "
                    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
                    "font-src 'self' https://fonts.gstatic.com; "
                    "img-src 'self' data: blob: https:; "
                    # Stage maps use the vendored GL runtime, but fetch styles,
                    # sprites, glyphs and tiles from Mapbox and start a blob worker.
                    "connect-src 'self' blob: https://www.googleapis.com "
                    "https://api.mapbox.com https://events.mapbox.com https://*.tiles.mapbox.com; "
                    "worker-src 'self' blob:; "
                    "frame-src 'self' https://docs.google.com https://drive.google.com https://accounts.google.com; "
                    "object-src 'none'; "
                    "base-uri 'none'; frame-ancestors 'self'; form-action 'self'"
                ),
                "x-content-type-options": "nosniff",
            },
        )

