    @mcp.custom_route("/calliope/specialists/{avatar_file}", methods=["GET"])
    async def calliope_specialist_avatar(request):
        owner, _ = _canonical_owner(request)
        if not owner:
            return Response(status_code=401)
        avatar_file = str(request.path_params.get("avatar_file") or "").strip()
        if not _AGENT_AVATAR_FILE_RE.fullmatch(avatar_file):
            return Response(status_code=404)
        async def thumbnail(raw):
            if request.query_params.get("thumbnail") != "1":
                return None
            small = await asyncio.to_thread(_small_agent_avatar, raw)
            if small:
                return Response(small[0], media_type=small[1], headers={
                    "cache-control": "private, max-age=3600",
                    "x-content-type-options": "nosniff",
                })
            return None

        path = _ASSET_DIR / avatar_file
        if not path.is_file():
            # Factory-minted experts keep their generated portraits in the
            # database (they replicate with everything else).
            if avatar_file.startswith("generated-") and avatar_file.endswith(".png"):
                specialist_key = avatar_file[len("generated-"):-len(".png")]

                def _load_generated_avatar():
                    with conn_factory() as conn:
                        ready = conn.execute(
                            "SELECT to_regclass('rvbbit.generated_specialist_avatars')"
                            " IS NOT NULL AS r"
                        ).fetchone()
                        if not (ready and ready["r"]):
                            return None
                        row = conn.execute(
                            "SELECT png FROM rvbbit.generated_specialist_avatars "
                            "WHERE specialist_key=%s",
                            (specialist_key,),
                        ).fetchone()
                    return bytes(row["png"]) if row else None

                png = await asyncio.to_thread(_load_generated_avatar)
                if png:
                    small = await thumbnail(png)
                    if small is not None:
                        return small
                    import expert_portraits
                    return Response(
                        png,
                        media_type=expert_portraits.image_media_type(png),
                        headers={
                            "cache-control": "private, max-age=3600",
                            "x-content-type-options": "nosniff",
                        },
                    )
            return Response(status_code=404)
        if request.query_params.get("thumbnail") == "1":
            small = await thumbnail(await asyncio.to_thread(path.read_bytes))
            if small is not None:
                return small
        media_type = {
            ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp",
        }.get(path.suffix.lower(), "image/png")
        return FileResponse(
            path,
            media_type=media_type,
            headers={
                "cache-control": "private, max-age=3600",
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route("/api/calliope/avatars/{avatar_key}", methods=["GET"])
    async def calliope_person_avatar(request):
        """Proxy observed real avatars; a provider miss intentionally stays 404."""
        _viewer, err = api_owner(request)
        if err:
            return Response(status_code=404)
        avatar_key = _uuid(request.path_params.get("avatar_key"))
        if not avatar_key:
            return Response(status_code=404)
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT email,avatar_provider,avatar_source_url "
                "FROM rvbbit.application_principals WHERE avatar_key=%s::uuid",
                (avatar_key,),
            ).fetchone()
        if not row:
            return Response(status_code=404)
        source_url = str(row.get("avatar_source_url") or "")
        if row.get("avatar_provider") == "google" and source_url:
            fetch = auth._fetch_google_avatar(source_url)
        else:
            fetch = auth._fetch_gravatar_avatar(str(row.get("email") or ""))
        try:
            data, media_type = await fetch
        except auth._AvatarNotFound:
            return Response(
                status_code=404,
                headers={"cache-control": "private, max-age=900"},
            )
        except Exception:
            return Response(
                status_code=404,
                headers={"cache-control": "private, max-age=60"},
            )
        return Response(
            data,
            media_type=media_type,
            headers={
                "cache-control": "private, max-age=900",
                "cross-origin-resource-policy": "same-origin",
                "x-content-type-options": "nosniff",
            },
        )

    async def configured_chat_agents():
        with conn_factory() as conn:
            specialist_rows = conn.execute(
                "SELECT specialist_key,profile_name,display_name,description,capabilities "
                "FROM rvbbit.calliope_specialists WHERE status='active' "
                "ORDER BY display_name"
            ).fetchall()
        try:
            profile_payload = await asyncio.to_thread(hermes_profiles.profiles)
            profile_agents = {
                str(item.get("key") or "").strip().lower(): item
                for item in profile_payload.get("profiles") or []
                if isinstance(item, dict) and item.get("key")
            }
        except Exception:
            profile_agents = {}
        primary_identity = profile_agents.get("default", {})
        chat_agents = [{
            "key": "calliope",
            "profile": None,
            "name": str(primary_identity.get("name") or "Calliope"),
            "role_label": str(primary_identity.get("role_label") or "Warehouse muse"),
            "description": str(primary_identity.get("description") or (
                "Warehouse muse — explores the company brain, coordinates specialists, "
                "and turns questions into durable analysis and artifacts."
            )),
            "capabilities": ["company_brain", "analysis", "coordination", "artifacts"],
            "primary": True,
            "signature_font": primary_identity.get("signature_font"),
            "voice_id": primary_identity.get("voice_id"),
            "voice_preview_text": primary_identity.get("voice_preview_text"),
            **{field: primary_identity.get(field) for field in ("avatar_color", "avatar_day_color", "avatar_night_color")},
            "avatar_day_url": _agent_avatar_url(primary_identity.get("avatar_day_file")),
            "avatar_night_url": _agent_avatar_url(primary_identity.get("avatar_night_file")),
        }]
        for row in specialist_rows:
            key = str(row.get("specialist_key") or "")
            profile = str(row.get("profile_name") or "")
            identity = profile_agents.get(profile.strip().lower()) or profile_agents.get(key.strip().lower()) or {}
            chat_agents.append({
                "key": key,
                "profile": profile,
                "name": str(identity.get("name") or row.get("display_name") or "Specialist"),
                "role_label": str(identity.get("role_label") or "Specialist"),
                "description": str(identity.get("description") or row.get("description") or ""),
                "capabilities": row.get("capabilities") or [],
                "primary": False,
                "signature_font": identity.get("signature_font"),
                "voice_id": identity.get("voice_id"),
                "voice_preview_text": identity.get("voice_preview_text"),
                **{field: identity.get(field) for field in ("avatar_color", "avatar_day_color", "avatar_night_color")},
                "avatar_url": _agent_avatar_url(identity.get("avatar_file")),
            })
        return chat_agents

