    @mcp.custom_route("/api/calliope/response-preferences", methods=["PUT"])
    async def put_calliope_response_preferences(request):
        owner, err = api_owner(request)
        if err:
            return err
        raw = await request.body()
        if len(raw) > 8 * 1024:
            return json_response({
                "error": {"code": "RESPONSE_PREFERENCES_TOO_LARGE"}
            }, 413)
        try:
            body = json.loads(raw or b"{}")
            if not isinstance(body, dict):
                raise ValueError("response preference payload must be an object")
            preferences = _normalize_response_preferences(body.get("preferences"))
            if_absent = body.get("if_absent") is True
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
            return json_response({
                "error": {
                    "code": "INVALID_RESPONSE_PREFERENCES",
                    "message": str(exc)[:400],
                }
            }, 400)
        values = (
            owner,
            preferences["conversational_answers"],
            preferences["read_aloud_mode"],
            preferences["response_personality"],
            preferences["speak_working_updates"],
        )
        returning = (
            "conversational_answers,read_aloud_mode,response_personality,"
            "speak_working_updates,updated_at"
        )
        with conn_factory() as conn:
            if if_absent:
                row = conn.execute(
                    "INSERT INTO rvbbit.calliope_response_preferences "
                    "(owner_email,conversational_answers,read_aloud_mode,"
                    "response_personality,speak_working_updates,updated_at) "
                    "VALUES (%s,%s,%s,%s,%s,now()) ON CONFLICT (owner_email) "
                    f"DO NOTHING RETURNING {returning}",
                    values,
                ).fetchone()
                if not row:
                    row = conn.execute(
                        f"SELECT {returning} FROM rvbbit.calliope_response_preferences "
                        "WHERE owner_email=%s",
                        (owner,),
                    ).fetchone()
            else:
                row = conn.execute(
                    "INSERT INTO rvbbit.calliope_response_preferences "
                    "(owner_email,conversational_answers,read_aloud_mode,"
                    "response_personality,speak_working_updates,updated_at) "
                    "VALUES (%s,%s,%s,%s,%s,now()) ON CONFLICT (owner_email) DO UPDATE SET "
                    "conversational_answers=EXCLUDED.conversational_answers,"
                    "read_aloud_mode=EXCLUDED.read_aloud_mode,"
                    "response_personality=EXCLUDED.response_personality,"
                    "speak_working_updates=EXCLUDED.speak_working_updates,updated_at=now() "
                    f"RETURNING {returning}",
                    values,
                ).fetchone()
        return json_response(_response_preferences_payload(owner, row))

