    @mcp.custom_route("/api/calliope/gallery/tables/ask", methods=["POST"])
    async def gallery_table_ask(request):
        owner, err = api_owner(request)
        if err:
            return err
        import gallery_tables
        try:
            body = await request.json()
            table = await asyncio.to_thread(gallery_tables.detail, conn_factory, owner, body.get("ref"))
            question = str(body.get("question") or "Explain what this table represents, how it is maintained, and whether its stored observations need attention.").strip()[:2000]
        except PermissionError as exc:
            return json_response({"error": {"message": str(exc)}}, 403)
        except LookupError as exc:
            return json_response({"error": {"message": str(exc)}}, 404)
        except (ValueError, AttributeError) as exc:
            return json_response({"error": {"message": str(exc)}}, 400)
        title = "Table · " + table['qualified_name']
        session = await _create_session_record(config, conn_factory, owner, title[:120])
        turn_id = str(uuid.uuid4())
        with conn_factory() as conn:
            conn.execute("INSERT INTO rvbbit.calliope_turns(id,session_id,ordinal,user_message,assistant_message,status,completed_at,turn_kind) "
                         "VALUES(%s,%s,1,%s,%s,'complete',now(),'action')",
                         (turn_id,session['id'],title,"The table metadata and saved observations are pinned. Ask Calliope what you would like to know or change."))
        item = {"ref":table['ref'],"kind":"table","title":table['qualified_name'],"label":table['qualified_name'],
                "summary":table['description'] or "Table metadata and saved observations", "state":"ready",
                "facts":[{"label":"Rows","value":table['rows']},{"label":"Row source","value":table['row_source']},
                         {"label":"Catalog observation","value":table['observed_at'] or "Not available"},
                         {"label":"Columns","value":table['column_count']}],
                "section":"data","section_label":"Tables","detail":table}
        surfaces = _insert_surfaces(conn_factory, str(session['id']), turn_id, [{
            "kind":"inventory","title":title,"tool_name":"gallery_table_handoff",
            "tool_call_id":f"table-handoff:{turn_id}","lineage_key":table['ref'],
            "payload":{"mode":"system_inventory","items":[item],"summary":{"selected":1,"sections":["Tables"],"state_label":"Saved observations"},
                       "action":{"id":"system.inspect","title":title,"summary":item['summary'],"risk":"read_only","state":"ready"}},
            "source":{"origin":"gallery_tables","inventory_refs":[table['ref']]},"presentation":{"view":"system_inventory"}}])
        prompt = (question + "\n\nUse the pinned table " + table['qualified_name'] + " (" + table['ref'] +
                  "). Saved profiles and business context are dated observations, not live truth. Verify the current relation and relevant evidence before drawing conclusions. "
                  "A catalog observation time is not a data freshness timestamp; acceleration lag is distinct from schema or business drift.")
        return json_response({"url":"/calliope?"+urlencode({"session":str(session['id']),"surface":str(surfaces[0]['id']),"prompt":prompt})},201)

