    @mcp.custom_route("/api/calliope/gallery/jobs/ask", methods=["POST"])
    async def gallery_job_ask(request):
        owner, err = api_owner(request)
        if err:
            return err
        import gallery_jobs
        try:
            body = await request.json()
            job = (await asyncio.to_thread(gallery_jobs.snapshot, conn_factory, owner, body.get("ref") or "invalid"))["jobs"][0]
            question = str(body.get("question") or "Explain what this job does and whether its recent runs need attention.").strip()[:2000]
        except PermissionError as exc:
            return json_response({"error": {"message": str(exc)}}, 403)
        except LookupError as exc:
            return json_response({"error": {"message": str(exc)}}, 404)
        except (ValueError, AttributeError) as exc:
            return json_response({"error": {"message": str(exc)}}, 400)
        session = await _create_session_record(config, conn_factory, owner, f"Job · {job['name']}"[:120])
        turn_id = str(uuid.uuid4())
        with conn_factory() as conn:
            conn.execute("INSERT INTO rvbbit.calliope_turns(id,session_id,ordinal,user_message,assistant_message,status,completed_at,turn_kind) "
                         "VALUES(%s,%s,1,%s,%s,'complete',now(),'action')",
                         (turn_id,session['id'],f"Inspect job · {job['name']}","The job and recent run history are pinned. Ask Calliope what you would like to know or change."))
        item = {"ref":job['ref'],"kind":"mirror_job" if job['kind']=='mirror' else "workspace_job",
                "title":job['name'],"label":job['name'],"summary":job['description'],"state":"attention" if job['status']=='failed' else "ready",
                "facts":[{"label":"Status","value":job['status']},{"label":"Last success","value":job['last_success'] or "No successful runs yet"},
                         {"label":"Maintains","value":job['destinations']},{"label":"Next run","value":job['next_run_at'] or "Not scheduled"}],
                "section":"data","section_label":"Data jobs","detail":job}
        surfaces = _insert_surfaces(conn_factory, str(session['id']), turn_id, [{
            "kind":"inventory","title":f"Job · {job['name']}","tool_name":"gallery_job_handoff",
            "tool_call_id":f"job-handoff:{turn_id}","lineage_key":job['ref'],
            "payload":{"mode":"system_inventory","items":[item],"summary":{"selected":1,"sections":["Data jobs"],"state_label":job["status"],"needs_attention":int(job["status"]=="failed")},
                       "action":{"id":"system.inspect","title":job['name'],"summary":job['description'],"risk":"read_only","state":"ready"}},
            "source":{"origin":"gallery_jobs","inventory_refs":[job['ref']]},"presentation":{"view":"system_inventory"}}])
        prompt = (question + "\n\nUse the pinned job reference " + job['ref'] +
                  ". Its snapshot is context, not live state. Inspect the exact job and recent receipts before diagnosing or changing it. "
                  "SQL jobs run directly through the workspace worker; mirrors use the DLT controller. Do not substitute a Hermes Workflow. "
                  "Keep the existing execution owner; do not create a duplicate job in this new thread.")
        return json_response({"url":"/calliope?"+urlencode({"session":str(session['id']),"surface":str(surfaces[0]['id']),"prompt":prompt})},201)

