    @mcp.custom_route("/api/calliope/appearance", methods=["PUT"])
    async def put_calliope_appearance(request):
        owner, err = api_owner(request)
        if err:
            return err
        raw = await request.body()
        if len(raw) > 128 * 1024:
            return json_response({"error": {"code": "APPEARANCE_TOO_LARGE"}}, 413)
        try:
            body = json.loads(raw or b"{}")
            if not isinstance(body, dict):
                raise ValueError("appearance payload must be an object")
            mode = body.get("mode")
            if mode not in (None, "light", "dark"):
                raise ValueError("mode must be light, dark, or null to inherit")
            appearance = _normalize_appearance_preference(body.get("appearance"))
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
            return json_response({
                "error": {"code": "INVALID_APPEARANCE", "message": str(exc)[:400]}
            }, 400)
        source_kind = str((appearance or {}).get("source", {}).get("kind") or "")
        with conn_factory() as conn:
            if "appearance" not in body:
                row = conn.execute(
                    "UPDATE rvbbit.calliope_appearance_preferences SET color_mode=%s,updated_at=now() WHERE owner_email=%s "
                    "RETURNING color_mode,appearance,upload_bytes IS NOT NULL AS has_upload,updated_at",
                    (mode, owner),
                ).fetchone()
                if row is None:
                    row = conn.execute(
                        "INSERT INTO rvbbit.calliope_appearance_preferences(owner_email,color_mode) VALUES(%s,%s) "
                        "ON CONFLICT(owner_email) DO UPDATE SET color_mode=excluded.color_mode,updated_at=now() "
                        "RETURNING color_mode,appearance,upload_bytes IS NOT NULL AS has_upload,updated_at",
                        (owner, mode),
                    ).fetchone()
                return json_response(_appearance_response_payload(row))
            row = conn.execute(
                "INSERT INTO rvbbit.calliope_appearance_preferences "
                "(owner_email,color_mode,appearance,updated_at) VALUES (%s,%s,%s::jsonb,now()) "
                "ON CONFLICT (owner_email) DO UPDATE SET color_mode=EXCLUDED.color_mode,"
                "appearance=EXCLUDED.appearance,updated_at=now() "
                "RETURNING color_mode,appearance,upload_bytes IS NOT NULL AS has_upload,updated_at",
                (owner, mode, json.dumps(appearance) if appearance is not None else None),
            ).fetchone()
            if source_kind != "upload":
                row = conn.execute(
                    "UPDATE rvbbit.calliope_appearance_preferences SET upload_name=NULL,"
                    "upload_mime=NULL,upload_bytes=NULL WHERE owner_email=%s "
                    "RETURNING color_mode,appearance,false AS has_upload,updated_at",
                    (owner,),
                ).fetchone()
        return json_response(_appearance_response_payload(row or {
            "appearance": appearance,
            "color_mode": mode,
        }))

