    @mcp.custom_route("/api/calliope/appearance/image", methods=["PUT"])
    async def put_calliope_appearance_image(request):
        owner, err = api_owner(request)
        if err:
            return err
        mime = str(request.headers.get("content-type") or "").split(";", 1)[0].lower()
        if mime not in _APPEARANCE_UPLOAD_MIMES:
            return json_response({"error": {"code": "UNSUPPORTED_APPEARANCE_IMAGE"}}, 415)
        raw = await request.body()
        if not raw or len(raw) > min(config.max_image_bytes, 20 * 1024 * 1024):
            return json_response({"error": {"code": "APPEARANCE_IMAGE_TOO_LARGE"}}, 413)
        name = unquote(str(request.headers.get("x-rvbbit-filename") or "wallpaper"))
        name = re.sub(r"[\x00-\x1f\x7f]", "", name).strip()[:240] or "wallpaper"
        with conn_factory() as conn:
            conn.execute(
                "INSERT INTO rvbbit.calliope_appearance_preferences "
                "(owner_email,color_mode,upload_name,upload_mime,upload_bytes,updated_at) "
                "VALUES (%s,NULL,%s,%s,%s,now()) ON CONFLICT (owner_email) DO UPDATE SET "
                "upload_name=EXCLUDED.upload_name,upload_mime=EXCLUDED.upload_mime,"
                "upload_bytes=EXCLUDED.upload_bytes,updated_at=now()",
                (owner, name, mime, raw),
            )
        return json_response({"ok": True, "name": name, "mime": mime, "bytes": len(raw)})

