    @mcp.custom_route("/api/calliope/generated-images/{image_id}", methods=["GET"])
    async def calliope_generated_image(request):
        owner, err = api_owner(request)
        if err:
            return Response(status_code=404)
        image_id = _uuid(request.path_params.get("image_id"))
        if not image_id:
            return Response(status_code=404)

        def _load():
            with conn_factory() as conn:
                ready = conn.execute(
                    "SELECT to_regclass('rvbbit.generated_images') IS NOT NULL AS r"
                ).fetchone()
                if not (ready and ready["r"]):
                    return None
                row = conn.execute(
                    "SELECT png FROM rvbbit.generated_images WHERE id=%s::uuid",
                    (image_id,),
                ).fetchone()
            return bytes(row["png"]) if row else None

        png = await asyncio.to_thread(_load)
        if not png:
            return Response(status_code=404)
        import expert_portraits
        return Response(
            png,
            media_type=expert_portraits.image_media_type(png),
            headers={
                "cache-control": "private, max-age=86400",
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route("/api/calliope/expert-portraits", methods=["GET", "PATCH"])
    async def calliope_expert_portraits(request):
        owner, err = api_owner(request)
        if err:
            return err

        def _read():
            import expert_portraits
            with conn_factory() as conn:
                row = conn.execute(
                    "SELECT value FROM rvbbit.settings WHERE key='expert_portraits'"
                ).fetchone()
                value = (row or {}).get("value") if row else None
                value = value if isinstance(value, dict) else {}
                resolved = expert_portraits._config(conn) is not None
                counts = conn.execute(
                    "SELECT count(*) FILTER (WHERE a.specialist_key IS NOT NULL) AS have, "
                    "count(*) FILTER (WHERE a.specialist_key IS NULL) AS missing "
                    "FROM rvbbit.generated_specialists g "
                    "LEFT JOIN rvbbit.generated_specialist_avatars a USING (specialist_key) "
                    "WHERE g.status='active'"
                ).fetchone() if conn.execute(
                    "SELECT to_regclass('rvbbit.generated_specialist_avatars') IS NOT NULL AS r"
                ).fetchone()["r"] else {"have": 0, "missing": 0}
                status_row = conn.execute(
                    "SELECT value FROM rvbbit.settings WHERE key='expert_portraits_status'"
                ).fetchone()
                last_run = (status_row or {}).get("value") if status_row else None
            return {
                "config": {
                    "model": value.get("model"),
                    "base_url": value.get("base_url"),
                    "api_key_env": value.get("api_key_env"),
                },
                "resolved": resolved,
                "portraits": int(counts["have"] or 0),
                "missing": int(counts["missing"] or 0),
                "last_run": last_run if isinstance(last_run, dict) else None,
            }

        if request.method == "GET":
            return json_response(await asyncio.to_thread(_read))

        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        model = body.get("model")
        base_url = body.get("base_url")
        api_key_env = body.get("api_key_env")
        if model is not None and (not isinstance(model, str) or len(model) > 200):
            return json_response({"error": {"code": "INVALID_MODEL"}}, 400)
        if base_url not in (None, "") and str(base_url).strip().lower() != "hermes" \
                and not re.fullmatch(r"https?://[^\s]{1,300}", str(base_url)):
            return json_response({"error": {"code": "INVALID_BASE_URL"}}, 400)
        if api_key_env not in (None, "") and not re.fullmatch(
            r"[A-Z][A-Z0-9_]{0,63}", str(api_key_env)
        ):
            return json_response({"error": {"code": "INVALID_KEY_ENV"}}, 400)
        # A vendor/model slug with no endpoint would post to the default
        # Clover proxy, which serves none of them — the lane then 404s every
        # factory cycle (pilot, 2026-09-08). Refuse at save time instead.
        if "/" in str(model or "") and not str(base_url or "").strip():
            return json_response({"error": {
                "code": "PROVIDER_SLUG_NEEDS_ENDPOINT",
                "message": "That model id is provider-routed (vendor/model). "
                           "Set the endpoint it lives on (e.g. "
                           "https://openrouter.ai/api/v1) or 'hermes' to ride "
                           "the Hermes agent's own image tool — with no "
                           "endpoint it would post to the Clover proxy, which "
                           "doesn't serve it.",
            }}, 400)

        def _write():
            with conn_factory() as conn:
                conn.execute(
                    "INSERT INTO rvbbit.settings (key, value, updated_at) "
                    "VALUES ('expert_portraits', %s::jsonb, now()) "
                    "ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=now()",
                    (json.dumps({
                        "model": (model or "").strip() or None,
                        "base_url": (base_url or "").strip() or None,
                        "api_key_env": (api_key_env or "").strip() or None,
                    }),),
                )
            return _read()

        return json_response(await asyncio.to_thread(_write))

