    @mcp.custom_route("/api/calliope/generated-specialists", methods=["GET"])
    async def calliope_generated_specialists(request):
        # Internal: the Hermes specialist reconciler synthesizes profiles for
        # factory-generated domain experts from these rows. Same auth as the
        # agent-overlays feed.
        import auth
        supplied = (request.headers.get("authorization") or "")
        supplied = supplied[7:] if supplied.lower().startswith("bearer ") else ""
        if not auth.HERMES_KEY or not hmac.compare_digest(supplied, auth.HERMES_KEY):
            return json_response({"error": {"code": "FORBIDDEN"}}, 403)

        def _load_generated():
            with conn_factory() as conn:
                ready = conn.execute(
                    "SELECT to_regclass('rvbbit.generated_specialists') IS NOT NULL AS ready"
                ).fetchone()
                if not (ready and ready["ready"]):
                    return {"specialists": [], "retired": []}
                has_avatars = conn.execute(
                    "SELECT to_regclass('rvbbit.generated_specialist_avatars')"
                    " IS NOT NULL AS r"
                ).fetchone()["r"]
                avatar_join = (
                    "LEFT JOIN rvbbit.generated_specialist_avatars a USING (specialist_key) "
                    if has_avatars else ""
                )
                avatar_col = (
                    "CASE WHEN a.specialist_key IS NOT NULL THEN "
                    "'generated-'||g.specialist_key||'.png' END AS avatar_file, "
                    if has_avatars else "NULL AS avatar_file, "
                )
                rows = conn.execute(
                    "SELECT g.specialist_key, g.display_name, g.role_label, g.description, "
                    f"g.soul_markdown, g.memory_mission, g.skills, g.soul_version, {avatar_col}"
                    "g.updated_at::text "
                    f"FROM rvbbit.generated_specialists g {avatar_join}"
                    "WHERE g.status='active' ORDER BY g.specialist_key"
                ).fetchall()
                # Keys the table knows but no longer serves. The reconciler
                # archives their profile directories out of the served tree;
                # a key absent from BOTH lists is an operator's own profile
                # and is never touched.
                retired = conn.execute(
                    "SELECT specialist_key FROM rvbbit.generated_specialists "
                    "WHERE status IS DISTINCT FROM 'active' ORDER BY specialist_key"
                ).fetchall()
            return {
                "specialists": [dict(row) for row in rows],
                "retired": [str(row["specialist_key"]) for row in retired],
            }

        try:
            result = await asyncio.to_thread(_load_generated)
        except Exception as exc:
            return json_response({
                "error": {"code": "GENERATED_SPECIALISTS_FAILED", "message": str(exc)[:300]}
            }, 500)
        return json_response(result)

    @mcp.custom_route("/api/calliope/agent-overlays", methods=["GET"])
    async def calliope_agent_overlays(request):
        # Internal: the Hermes specialist reconciler composes learned overlay
        # blocks beneath repo-baseline SOUL/SKILL files. Authenticated with
        # the first-party Hermes key the caller already holds.
        import auth
        supplied = (request.headers.get("authorization") or "")
        supplied = supplied[7:] if supplied.lower().startswith("bearer ") else ""
        if not auth.HERMES_KEY or not hmac.compare_digest(supplied, auth.HERMES_KEY):
            return json_response({"error": {"code": "FORBIDDEN"}}, 403)

        def _load_overlays():
            with conn_factory() as conn:
                ready = conn.execute(
                    "SELECT to_regclass('rvbbit.agent_overlays_active') IS NOT NULL AS ready"
                ).fetchone()
                if not (ready and ready["ready"]):
                    return {"overlays": []}
                rows = conn.execute(
                    "SELECT overlay_id::text, agent_key, target_kind, target_key, "
                    "section, body, kind, updated_at::text "
                    "FROM rvbbit.agent_overlays_active"
                ).fetchall()
            return {"overlays": [dict(row) for row in rows]}

        try:
            result = await asyncio.to_thread(_load_overlays)
        except Exception as exc:
            return json_response({
                "error": {"code": "OVERLAYS_FAILED", "message": str(exc)[:300]}
            }, 500)
        return json_response(result)

