    @mcp.custom_route("/api/calliope/team/{agent_key}/voice", methods=["POST"])
    async def preview_team_voice(request):
        owner, err = api_owner(request)
        if err:
            return err
        if not config.voice_enabled:
            return json_response({"error": {"message": "Spoken responses are not configured."}}, 503)
        agents = await configured_chat_agents()
        agent = next((a for a in agents if a["key"] == request.path_params["agent_key"]), None)
        if not agent:
            return json_response({"error": {"message": "That team member is unavailable."}}, 404)
        try:
            raw = await request.body()
            if len(raw) > 4096:
                raise ValueError("Speech persona is too long.")
            body = json.loads(raw or b"{}")
            if not isinstance(body, dict):
                raise ValueError("Expected a speech persona object.")
            if "personality" in body:
                if not isinstance(body["personality"], str) or len(body["personality"]) > 600:
                    raise ValueError("Use at most 600 characters for your speech persona.")
                personality = _clean_voice_personality(body["personality"])
                if not personality:
                    personality = await asyncio.to_thread(_profile_speech_persona, conn_factory, agent["key"])
            else:
                personality = await asyncio.to_thread(_agent_speech_persona, conn_factory, owner, agent["key"])
        except (ValueError, UnicodeDecodeError) as exc:
            return json_response({"error": {"message": str(exc)}}, 400)
        async def open_preview():
            script = await asyncio.to_thread(_prepare_agent_voice_preview, conn_factory, config, owner, agent, personality)
            profile = await asyncio.to_thread(_voice_synthesis_profile, config, "expressive")
            primary = next((a for a in agents if a.get("primary")), {})
            voice = _effective_tts_voice(config, profile,
                hermes_profiles.clean_voice_id(agent.get("voice_id")) or hermes_profiles.clean_voice_id(primary.get("voice_id")))
            render = {"script": script,
                      "mode": "expressive", "tts_profile": profile, "tts_voice": voice,
                      "tts_model": profile.get("upstream_model") or config.voice_expressive_model,
                      "sample_rate": int(profile.get("sample_rate") or config.voice_sample_rate)}
            client, upstream = await _open_voice_provider_stream(config, render)
            return render, client, upstream
        try:
            render, client, upstream = await asyncio.wait_for(open_preview(), timeout=config.voice_prepare_timeout_seconds)
        except (TimeoutError, VoiceProviderError, ValueError) as exc:
            message = str(exc) if isinstance(exc, (VoiceProviderError, ValueError)) else "The voice preview timed out. Try again."
            return json_response({"error": {"message": message}}, 503)

        async def preview_stream():
            written = 0
            rate = render["sample_rate"]
            try:
                async with asyncio.timeout(90):
                    async for audio, alignment in _voice_provider_frames(config, upstream):
                        if not audio:
                            continue
                        if len(audio) % 2:
                            raise ValueError("The speech provider returned incomplete audio.")
                        offset = written / (rate * 2)
                        written += len(audio)
                        if written > min(config.max_voice_audio_bytes, rate * 2 * 30):
                            raise ValueError("Voice preview exceeded its duration limit.")
                        yield _voice_stream_line(audio, audio_offset_seconds=offset, alignment=alignment)
                    if not written:
                        raise ValueError("The speech provider returned no playable audio.")
            except (TimeoutError, VoiceProviderError, ValueError) as exc:
                yield _voice_stream_error(str(exc) or "The voice preview timed out.", "VOICE_PREVIEW_FAILED")
            finally:
                await upstream.aclose()
                await client.aclose()

        return StreamingResponse(preview_stream(), media_type="application/x-ndjson", headers={
            "cache-control": "no-store", "x-content-type-options": "nosniff",
            "x-audio-format": "s16le", "x-audio-sample-rate": str(render["sample_rate"]),
            "x-calliope-audio-protocol": _VOICE_STREAM_PROTOCOL,
        })

    @mcp.custom_route("/api/calliope/voice/renders", methods=["POST"])
    async def create_calliope_voice_render(request):
        owner, err = api_owner(request)
        if err:
            return err
        if not (config.enabled or config.voice_enabled):
            return json_response({
                "error": {
                    "code": "PRESENTATION_UNAVAILABLE",
                    "message": "Conversational answers are not configured for this installation.",
                }
            }, 503)
        try:
            content_length = int(request.headers.get("content-length") or 0)
        except (TypeError, ValueError):
            content_length = 0
        if content_length > 32 * 1024:
            return json_response({
                "error": {
                    "code": "VOICE_REQUEST_TOO_LARGE",
                    "message": "That presentation preference is too large.",
                }
            }, 413)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        render_started = time.monotonic()
        try:
            render, reused = await asyncio.wait_for(
                asyncio.to_thread(
                    _voice_render,
                    conn_factory,
                    config,
                    owner,
                    body.get("session_id"),
                    body.get("turn_id"),
                    body.get("mode"),
                    body.get("personality"),
                    {
                        "agent_key": body.get("tuning_agent_key"),
                        "queued_after_turn_id": body.get("queued_after_turn_id"),
                        "voice_id": body.get("voice_id"),
                        "direction": body.get("direction"),
                        "regenerate": body.get("regenerate") is True,
                        "respeak": body.get("respeak") is True,
                    },
                ),
                timeout=config.voice_prepare_timeout_seconds,
            )
            # One line per render request: the forensic trail for "why did it speak twice".
            print(
                "INFO: voice render "
                f"turn={str(body.get('turn_id') or '')[:36]} mode={str(body.get('mode') or '')[:16]} "
                f"reused={'yes' if reused else 'no'} render={str(render.get('id') or '')[:36]} "
                f"script_chars={len(str(render.get('script') or ''))} "
                f"memory={str((render.get('presentation_memory') or {}).get('recall_status') or '-')} "
                f"ms={round((time.monotonic() - render_started) * 1000)}",
                file=os.sys.stderr,
            )
        except TimeoutError:
            print(
                "WARNING: Calliope conversational presentation rewrite timed out",
                file=os.sys.stderr,
            )
            return json_response({
                "error": {
                    "code": "VOICE_TEXT_TIMEOUT",
                    "stage": "text",
                    "message": (
                        "The conversational rewrite took too long. "
                        "Showing the complete answer instead."
                    ),
                }
            }, 504)
        except VoiceProviderError as exc:
            return json_response({"error": {"code": exc.code, "stage": "audio", "message": str(exc)}}, 503)
        except LookupError as exc:
            return json_response({
                "error": {"code": "VOICE_TURN_NOT_FOUND", "message": str(exc)}
            }, 404)
        except ValueError as exc:
            return json_response({
                "error": {"code": "VOICE_REQUEST_INVALID", "message": str(exc)}
            }, 400)
        except Exception as exc:
            print(f"WARNING: Calliope presentation render failed: {exc}", file=os.sys.stderr)
            return json_response({
                "error": {
                    "code": "VOICE_RENDER_FAILED",
                    "stage": "text",
                    "message": "Calliope could not prepare that conversational answer.",
                }
            }, 502)
        render_id = quote(str(render["id"]), safe="")
        turn_id = quote(str(body.get("turn_id") or ""), safe="")
        return json_response({
            "render": render,
            "reused": reused,
            "takes": _voice_takes_for_turn(conn_factory, owner, body.get("turn_id")),
            "audio_url": (
                f"/api/calliope/voice/turns/{turn_id}/audio?render={render_id}"
                if config.voice_enabled else None
            ),
        }, 200 if reused else 201)

    @mcp.custom_route("/api/calliope/voice/progress", methods=["POST"])
    async def stream_calliope_progress_voice(request):
        """Rewrite one in-turn progress update in persona, keep it for this person, and
        stream it as speech, or return only the words when they are not listening
        ("audio": false)."""
        owner, err = api_owner(request)
        if err:
            return err
        try:
            peek = json.loads(await request.body() or b"{}")
        except Exception:
            peek = {}
        text_only = isinstance(peek, dict) and peek.get("audio") is False
        if not (config.voice_enabled or (text_only and config.enabled)):
            return json_response({
                "error": {
                    "code": "VOICE_UNAVAILABLE",
                    "message": "Spoken responses are not configured for this installation.",
                }
            }, 503)
        try:
            content_length = int(request.headers.get("content-length") or 0)
        except (TypeError, ValueError):
            content_length = 0
        if content_length > 256 * 1024:
            return json_response({
                "error": {
                    "code": "VOICE_REQUEST_TOO_LARGE",
                    "message": "That working update is too large to speak.",
                }
            }, 413)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        try:
            render = await asyncio.wait_for(
                asyncio.to_thread(
                    _voice_progress_render,
                    conn_factory,
                    config,
                    owner,
                    body.get("session_id"),
                    body.get("turn_id"),
                    body.get("text"),
                    body.get("mode"),
                    body.get("personality"),
                    body.get("prior_scripts"),
                ),
                timeout=config.voice_prepare_timeout_seconds,
            )
        except TimeoutError:
            return json_response({
                "error": {
                    "code": "VOICE_TEXT_TIMEOUT",
                    "stage": "text",
                    "message": "That spoken working update took too long to prepare.",
                }
            }, 504)
        except VoiceProviderError as exc:
            return json_response({"error": {"code": exc.code, "stage": "audio", "message": str(exc)}}, 503)
        except LookupError as exc:
            return json_response({
                "error": {"code": "VOICE_TURN_NOT_FOUND", "message": str(exc)}
            }, 404)
        except ValueError as exc:
            return json_response({
                "error": {"code": "VOICE_REQUEST_INVALID", "message": str(exc)}
            }, 400)
        except Exception as exc:
            print(f"WARNING: Calliope progress voice render failed: {exc}", file=os.sys.stderr)
            return json_response({
                "error": {
                    "code": "VOICE_RENDER_FAILED",
                    "stage": "text",
                    "message": "Calliope could not prepare that spoken working update.",
                }
            }, 502)
        try:
            await asyncio.to_thread(_save_take_note, conn_factory, owner, body.get("turn_id"),
                                    body.get("text"), render.get("script"))
        except Exception as exc:  # noqa: BLE001 - the note still shows now, just not after a reload
            print(f"WARNING: take note not kept: {type(exc).__name__}: {exc}", file=os.sys.stderr)
        if text_only:
            response = json_response({"script": str(render.get("script") or "")})
            response.headers["cache-control"] = "no-store"
            return response
        try:
            client, upstream = await asyncio.wait_for(
                _open_voice_provider_stream(config, render),
                timeout=config.voice_prepare_timeout_seconds,
            )
        except TimeoutError:
            return json_response({
                "error": {
                    "code": "VOICE_AUDIO_TIMEOUT",
                    "stage": "audio",
                    "message": "Audio generation did not start in time.",
                }
            }, 504)
        except VoiceProviderError as exc:
            status = 503 if exc.code in {
                "VOICE_UNAVAILABLE", "VOICE_PROVIDER_UNAVAILABLE", "VOICE_RATE_LIMITED",
            } else 502
            return json_response({
                "error": {"code": exc.code, "stage": "audio", "message": str(exc)[:400]}
            }, status)

        async def progress_audio_stream() -> AsyncIterator[bytes]:
            written = 0
            try:
                yield (
                    json.dumps(
                        {"type": "metadata", "script": str(render.get("script") or "")},
                        separators=(",", ":"),
                    )
                    + "\n"
                ).encode("utf-8")
                provider_frames = _voice_provider_frames(config, upstream).__aiter__()
                while True:
                    try:
                        audio, alignment = await anext(provider_frames)
                    except StopAsyncIteration:
                        break
                    if not audio:
                        continue
                    if len(audio) % 2:
                        raise VoiceProviderError(
                            "The voice provider returned malformed PCM audio.",
                            "VOICE_PROVIDER_STREAM_INVALID",
                        )
                    offset = written / (int(render.get("sample_rate") or config.voice_sample_rate) * 2)
                    written += len(audio)
                    if written > config.max_voice_audio_bytes:
                        raise VoiceProviderError(
                            "The generated spoken update was unexpectedly large.",
                            "VOICE_AUDIO_TOO_LARGE",
                        )
                    yield _voice_stream_line(
                        audio,
                        audio_offset_seconds=offset,
                        alignment=alignment,
                    )
                if not written:
                    yield _voice_stream_error(
                        "The voice provider returned no playable audio.",
                        "VOICE_PROVIDER_STREAM_EMPTY",
                    )
            except VoiceProviderError as exc:
                yield _voice_stream_error(str(exc), exc.code)
            finally:
                await upstream.aclose()
                await client.aclose()

        return StreamingResponse(
            progress_audio_stream(),
            media_type="application/x-ndjson",
            headers={
                "cache-control": "no-store",
                "x-content-type-options": "nosniff",
                "x-audio-format": "s16le",
                "x-audio-sample-rate": str(int(render.get("sample_rate") or config.voice_sample_rate)),
                "x-calliope-voice-mode": str(render.get("mode") or "fast"),
                "x-calliope-audio-protocol": _VOICE_STREAM_PROTOCOL,
            },
        )

    @mcp.custom_route(
        "/api/calliope/voice/turns/{turn_id}/audio", methods=["GET"]
    )
    async def stream_calliope_voice_audio(request):
        owner, err = api_owner(request)
        if err:
            return err
        if not config.voice_enabled:
            return json_response({
                "error": {
                    "code": "VOICE_UNAVAILABLE",
                    "message": "Spoken responses are not configured for this installation.",
                }
            }, 503)
        try:
            render = await asyncio.wait_for(
                asyncio.to_thread(
                    _voice_render_for_audio,
                    conn_factory,
                    owner,
                    request.path_params.get("turn_id"),
                    request.query_params.get("render"),
                    config.voice_prepare_timeout_seconds,
                ),
                timeout=config.voice_prepare_timeout_seconds,
            )
        except TimeoutError:
            return json_response({
                "error": {
                    "code": "VOICE_AUDIO_TIMEOUT",
                    "stage": "audio",
                    "message": "Audio generation did not start in time.",
                }
            }, 504)
        except VoiceProviderError as exc:
            return json_response({"error": {"code": exc.code, "stage": "audio", "message": str(exc)}}, 503)
        except LookupError as exc:
            return json_response({
                "error": {"code": "VOICE_RENDER_NOT_FOUND", "message": str(exc)}
            }, 404)

        cache_path = _voice_cache_path(config, render)
        timing_path = _voice_timing_cache_path(cache_path)
        try:
            cache_size = cache_path.stat().st_size
        except OSError:
            cache_size = 0
        cached_frames = (
            _read_voice_timing_cache(
                timing_path,
                audio_size=cache_size,
                sample_rate=int(render.get("sample_rate") or config.voice_sample_rate),
            )
            if 0 < cache_size <= config.max_voice_audio_bytes and cache_size % 2 == 0
            else None
        )
        # One take speaks at a time per person (their tabs); room members each hear their own.
        lease_turn = f"{str(owner).lower()}\0{request.path_params.get('turn_id') or ''}"
        automatic_play = str(request.query_params.get("auto") or "") == "1"
        holder = _voice_take_lease_conflict(lease_turn, str(render.get("id") or ""), automatic_play)
        if holder:
            print(
                f"INFO: voice audio refused turn={str(request.path_params.get('turn_id') or '')[:36]} render={str(render.get('id') or '')[:36]} "
                f"automatic play while take {holder[:36]} is speaking",
                file=os.sys.stderr,
            )
            return json_response({"error": {
                "code": "VOICE_TAKE_PLAYING", "stage": "audio",
                "message": "Another take of this answer is already being spoken.",
            }}, 409)
        lease_rate = int(render.get("sample_rate") or config.voice_sample_rate) * 2
        _voice_take_lease_set(
            lease_turn, str(render.get("id") or ""),
            (cache_size / lease_rate + 2.0) if cached_frames is not None and cache_size else _VOICE_TAKE_LEASE_DEFAULT_SECONDS,
        )
        print(
            "INFO: voice audio "
            f"turn={str(render.get('turn_id') or request.path_params.get('turn_id') or '')[:36]} "
            f"render={str(render.get('id') or '')[:36]} mode={str(render.get('mode') or '')[:16]} "
            f"source={'cache' if cached_frames is not None else 'synthesize'} bytes={cache_size}"
            f"{' auto' if automatic_play else ''}",
            file=os.sys.stderr,
        )
        audio_headers = {
            "cache-control": "private, max-age=86400",
            "x-content-type-options": "nosniff",
            "x-audio-format": "s16le",
            "x-audio-sample-rate": str(int(render.get("sample_rate") or config.voice_sample_rate)),
            "x-calliope-voice-mode": str(render.get("mode") or "fast"),
            "x-calliope-audio-protocol": _VOICE_STREAM_PROTOCOL,
        }

        if cached_frames:
            async def cached_audio_stream() -> AsyncIterator[bytes]:
                with cache_path.open("rb") as handle:
                    for frame in cached_frames:
                        audio = handle.read(frame["byte_length"])
                        if len(audio) != frame["byte_length"]:
                            yield _voice_stream_error(
                                "The cached spoken response was incomplete.",
                                "VOICE_CACHE_INVALID",
                            )
                            return
                        yield _voice_stream_line(
                            audio,
                            audio_offset_seconds=frame["audio_offset_seconds"],
                            alignment=frame.get("alignment"),
                        )

            return StreamingResponse(
                cached_audio_stream(),
                media_type="application/x-ndjson",
                headers=audio_headers,
            )

        try:
            client, upstream = await asyncio.wait_for(
                _open_voice_provider_stream(config, render),
                timeout=config.voice_prepare_timeout_seconds,
            )
        except TimeoutError:
            print(
                "WARNING: Calliope voice provider connection timed out",
                file=os.sys.stderr,
            )
            return json_response({
                "error": {
                    "code": "VOICE_AUDIO_TIMEOUT",
                    "stage": "audio",
                    "message": "Audio generation did not start in time.",
                }
            }, 504)
        except VoiceProviderError as exc:
            status = 503 if exc.code in {
                "VOICE_UNAVAILABLE",
                "VOICE_PROVIDER_UNAVAILABLE",
                "VOICE_RATE_LIMITED",
            } else 502
            return json_response({
                "error": {
                    "code": exc.code,
                    "stage": "audio",
                    "message": str(exc)[:400],
                }
            }, status)

        cache_path.parent.mkdir(parents=True, exist_ok=True)
        stream_started = time.monotonic()
        temporary = cache_path.with_name(
            f".{cache_path.name}.{uuid.uuid4().hex}.part"
        )
        timing_temporary = timing_path.with_name(
            f".{timing_path.name}.{uuid.uuid4().hex}.part"
        )

        async def audio_stream() -> AsyncIterator[bytes]:
            written = 0
            complete = False
            frames: list[dict[str, Any]] = []
            first_audio_deadline = (
                time.monotonic() + config.voice_prepare_timeout_seconds
            )
            try:
                with temporary.open("wb") as handle:
                    provider_frames = _voice_provider_frames(config, upstream).__aiter__()
                    while True:
                        try:
                            if written:
                                audio, alignment = await anext(provider_frames)
                            else:
                                remaining = first_audio_deadline - time.monotonic()
                                if remaining <= 0:
                                    raise TimeoutError
                                audio, alignment = await asyncio.wait_for(
                                    anext(provider_frames),
                                    timeout=remaining,
                                )
                        except StopAsyncIteration:
                            break
                        if not audio:
                            continue
                        if len(audio) % 2:
                            raise VoiceProviderError(
                                "The voice provider returned malformed PCM audio.",
                                "VOICE_PROVIDER_STREAM_INVALID",
                            )
                        offset = written / (int(render.get("sample_rate") or config.voice_sample_rate) * 2)
                        written += len(audio)
                        if written > config.max_voice_audio_bytes:
                            raise VoiceProviderError(
                                "The generated spoken response was unexpectedly large.",
                                "VOICE_AUDIO_TOO_LARGE",
                            )
                        handle.write(audio)
                        frames.append({
                            "byte_length": len(audio),
                            "audio_offset_seconds": round(offset, 6),
                            "alignment": alignment,
                        })
                        yield _voice_stream_line(
                            audio,
                            audio_offset_seconds=offset,
                            alignment=alignment,
                        )
                complete = written > 0 and written % 2 == 0
                if not complete:
                    yield _voice_stream_error(
                        "The voice provider returned no playable audio.",
                        "VOICE_PROVIDER_STREAM_EMPTY",
                    )
            except VoiceProviderError as exc:
                request_id = str(
                    upstream.headers.get("request-id")
                    or upstream.headers.get("x-request-id")
                    or ""
                )[:160]
                print(
                    "WARNING: Speech provider stream failed: "
                    f"code={exc.code} request_id={request_id or '-'} detail={exc}",
                    file=os.sys.stderr,
                )
                yield _voice_stream_error(str(exc), exc.code)
            except TimeoutError:
                print(
                    "WARNING: Calliope voice provider produced no audio before timeout",
                    file=os.sys.stderr,
                )
                yield _voice_stream_error(
                    "Audio generation did not start in time.",
                    "VOICE_AUDIO_TIMEOUT",
                )
            finally:
                await upstream.aclose()
                await client.aclose()
                if complete:
                    timing_temporary.write_text(
                        json.dumps(
                            {
                                "protocol": _VOICE_STREAM_PROTOCOL,
                                "sample_rate": int(render.get("sample_rate") or config.voice_sample_rate),
                                "frames": frames,
                            },
                            separators=(",", ":"),
                        ),
                        encoding="utf-8",
                    )
                    _voice_take_lease_set(lease_turn, str(render.get("id") or ""), written / lease_rate + 2.0 - max(0.0, time.monotonic() - stream_started))
                    os.replace(temporary, cache_path)
                    os.replace(timing_temporary, timing_path)
                else:
                    temporary.unlink(missing_ok=True)
                    timing_temporary.unlink(missing_ok=True)

        return StreamingResponse(
            audio_stream(),
            media_type="application/x-ndjson",
            headers=audio_headers,
        )

