    @mcp.custom_route(
        "/api/calliope/actions/{action_id}/execute", methods=["POST"]
    )
    async def administer_calliope_action_native(request):
        """Apply and verify a typed local administration action in one native submit."""
        owner, err = api_owner(request)
        if err:
            return err
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        secure_surface_id = body.get("surface_id")
        if secure_surface_id:
            import connection_workflow
            try:
                result, status = await connection_workflow.execute(conn_factory, owner, request.path_params["action_id"], body)
            except PermissionError as exc:
                return json_response({"error": {"code": "ACTION_ADMIN_REQUIRED", "message": str(exc)}}, 403)
            except (ValueError, LookupError) as exc:
                return json_response({"error": {"code": "BAD_ACTION_INPUT", "message": str(exc)}}, 400)
            return json_response(result, status)
        try:
            result = await administer_action_with_secure_inputs(
                conn_factory,
                owner,
                request.path_params["action_id"],
                body.get("inputs"),
                body.get("session_id"),
            )
        except LookupError as exc:
            return json_response(
                {"error": {"code": "ACTION_NOT_FOUND", "message": str(exc)}}, 404
            )
        except PermissionError as exc:
            return json_response(
                {"error": {"code": "ACTION_ADMIN_REQUIRED", "message": str(exc)}}, 403
            )
        except ValueError as exc:
            run_id = getattr(exc, "action_run_id", None)
            payload: dict[str, Any] = {
                "error": {"code": "BAD_ACTION_INPUT", "message": str(exc)}
            }
            if run_id:
                payload["run"] = _action_run_for_owner(conn_factory, owner, run_id)
            _resolve_secure_action_surface(
                conn_factory,
                owner,
                secure_surface_id,
                request.path_params["action_id"],
                payload,
            )
            return json_response(payload, 400)
        except Exception as exc:
            run_id = getattr(exc, "action_run_id", None)
            payload = {
                "error": {
                    "code": "ACTION_EXECUTION_FAILED",
                    "message": _action_error_text(exc)[:1200],
                }
            }
            if run_id:
                payload["run"] = _action_run_for_owner(conn_factory, owner, run_id)
            _resolve_secure_action_surface(
                conn_factory,
                owner,
                secure_surface_id,
                request.path_params["action_id"],
                payload,
            )
            return json_response(payload, 502)
        _resolve_secure_action_surface(
            conn_factory,
            owner,
            secure_surface_id,
            request.path_params["action_id"],
            result,
        )
        return json_response(result, 200)

