    @mcp.custom_route("/api/calliope/floor/answerable", methods=["GET"])
    async def floor_answerable_index(request):
        # The Floor composer's answerable index: metrics plus the words that
        # reach them. Cached two minutes server-side; the browser matches locally.
        owner, err = api_owner(request)
        if err:
            return err
        try:
            payload = await asyncio.to_thread(_floor_answerable_index, conn_factory)
        except Exception as exc:
            return json_response({
                "error": {"code": "FLOOR_ANSWERABLE_FAILED", "message": str(exc)[:600]}
            }, 502)
        # Artifacts are viewer-scoped and only the chat composer's rail stages
        # them, so the Floor keeps asking for the cacheable metric-only payload.
        if str(request.query_params.get("artifacts") or "").strip() in {"1", "true", "yes"}:
            try:
                artifacts = await asyncio.to_thread(_composer_artifact_index, conn_factory, owner)
            except Exception:  # noqa: BLE001 - suggestions degrade, they do not fail
                artifacts = []
            payload = {**payload, "artifacts": artifacts}
        return json_response(payload)

