    def _desk_rows(sql: str, params: tuple = ()) -> list[dict[str, Any]]:
        """One defensive query: a missing table (fresh box, mirror not yet
        run) degrades to an empty section, never a 500."""
        try:
            with conn_factory() as conn:
                return [dict(row) for row in conn.execute(sql, params).fetchall()]
        except Exception:  # noqa: BLE001
            return []

    def _desk_iso(value: Any) -> str | None:
        return value.isoformat() if hasattr(value, "isoformat") else (str(value) if value else None)

    # ── The Floor — a read-only Work Graph hub ─────────────────────────
    # This began as the the-floor-live-prototype artifact. The built-in page
    # keeps its presentation and time lens, but replaces the live-app SQL
    # bridge with fixed, authenticated Calliope projections.

    floor_visibility_sql = """
        (
            w.owner_email IS NULL
            OR lower(w.owner_email) = lower(%s)
            OR (
                w.item_kind = 'chat'
                AND EXISTS (
                    SELECT 1
                    FROM rvbbit.calliope_sessions visible_session
                    WHERE visible_session.id::text = split_part(w.item_id, ':', 2)
                      AND rvbbit.calliope_session_can_view(
                          visible_session.id, %s, false
                      )
                )
            )
            OR (
                -- Approved playbooks published to everyone (factory canon,
                -- deliberately shared SOPs) are shared furniture: every
                -- Floor shows them in Standing regardless of owner.
                w.item_kind = 'playbook'
                AND EXISTS (
                    SELECT 1
                    FROM rvbbit.calliope_playbooks everyone_pb
                    JOIN rvbbit.capability_access_policies everyone_cap
                      ON everyone_cap.capability_kind = 'cap_playbook'
                     AND everyone_cap.capability_name = everyone_pb.capability_name
                    WHERE everyone_pb.id::text = split_part(w.item_id, ':', 2)
                      AND everyone_pb.approved_version IS NOT NULL
                      AND everyone_cap.visibility = 'everyone'
                )
            )
        )
        AND (
            w.item_kind <> 'chat'
            OR EXISTS (
                SELECT 1
                FROM rvbbit.calliope_turns visible_turn
                WHERE visible_turn.session_id::text = split_part(w.item_id, ':', 2)
                  AND visible_turn.turn_kind IN ('chat', 'agent_message', 'data_publish')
            )
        )
    """
    floor_card_columns = """
        w.last_activity_at,
        w.item_id,
        w.item_kind,
        w.session_id,
        -- A session's home channel is stable provenance, including for older
        -- timeline frames that predate channel metadata in the graph itself.
        CASE WHEN w.item_kind = 'chat' THEN (
            SELECT source_session.channel
            FROM rvbbit.calliope_sessions source_session
            WHERE source_session.id = w.session_id
        ) END AS channel,
        w.display_title,
        CASE
            WHEN w.item_kind = 'duty_cycle'
             AND w.detail_state IN ('claimed', 'running') THEN 'in_motion'
            ELSE w.column_state
        END AS column_state,
        w.detail_state,
        w.owner_email,
        w.agents,
        w.summary,
        w.state_reason,
        CASE
            WHEN w.item_kind = 'duty_cycle'
             AND w.detail_state IN ('claimed', 'running') THEN true
            ELSE w.active_now
        END AS active_now,
        w.default_hidden,
        w.idle_seconds,
        w.child_thread_count,
        w.active_child_count,
        w.related_signal_count,
        w.surface_count,
        w.attention_rank,
        w.route,
        w.ref->>'urgency' AS urgency,
        w.ref->>'schedule' AS schedule,
        w.ref->>'kind' AS signal_kind,
        w.ref->>'source' AS signal_source,
        NULL::text AS driver_email,
        NULL::text[] AS room_members,
        CASE WHEN w.item_kind='curated_dream' THEN w.ref->'dream' END AS dream,
        NULL::jsonb AS dream_origin,
        w.ref->>'action_prompt' AS action_prompt,
        w.ref->>'pinned' AS pinned,
        w.ref->>'drift' AS drift,
        w.ref->>'streak' AS streak,
        w.ref->>'failures_14' AS failures_14,
        NULL::text AS next_run_at,
        CASE
            WHEN w.item_kind = 'duty_cycle'
             AND w.detail_state IN ('claimed', 'running') THEN w.detail_state
            ELSE w.ref->>'last_status'
        END AS last_status
    """
