    @mcp.custom_route("/api/calliope/data-inventory", methods=["GET"])
    async def data_inventory(request):
        """User-space inventory: schemas → tables with freshness, MCP
        services → functions (from the mirror's receipts), and connected
        integrations. Names, counts, and timestamps only — never rows."""
        owner, err = api_owner(request)
        if err:
            return err

        def iso(value: Any) -> str | None:
            return value.isoformat() if hasattr(value, "isoformat") else (
                str(value) if value else None
            )

        def build() -> dict[str, Any]:
            with conn_factory() as conn:
                table_rows = conn.execute(
                    "SELECT schemaname, relname, n_live_tup::bigint AS live_rows, "
                    "greatest(last_analyze,last_autoanalyze,last_vacuum,last_autovacuum) AS last_activity "
                    "FROM pg_stat_user_tables "
                    "WHERE schemaname NOT IN ('rvbbit','hindsight') "
                    "AND schemaname NOT LIKE '\\_%' "
                    "AND schemaname NOT LIKE '%\\_staging' "
                    "AND relname NOT LIKE '\\_dlt\\_%' "
                    "ORDER BY schemaname, relname LIMIT 2000"
                ).fetchall()
                # pg_stat's n_live_tup reads zero for never-analyzed tables;
                # the RVBBIT catalog crawler profiles real counts. Prefer its
                # latest n_rows per table, fall back to the stats estimate.
                catalog_counts: dict[tuple[str, str], int] = {}
                try:
                    with conn.transaction():
                        for row in conn.execute(
                            "SELECT DISTINCT ON (schema_name, rel_name) "
                            "schema_name, rel_name, "
                            "(fingerprint::jsonb->>'n_rows')::bigint AS n_rows "
                            "FROM rvbbit.catalog_snapshots "
                            "WHERE kind='db_table' "
                            "AND fingerprint::jsonb->>'n_rows' IS NOT NULL "
                            "ORDER BY schema_name, rel_name, captured_at DESC "
                            "LIMIT 4000"
                        ).fetchall():
                            catalog_counts[
                                (str(row["schema_name"]), str(row["rel_name"]))
                            ] = int(row["n_rows"])
                except Exception:
                    catalog_counts = {}
                dlt_schemas = [
                    str(row["table_schema"]) for row in conn.execute(
                        "SELECT table_schema FROM information_schema.tables "
                        "WHERE table_name='_dlt_loads' "
                        "AND table_schema NOT IN ('rvbbit','hindsight') LIMIT 40"
                    ).fetchall()
                ]
                loads: dict[str, Any] = {}
                for schema in dlt_schemas:
                    # Identifier allow-list; these names come from the catalog
                    # but the quote-free format string earns a strict gate.
                    if not re.fullmatch(r"[a-z_][a-z0-9_]*", schema):
                        continue
                    try:
                        # Savepoint per probe: a schema the app role cannot
                        # read must not poison the transaction for the rest
                        # of the inventory (the original 500 on the box).
                        with conn.transaction():
                            row = conn.execute(
                                f'SELECT max(inserted_at) AS last FROM "{schema}"._dlt_loads'
                            ).fetchone()
                        if row and row.get("last"):
                            loads[schema] = row["last"]
                    except Exception:
                        pass
                # The generated Briarpatch scene IS the map of this same
                # universe — surface the newest one the viewer may open so
                # the page can render the real sketch as its primary layer.
                sketch_payload = None
                try:
                    # Savepointed like the loads probe: a missing helper
                    # function on an older database must degrade to "no
                    # sketch", never poison the rest of the inventory. The
                    # doubled %% matters: with bound params psycopg parses
                    # placeholders, and a bare '%b' reads as one.
                    with conn.transaction():
                        briarpatch = conn.execute(
                            "SELECT k.id,k.session_id,k.title,k.updated_at "
                            "FROM rvbbit.calliope_sketches k "
                            "WHERE k.title ILIKE '%%briarpatch%%' "
                            "AND rvbbit.calliope_session_can_view(k.session_id,%s,false) "
                            "ORDER BY k.updated_at DESC LIMIT 1",
                            (owner,),
                        ).fetchone()
                    if briarpatch:
                        sketch_payload = {
                            "id": str(briarpatch["id"]),
                            "title": str(briarpatch["title"]),
                            "updated_at": iso(briarpatch.get("updated_at")),
                            "url": f"/calliope/sketches/{briarpatch['id']}",
                        }
                except Exception:
                    sketch_payload = None
                mirror_ready = bool(conn.execute(
                    "SELECT to_regclass('rvbbit.hermes_messages') AS relation"
                ).fetchone().get("relation"))
                service_rows = conn.execute(
                    "SELECT split_part(tc->'function'->>'name','__',2) AS service, "
                    "tc->'function'->>'name' AS fn, count(*)::bigint AS calls, "
                    "max(m.ts) AS last_used "
                    "FROM rvbbit.hermes_messages m, "
                    "jsonb_array_elements(m.tool_calls) tc "
                    "WHERE jsonb_typeof(m.tool_calls)='array' "
                    "AND tc->'function'->>'name' LIKE 'mcp\\_\\_%' "
                    "GROUP BY 1, 2 ORDER BY 1, calls DESC LIMIT 400"
                ).fetchall() if mirror_ready else []

            schemas: dict[str, dict[str, Any]] = {}
            for row in table_rows:
                schema = schemas.setdefault(str(row["schemaname"]), {
                    "name": str(row["schemaname"]),
                    "tables": [],
                    "total_rows": 0,
                    "last_activity": None,
                    "last_load": None,
                })
                activity = row.get("last_activity")
                profiled = catalog_counts.get(
                    (str(row["schemaname"]), str(row["relname"]))
                )
                row_count = profiled if profiled is not None else int(row.get("live_rows") or 0)
                schema["tables"].append({
                    "name": str(row["relname"]),
                    "rows": row_count,
                    "last_activity": iso(activity),
                })
                schema["total_rows"] += row_count
                if activity and (schema["last_activity"] is None or activity > schema["last_activity"]):
                    schema["last_activity"] = activity
            for name, loaded_at in loads.items():
                if name in schemas:
                    schemas[name]["last_load"] = loaded_at
            schema_list = [
                {**schema,
                 "last_activity": iso(schema["last_activity"]),
                 "last_load": iso(schema["last_load"])}
                for schema in schemas.values()
            ]

            services: dict[str, dict[str, Any]] = {}
            for row in service_rows:
                service = services.setdefault(str(row["service"]), {
                    "name": str(row["service"]),
                    "functions": [],
                    "call_count": 0,
                    "last_used": None,
                })
                service["functions"].append({
                    "name": str(row["fn"]),
                    "calls": int(row.get("calls") or 0),
                })
                service["call_count"] += int(row.get("calls") or 0)
                used = row.get("last_used")
                if used and (service["last_used"] is None or used > service["last_used"]):
                    service["last_used"] = used
            service_list = [
                {**service, "last_used": iso(service["last_used"])}
                for service in services.values()
            ]

            integrations: list[dict[str, Any]] = []
            if google_workspace_enabled:
                integrations.append({
                    "name": "Google Workspace",
                    "detail": "Sheets, Docs, and Calendar reachable with your account",
                })
            if config.voice_enabled:
                integrations.append({
                    "name": "Hutch voice" if config.voice_provider == "hutch" else "ElevenLabs voice",
                    "detail": "Spoken answers and read-aloud",
                })
            integrations.append({
                "name": "Hindsight memory",
                "detail": "Long-term memory service behind Calliope",
            })
            integrations.append({
                "name": "Hermes agents",
                "detail": "The agent runtime running Calliope and her specialists",
            })
            return {
                "schemas": schema_list,
                "services": service_list,
                "integrations": integrations,
                "sketch": sketch_payload,
            }

        payload = await asyncio.to_thread(build)
        return json_response(payload)

