    @mcp.custom_route(
        "/api/calliope/sessions/{session_id}/access", methods=["PUT"]
    )
    async def update_session_access(request):
        _owner, err = api_owner(request)
        if err:
            return err
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        try:
            result = await asyncio.to_thread(
                calliope_access.replace_access,
                conn_factory,
                request_authorization(request),
                request.path_params["session_id"],
                body.get("expected_revision"),
                team_ids=body.get("team_ids"),
                people=body.get("people"),
                participants=body.get("participants"),
                managers=body.get("managers"),
                confirm_everyone=body.get("confirm_everyone") is True,
            )
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        if result.get("changed"):
            # Tell the people just brought in; Teams are told on the Floor.
            added = []
            for event in result.get("events") or []:
                added = list(((event.get("detail") or {}).get("people_added")) or [])
                break
            if added:
                try:
                    with conn_factory() as conn:
                        calliope_rooms.settle_knocks(conn, result["session"]["id"], added, _owner)
                        calliope_rooms.notify_added(conn, result["session"], added, _owner)
                except Exception as exc:  # noqa: BLE001 — the grant already landed
                    print(f"WARNING: room invite notification failed: {exc}", file=os.sys.stderr)
        return json_response(result)

