    @mcp.custom_route("/api/calliope/floor/silhouettes/{shadow}/knock", methods=["POST"])
    async def knock_on_floor_silhouette(request):
        """Knock on someone's private chat you can see is in motion on the Floor.

        A silhouette carries only a hash of its chat (never the id); resolve it
        here, for a chat this viewer can't already see."""
        owner, err = api_owner(request)
        if err:
            return err
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        shadow = str(request.path_params.get("shadow") or "").strip().lower()
        if shadow.startswith("shadow:"):
            shadow = shadow.split(":", 1)[1]
        if not re.fullmatch(r"[0-9a-f]{32}", shadow):
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT s.id::text AS id FROM rvbbit.work_graph w "
                "JOIN rvbbit.calliope_sessions s ON s.id::text=split_part(w.item_id,':',2) "
                "WHERE w.item_kind='chat' AND md5(w.item_id)=%s AND lower(s.owner_email)<>lower(%s) "
                "AND NOT rvbbit.calliope_session_can_view(s.id,%s,false) LIMIT 1",
                (shadow, owner, owner),
            ).fetchone()
        if not row:
            return json_response({"error": {"code": "NOT_FOUND", "message": "That chat isn't open for knocking."}}, 404)
        try:
            result = await asyncio.to_thread(
                calliope_rooms.knock, conn_factory, owner, row["id"],
                reason=body.get("reason"), via="floor",
            )
        except calliope_rooms.RoomError as exc:
            return room_error_response(exc)
        # The requester learns their knock landed, not which chat it was.
        return json_response({"status": result["status"]}, 201)

