    @mcp.custom_route("/api/calliope/session-events", methods=["GET"])
    async def calliope_session_events(request):
        owner, err = api_owner(request)
        if err:
            return err

        # ?session=<id> scopes the stream to the open notebook: its turn
        # statuses and surface set join the digest (see _session_state_digest).
        scope = _uuid(request.query_params.get("session"))

        async def current_digest() -> str:
            visible = await asyncio.to_thread(
                calliope_access.visible_digest, conn_factory, owner
            )
            if not scope:
                return visible
            scoped = await asyncio.to_thread(
                _session_state_digest, conn_factory, owner, scope
            )
            return f"{visible}|{scoped}"

        async def inputs_digest() -> str:
            if not scope:
                return ""
            return await asyncio.to_thread(
                _session_inputs_digest, conn_factory, owner, scope
            )

        async def presence() -> list[str]:
            if not scope:
                return []
            return await asyncio.to_thread(
                _room_presence_tick, conn_factory, owner, scope
            )

        async def changes() -> AsyncIterator[bytes]:
            digest = await current_digest()
            questions = await inputs_digest()
            present = await presence()
            yield _sse("calliope.sessions.ready", {"digest": digest})
            if scope:
                yield _sse("calliope.room.presence", {"session_id": scope, "present": present})
            heartbeat_at = time.monotonic()
            presence_at = time.monotonic()
            while not await request.is_disconnected():
                await asyncio.sleep(1.5)
                next_questions = await inputs_digest()
                if next_questions != questions:
                    questions = next_questions
                    yield _sse("calliope.session.inputs.changed", {"session_id": scope})
                if scope and time.monotonic() - presence_at >= 15:
                    presence_at = time.monotonic()
                    next_present = await presence()
                    if next_present != present:
                        present = next_present
                        yield _sse("calliope.room.presence", {"session_id": scope, "present": present})
                next_digest = await current_digest()
                if next_digest != digest:
                    digest = next_digest
                    yield _sse("calliope.sessions.changed", {"digest": digest})
                    heartbeat_at = time.monotonic()
                elif time.monotonic() - heartbeat_at >= 15:
                    yield b": keepalive\n\n"
                    heartbeat_at = time.monotonic()

        return StreamingResponse(
            changes(),
            media_type="text/event-stream",
            headers={
                "cache-control": "no-store",
                "x-accel-buffering": "no",
                "connection": "keep-alive",
            },
        )

    @mcp.custom_route("/api/calliope/turn-lifecycle", methods=["POST"])
    async def calliope_turn_lifecycle(request):
        """Log bounded browser lifecycle evidence without retaining chat content."""
        owner, err = api_owner(request)
        if err:
            return err
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        client_turn_id = _uuid(body.get("client_turn_id"))
        turn_id = _uuid(body.get("turn_id"))
        if not client_turn_id and not turn_id:
            return Response(status_code=204)
        with conn_factory() as conn:
            turn = conn.execute(
                "SELECT t.id,t.client_turn_id,t.status FROM rvbbit.calliope_turns t "
                "JOIN rvbbit.calliope_sessions s ON s.id=t.session_id "
                "WHERE lower(s.owner_email)=lower(%s) AND ("
                "t.id=%s::uuid OR t.client_turn_id=%s::uuid) LIMIT 1",
                (owner, turn_id, client_turn_id),
            ).fetchone()
        if not turn:
            return Response(status_code=204)
        event = re.sub(
            r"[^a-z0-9._-]+", "-", str(body.get("event") or "unknown").lower()
        ).strip("-")[:48] or "unknown"
        visibility = str(body.get("visibility") or "unknown").lower()
        if visibility not in {"visible", "hidden", "prerender", "unknown"}:
            visibility = "unknown"
        print(
            "INFO: Calliope browser lifecycle "
            + json.dumps({
                "turn_id": str(turn["id"]),
                "client_turn_id": (
                    str(turn["client_turn_id"])
                    if turn.get("client_turn_id") else None
                ),
                "status": str(turn.get("status") or ""),
                "event": event,
                "visibility": visibility,
                "persisted": body.get("persisted") is True,
                "online": body.get("online") is not False,
                "page_id": str(body.get("page_id") or "")[:80],
            }, separators=(",", ":")),
            file=os.sys.stderr,
        )
        return Response(status_code=204)

    @mcp.custom_route(
        "/api/calliope/sessions/{session_id}/turns/{turn_id}/events",
        methods=["GET"],
    )
    async def calliope_turn_events(request):
        """Return compact ordered progress for cross-browser reattachment."""
        owner, err = api_owner(request)
        if err:
            return err
        session_id = _uuid(request.path_params.get("session_id"))
        turn_id = _uuid(request.path_params.get("turn_id"))
        if not session_id or not turn_id:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            after = max(0, int(request.query_params.get("after") or 0))
            limit = max(1, min(int(request.query_params.get("limit") or 500), 2_000))
        except (TypeError, ValueError):
            return json_response(
                {"error": {"code": "INVALID_EVENT_CURSOR"}}, 400
            )
        try:
            with conn_factory() as conn:
                calliope_access.require_view(conn, session_id, owner)
                turn = conn.execute(
                    "SELECT t.*,p.display_name AS author_profile_name,"
                    "p.avatar_key::text AS author_avatar_key "
                    "FROM rvbbit.calliope_turns t "
                    "LEFT JOIN rvbbit.application_principals p "
                    "ON p.email=lower(t.author_email) "
                    "WHERE t.id=%s::uuid AND t.session_id=%s::uuid",
                    (turn_id, session_id),
                ).fetchone()
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        if not turn:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        events = _turn_event_ledger(
            conn_factory,
            turn_id,
            after_sequence=after,
            limit=limit,
        )
        return json_response({
            "turn": _turn_json(turn),
            "events": events,
            "next_sequence": (
                events[-1]["sequence"] if events else after
            ),
            "has_more": len(events) >= limit,
        })

