    @mcp.custom_route(
        "/api/calliope/sessions/{session_id}/command", methods=["POST"]
    )
    async def run_calliope_command(request):
        """Execute Calliope-owned slash commands as durable Stage surfaces."""
        owner, err = api_owner(request)
        if err:
            return err
        signed_profile = observe_browser_principal(request) or {}
        author_display_name = (
            re.sub(r"\s+", " ", str(signed_profile.get("name") or "")).strip()[:160]
            or owner
        )
        session = _session_for_owner(
            conn_factory, request.path_params["session_id"], owner
        )
        if not session:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            body = await request.json()
        except Exception:
            body = {}
        raw_command = str((body or {}).get("command") or "").strip()
        match = re.fullmatch(
            r"/([a-z][a-z0-9_-]{0,79})(?:\s+([^\r\n]{1,4000}))?",
            raw_command,
            re.I,
        )
        if not match:
            return json_response({
                "error": {
                    "code": "INVALID_COMMAND",
                    "message": "Enter one slash command on a single line.",
                }
            }, 400)
        typed_name = match.group(1).lower()
        initial_query = re.sub(r"\s+", " ", str(match.group(2) or "")).strip()[:200]
        hermes_base_url = _session_hermes_base_url(config, conn_factory, session)
        try:
            catalog = await _calliope_command_catalog(
                config,
                base_url=hermes_base_url,
            )
        except Exception as exc:
            return json_response({
                "error": {
                    "code": "COMMAND_CATALOG_UNAVAILABLE",
                    "message": str(exc)[:600],
                }
            }, 502)
        command_item = _find_calliope_command(catalog, typed_name)
        if not command_item:
            return json_response({
                "error": {
                    "code": "UNKNOWN_COMMAND",
                    "message": f"/{typed_name} is not active in this Hermes profile.",
                }
            }, 404)
        execution = str(command_item.get("execution") or "blocked")
        if execution == "blocked":
            return json_response({
                "error": {
                    "code": "COMMAND_NOT_AVAILABLE",
                    "message": str(command_item.get("policy_reason") or "This command is not available in Calliope."),
                }
            }, 409)
        if execution == "hermes_skill":
            return json_response({
                "route": "agent",
                "command": command_item,
                "catalog": catalog,
            })
        command_name = str(command_item.get("name") or typed_name)
        command_output = ""
        if execution == "hermes_command":
            try:
                result = await _hermes_json(
                    config,
                    "POST",
                    "/v1/commands/execute",
                    {
                        "command": raw_command,
                        "session_id": str(session.get("hermes_session_id") or ""),
                        "user_id": owner,
                        "user_name": author_display_name,
                    },
                    timeout_seconds=120,
                    base_url=hermes_base_url,
                )
                command_output = str(result.get("output") or "Command completed.")
                if command_name == "version":
                    command_output = _calliope_version_command_output(
                        command_output, conn_factory
                    )
            except Exception as exc:
                return json_response({
                    "error": {
                        "code": "COMMAND_EXECUTION_FAILED",
                        "message": str(exc)[:600],
                    }
                }, 502)
        rows = list(catalog.get("commands") or [])
        scope = "skills" if command_name == "skills" else "all"
        if execution == "stage_library" and scope == "skills":
            rows = [item for item in rows if item.get("source") == "skill"]
        payload = {
            **catalog,
            "mode": "command_catalog",
            "scope": scope,
            "initial_query": initial_query,
            "commands": rows,
            "summary": {
                **(catalog.get("summary") or {}),
                "shown": len(rows),
            },
        } if execution == "stage_library" else {}
        turn_id = str(uuid.uuid4())
        with conn_factory() as conn:
            with conn.transaction():
                locked = conn.execute(
                    "SELECT * FROM rvbbit.calliope_sessions "
                    "WHERE id=%s::uuid AND lower(owner_email)=lower(%s) FOR UPDATE",
                    (str(session["id"]), owner),
                ).fetchone()
                if not locked:
                    return json_response({"error": {"code": "NOT_FOUND"}}, 404)
                active = conn.execute(
                    "SELECT id FROM rvbbit.calliope_turns "
                    "WHERE session_id=%s::uuid AND status='running' LIMIT 1",
                    (str(session["id"]),),
                ).fetchone()
                if active:
                    return json_response({
                        "error": {
                            "code": "TURN_IN_PROGRESS",
                            "message": "Calliope is still working in this notebook.",
                        }
                    }, 409)
                next_ordinal = conn.execute(
                    "SELECT coalesce(max(ordinal),0)+1 AS n "
                    "FROM rvbbit.calliope_turns WHERE session_id=%s::uuid",
                    (str(session["id"]),),
                ).fetchone()["n"]
                turn = conn.execute(
                    "INSERT INTO rvbbit.calliope_turns "
                    "(id,session_id,ordinal,user_message,assistant_message,status,"
                    "completed_at,turn_kind,author_email,author_display_name) "
                    "VALUES (%s::uuid,%s::uuid,%s,%s,%s,'complete',now(),%s,%s,%s) "
                    "RETURNING *",
                    (
                        turn_id,
                        str(session["id"]),
                        next_ordinal,
                        raw_command,
                        (
                            "Opened Calliope's active Library on the Stage."
                            if execution == "stage_library"
                            else command_output
                        ),
                        "command" if execution == "stage_library" else "chat",
                        owner,
                        author_display_name,
                    ),
                ).fetchone()
                session = conn.execute(
                    "UPDATE rvbbit.calliope_sessions SET updated_at=now() "
                    "WHERE id=%s::uuid RETURNING *",
                    (str(session["id"]),),
                ).fetchone()
        surfaces = _insert_surfaces(
            conn_factory,
            str(session["id"]),
            turn_id,
            [{
                "kind": "library",
                "title": "Skills" if scope == "skills" else "Commands & skills",
                "tool_name": "calliope_command_catalog",
                "tool_call_id": f"calliope-command-catalog:{turn_id}",
                "lineage_key": f"command-catalog:{catalog.get('generation')}:{scope}",
                "payload": payload,
                "source": {
                    "origin": "hermes_command_registry",
                    "profile": catalog.get("profile"),
                    "generation": catalog.get("generation"),
                },
                "presentation": {"view": "command_catalog"},
            }] if execution == "stage_library" else [],
        )
        if execution == "stage_library" and not surfaces:
            with conn_factory() as conn:
                conn.execute(
                    "DELETE FROM rvbbit.calliope_turns WHERE id=%s::uuid", (turn_id,)
                )
            return json_response({
                "error": {
                    "code": "COMMAND_CATALOG_SAVE_FAILED",
                    "message": "The Library could not be placed on the Stage.",
                }
            }, 500)
        return json_response({
            "session": _session_json(session),
            "turn": _turn_json(turn),
            "surfaces": surfaces,
            "catalog": catalog,
        }, 201)

    @mcp.custom_route("/api/calliope/sessions", methods=["GET"])
    async def list_sessions(request):
        owner, err = api_owner(request)
        if err:
            return err
        purpose = (
            "setup"
            if str(request.query_params.get("purpose") or "").strip().lower() == "setup"
            else "chat"
        )
        with conn_factory() as conn:
            rows = conn.execute(
                "SELECT s.*, (count(DISTINCT t.id) FILTER "
                "(WHERE t.turn_kind<>'sketch_bootstrap'))::int AS turn_count,"
                " (count(DISTINCT f.id) FILTER (WHERE NOT (f.kind='sketch' AND "
                "f.payload @> '{\"auto_created\":true,\"element_count\":0}'::jsonb)))::int "
                "AS surface_count,"
                " max(f.created_at) AS last_surface_at,"
                " rvbbit.calliope_session_role(s.id,%s)"
                " AS access_role,"
                " (SELECT p.display_name FROM rvbbit.application_principals p"
                " WHERE p.email=lower(s.owner_email)) AS owner_display_name,"
                " (SELECT p.avatar_key::text FROM rvbbit.application_principals p"
                " WHERE p.email=lower(s.owner_email)) AS owner_avatar_key,"
                " (SELECT count(*)::int FROM rvbbit.calliope_session_view_grants g"
                " WHERE g.session_id=s.id) AS share_count,"
                " sn.synopsis,sn.status AS synopsis_status,sn.updated_at AS synopsis_updated_at,"
                " b.id AS brief_id,b.brief_date,b.timezone AS brief_timezone,"
                " wr.workflow_run_id,wr.workflow_id,wr.workflow_version,"
                " wr.workflow_name,wr.workflow_run_status,wr.workflow_run_trigger_kind,"
                " wr.workflow_run_started_at,wr.workflow_run_completed_at,"
                " wor.work_order_run_id,wor.work_order_id,wor.work_order_title,"
                " wor.work_order_run_status,wor.work_order_run_trigger_kind,"
                " wor.work_order_run_started_at,wor.work_order_run_completed_at,"
                " ir.instrument_run_surface_id,ir.instrument_id,"
                " ir.instrument_version,ir.instrument_name,"
                " ac.action_handoff_surface_id,ac.action_id,ac.action_title,"
                " ac.action_created_at,"
                " (SELECT active.id FROM rvbbit.calliope_turns active "
                "  WHERE active.session_id=s.id AND active.status='running' "
                "  ORDER BY active.created_at LIMIT 1) AS active_turn_id,"
                " (SELECT active.client_turn_id FROM rvbbit.calliope_turns active "
                "  WHERE active.session_id=s.id AND active.status='running' "
                "  ORDER BY active.created_at LIMIT 1) AS active_turn_client_id,"
                " (SELECT active.hermes_run_id FROM rvbbit.calliope_turns active "
                "  WHERE active.session_id=s.id AND active.status='running' "
                "  ORDER BY active.created_at LIMIT 1) AS active_hermes_run_id,"
                " (SELECT active.heartbeat_at FROM rvbbit.calliope_turns active "
                "  WHERE active.session_id=s.id AND active.status='running' "
                "  ORDER BY active.created_at LIMIT 1) AS active_turn_heartbeat_at "
                "FROM rvbbit.calliope_sessions s "
                "LEFT JOIN LATERAL ("
                " SELECT id,brief_date,timezone FROM rvbbit.calliope_briefs "
                " WHERE session_id=s.id AND lower(owner_email)=lower(s.owner_email) "
                " ORDER BY brief_date DESC LIMIT 1"
                ") b ON true "
                "LEFT JOIN LATERAL ("
                " SELECT r.id AS workflow_run_id,r.workflow_id,r.workflow_version,"
                " v.name AS workflow_name,r.status AS workflow_run_status,"
                " r.trigger_kind AS workflow_run_trigger_kind,"
                " r.started_at AS workflow_run_started_at,"
                " r.completed_at AS workflow_run_completed_at "
                " FROM rvbbit.calliope_workflow_runs r "
                " JOIN rvbbit.calliope_workflow_versions v "
                " ON v.workflow_id=r.workflow_id AND v.version=r.workflow_version "
                " WHERE r.session_id=s.id AND lower(r.owner_email)=lower(s.owner_email) "
                " ORDER BY r.started_at DESC LIMIT 1"
                ") wr ON true "
                "LEFT JOIN LATERAL ("
                " SELECT r.id AS work_order_run_id,r.work_order_id,"
                " w.title AS work_order_title,r.status AS work_order_run_status,"
                " r.trigger_kind AS work_order_run_trigger_kind,"
                " r.started_at AS work_order_run_started_at,"
                " r.completed_at AS work_order_run_completed_at "
                " FROM rvbbit.calliope_work_order_runs r "
                " JOIN rvbbit.calliope_work_orders w ON w.id=r.work_order_id "
                " WHERE r.session_id=s.id AND lower(r.owner_email)=lower(s.owner_email) "
                " ORDER BY r.started_at DESC LIMIT 1"
                ") wor ON true "
                "LEFT JOIN LATERAL ("
                " SELECT sf.id AS instrument_run_surface_id,"
                " nullif(sf.payload #>> '{items,0,provenance,instrument_id}','') "
                " AS instrument_id,"
                " nullif(sf.payload #>> '{items,0,provenance,version}','') "
                " AS instrument_version,"
                " coalesce(nullif(sf.payload #>> '{items,0,title}',''),"
                " nullif(sf.source->>'query','')) AS instrument_name "
                " FROM rvbbit.calliope_surfaces sf "
                " WHERE sf.session_id=s.id "
                " AND sf.source->>'origin'='calliope_instrument_run' "
                " ORDER BY sf.created_at LIMIT 1"
                ") ir ON true "
                "LEFT JOIN LATERAL ("
                " SELECT sf.id AS action_handoff_surface_id,"
                " coalesce(nullif(sf.source->>'action_id',''),"
                " nullif(sf.payload #>> '{action,id}','')) AS action_id,"
                " coalesce(nullif(sf.payload #>> '{action,title}',''),sf.title)"
                " AS action_title,sf.created_at AS action_created_at "
                " FROM rvbbit.calliope_surfaces sf "
                " WHERE sf.session_id=s.id "
                " AND sf.source->>'origin'='calliope_action_library' "
                " ORDER BY sf.created_at LIMIT 1"
                ") ac ON true "
                "LEFT JOIN rvbbit.calliope_session_synopses sn ON sn.session_id=s.id "
                "LEFT JOIN rvbbit.calliope_turns t ON t.session_id=s.id "
                "LEFT JOIN rvbbit.calliope_surfaces f ON f.session_id=s.id "
                "WHERE rvbbit.calliope_session_can_view(s.id,%s,false) "
                "AND s.purpose=%s "
                "AND (%s<>'setup' OR lower(s.owner_email)=lower(%s)) "
                "GROUP BY s.id,b.id,b.brief_date,b.timezone,"
                " wr.workflow_run_id,wr.workflow_id,wr.workflow_version,wr.workflow_name,"
                " wr.workflow_run_status,wr.workflow_run_trigger_kind,"
                " wr.workflow_run_started_at,wr.workflow_run_completed_at,"
                " wor.work_order_run_id,wor.work_order_id,wor.work_order_title,"
                " wor.work_order_run_status,wor.work_order_run_trigger_kind,"
                " wor.work_order_run_started_at,wor.work_order_run_completed_at,"
                " ir.instrument_run_surface_id,ir.instrument_id,"
                " ir.instrument_version,ir.instrument_name,"
                " ac.action_handoff_surface_id,ac.action_id,ac.action_title,"
                " ac.action_created_at,sn.session_id,sn.synopsis,sn.status,sn.updated_at "
                "ORDER BY s.updated_at DESC",
                (owner, owner, purpose, purpose, owner),
            ).fetchall()
            thread_rows = (
                _specialist_thread_rows(conn, owner) if purpose == "chat" else []
            )
        threads_by_session: dict[str, list[dict[str, Any]]] = {}
        for thread_row in thread_rows:
            summary = _specialist_thread_summary_json(thread_row)
            threads_by_session.setdefault(summary["session_id"], []).append(summary)
        sessions = []
        for row in rows:
            session_item = _session_json(row)
            session_item["specialist_threads"] = threads_by_session.get(
                session_item["id"], []
            )
            sessions.append(session_item)
        return json_response({"sessions": sessions})

    @mcp.custom_route("/api/calliope/setup", methods=["POST"])
    async def setup_workspace(request):
        owner, err = api_owner(request)
        if err:
            return err
        try:
            session = await _ensure_setup_session(config, conn_factory, owner)
            can_manage = await asyncio.to_thread(
                calliope_dreams.is_company_admin, conn_factory, owner
            )
            snapshot = await asyncio.to_thread(
                _setup_workspace_snapshot,
                conn_factory,
                owner,
                session,
                can_manage=can_manage,
            )
            snapshot["can_manage"] = can_manage
            snapshot["identity"] = _setup_identity_snapshot(
                owner, can_manage, auth.read_session_full(request)
            )
            snapshot["mutation_token"] = (
                _setup_mutation_token(config, owner, session["id"])
                if can_manage
                else None
            )
        except Exception as exc:
            return json_response(
                {
                    "error": {
                        "code": "SETUP_UNAVAILABLE",
                        "message": str(exc)[:600],
                    }
                },
                502,
            )
        return json_response(snapshot)

    async def hermes_admin_access(
        request: Any, *, mutation: bool
    ) -> tuple[str | None, Response | None]:
        owner, err = api_owner(request)
        if err:
            return None, err
        can_manage = await asyncio.to_thread(
            calliope_dreams.is_company_admin, conn_factory, owner
        )
        if not can_manage:
            return None, json_response(
                {
                    "error": {
                        "code": "HERMES_ADMIN_REQUIRED",
                        "message": "Only a member of the Admins Team may administer Hermes.",
                    }
                },
                403,
            )
        if mutation:
            headers = getattr(request, "headers", {}) or {}
            if str(headers.get("sec-fetch-site") or "").lower() == "cross-site":
                return None, json_response(
                    {"error": {"code": "HERMES_REQUEST_REJECTED"}}, 403
                )
            if str(headers.get("x-calliope-admin") or "") != "1":
                return None, json_response(
                    {
                        "error": {
                            "code": "HERMES_ADMIN_HEADER_REQUIRED",
                            "message": "Reload the admin surface before applying this change.",
                        }
                    },
                    403,
                )
        return owner, None

    async def computer_admin_access(
        request: Any, *, mutation: bool
    ) -> tuple[str | None, Response | None]:
        owner, err = await hermes_admin_access(request, mutation=mutation)
        if err:
            return None, err
        if not config.desktop_enabled:
            return None, json_response(
                {
                    "error": {
                        "code": "DESKTOP_DISABLED",
                        "message": "The Debug Desktop is not enabled on this Calliope installation.",
                    }
                },
                404,
            )
        return owner, None

    def workbench_recording_json(item: dict[str, Any]) -> dict[str, Any]:
        result = dict(item)
        if result.get("state") == "ready":
            result["media_url"] = (
                f"/api/calliope/workbenches/{quote(str(result['workbench_id']), safe='')}"
                f"/recordings/{quote(str(result['id']), safe='')}/media"
            )
        return result

