    @mcp.custom_route(
        "/api/calliope/workbenches/{workbench_id}/screenshots/{request_event_id}",
        methods=["GET"],
    )
    async def get_calliope_workbench_screenshot(request):
        owner, err = await computer_admin_access(request, mutation=False)
        if err:
            return err
        try:
            request_event_id = _uuid(request.path_params.get("request_event_id"))
            items = await asyncio.to_thread(
                workbench_access.events,
                conn_factory,
                owner,
                request.path_params.get("workbench_id"),
            )
            result = next(
                (
                    item
                    for item in items
                    if (
                        item.get("request_event_id") == request_event_id
                        and item.get("event_type") == "action.succeeded"
                    )
                    or (
                        # Calliope's read-only looks carry their PNG on their own event.
                        item.get("id") == request_event_id
                        and item.get("event_type") == "look.captured"
                    )
                ),
                None,
            )
            object_key = ((result or {}).get("payload") or {}).get("screenshot", {}).get("object_key")
            if not object_key:
                return Response(status_code=404)
            root = config.desktop_recording_root.resolve()
            path = (root / str(object_key)).resolve(strict=True)
            path.relative_to(root)
            return FileResponse(
                path,
                media_type="image/png",
                headers={"cache-control": "private, no-store", "x-content-type-options": "nosniff"},
            )
        except Exception:
            return Response(status_code=404)

    @mcp.custom_route(
        "/api/calliope/workbenches/{workbench_id}/recordings/{recording_id}/media",
        methods=["GET"],
    )
    async def get_calliope_workbench_recording(request):
        owner, err = await computer_admin_access(request, mutation=False)
        if err:
            return err
        try:
            recording = await asyncio.to_thread(
                workbench_access.recording,
                conn_factory,
                owner,
                request.path_params.get("workbench_id"),
                request.path_params.get("recording_id"),
            )
            if recording.get("state") != "ready":
                return Response(status_code=404)
            root = config.desktop_recording_root.resolve()
            path = (root / str(recording["object_key"])).resolve(strict=True)
            path.relative_to(root)
            return FileResponse(
                path,
                media_type="video/mp4",
                filename=f"calliope-desktop-{recording['id']}.mp4",
                content_disposition_type="inline",
                headers={
                    "cache-control": "private, no-store",
                    "accept-ranges": "bytes",
                    "x-content-type-options": "nosniff",
                },
            )
        except Exception:
            return Response(status_code=404)

