    @mcp.custom_route("/api/calliope/admin/computer-storage", methods=["GET", "PUT"])
    async def computer_storage_settings(request):
        owner, err = await hermes_admin_access(request, mutation=request.method == 'PUT')
        if err:
            return err
        import desktop_storage
        try:
            if request.method == 'PUT':
                raw = await request.body()
                if len(raw) > 4096:
                    return json_response({'error': {'message': 'Storage settings are too large'}}, 413)
                await asyncio.to_thread(desktop_storage.save_policy, conn_factory, config,
                                        json.loads(raw or b'{}'), owner)
            return json_response(await asyncio.to_thread(desktop_storage.status, config))
        except (ValueError, TypeError, UnicodeDecodeError) as exc:
            return json_response({'error': {'message': str(exc)[:400]}}, 400)

    @mcp.custom_route("/api/calliope/admin/workspace", methods=["GET", "PUT"])
    async def workspace_admin_settings(request):
        owner, err = await hermes_admin_access(request, mutation=request.method == "PUT")
        if err:
            return err
        if request.method == "PUT":
            raw = await request.body()
            if len(raw) > 128 * 1024:
                return json_response({"error": {"message": "Workspace settings are too large"}}, 413)
            try:
                body = json.loads(raw or b"{}")
                if not isinstance(body, dict):
                    raise ValueError("Workspace settings must be an object")
                appearance = _normalize_appearance_preference(body.get("appearance"))
                if appearance and appearance["source"]["kind"] != "library":
                    raise ValueError("Choose a shared library wallpaper for the workspace")
                if appearance:
                    from warehouse_theme import theme_library
                    if not any(item["id"] == appearance["source"]["id"] and item["url"] == appearance["source"]["url"] for item in theme_library()):
                        raise ValueError("Wallpaper is not in the shared library")
                mode = body.get("mode", "dark")
                if mode not in ("dark", "light"):
                    raise ValueError("Choose light or dark mode")
            except (ValueError, TypeError, UnicodeDecodeError) as exc:
                return json_response({"error": {"message": str(exc)[:400]}}, 400)
            with conn_factory() as conn:
                conn.execute(
                    "INSERT INTO rvbbit.calliope_workspace_settings(singleton,appearance,color_mode,updated_by) "
                    "VALUES(true,%s::jsonb,%s,%s) ON CONFLICT(singleton) DO UPDATE SET "
                    "appearance=excluded.appearance,color_mode=excluded.color_mode,"
                    "updated_by=excluded.updated_by,updated_at=now()",
                    (json.dumps(appearance) if appearance is not None else None, mode, owner),
                )
        with conn_factory() as conn:
            row = conn.execute("SELECT appearance,color_mode,updated_at FROM rvbbit.calliope_workspace_settings WHERE singleton").fetchone()
        payload = _appearance_response_payload(row)
        payload["mode"] = payload["mode"] or "dark"
        return json_response(payload)

