    @mcp.custom_route(
        "/api/calliope/playbooks/{playbook_id}/schedule", methods=["POST"]
    )
    async def schedule_calliope_playbook(request):
        """Arm a standing heartbeat for one approved playbook, direct from the
        Floor. Mints a dedicated thread (the run log and steering channel) and
        hangs the schedule on it; the trust ladder inside
        upsert_session_schedule refuses unapproved playbooks, so only armed
        SOPs can run unattended. The runtime intent ("run for today, send to
        my inbox") travels as the mission — never by editing the playbook."""
        owner, err = api_owner(request)
        if err:
            return err
        playbook_id = _uuid(request.path_params["playbook_id"])
        if not playbook_id:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        schedule = str(body.get("schedule") or "").strip()
        mission = str(body.get("mission") or "").strip()[:4_000]
        if not _STANDING_CRON_RE.fullmatch(schedule):
            return json_response(
                {"error": {"code": "INVALID_SCHEDULE",
                           "message": "schedule must be a five-field cron expression"}},
                400,
            )
        # The same rule as every other Playbook read: the owner, an Admin for a
        # built-in, or anyone the approved version is shared with.
        try:
            visible = (await asyncio.to_thread(
                playbook_access.read, conn_factory, owner, playbook_id
            ))["playbook"]
        except playbook_access.PlaybookError:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        if visible.get("archived"):
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        playbook = {
            "capability_name": visible["capability_name"],
            "approved_version": visible.get("approved_version"),
        }
        title_row = {"title": visible.get("title")}
        if playbook["approved_version"] and visible.get("version") != playbook["approved_version"]:
            title_row = (await asyncio.to_thread(
                playbook_access.read, conn_factory, owner, playbook_id,
                playbook["approved_version"],
            ))["playbook"]
        if not playbook.get("approved_version"):
            return json_response(
                {"error": {"code": "NOT_APPROVED",
                           "message": "Only approved playbooks can run unattended — approve a version first."}},
                409,
            )
        display_title = str(
            (title_row or {}).get("title") or playbook["capability_name"]
        )[:96]
        session = None
        try:
            session = await _create_session_record(
                config, conn_factory, owner, f"Scheduled · {display_title}"[:120]
            )
            row = await asyncio.to_thread(
                upsert_session_schedule,
                conn_factory,
                owner,
                str(session["id"]),
                schedule,
                playbook_name=str(playbook["capability_name"]),
                mission=mission,
                created_by=owner,
            )
        except Exception as exc:
            if session:
                await discard_created_session(session)
            code = "HERMES_UNAVAILABLE" if session is None else "SCHEDULE_FAILED"
            return json_response(
                {"error": {"code": code, "message": str(exc)[:600]}},
                502 if session is None else 400,
            )
        return json_response(
            {
                "session": _session_json(session),
                "schedule": row,
                "url": "/calliope?" + urlencode(
                    {"session": str(session["id"]), "view": "zen"}
                ),
            },
            201,
        )

    @mcp.custom_route(
        "/calliope/playbooks/{playbook_id}/sketch",
        methods=["GET"],
    )
    async def calliope_playbook_sketch_page(request):
        owner, signed = _canonical_owner(request)
        if not owner:
            return RedirectResponse(
                f"/login?next={quote(request.url.path)}", status_code=302
            )
        if not (signed or {}).get("mapped", True):
            return RedirectResponse("/gallery", status_code=302)
        playbook_id = _uuid(request.path_params.get("playbook_id"))
        if not playbook_id:
            return Response(status_code=404)
        requested_version = request.query_params.get("version")
        try:
            snapshot = await asyncio.to_thread(
                playbook_access.read_sketch,
                conn_factory,
                owner,
                playbook_id,
                requested_version if requested_version not in (None, "") else None,
            )
        except playbook_access.PlaybookError:
            return Response(status_code=404)
        selected_version = int(snapshot["playbook"]["version"])
        source_url = (
            f"/api/calliope/playbooks/{quote(playbook_id, safe='')}/sketch?"
            + urlencode({"version": selected_version})
        )
        template = (_ASSET_DIR / "sketch.html").read_text(encoding="utf-8")
        html = (
            template.replace(
                "__SKETCH_ID__",
                escape(str(snapshot["sketch"]["id"]), quote=True),
            )
            .replace("__SKETCH_READ_ONLY__", "true")
            .replace("__SKETCH_SOURCE_URL__", escape(source_url, quote=True))
            .replace("__SKETCH_PRESENTATION__", "true")
            .replace("__CALLIOPE_ASSET_VERSION__", _ASSET_VERSION)
            .replace("__CALLIOPE_EXCALIFONT__", _EXCALIFONT_HASHES)
        )
        return HTMLResponse(
            html,
            headers={
                "cache-control": "private, no-store, max-age=0, must-revalidate",
                "content-security-policy": (
                    "default-src 'self'; script-src 'self'; "
                    "style-src 'self' 'unsafe-inline'; "
                    "font-src 'self' data: https://esm.sh; "
                    "img-src 'self' data: blob:; connect-src 'self'; "
                    "worker-src 'self' blob:; object-src 'none'; base-uri 'none'; "
                    "frame-ancestors 'self'; form-action 'self'"
                ),
                "x-content-type-options": "nosniff",
            },
        )

