    @mcp.custom_route(
        "/api/calliope/sessions/{session_id}/playbook",
        methods=["POST"],
    )
    async def save_session_as_playbook(request):
        """Save a chat as a Playbook: open a home thread beside it, where
        Calliope drafts the method from the whole chat and talks it through.
        The chat itself is left as it was."""
        owner, err = api_owner(request)
        if err:
            return err
        viewer = str(owner).lower()
        source_id = _uuid(request.path_params["session_id"])
        if not source_id:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        requested_focus = body.get("focus_turn_id")
        focus_id = _uuid(requested_focus) if requested_focus not in (None, "") else None
        if requested_focus not in (None, "") and not focus_id:
            return json_response({"error": {"code": "INVALID_SOURCE_TURN"}}, 400)

        def prepare():
            with conn_factory() as conn:
                source = conn.execute(
                    "SELECT id::text,title FROM rvbbit.calliope_sessions WHERE id=%s::uuid "
                    "AND rvbbit.calliope_session_can_view(id,%s,false)",
                    (source_id, viewer),
                ).fetchone()
                if not source:
                    return None, "NOT_FOUND", None
                if focus_id and not conn.execute(
                    "SELECT 1 FROM rvbbit.calliope_turns WHERE id=%s::uuid AND session_id=%s::uuid "
                    "AND turn_kind='chat' AND status IN ('complete','partial')",
                    (focus_id, source_id),
                ).fetchone():
                    return dict(source), "SOURCE_TURN_NOT_FOUND", None
                # A second click reuses the home that has not started yet.
                waiting = conn.execute(
                    "SELECT h.session_id::text FROM rvbbit.calliope_playbook_homes h "
                    "WHERE h.owner_email=%s AND h.source_session_id=%s::uuid AND h.playbook_id IS NULL "
                    "AND h.focus_turn_id IS NOT DISTINCT FROM %s::uuid "
                    "AND h.created_at > now() - interval '10 minutes' "
                    "AND NOT EXISTS (SELECT 1 FROM rvbbit.calliope_turns t WHERE t.session_id=h.session_id) "
                    "ORDER BY h.created_at DESC LIMIT 1",
                    (viewer, source_id, focus_id),
                ).fetchone()
                return dict(source), None, waiting and str(waiting["session_id"])

        source, problem, home_id = await asyncio.to_thread(prepare)
        if problem:
            return json_response({"error": {"code": problem}}, 404)
        title = re.sub(r"\s+", " ", str(source.get("title") or "this chat")).strip()[:80]
        if not home_id:
            try:
                session = await _create_session_record(
                    config, conn_factory, owner, f"Playbook · from “{title}”"[:120]
                )
            except Exception as exc:
                return json_response(
                    {"error": {"code": "HERMES_UNAVAILABLE", "message": str(exc)[:600]}}, 502
                )
            home_id = str(session["id"])

            def record():
                with conn_factory() as conn:
                    conn.execute(
                        "INSERT INTO rvbbit.calliope_playbook_homes "
                        "(session_id,owner_email,source_session_id,focus_turn_id) "
                        "VALUES (%s::uuid,%s,%s::uuid,%s::uuid)",
                        (home_id, viewer, source_id, focus_id),
                    )

            try:
                await asyncio.to_thread(record)
            except Exception as exc:
                await discard_created_session(session)
                return json_response(
                    {"error": {"code": "PLAYBOOK_HOME_FAILED", "message": str(exc)[:600]}}, 500
                )
        prompt = f"Draft a playbook from “{title}”."
        return json_response(
            {
                "session_id": home_id,
                "url": "/calliope?" + urlencode(
                    {"session": home_id, "prompt": prompt, "autorun": "playbook"}
                ),
            },
            201,
        )

    @mcp.custom_route(
        "/api/calliope/playbooks/{playbook_id}/home",
        methods=["POST"],
    )
    async def open_playbook_home(request):
        """Open the thread where this person shapes a Playbook: its home for
        whoever manages it (made the first time), or a new home for their own
        copy of a Playbook someone shared with them."""
        owner, err = api_owner(request)
        if err:
            return err
        viewer = str(owner).lower()
        playbook_id = _uuid(request.path_params["playbook_id"])
        if not playbook_id:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            snapshot = await asyncio.to_thread(
                playbook_access.read, conn_factory, viewer, playbook_id
            )
        except playbook_access.PlaybookError as exc:
            return playbook_error_response(exc)
        playbook = snapshot["playbook"]
        title = re.sub(r"\s+", " ", str(playbook.get("title") or "Playbook")).strip()[:90]
        managing = bool(snapshot.get("can_manage"))
        if managing and playbook.get("home_session_id"):
            home_id = str(playbook["home_session_id"])
            return json_response(
                {"session_id": home_id, "url": "/calliope?" + urlencode({"session": home_id})}
            )
        try:
            session = await _create_session_record(
                config, conn_factory, owner,
                (f"Playbook · {title}" if managing else f"Playbook · {title} (your copy)")[:120],
            )
        except Exception as exc:
            return json_response(
                {"error": {"code": "HERMES_UNAVAILABLE", "message": str(exc)[:600]}}, 502
            )
        home_id = str(session["id"])

        def record():
            with conn_factory() as conn:
                if managing:
                    row = conn.execute(
                        "INSERT INTO rvbbit.calliope_playbook_homes "
                        "(session_id,owner_email,playbook_id,source_session_id) "
                        "VALUES (%s::uuid,%s,%s::uuid,%s::uuid) ON CONFLICT DO NOTHING "
                        "RETURNING session_id::text",
                        (home_id, viewer, playbook_id, playbook.get("source_session_id")),
                    ).fetchone()
                    if row:
                        return home_id
                    # Another tab made the home first; use that one.
                    return playbook_access.home_of(conn, playbook_id, viewer)
                conn.execute(
                    "INSERT INTO rvbbit.calliope_playbook_homes (session_id,owner_email,fork_of) "
                    "VALUES (%s::uuid,%s,%s::uuid)",
                    (home_id, viewer, playbook_id),
                )
                return home_id

        try:
            chosen = await asyncio.to_thread(record)
        except Exception as exc:
            await discard_created_session(session)
            return json_response(
                {"error": {"code": "PLAYBOOK_HOME_FAILED", "message": str(exc)[:600]}}, 500
            )
        if chosen != home_id:
            await discard_created_session(session)
            return json_response(
                {"session_id": chosen, "url": "/calliope?" + urlencode({"session": chosen})}
            )
        if managing:
            # A new home opens on the Playbook itself rather than an empty thread.
            note = (f"This is where the “{title}” Playbook is shaped. Tell me what to change and I'll "
                    "draft the next version; the approved one keeps working until you approve it.")
            if snapshot.get("built_in"):
                note += " It's built in, so as an Admin you're changing it for everyone."

            def seed():
                turn_id = str(uuid.uuid4())
                with conn_factory() as conn:
                    conn.execute(
                        "INSERT INTO rvbbit.calliope_turns (id,session_id,ordinal,user_message,"
                        "assistant_message,status,completed_at,turn_kind,author_email) VALUES "
                        "(%s::uuid,%s::uuid,1,%s,%s,'complete',now(),'chat',%s)",
                        (turn_id, home_id, f"Open the “{title}” Playbook", note, viewer),
                    )
                _insert_surfaces(conn_factory, home_id, turn_id, [{
                    "kind": "playbook",
                    "title": title,
                    "tool_name": "open_calliope_playbook_home",
                    "tool_call_id": f"playbook-home:{playbook_id}",
                    "lineage_key": f"playbook:{playbook_id}",
                    "payload": {"mode": "calliope_playbook", **snapshot},
                    "source": {"origin": "calliope_playbook"},
                    "presentation": {"view": "playbook"},
                }])

            try:
                await asyncio.to_thread(seed)
            except Exception as exc:  # the home still works; the card arrives with the first change
                print(f"WARNING: playbook home seed failed: {type(exc).__name__}: {exc}", file=os.sys.stderr)
            return json_response(
                {"session_id": home_id, "url": "/calliope?" + urlencode({"session": home_id})}, 201
            )
        return json_response(
            {
                "session_id": home_id,
                "url": "/calliope?" + urlencode({
                    "session": home_id,
                    "prompt": f"Make my own copy of the “{title}” playbook.",
                    "autorun": "playbook",
                }),
            },
            201,
        )

