    @mcp.custom_route("/api/calliope/sessions/{session_id}/artifact-work", methods=["GET"])
    async def get_session_artifact_work(request):
        owner, err = api_owner(request)
        if err:
            return err
        try:
            with conn_factory() as conn:
                session = calliope_access.require_view(conn, request.path_params['session_id'], owner)
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        items = await asyncio.to_thread(artifact_work.snapshot, config, conn_factory, str(session['id']))
        _, signed = _canonical_owner(request)
        subject = (signed or {}).get('sub') or owner
        for item in items:
            source = item.pop('render_html', None)
            app_source = item.pop('render_app', None)
            if item.get('kind') == 'a2ui':
                import artifact_app_preview
                theme = artifact_app_preview.theme_for(conn_factory, owner)
                item.update(artifact_app_preview.describe(config, str(session['id']), item, app_source, subject, theme))
            else:
                item.update(artifact_render.describe(config, str(session['id']), item, source, subject, owner))
        payload = json_response({"items": items})
        etag = '"' + hashlib.sha256(payload.body).hexdigest() + '"'
        if request.headers.get("if-none-match") == etag:
            return Response(status_code=304, headers={"ETag": etag, "Cache-Control": "no-store"})
        payload.headers["ETag"] = etag
        return payload

    @mcp.custom_route("/api/calliope/sessions/{session_id}/artifact-work/{build_key}/image", methods=["GET"])
    async def get_session_artifact_image(request):
        owner, err = api_owner(request)
        if err:
            return err
        try:
            with conn_factory() as conn:
                session = calliope_access.require_view(conn, request.path_params['session_id'], owner)
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        items = await asyncio.to_thread(artifact_work.snapshot, config, conn_factory, str(session['id']))
        item = next((i for i in items if i['key'] == request.path_params['build_key']), None)
        if not item:
            return Response(status_code=404)
        _, signed = _canonical_owner(request)
        subject = (signed or {}).get('sub') or owner
