    @mcp.custom_route('/api/calliope/sessions/{session_id}/artifact-work/{build_key}/preview', methods=['GET'])
    @mcp.custom_route('/api/calliope/sessions/{session_id}/artifact-work/{build_key}/preview/ui', methods=['POST'])
    async def app_draft_preview(request):
        owner, err = api_owner(request)
        if err: return err
        try:
            with conn_factory() as conn:
                session = calliope_access.require_view(conn, request.path_params['session_id'], owner)
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        items = await asyncio.to_thread(artifact_work.snapshot, config, conn_factory, str(session['id']))
        item = next((i for i in items if i['key'] == request.path_params['build_key'] and i.get('kind') == 'a2ui'), None)
        if not item or not item.get('render_app'):
            return json_response({'error': {'message': 'This app draft is unavailable or expired'}}, 404)
        import ui_apps
        import ui_app_preview
        if request.method == 'GET':
            return Response(ui_apps.shell(), media_type='text/html', headers={'Cache-Control': 'no-store', 'X-Frame-Options': 'SAMEORIGIN'})
        origin = request.headers.get('origin')
        allowed = {str(request.base_url).rstrip('/'), os.environ.get('WAREHOUSE_PUBLIC_URL', '').rstrip('/')}
        if request.headers.get('sec-fetch-site') == 'cross-site' or (origin and origin not in allowed) or request.headers.get('content-type', '').split(';')[0] != 'application/json':
            return json_response({'error': {'message': 'Invalid preview origin'}}, 403)
        raw = await request.body()
        if len(raw) > 160000:
            return json_response({'error': {'message': 'Preview state is too large'}}, 413)
        _, signed = _canonical_owner(request)
        subject = (signed or {}).get('sub') or owner
        def run():
            import server
            try:
                body = json.loads(raw)
                if set(body) - {'state', 'event', 'context', 'expected_hash'}:
                    raise ValueError('Use state, event, context and expected_hash')
                if ('state' in body or body.get('event')) and not body.get('expected_hash'):
                    raise ValueError('Preview interactions require the loaded definition hash')
                return json_response(ui_app_preview.request_snapshot(server, item['render_app'], {**body, 'mode': 'server-read'}, subject))
            except (ValueError, KeyError, TypeError) as exc:
                return json_response({'error': {'message': str(exc)}}, 400)
        return await asyncio.to_thread(run)

