    @mcp.custom_route("/api/calliope/sessions/{session_id}/fork", methods=["POST"])
    async def fork_session(request):
        """Fork this chat at one of its messages into a new chat the caller owns."""
        import calliope_fork
        owner, err = api_owner(request)
        if err:
            return err
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}

        def planned():
            with conn_factory() as conn:
                return calliope_fork.plan(conn, request.path_params["session_id"], body.get("turn_id"), owner)

        try:
            fork = await asyncio.to_thread(planned)
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        except calliope_fork.ForkError as exc:
            return json_response({"error": {"code": exc.code, "message": str(exc)}}, exc.status)
        source = fork["session"]
        base_url = _session_hermes_base_url(config, conn_factory, source)
        try:
            capabilities = await _hermes_json(config, "GET", "/v1/capabilities", base_url=base_url)
        except Exception:
            capabilities = {}
        if not ((capabilities or {}).get("features") or {}).get("calliope_session_fork"):
            # Stock Hermes would copy everything and end the original chat.
            return json_response({"error": {"code": "FORK_UNSUPPORTED",
                                            "message": "This agent runtime cannot fork a chat yet; update the Hermes image."}}, 409)
        session_id = str(uuid.uuid4())
        hermes_id = f"calliope_{int(time.time())}_{uuid.uuid4().hex[:10]}"
        try:
            await _hermes_json(
                config, "POST",
                f"/api/sessions/{quote(str(source['hermes_session_id']), safe='')}/fork",
                # No title: Hermes titles must be unique and it numbers a fork's lineage itself.
                {"id": hermes_id, "keep_source": True,
                 "until_ts": fork["hermes_until"], "replacements": fork["slugs"]},
                base_url=base_url,
            )
        except Exception as exc:
            logging.getLogger(__name__).warning("Fork of %s: Hermes fork failed: %s", source["id"], exc)
            try:  # a half-made Hermes session must not linger
                await _hermes_json(config, "DELETE", f"/api/sessions/{quote(hermes_id, safe='')}",
                                   base_url=base_url)
            except Exception:
                pass
            return json_response({"error": {"code": "FORK_FAILED",
                                            "message": "The chat could not be forked right now."}}, 503)

        def written():
            with conn_factory() as conn:
                with conn.transaction():
                    return calliope_fork.apply(conn, fork, owner=owner, session_id=session_id,
                                               hermes_session_id=hermes_id)

        try:
            row = await asyncio.to_thread(written)
        except Exception as exc:
            logging.getLogger(__name__).warning("Fork of %s failed: %s: %s", source["id"], type(exc).__name__, exc)
            try:
                await _hermes_json(config, "DELETE", f"/api/sessions/{quote(hermes_id, safe='')}",
                                   base_url=base_url)
            except Exception:
                pass
            return json_response({"error": {"code": "FORK_FAILED",
                                            "message": "The chat could not be forked right now."}}, 503)
        return json_response({"session": _session_json(row), "fork": row.get("forked_from")}, 201)

    @mcp.custom_route("/api/calliope/sessions/{session_id}/views", methods=["POST"])
    async def session_stage_views(request):
        """Stage items as A2UI documents for the client's declared catalog."""
        owner, err = api_owner(request)
        if err:
            return err
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        ids = [value for value in (_uuid(item) for item in (body.get("surface_ids") or [])[:20]) if value]
        try:
            with conn_factory() as conn:
                session = calliope_access.require_view(conn, request.path_params["session_id"], owner)
                participate = conn.execute(
                    "SELECT rvbbit.calliope_session_can_participate(%s::uuid,%s) AS ok",
                    (str(session["id"]), owner),
                ).fetchone()
                rows = conn.execute(
                    "SELECT * FROM rvbbit.calliope_surfaces WHERE session_id=%s::uuid AND id=ANY(%s::uuid[])",
                    (str(session["id"]), ids),
                ).fetchall() if ids else []
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        # Answers go through the input-request API, which applies the same rules.
        can_answer = bool((participate or {}).get("ok")) and not session.get("archived") and (
            session.get("channel") or "web") == "web"
        import stage_views
        # Receipts follow their canonical runs, as the session view shows them.
        surfaces = _refresh_local_sql_surfaces(
            conn_factory, str(session["id"]), str(session.get("owner_email") or owner),
            [_surface_json(row) for row in rows],
        )
        decision_ids = [
            str((surface.get("payload") or {}).get("id")) for surface in surfaces
            if surface.get("kind") == "decision" and _uuid((surface.get("payload") or {}).get("id"))
        ]
        if decision_ids:
            # The Stage copy is a snapshot; status and revision live on the request.
            import calliope_decisions
            with conn_factory() as conn:
                live = {
                    str(row["id"]): calliope_decisions.decision_public(row)
                    for row in conn.execute(
                        "SELECT * FROM rvbbit.calliope_decision_requests WHERE id=ANY(%s::uuid[])",
                        (decision_ids,),
                    ).fetchall()
                }
            surfaces = [
                {**surface, "payload": live.get(str((surface.get("payload") or {}).get("id")), surface.get("payload"))}
                if surface.get("kind") == "decision" else surface
                for surface in surfaces
            ]

        async def chart_data(row, surface):
            if not stage_views.wants_chart_data(surface, body.get("client")):
                return None
            import server
            try:
                return await server.stage_chart_data(row, owner)
            except Exception as exc:  # A failed dataset keeps the hand-off.
                return {"error": str(exc)[:300]}

        data = await asyncio.gather(*(chart_data(row, surface) for row, surface in zip(rows, surfaces)))
        return json_response({
            "template_version": stage_views.TEMPLATE_VERSION,
            "views": [stage_views.project(surface, body.get("client"), can_answer=can_answer, chart_data=item)
                      for surface, item in zip(surfaces, data)],
        })

    @mcp.custom_route("/api/calliope/sessions/{session_id}", methods=["GET"])
    async def get_session(request, *, for_export=False):
        owner, err = api_owner(request)
        if err:
            return err
        try:
            with conn_factory() as conn:
                session = calliope_access.require_view(
                    conn, request.path_params["session_id"], owner
                )
                audience = calliope_access._audience(conn, session)
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        if session.get("access_role") == "owner" and not for_export:
            _reconcile_session_files(conn_factory, config, str(session["id"]))
        with conn_factory() as conn:
            turns = conn.execute(
                "SELECT t.*,p.display_name AS author_profile_name,"
                "p.avatar_key::text AS author_avatar_key "
                "FROM rvbbit.calliope_turns t "
                "LEFT JOIN rvbbit.application_principals p "
                "ON p.email=lower(t.author_email) WHERE t.session_id=%s::uuid "
                "ORDER BY ordinal",
                (str(session["id"]),),
            ).fetchall()
            display_updates = _turn_display_updates(conn, [str(row["id"]) for row in turns])
            export_progress = conn.execute(
                "SELECT e.turn_id::text,e.sequence,e.created_at,e.payload->>'text' AS text "
                "FROM rvbbit.calliope_turn_events e JOIN rvbbit.calliope_turns t ON t.id=e.turn_id "
                "WHERE t.session_id=%s::uuid AND e.event_type='calliope.progress' "
                "ORDER BY e.created_at,e.turn_id,e.sequence", (str(session["id"]),)
            ).fetchall() if for_export else []
            surfaces = conn.execute(
                "SELECT * FROM rvbbit.calliope_surfaces WHERE session_id=%s::uuid "
                "ORDER BY created_at DESC, ordinal DESC",
                (str(session["id"]),),
            ).fetchall()
            specialist_threads = _specialist_thread_rows(
                conn,
                str(session.get("owner_email") or owner),
                str(session["id"]),
            )
            try:
                with conn.transaction():
                    # Whoever saved a Playbook from this chat (owner or room
                    # member) sees it on the reply it was learned through.
                    playbook_sources = conn.execute(
                        "SELECT v.source_turn_id::text,p.id::text AS playbook_id,v.version,v.title,"
                        "(p.approved_version=v.version) AS approved,"
                        "(SELECT h.session_id::text FROM rvbbit.calliope_playbook_homes h "
                        " WHERE h.playbook_id=p.id AND h.owner_email=lower(%s) LIMIT 1) AS home_session_id "
                        "FROM rvbbit.calliope_playbook_versions v "
                        "JOIN rvbbit.calliope_playbooks p ON p.id=v.playbook_id "
                        "WHERE v.source_session_id=%s::uuid AND v.source_turn_id IS NOT NULL "
                        "AND NOT p.archived AND lower(v.created_by)=lower(%s) "
                        "ORDER BY v.created_at DESC LIMIT 200",
                        (owner, str(session["id"]), owner),
                    ).fetchall()
            except Exception:
                playbook_sources = []
        page_sources = []
        if session.get('access_role') == 'owner':
            with conn_factory() as conn:
                page_sources = conn.execute(
                    "SELECT DISTINCT r.source_turn_id::text,p.id::text,p.session_id::text,p.title "
                    "FROM rvbbit.calliope_page_runs r JOIN rvbbit.calliope_pages p ON p.id=r.page_id "
                    "WHERE r.session_id=%s AND r.source_turn_id IS NOT NULL "
                    "AND p.owner_email=%s AND p.status<>'archived'", (session['id'],owner)).fetchall()
        pages_by_turn = {}
        for item in page_sources:
            pages_by_turn.setdefault(item['source_turn_id'], []).append(dict(item))
        playbook_surface_cache: dict[
            tuple[str, int | None], dict[str, Any] | None
        ] = {}
        visible_surfaces = [
            projected
            for row in surfaces
            if (
                projected := _playbook_surface_json(
                    conn_factory,
                    owner,
                    row,
                    playbook_surface_cache,
                )
            )
            is not None
        ]
        visible_surfaces = _merge_specialist_thread_surfaces(
            conn_factory,
            str(session.get("owner_email") or owner),
            visible_surfaces,
            specialist_threads,
        )
        if not for_export:
            visible_surfaces = _refresh_local_sql_surfaces(
                conn_factory, str(session['id']), str(session.get('owner_email') or owner), visible_surfaces,
            )
        saved_by_turn: dict[str, list[dict[str, Any]]] = {}
        for row in playbook_sources:
            saved_by_turn.setdefault(str(row["source_turn_id"]), []).append({
                "id": str(row["playbook_id"]),
                "version": int(row["version"]),
                "title": str(row.get("title") or "Playbook")[:240],
                "approved": bool(row.get("approved")),
                "home_session_id": row.get("home_session_id"),
            })
        viewer_takes = {} if for_export else await asyncio.to_thread(
            _viewer_takes, conn_factory, owner, str(session["id"]))
        viewer_notes = {} if for_export else await asyncio.to_thread(
            _viewer_take_notes, conn_factory, owner, str(session["id"]))
        turn_items = []
        for row in turns:
            turn = _turn_json(row)
            take = viewer_takes.get(str(turn["id"]))
            if take:
                turn["response_receipt"] = {**turn["response_receipt"], **take}
            turn["working_take_notes"] = viewer_notes.get(str(turn["id"]), [])
            turn["working_updates"] = display_updates.get(str(turn["id"]), [])
            saved = saved_by_turn.get(str(turn.get("id") or ""), [])
            if saved:
                turn["response_receipt"] = {
                    **(turn.get("response_receipt") or {}),
                    "saved_playbooks": saved,
                }
            if str(turn['id']) in pages_by_turn:
                turn['response_receipt'] = {**(turn.get('response_receipt') or {}),
                    'saved_pages': pages_by_turn[str(turn['id'])]}
            turn_items.append(turn)
        if not for_export:
            # Turns that completed before citations shipped get theirs the
            # first time the thread is opened, a few per read.
            try:
                import stage_citations
                stage_citations.backfill(conn_factory, turn_items)
            except Exception as exc:
                print(f"WARNING: stage citation backfill failed: {type(exc).__name__}: {exc}", file=os.sys.stderr)
        return json_response({
            "session": _session_json(session),
            "turns": turn_items,
            "presentation": await asyncio.to_thread(floor_presentations.read_thread, conn_factory, str(session["id"]), owner),
            "page": await asyncio.to_thread(calliope_pages.page_for_session, conn_factory, owner, str(session["id"])),
            "surfaces": visible_surfaces,
            "specialist_threads": [
                _specialist_thread_summary_json(row) for row in specialist_threads
            ],
            "agent_work": None if for_export else _session_agent_work(conn_factory, str(session["id"])),
            **({"export_progress": export_progress} if for_export else {}),
            "audience": audience,
            **({} if for_export else {
                "room": await asyncio.to_thread(_room_payload, conn_factory, str(session["id"]), owner),
                "playbook_home": await asyncio.to_thread(
                    _playbook_home_payload, conn_factory, str(session["id"]), owner),
            }),
        })

    @mcp.custom_route("/api/calliope/sessions/{session_id}/export.md", methods=["GET"])
    async def export_session_markdown(request):
        # Share the chat's access check and separately-authorized Stage projection.
        response = await get_session(request, for_export=True)
        if response.status_code != 200:
            return response
        data = json.loads(response.body)
        def build():
            documents = thread_export.text_documents(conn_factory, data['session']['id'],
                                                      data['surfaces'], config.file_root)
            return thread_export.render(data, os.environ.get('WAREHOUSE_PUBLIC_URL') or str(request.base_url),
                                        progress=data.get('export_progress', []), documents=documents)
        markdown, filename = await asyncio.to_thread(build)
        return Response(markdown, media_type="text/markdown; charset=utf-8", headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
            "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff",
        })

