    @mcp.custom_route("/api/calliope/sessions/{session_id}", methods=["PATCH"])
    async def patch_session(request):
        owner, err = api_owner(request)
        if err:
            return err
        session = _session_for_owner(conn_factory, request.path_params["session_id"], owner)
        manager = False
        if not session:
            # A manager renames, archives and sets up a room like its owner.
            try:
                with conn_factory() as conn:
                    session = calliope_access.require_manager(
                        conn, request.path_params["session_id"], {"subject": owner}
                    )
                manager = True
            except calliope_access.CalliopeAccessError:
                session = None
        if not session:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            body = await request.json()
        except Exception:
            body = {}
        if manager and "agent_key" in body:
            return json_response({"error": {"code": "OWNER_ONLY",
                "message": "Only the chat's owner can switch its agent."}}, 403)
        if manager:
            with conn_factory() as conn:
                session = dict(conn.execute(
                    "SELECT * FROM rvbbit.calliope_sessions WHERE id=%s::uuid",
                    (str(session["id"]),),
                ).fetchone())
        if "agent_key" in body:
            try:
                session = await _switch_empty_session_agent(
                    config,
                    conn_factory,
                    session,
                    body.get("agent_key"),
                )
            except ValueError as exc:
                return json_response(
                    {"error": {"code": "AGENT_NOT_AVAILABLE", "message": str(exc)}},
                    400,
                )
            except RuntimeError as exc:
                return json_response(
                    {"error": {"code": "AGENT_LOCKED", "message": str(exc)}},
                    409,
                )
            except Exception as exc:
                return json_response(
                    {
                        "error": {
                            "code": "AGENT_SWITCH_FAILED",
                            "message": str(exc)[:600],
                        }
                    },
                    502,
                )
        updates, values = [], []
        if "title" in body:
            title = re.sub(r"\s+", " ", str(body.get("title") or "")).strip()[:120]
            if not title:
                return json_response({"error": {"code": "INVALID_TITLE"}}, 400)
            updates.append("title=%s")
            values.append(title)
            updates.append("title_source='manual'")
            updates.append("title_generated_at=NULL")
        if "archived" in body:
            updates.append("archived=%s")
            values.append(bool(body.get("archived")))
        if "authoring_mode" in body:
            mode = body["authoring_mode"]
            if mode not in ("html", "dashboard"):
                return json_response({"error": {"code": "INVALID_AUTHORING_MODE"}}, 400)
            # Accept stale clients' mode fields, but never re-enable Dashboard authoring.
            mode = "html"
            updates.append("authoring_mode=%s")
            values.append(mode)
        if "team_mode" in body:
            updates.append("team_mode=%s")
            values.append(bool(body.get("team_mode")))
        if "design_profile_version_id" in body:
            requested = body.get("design_profile_version_id")
            version_id = _uuid(requested)
            if requested not in (None, "") and not version_id:
                return json_response(
                    {"error": {"code": "INVALID_DESIGN_PROFILE"}},
                    400,
                )
            if version_id and not _design_profile_version(
                conn_factory,
                version_id,
                active_only=True,
            ):
                return json_response(
                    {"error": {"code": "DESIGN_PROFILE_NOT_FOUND"}},
                    404,
                )
            updates.append("design_profile_version_id=%s::uuid")
            values.append(version_id)
        if not updates and "agent_key" not in body:
            return json_response({"error": {"code": "NO_CHANGES"}}, 400)
        if updates:
            values.extend([str(session["id"]), owner, owner])
            with conn_factory() as conn:
                row = conn.execute(
                    f"UPDATE rvbbit.calliope_sessions SET {','.join(updates)},updated_at=now() "
                    "WHERE id=%s::uuid AND (owner_email=%s OR rvbbit.calliope_session_role(id,%s)='manager') "
                    "RETURNING *",
                    values,
                ).fetchone()
            if not row:
                return json_response({"error": {"code": "NOT_FOUND"}}, 404)
            if manager:
                row = {**dict(row), "access_role": "manager"}
        else:
            row = session
        if "title" in body:
            await _sync_hermes_session_title(
                config,
                row.get("hermes_session_id"),
                row.get("title"),
                base_url=_session_hermes_base_url(config, conn_factory, row),
            )
        return json_response({"session": _session_json(row)})

    @mcp.custom_route("/api/calliope/attachments/{attachment_id}", methods=["GET"])
    async def get_attachment(request):
        owner, err = api_owner(request)
        if err:
            return err
        aid = _uuid(request.path_params["attachment_id"])
        if not aid:
            return Response(status_code=404)
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT a.* FROM rvbbit.calliope_attachments a "
                "WHERE a.id=%s::uuid "
                "AND rvbbit.calliope_session_can_view(a.session_id,%s,false)",
                (aid, owner),
            ).fetchone()
        if not row:
            return Response(status_code=404)
        path = Path(row["storage_path"]).resolve()
        try:
            path.relative_to(config.file_root.resolve())
        except ValueError:
            return Response(status_code=404)
        if not path.is_file():
            return Response(status_code=404)
        return FileResponse(
            path,
            media_type=row["mime_type"],
            filename=row.get("original_name") or path.name,
            content_disposition_type=("inline" if row['mime_type'] in {'image/png','image/jpeg','image/webp','image/gif'} else "attachment"),
            headers={
                "cache-control": "private, no-store",
                "x-content-type-options": "nosniff",
            },
        )

