    @mcp.custom_route("/api/calliope/surfaces/{surface_id}/chart-data", methods=["POST"])
    async def get_stage_chart_data(request):
        owner, err = api_owner(request)
        if err:
            return err
        surface_id = _uuid(request.path_params["surface_id"])
        if not surface_id:
            return Response(status_code=404)
        def lookup():
            with conn_factory() as conn:
                return conn.execute(
                    "SELECT f.id,f.payload FROM rvbbit.calliope_surfaces f WHERE f.id=%s::uuid "
                    "AND f.kind='chart' AND rvbbit.calliope_session_can_view(f.session_id,%s,false)",
                    (surface_id, owner),
                ).fetchone()
        row = await asyncio.to_thread(lookup)
        if not row or not (row.get("payload") or {}).get("queries"):
            return Response(status_code=404)
        try:
            body = await request.json()
            import server
            import stage_charts
            try:
                attempt = await asyncio.to_thread(stage_charts.begin_render, conn_factory, surface_id, owner)
            except Exception as exc:
                attempt = None
                print(f"WARNING: chart render attempt could not be saved: {type(exc).__name__}", file=os.sys.stderr)
            try:
                result = await server.stage_chart_data(row, owner, refresh=isinstance(body, dict) and body.get("refresh") is True)
            except Exception as exc:
                if attempt:
                    try:
                        await asyncio.to_thread(stage_charts.record_render, conn_factory, surface_id, owner,
                            {"attempt": attempt, "sequence": 0, "status": "error", "phase": "query", "message": str(exc)})
                    except Exception as report_error:
                        print(f"WARNING: chart query diagnostic could not be saved: {type(report_error).__name__}", file=os.sys.stderr)
                raise
            return json_response({**result, "render_attempt": attempt})
        except Exception as exc:
            return json_response({"error": {"message": str(exc)[:1000]}}, 400)

